object Main extends App {
  val sc = new java.util.Scanner(System.in)
  val n = sc.nextInt()
  val a = Array.fill(3 * n)(sc.nextInt()-1)

  def compose(x1: Int, x2: Int): Int = {
    x1 * n + x2
  }

  val dp = Array.fill(n * n)(-1)
  val m1 = Array.fill(n)(-1)
  val m2 = Array.fill(n)(-1)
  var m = 0
  var ans = 0

  dp(compose(a(0), a(1))) = 0
  m1(a(0)) = 0
  m2(a(1)) = 0

  for (i <- 1 until n) {
    val dpNew = Array.fill(n * n)(-1)
    val m1New = Array.fill(n)(-1)
    val m2New = Array.fill(n)(-1)

    def maximize(i: Int, j: Int, v: Int): Unit = {
      dpNew(compose(i, j)) = dp(compose(i, j)).max(dpNew(compose(i, j))).max(v)
      m1New(i) = m1New(i).max(dpNew(compose(i, j)))
      m2New(j) = m2New(j).max(dpNew(compose(i, j)))
    }

    val p = a(3 * i - 1)
    val q = a(3 * i)
    val r = a(3 * i + 1)
    if (p == q && q == r) {
      ans += 1
    } else {
      if (p == q || p == r || q == r) {
        val x = if (p == q || p == r) p else q
        val y = if (p == q) r else if (p == r) q else p
        for (i <- 0 until n) {
          maximize(i, y, dp(compose(x, i)).max(dp(compose(i, x))) + 1)
        }
      }

      maximize(q, r, dp(compose(p, p)) + 1)
      maximize(p, r, dp(compose(q, q)) + 1)
      maximize(p, q, dp(compose(r, r)) + 1)

      maximize(p, q, dp(m))
      maximize(p, r, dp(m))
      maximize(q, r, dp(m))

      for (i <- 0 until n) {
        maximize(i, p, m1(i).max(m2(i)))
        maximize(i, q, m1(i).max(m2(i)))
        maximize(i, r, m1(i).max(m2(i)))
      }

      for {
        i <- 0 until n
        j <- 0 until n
      } {
        dp(compose(i, j)) = dp(compose(i, j)).max(dpNew(compose(i, j)))
        m = m.max(dpNew(compose(i, j)))
      }

      for (i <- 0 until n) {
        m1(i) = m1New(i)
        m2(i) = m2New(i)
      }
    }
  }

  val last = a(3*n - 1)
  m = m.max(dp(compose(last, last)) + 1)

  println(ans + m)
}

