  val dp = Array.fill(N*N)(Int.MinValue)
  val m1 = Array.fill(N)(Int.MinValue)
  val m2 = Array.fill(N)(Int.MinValue)
  var m = 0
  var ans = 0
  dp(comp(As(0), As(1))) = 0
  m1(As(0)) = 0
  m2(As(1)) = 0
  var update = List[(Int, Int, Int)]()
  for (i <- 1 until N) {
    val p = As(3*i - 1)
    val q = As(3*i)
    val r = As(3*i + 1)
    if (p == q && q == r) {
      ans += 1
    } else {
      if (p == q || p == r || r == q) {
        val x = if (p == q || r == p) p else q
        val y = if (p == q) r else if (r == p) q else p
        for (i <- 0 until N) {
          update ::= (i, y, dp(comp(x, i)).max(dp(comp(i, x))) + 1)
        }
      }
      update ::= (q, r, dp(comp(p, p)) + 1)
      update ::= (p, r, dp(comp(q, q)) + 1)
      update ::= (p, q, dp(comp(r, r)) + 1)
      update ::= (p, q, m)
