        update ::= (i, r, m1(i).max(m2(i)))
      }
      for ((i, j, v) <- update) {
        dp(comp(i, j)) = dp(comp(i, j)).max(v)
        m1(i) = m1(i).max(dp(comp(i, j)))
        m2(j) = m2(j).max(dp(comp(i, j)))
        m = m.max(dp(comp(i, j)))
      }
      update = Nil
    }
  }
  val last = As(3*N - 1)
  m = m.max(dp(comp(last, last)) + 1)
  println(ans + m)
}

