#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ull = unsigned long long;
#define REP(i,n) for (ll i = 0; i < (n); ++i)
#define RREP(i, n) for (ll i = (n) - 1; i >= 0; --i)
#define ALL(v) (v).begin(), (v).end()
template<class T>
using reverse_priority_queue = priority_queue<T, vector<T>, greater<T>>;

ll get_3elem(const map<ll, ll>& count){
    for(auto it = count.begin(); it != count.end(); ++it){
        if(it->second >= 3){ return it->first; }
    }
    return -1;
}

map<ll, ll> get_count(const vector<ll>& x){
    map<ll, ll> ret;
    for(ll xi : x){
        ret[xi]++;
    }
    return ret;
}

void push_back_count(const map<ll, ll>& count, vector<ll>& out){
    for(auto it = count.begin(); it != count.end(); ++it){
        REP(_, it->second){
            out.push_back(it->first);
        }
    }
}

int main(){
    ll n;
    cin >> n;
    vector<ll> a(3 * n);
    REP(i, 3 * n){ cin >> a.at(i); }
    reverse(ALL(a));

    ll ans = 0;
    while(a.size() > 3){
        vector<ll> x;
        REP(i, 5){
            x.push_back(a.back());
            a.pop_back();
        }

        map<ll, ll> count  = get_count(x);
        const ll e3 = get_3elem(count);

        if(e3 != -1){
            ans++;
            count[e3] -= 3;
            push_back_count(count, a);
        }else{
            auto count2 = count;
            map<ll, ll> pos;
            for(ll xi : x){ pos[xi] = numeric_limits<ll>::max(); }
            RREP(i, a.size()){
                const ll ai = a.at(i);
                if(count2.count(ai) == 0){ continue; }
                count2.at(ai)++;
                if(count2.at(ai) == 3){
                    pos.at(ai) = i;
                }
            }
            vector<pair<ll, ll>> pos2;
            for(auto it = pos.begin(); it != pos.end(); ++it){
                pos2.emplace_back(it->second, it->first);
            }
            sort(pos2.rbegin(), pos2.rend());

            ll erase_num = 0;
            for(ll i = 0; i < pos2.size() && erase_num < 3; ++i){
                const ll ai = pos2.at(i).second;
                while(count.at(ai) > 0 && erase_num < 3){
                    erase_num++;
                    count.at(ai)--;
                }
            }
            push_back_count(count, a);
        }
        assert(a.size() % 3 == 0);
    }

    // last three
    const auto count = get_count(a);
    if(get_3elem(count) != -1){
        ans++;
    }

    cout << ans << endl;
    return 0;
}

