template<typename T>
struct pair2 {
	T first;
	T second;
	pair2(const T& first, const T& second) :first(first), second(second) {}
	bool operator <(const pair2<T>& op) const {
		return dp[index(this->first, this->second)] > dp[index(op.first, op.second)];
	}
};


vector<set<pair2<int>>> r;

void update(int k1, int k2, int v) {
	if (dp[index(k1, k2)] < v) {
		dp[index(k1, k2)] = v;

		auto p = pair2<int>(min(k1, k2), max(k1, k2));
		r[k1].erase(p);
		r[k2].erase(p);

		r[k1].insert(p);
		r[k2].insert(p);
	}
}

int getmax(int k) {
	return dp[index(r[k].begin()->first, r[k].begin()->second)];
}

