		r.emplace_back(set<pair2<int>>());
		for (int j = 0; j < N; ++j) {
			r[i].insert(pair2<int>(min(i, j),max(i,j)));
		}
	}

	int combo3 = 0;
	for (int i = 0; i < N - 1; ++i) {
		int ind = 2 + 3 * i;

		if (A[ind] == A[ind + 1] && A[ind + 1] == A[ind + 2]) {
			combo3++;
			continue;
		}

		bool dup = false;
		int dupind[2];
		int ndupind;
		if (A[ind] == A[ind + 1]) {
			dup = true;
			dupind[0] = 0;
			dupind[1] = 1;
			ndupind = 2;
		}
		else if (A[ind + 1] == A[ind + 2]) {
			dup = true;
			dupind[0] = 1;
			dupind[1] = 2;
			ndupind = 0;
		}
		else if (A[ind + 2] == A[ind]) {
			dup = true;
			dupind[0] = 0;
			dupind[1] = 2;
			ndupind = 1;
		}

		if (dup) {

			int b;
