				int cv = A[ind + ndupind];
				b = dp[index(cv, cv)];

				update(cv, cv, getmax(cv));

				for (int k = 0; k < N; ++k) {
					if (k == A[ind + ndupind]) continue;
					update(cv, k, getmax(k));
				}
			}

			for (int l = 0; l < 2; ++l) {
				int cv = A[ind + dupind[l]];

