					update(cv, k, getmax(k));
				}
			}

			update(A[ind + dupind[0]], A[ind + dupind[1]], b + 1);
			for (int k = 0; k < N; ++k) {
				update(k, A[ind + ndupind], bv[k] + 1);
			}
		}
		else {
			int b[3];
			for (int j = 0; j < 3; ++j) {
				int cv = A[ind + j];
				b[j] = dp[index(cv, cv)];

				update(cv, cv, getmax(cv));

