					if (k == A[ind + j]) continue;
					update(cv, k, getmax(k));
				}
			}

			update(A[ind + 0], A[ind + 1], b[2] + 1);
			update(A[ind + 1], A[ind + 2], b[0] + 1);
			update(A[ind + 2], A[ind + 0], b[1] + 1);
		}
	}

	update(A.back(), A.back(), dp[index(A.back(), A.back())] + 1);

	int res = 0;

