			for (int j=1;j<=n;j++)
				first[i][j]=max(f[i][j],first[i-1][j]);
		}
	}
	int max=0;
	for (int i=0;i<=n;i++)
		for (int j=1;j<=n;j++)
		{
			if (max<f[i][j]) max=f[i][j];
		}
