pii p2(int a, int b){
    if(a<b) swap(a,b);
    return make_pair(a,b);
}

int solve(){
    vector<map<pii, int > > dp;
    dp.resize(N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[1][p2(A[0], A[1])] = 0;
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1]){
            dp[i+1] = dp[i];
            for(auto &[p,c]:dp[i+1]){
                c++;
            }
        }
        else{
            vector<int> vec;
            vec.push_back(A[3*i-1]);
            vec.push_back(A[3*i]);
            vec.push_back(A[3*i+1]);
            for(auto [p,c]:dp[i]){
                int a = p.first;
                int b = p.second;
                // if(a<b) continue;
                vector<int> combi = vec;
                combi.push_back(a);
                combi.push_back(b);
                // sort(combi.begin(),combi.end());
                map<int ,int > cnt;
                for(auto c:combi) cnt[c]++;
                auto cnt_max = *max_element(cnt.begin(),cnt.end(),[](pii a, pii b){return a.second < b.second;});
                if(cnt_max.second>=3){
                    vector<int> mp;
                    for(auto c:combi) {
                        if(c!=cnt_max.first){
                            mp.push_back(c);
                        }
                    }
                    if(mp.size()==0){
                        mp.push_back(cnt_max.first);
                        mp.push_back(cnt_max.first);
                    }
                    else if(mp.size()==1){
                        mp.push_back(cnt_max.first);
                    }
                    // sort(mp.begin(),mp.end(),greater<int>());
                    dp[i+1][p2(mp[0], mp[1])] = c+1;
                }
                else{
                    dp[i+1] = dp[i];
                    dp[i+1][p2(vec[0], vec[1])] = c;
                    dp[i+1][p2(vec[0], vec[2])] = c;
                    dp[i+1][p2(vec[1], vec[2])] = c;

                    dp[i+1][p2(a, vec[0])] = c;
                    dp[i+1][p2(a, vec[1])] = c;
                    dp[i+1][p2(a, vec[2])] = c;

                    dp[i+1][p2(b, vec[0])] = c;
                    dp[i+1][p2(b, vec[1])] = c;
                    dp[i+1][p2(b, vec[2])] = c;
                }
            }
        }
        dp[i].clear();
    }
    int ans = 0;
    for(auto [p,c]:dp[N]){
        int a = p.first;
        int b = p.second;
        if((a==b) && (b==A[3*N-1])) ans = max(ans, c + 1);
        else ans = max(ans, c);
    }
    cout << ans << endl;
    return 0;
} 

