	dp[a[0]][a[1]] = 0;
	dp[a[1]][a[0]] = 0;
	ll ans = 0;
	ll maxi = 0;
	vll m(n, -dekai);
	m[a[1]] = 0;
	m[a[0]] = 0;
	rep(i, n - 1) {
		ll b, c, d;
		b = a[i * 3 + 2], c = a[i * 3 + 3], d = a[i * 3 + 4];
