			} else {
				rep(i, n) { update(i, d, dp[i][b] + 1); }
				update(b, c, dp[d][d] + 1);
			}
		} else {
			update(b, c, dp[d][d] + 1);
			update(b, d, dp[c][c] + 1);
			update(d, c, dp[b][b] + 1);
		}
		rep(i, n) {
			update(i, b, m[i]);
			update(i, c, m[i]);
			update(i, d, m[i]);
