#include <bits/stdc++.h>

using namespace std;

int dp[2003];

int sol(int i, int pos, int b, int bb, const vector<int>& a) {
	if (b > bb)
		swap(b, bb);
	if (i == ((int)a.size()/3)-1)
		return (a[pos]==b&&a[pos]==bb);
	if (dp[i] != -1)
			return dp[i];
	int& ret = dp[i];
	ret = 0;
	vector<int> v(begin(a)+pos, begin(a)+pos+3);
	v.emplace_back(b);
	v.emplace_back(bb);
	assert(v.size() == 5);
	map<int, int> mp;
	for (int ii = 0; ii < 5; ii++) {
		mp[v[ii]]++;
	}
	for (int ii=0; ii<5; ii++)
		for (int j = ii+1; j < 5; j++) {
			mp[v[ii]]--;
			mp[v[j]]--;
			int ans = 0;
			for (const auto& x : mp) {
				ans += (x.second==3);
			}
			mp[v[ii]]++;
			mp[v[j]]++;
			ret = max(ret, ans+sol(i+1, pos+3, v[ii], v[j], a));
		}
	return ret;
}
