int dp[N][N], t[N][N], n;

void upd(int x, int y, int z) {
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) t[i][j] = -oo;
    vector<int> v({x, y, z});
    sort(v.begin(), v.end());
    do {
        x = v[0]; y = v[1]; z = v[2];
        for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
            t[i][j] = max(t[i][j], dp[i][j] + ((x == y) && (y == z)));
            t[x][y] = max(t[x][y], dp[i][j] + ((i == j) && (j == z)));
            t[i][z] = max(t[i][z], dp[i][j] + ((x == y) && (y == j)));
        }
    } while(next_permutation(v.begin(), v.end()));

    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) dp[i][j] = t[i][j];
}

int v[3*N];

void solve() {  
    cin >> n;
    assert(n<500);
    for (int i=1;i<=3*n;++i) {
        cin >> v[i];
        assert(v[i] >= 1 && v[i] <= n);
    }
    if (n == 1) {
        cout << ((v[1] == v[2]) && (v[2] == v[3])) << '\n';
        return;
    }
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) dp[i][j] = -oo;

    sort(v+1, v+6);

    do {
        dp[v[1]][v[2]] = max(dp[v[1]][v[2]], (int)((v[3] == v[4]) && (v[4] == v[5])));
    }while(next_permutation(v+1, v+6));

    for (int i=6;i<3*n;i+=3) {
        upd(v[i], v[i+1], v[i+2]);
    }

    int ans = 0;
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
        ans = max(ans, dp[i][j] + ((i == j) && (j == v[3*n])));
    }

    cout << ans << '\n';
}

