int main() {
  int N;
  std::cin >> N;
  std::vector<int> A(3 * N);
  for (int i = 0; i < 3 * N; ++i) {
    std::cin >> A[i];
  }
  std::vector<int> counts(N + 1);
  ++counts[A[0]];
  ++counts[A[1]];
  int score = 0;
  for (int i = 0; i < N - 1; ++i) {
    const auto a = A[3 * i + 2];
    const auto b = A[3 * i + 3];
    const auto c = A[3 * i + 4];
    const auto equality = (a == b) + (b == c) + (c == a);
    if (equality == 3) {
      ++score;
      continue;
    }
    if (equality == 0) {
      std::vector<int> next;
      for (const auto n : {a, b, c}) {
        if (counts[n] == 2) {
          next.push_back(n);
        }
      }
      if (!next.empty()) {
        ++score;
        std::fill(counts.begin(), counts.end(), 0);
        for (const auto n : {a, b, c}) {
          if (next.size() > 1 || n != next[0]) {
            ++counts[n];
          }
        }
        continue;
      }
    }
    if (equality == 1) {
      const int single = (a == b) ? c : ((b == c) ? a : b);
      const int pair = (a == b) ? a : c;
      const bool single_ok = counts[single] == 2;
      const bool pair_ok = counts[pair] >= 1;
      if (single_ok || pair_ok) {
        ++score;
        const int pair_count = counts[pair];
        if (pair_ok) {
          for (int j = 1; j <= N; ++j) {
            counts[j] = std::min(1, counts[j]);
          }
          counts[pair] = pair_count - 1;
        } else {
          std::fill(counts.begin(), counts.end(), 0);
        }
        if (pair_ok) {
          ++counts[single];
        }
        if (single_ok) {
          counts[pair] = 2;
        }
        continue;
      }
    }
    for (const auto n : {a, b, c}) {
      ++counts[n];
    }
  }
  score += counts[A.back()] == 2;
  std::cout << score << std::endl;
  return 0;
}

