    int n;
    cin >> n;
    vector<int> v(3 * n, 0);
    vector<vector<int>> pos(n + 1, vector<int>(0));
    for (int i = 0; i < 3 * n; i++) {
        cin >> v[i];
        pos[v[i]].push_back(i);
    }
    unordered_map<int, unordered_map<int, int>> um1, um2;
    um1[min(v[0], v[1])][max(v[0], v[1])] = 0;
    for (int i = 2; i < 3 * n - 1; i += 3) {
        um2.clear();
        for (auto p1 : um1) {
            for (auto p2 : p1.second) {
                int x = p1.first, y = p2.first;
                if (x != y) {
                    if (pos[x][1] < i) continue;
                    if (pos[y][1] < i) continue;
                }
                if (x == y) {
                    if (pos[x][2] < i) continue;
                }
                int last = p2.second;
                vector<int> temp{x, y, v[i], v[i + 1], v[i + 2]};
                for (int i1 = 0; i1 < 5; i1++) {
                    for (int i2 = 0; i2 < 5; i2++) {
                        if (i1 == i2) continue;
                        unordered_map<int, int> um;
                        int flag = 0;
                        for (int ii = 0; ii < 5; ii++) {
                            if (ii != i1 && ii != i2) {
                                um[temp[ii]]++;
                                if (um[temp[ii]] == 3) flag = 1;
                            }
                        }
                        int nx = temp[i1], ny = temp[i2];
                        um2[min(nx, ny)][max(nx, ny)] = max(um2[min(nx, ny)][max(nx, ny)], last + flag);
                    }
                }
            }
        }
        // um1 = um2;
        swap(um1, um2);
    }
    int res = 0;
    for (auto p1 : um1) {
        for (auto p2 : p1.second) {
            res = max(res, p2.second + (v.back() == p1.first && p1.first == p2.first ? 1 : 0));
        }
    }
    cout << res << endl;
}

