    vl mx(n + 1, -inf);

    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    mx[a[0]] = 0;
    mx[a[1]] = 0;

    ll lazy = 0;
    vector<map<ll, ll>> tmp(n + 1);
    rep(i, n) {
        vl s = {a[i * 3 + 2], a[i * 3 + 3], a[i * 3 + 4]};
        sort(all(s));
        if (s[0] == s[1] && s[1] == s[2]) {
            lazy++;
        } else if (s[0] == s[1] || s[1] == s[2]) {
            int b = s[0];
            int c = s[2];
            if (c == s[1]) swap(b, c);

            rep(j, n + 1) {
                // 1枚変更
                tmp[j][b] = mx[j];
                tmp[j][c] = mx[j];
                chmax(tmp[j][c], dp[j][b] + 1);

                //両方変更
                chmax(tmp[b][b], mx[j]);
                chmax(tmp[b][c], mx[j]);
                chmax(tmp[c][b], mx[j]);
            }
            //両方変更
            chmax(tmp[b][b], dp[c][c] + 1);
            chmax(tmp[b][c], dp[b][b] + 1);
            chmax(tmp[c][b], dp[b][b] + 1);
        } else {
            //一枚だけ変更
            rep(j, 3) { rep(k, n + 1) chmax(tmp[k][s[j]], mx[k]); }
            //二枚とも変更
            rep(j, 3) {
                rep(k, 3) {
                    if (j == k) continue;
                    rep(l, n + 1) chmax(tmp[s[j]][s[k]], mx[l]);
                    // 1組プラス
                    chmax(tmp[s[j]][s[k]], dp[3 - j - k][3 - j - k] + 1);
                }
            }
        }
        rep(x, n + 1) {
            for (auto [y, value] : tmp[x]) {
                chmax(dp[x][y], value);
                chmax(dp[y][x], value);
                chmax(mx[x], dp[x][y]);
                chmax(mx[y], dp[y][x]);
            }
        }
        rep(j, n + 1) tmp[i].clear();
    }
    print(lazy + vmax(mx));
}

