int solve(int cnt, int l1, int l2){
	if(cnt==n){
		if(l1!=-1&&l2!=-1)return (a[l1]==a[l2]&&a[l2]==a[3*n-1]);
		else return 0;
	}
	if(l1>=cnt*3)l1=-1;
	if(l2>=cnt*3)l2=-1;
	if(memo[cnt].count(ii(l1,l2))){
		return memo[cnt][ii(l1,l2)];
	}
	int ans = 0;
	//cerr<<cnt<<" "<<l1<<" "<<l2<<"\n";
	for(int x:bit){
		set<int>st;
		vi left;
		for(int i=0; i<3; i++){
			if(x>>i&1){
				st.insert(a[cnt*3+i]);
			}else{
				left.eb(cnt*3+i);
			}
		}
		bool ok = 1;
		if(x>>3&1){
			if(l1!=-1)st.insert(a[l1]);
			else ok=0;
		}else{
			left.eb(l1);
		}
		if(x>>4&1){
			if(l2!=-1)st.insert(a[l2]);
			else ok=0;
		}else{
			left.eb(l2);
		}
		if(left[0]>left.back()){
			swap(left[0],left[1]);
		}
		ans = max(ans,solve(cnt+1,left[0],left.back())+(ok&&sz(st)==1?1:0));

		//cerr<<x<<" "<<left[0]<<" "<<left.back()<<" "<<sz(st)<<" "<<ans<<"\n";
	}
	//cerr<<cnt<<" "<<l1<<" "<<l2<<" "<<ans<<"\n";

	return memo[cnt][{l1,l2}]=ans;
}

