bool cmp(int a,int b)
{
    if( second[a] < second[b] )
        return a < b;
    return first[a] < first[b];
}

void fact(int pos,int l1,int l2)
{
    if( pos == n+2 )
    {
        if( l1 == a[n] && l2 == a[n] )
            ans++;
        return;
    }

    vector <int> v;

    if( pos == 5 )
        for(int i=1;i<=5;i++)
            v.push_back(a[i]);
    else
    {
        for(int i=pos-2;i<=pos;i++)
            v.push_back(a[i]);
        v.push_back(l1);
        v.push_back(l2);
    }

    sort(v.begin(),v.end());

    for(int i=0;i<3;i++)
    {
        bool q = 1;

        for(int j=i;j<=i+2;j++)
            if( v[j] != v[i] )
                q = 0;

        if( q )
        {
            l1 = l2 = 0;

            int l = i;
            int r = i+2;

            for(int i=0;i<5;i++)
                if( i < l || i > r )
                {
                    if( l1 )
                        l2 = v[i];
                    else
                        l1 = v[i];
                }

            ans++;
            fact(pos+3,l1,l2);

            return;
        }
    }

    for(int i=0;i<5;i++)
    {
        first[v[i]] = second[v[i]] = inf;
        for(int j=pos+1;j<=n;j++)
        {
            if( v[i] == a[j] )
            {
                if( first[v[i]] != inf )
                {
                    second[v[i]] = j;
                    break;
                }
                else
                    first[v[i]] = j;
            }
        }
    }

    sort(v.begin(),v.end(),cmp);

    fact(pos+3,v[3],v[4]);
}

