struct Node{
    int i,j;
    int value;
    Node(){}
    Node(int i,int j,int value):i(i),j(j),value(value){}
    bool operator < (const Node& other)const{
        return value<other.value;
    }
};
int a[6005];
std::vector<Node>wait;

int max(int a,int b){ return a>b?a:b; }

int getExtra(int a,int b,int c){
    return a==b && a==c;
}

int isGood(int left[3]){
    if(left[0]==left[1] && left[0]==left[2]) return 1;
    else return 0;
}

int main(){
    int n;
    scanf("%d",&n);
    for(int i = 1; i <= 3*n; i++) scanf("%d",&a[i]);
    std::priority_queue<Node>Q;
    Q.push(Node(a[1],a[2],0));
    int ans = 0;
    for(int i = 3; i <= 3*n; i+=3){
        int maxn = -1, nextMaxn = -1;
        while(Q.size()!=0){
            Node u = Q.top(); Q.pop();
            if(u.value+2<maxn || u.value+1+2<nextMaxn){
                while(Q.size()!=0) Q.pop();
            }
            else{
                int x = u.i, y = u.j;
                if(i==3*n){
                    int offer = u.value;
                    if(x==y && x==a[i]) offer++;
                    ans = max(ans,offer);
                }
                else{
                    //no
                    int offer = u.value;
                    if(a[i]==a[i+1] && a[i]==a[i+2]) offer++;
                    if(offer+2>=nextMaxn){
                        nextMaxn = max(offer+2,nextMaxn);
                        wait.push_back(Node(x,y,offer));
                    }
                    //1
                    for(int j = 0; j < 3; j++){
                        int left[3] = {-1,-1,-1}; int cnt = 0;
                        for(int k = 0; k < 3; k++){
                            if(j!=k) left[cnt++] = a[i+k];
                        }
                        left[2] = x;
                        int offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait.push_back(Node(y,a[i+j],offer));
                        }
                        left[2] = y;
                        offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait.push_back(Node(x,a[i+j],offer));
                        }
                    }
                    //2
                    for(int j = 0; j < 3; j++){
                        int left[3] = {x,y,a[i+j]};
                        int used[2] = {-1,-1}; int cnt = 0;
                        for(int k = 0; k < 3; k++){
                            if(k!=j) used[cnt++] = a[i+k];
                        }
                        int offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait.push_back(Node(used[0],used[1],offer));
                        }
                    }
                }
            }
        }
        for(Node u: wait) Q.push(u);
        wait.clear();
    }
    printf("%d\n",ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int N;
    cin >> N;
    vector<int> A(3*N);
    for(int i=0; i<3*N; i++) cin >> A[i], A[i]--;

    static bitset<2000> dp[2001][2000], dp_sub[2001][2000];
    dp[0][A[0]][A[1]] = dp[0][A[1]][A[0]] = 1;
    int mx = 0, fix = 0;
    for(int i=0; i<N-1; i++){
        map<int, int> mp;
        vector<int> vs;
        for(int k=0; k<3; k++){
            int v = A[3*i+k+2];
            mp[v]++;
            vs.push_back(v);
        }
        if(mp.size() == 1){
            fix++;
            continue;
        }

        int mx2 = mx;
        for(int m=mx; m>=mx-1; m--) if(m >= 0){
            for(auto [v, num] : mp){
                if(num == 2){
                    int r = 0;
                    for(auto [v2, _] : mp) if(v != v2) r = v2;
                    for(int j=0; j<N; j++) if(dp[m][v][j]){
                        mx2 = max(mx2, m+1);
                        dp[m+1][j][r] = dp[m+1][r][j] = 1;
                    }
                }
                if(num == 1){
                    vector<int> rs;
                    for(auto& [v2, num2] : mp) if(v2 != v) for(int k=0; k<num2; k++) rs.push_back(v2);
                    int r1 = rs[0], r2 = rs[1];
                    if(dp[m][v][v]){
                        mx2 = max(mx2, m+1);
                        dp[m+1][r1][r2] = dp[m+1][r2][r1] = 1;
                    }
                }
            }
        }

        for(int m=mx; m>=mx-1; m--) if(m >= 0){
            for(int j=0; j<N; j++) dp_sub[m][j].reset();
            for(int k=0; k<3; k++){
                bitset<2000> tmp;
                for(int a=0; a<3; a++) if(a != k) tmp[vs[a]] = 1;
                dp_sub[m][vs[k]] |= tmp;
            }
            bitset<2000> tmp;
            for(int v : vs) tmp[v] = 1;
            for(int i=0; i<N; i++) dp[m][i] |= tmp | dp_sub[m][i];
        }

        mx = mx2;
    }

    cerr << fix << endl;

    int L = A.back();
    int ans = mx + fix;
    if(dp[mx][L][L]) ans++;
    cout << ans << endl;
    return 0;
}

