        {
            vp.emplace(c*N+a,max(dp[b*N+b]+1,maxi));
        }
        {
            vp.emplace(a*N+b,max(dp[c*N+c]+1,maxi));
        }
        while(vp.size()) {
            auto p = vp.top(); vp.pop();
            int s=p.first/N,t=p.first%N,u=p.second;
            chmax(dp[s*N+t],u);
            chmax(dp[t*N+s],u);
            chmax(maxi,u);
            chmax(B[s],u);
            chmax(B[t],u);
        }
    }
    int& l=A[3*N-1];
    chmax(maxi,dp[l*N+l]+1);
