			if(i+1==g[y][2]){upd(i,i+2,dp[g[y][0]][g[y][1]]+1);}
			if(i+2==g[z][2]){upd(i,i+1,dp[g[z][0]][g[z][1]]+1);}
		}
	}
//	fz(i,1,3*n) fz(j,1,i-1) cout<<j<<" "<<i<<" "<<dp[j][i]<<endl;
	int v=a[3*n],p1=g[v][0],p2=g[v][1];
	int sum=0;
	for(int t=p2/3*3+3;t<3*n;t+=3){
		sum+=(a[t]==a[t+1]&&a[t+1]==a[t+2]);
	} 
	cout<<max(mx,dp[p1][p2]+sum+1)<<endl;
	return 0;
}
