int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin >> n; n *= 3;
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }

    int s = 2;
    int ans = 0;
    num[a[0]] += 1; num[a[1]] += 1;

    while(1){
        bool f= false;
        for(int i = s; i < s + 3; i++){
            num[a[i]] += 1;
            if(num[a[i]] == 3){
                num[a[i]] = 0;
                f= true;
            }
        }

        s += 3;

        if(f){
            ans += 1;
            if(s >= n)break;    
            continue;    
        }

        // 5개중에서 2개를 남겨야 한다. 

        if(s >= n)break;

        int e = s;
