		nx[a[i]] = i;
	}

	for(int i = 0; i <= n; i++){
		for(int j = 0; j <= 3*n; j++){
			for(int k = 0; k < 4; k++){
				dp[i][j][k] = -inf;
			}
		}
	}

	dp[0][0][0] = 0;
	for(int l = 1; l <= 2; l++){
		llint x = l, y = succ[x], z = succ[y];
		if(y > 3*n || z > 3*n) continue;
		if(x/3 == y/3){
			dp[0][z][2] = 0;
		}else{
			dp[0][y][1] = 0;
		}
	}

	for(int i = 0; i < n; i++){
		llint b[3] = {a[3*(i+1)], a[3*(i+1)+1], a[3*(i+1)+2]};
		for(int j = 0; j <= 3*n; j++){
			for(int k = 0; k < 4; k++){
				bool used[3] = {0, 0, 0}; llint nj = j, nk = k, cost = 0;
				if(k == 3){
					if(b[0] == b[1]) used[0] = used[1] = true;
					if(b[1] == b[2]) used[1] = used[2] = true;
					nk = 1;
				}
				if(k == 1 || k == 3){
					for(int l = 0; l < 3; l++){
						if(used[l]) continue;
						llint x = 3*(i+1)+l, y = succ[x];
						if(j == x){
							used[l] = true, nk = 2, nj = y;
							if(y/3 == x/3){
								used[y%3] = true;
								nk = 0;
								nj = 0;
								cost++;
							}
							break;
						}
					}
				}
				if(k == 2){
					for(int l = 0; l < 3; l++){
						if(used[l]) continue;
						llint x = 3*(i+1)+l, y = succ[x];
						if(j == x){
								used[y%3] = true;
								nk = 0;
								nj = 0;
								cost++;
							break;
						}
					}
				}

				if(i < n-1){
					if(!used[0] && !used[1] && !used[2] && b[0] == b[2]){
						chmax(dp[i+1][j][k], dp[i][j][k] + 1);
						continue;
					}
					if(nk == 0){
						for(int l = 0; l < 3; l++){
							if(used[l]) continue;
							llint x = 3*(i+1)+l, y = succ[x], z = succ[y];
							if(y > 3*n || z > 3*n) continue;
							if(x/3 == y/3){
								chmax(dp[i+1][z][2], dp[i][j][k] + cost);
							}else{
								chmax(dp[i+1][y][1], dp[i][j][k] + cost);
							}
						}
						chmax(dp[i+1][0][0], dp[i][j][k] + cost);
					}
					if(nk == 1){
						if(!used[0] && !used[1] && !used[2] && b[0] == b[2]){
							chmax(dp[i+1][j][k], dp[i][j][k] + 1);
							continue;
						}
						for(int l = 0; l < 3; l++){
							if(used[l]) continue;
							llint x = 3*(i+1)+l, y = succ[x], z = succ[y];
							if(y > 3*n || z > 3*n) continue;
							if(x/3 < y/3 && y/3 == z/3 && y/3 <= j/3){
								chmax(dp[y/3-1][j][3], dp[i][j][k] + 1);
							}
						}
					}
				}
				chmax(dp[i+1][nj][nk], dp[i][j][k] + cost);

			}
		}
	}

	llint ans = 0;
	for(int i = 0; i <= 3*n; i++){
		for(int j = 0; j < 4; j++){
			ans = max(ans, dp[n][i][j]);
		}
	}
	cout << ans << endl;

	return 0;
}

