        cout << endl;
    }*/
    int ret = 0;
    for(int i = 0; i < 5; i++)
        for(int j = 0; j < i; j++) {
            int x = ((suf[tarr[i]][curr + 3] + (tarr[i] == tarr[j])) > 1 ? tarr[i] : 0);
            int y = ((suf[tarr[j]][curr + 3] + (tarr[i] == tarr[j])) > 1 ? tarr[j] : 0);
