int main() {
	int N;
	cin >> N;
	vector<int> Nums(N + 1, 3);
	map<int, int> Hands;
	int points = 0;
	for (int i = 0; i < 5; i++) {
		int A;
		cin >> A;
		Hands[A]++;
	}
	map<int, int> NextHands;
	int Rest = 3;
	if (N == 1) Rest = 0;
	if (N == 2) Rest = 1;
	for (int i = 0; i < Rest; i++) {
		int A;
		cin >> A;
		NextHands[A]++;
	}
	vector<pair<int, int>> ForSort;
	bool nh = true;
	for (auto& p : Hands) {
		if (p.second == 3) {
			points++;
			p.second = 0;
			Nums[p.first] -= 3;
		}
		if (NextHands[p.first] == 2) {
			p.second = 0;
			NextHands[p.first]++;
			nh = false;
		}
		for (int i = 0; i < p.second; i++) ForSort.push_back({ Nums[p.first],p.first });
	}
	sort(ForSort.begin(), ForSort.end(), greater<pair<int, int>>());
	NextHands[ForSort[0].second]++;
	if (nh) NextHands[ForSort[1].second]++;
	else Nums[ForSort[1].second]--;
	for (int i = 2; i < ForSort.size(); i++) Nums[ForSort[i].second]--;
	Hands = NextHands;

	for (int t = 1; t < N - 1; t++) {
		map<int, int> NextHands;
		for (int i = 0; i < (t<N-2 ? 3 : 1); i++) {
			int A;
			cin >> A;
			NextHands[A]++;
		}
		vector<pair<int, int>> ForSort;
		bool nh = true;
		for (auto& p : Hands) {
			if (p.second == 3) {
				points++;
				p.second = 0;
				Nums[p.first] -= 3;
			}
			if (NextHands[p.first] == 2) {
				p.second = 0;
				NextHands[p.first]++;
				nh = false;
			}
			for (int i = 0; i < p.second; i++) ForSort.push_back({ Nums[p.first],p.first });
		}
		sort(ForSort.begin(), ForSort.end(), greater<pair<int, int>>());
		NextHands[ForSort[0].second]++;
		if (nh) NextHands[ForSort[1].second]++;
		for (int i = 2; i < ForSort.size(); i++) Nums[ForSort[i].second]--;
		Hands = NextHands;
	}

	if (Hands.begin()->second == 3) points++;
	cout << points << endl;
	for (auto p : Hands) Nums[p.first] -= p.second;
	//for (int n : Nums) cout << n << ",";
	cout << endl;
}

