                rep(_, 2){
                    rep(j, 4){
                        for (ll k : tar){
                            if (a[i + j + 1] == k) continue;
                            if (a[i + j] == k){
                                swap(a[i + j], a[i + j + 1]);
                                break;
                            }
                        }
                    }
                }
            }
        }
        if (a[i] == a[i + 1] && a[i + 1] == a[i + 2]) ans++;
    }
    if (a[n - 3] == a[n - 2] && a[n - 2] == a[n - 1]) ans++;
    co(ans);

    return 0;
}

