		dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
		auto modify = [&](int x, int y, int z) {
			dp[x][y] = max(dp[x][y], z);
			dp[y][x] = max(dp[y][x], z);
		};
		int ans = 0, res = 0;
		for (int i = 2; i + 2 < n * 3; i += 3) {
			vector<int> b = {a[i], a[i + 1], a[i + 2]};
			sort(b.begin(), b.end());
			if (b[0] == b[2]) {
				res++;
			} else if (b[0] == b[1]) {
				for (int j = 0; j < n; j++) {
					if (j == b[2]) {
						continue;
					}
					dp[b[2]][b[2]] = max(dp[b[2]][b[2]], dp[b[2]][j]);
				}
				for (int j = 0; j < n; j++) {
					modify(j, b[2], dp[b[0]][j] + 1);
				}
			} else if (b[1] == b[2]) {
				for (int j = 0; j < n; j++) {
					if (j == b[0]) {
						continue;
					}
					dp[b[0]][b[0]] = max(dp[b[2]][b[2]], dp[b[2]][j]);
				}
				for (int j = 0; j < n; j++) {
					modify(j, b[0], dp[b[2]][j] + 1);
				}
			} else {
				modify(b[0], b[1], dp[b[2]][b[2]] + 1);
				modify(b[0], b[2], dp[b[1]][b[1]] + 1);
				modify(b[1], b[2], dp[b[0]][b[0]] + 1);
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				ans = max(ans, dp[i][j]);
			}
		}
		ans = max(ans, dp[a.back()][a.back()] + 1);
		cout << ans + res << '\n';
	}
	return 0;
}

