int main() {
	int n; R(n);
	vector<int> a(3 * n); R(a);

	reverse(all(a));
	vector<int> cnt(n + 1, 0);
	vector<int> bcnt(n + 1, 0);

	for (int j = 0; j < 2; j++) {
		++cnt[a.back()];
		++bcnt[a.back()];
		a.pop_back();
	}

	int ans = 0;
	for (int i = 0; i < n; i++) {
		map<int, int> b;

		for (int j = 0; j < (i + 1 == n ? 1 : 3); j++) {
			int now = a.back();
			b[now]++;
			a.pop_back();
			++cnt[now];
			++bcnt[now];
		}

		int cand = -1;
		int candpri = -1;

		for (auto& j : b) {
			int v = j.F;
			int app = j.S;

			if (cnt[v] >= 3) {
				bool is = 0;

				if (app >= 2) {
					is = 1;
				}
				else if (app == 1) {
					if (bcnt[v] >= 2) {
						is = 1;
					}
				}

				if (!is) continue;

				if (cand == -1) {
					cand = v;
					candpri = app;
				}
				else if (app > candpri) {
					cand = v;
					candpri = app;
				}
			}
		}

		if (cand != -1) {
			ans++;
			cnt[cand] -= 3;

			if (candpri == 2) {
				for (auto& j : bcnt)
					j = 0;

				for (auto& j : b) {
					if (j.F != cand) {
						bcnt[j.F]++;
					}
				}
			}
			else if (candpri == 1) {
				for (auto& j : cnt)
					j = 0;
				for (auto& j : bcnt)
					j = 0;

				for (auto& j : b) {
					if (j.F != cand) {
						bcnt[j.F]++;
					}
				}
			}
		}
	}

	W(ans);

	return 0;
}

