inline void umax(int &x, int y){ x = max(x, y); }

class Upd{
public:
	int x, y, v;
	Upd(int x_, int y_, int v_): x(x_), y(y_), v(v_){}
};

int n, dlt, mx, ans; 
int a[maxn * 3], cmx[maxn];
int dp[maxn][maxn];
vector<Upd> upd;

inline void p2p(int x, int y, int z){
	upd.PB(Upd(y, z, dp[x][x] + dlt + 1));
	upd.PB(Upd(y, z, mx + dlt));
	return;
}

inline void r2r(int x, int z){
	FOR(k, 0, n)
		upd.PB(Upd(k, z, dp[x][k] + dlt + 1));
	return;
}

inline void r2p(int z){
	FOR(k, 0, n)
		upd.PB(Upd(k, z, cmx[k] + dlt));
	return;
}

inline void update(Upd u){
	int x = u.x, y = u.y, v = u.v;
	int res = max(dp[x][y] + dlt, v) - dlt;
	dp[x][y] = dp[y][x] = res;
	umax(cmx[x], res);
	umax(cmx[y], res);
	umax(mx, res);
	return;
}

inline void init(){
	FOR(i, 0, 10)
		dp[a[q[i][0]]][a[q[i][1]]] = dp[a[q[i][1]]][a[q[i][0]]] = (a[p[i][0]] == a[p[i][1]] && a[p[i][1]] == a[p[i][2]]);
	FOR(i, 0, n) FOR(j, 0, n){
		umax(cmx[i], dp[i][j]);
		umax(cmx[j], dp[i][j]);
		umax(mx, dp[i][j]);
	}
	return;
}

inline void print(){
	FOR(i, 0, n){
		FOR(j, 0, n)
			printf("%d ", dp[i][j] + dlt);
		puts("");
	}
	return;
}

int main(){
	scanf("%d", &n);
	FOR(i, 0, n * 3)
		scanf("%d", a + i), --a[i];

	if(n == 1){
		printf("%d\n", a[0] == a[1] && a[1] == a[2]);
		return 0;
	}	

	mx = -0x3f3f3f3f;
	REP(i, 0, n) REP(j, 0, n)
		dp[i][j] = -0x3f3f3f3f;
	REP(i, 0, n)
		cmx[i] = -0x3f3f3f3f;
	init();

	REP(i, 1, n - 2){
//		printf("i = %d\n", i);
//		print();

		int x = a[i * 3 + 2], y = a[3 * i + 3], z = a[3 * i + 4];
		upd.clear();

		p2p(x, y, z);
		p2p(x, z, y);
		p2p(y, z, x);

		if(x == y)
			r2r(x, z);
		if(x == z)
			r2r(x, y);
		if(y == z)
			r2r(y, x);
		r2p(x);
		r2p(y);
		r2p(z);

		if(x == y && y == z)
			++dlt;
		FOR(j, 0, upd.size()){
			update(upd[j]);
		}
	}

	FOR(i, 0, n) FOR(j, 0, n){
		umax(ans, dp[i][j] + dlt + (i == j && i == a[3 * n - 1]));
	}

	printf("%d\n", ans);
	return 0;
}

