                    chmax(dp[A[j]][A[k]],(s.size()==1));
                    chmax(Max_rest[A[j]],dp[A[j]][A[k]]);
                    chmax(Max_rest[A[k]],dp[A[j]][A[k]]);
                }
            }
        } else {
            vector<int> v={A[3*i+2],A[3*i+3],A[3*i+4]};
            int SAME=0;
            if (v[0]==v[1]&&v[1]==v[2]) ++same,SAME=1;
            map<pair<int,int>,int> DP;
            auto two_same=[&](int p,int q){
                int x=v[p],rest=v[3-p-q];
                for (int j=1;j<=N;++j){
                    chmax(DP[{j,rest}],dp[x][j]+1-SAME);
                    chmax(DP[{j,rest}],dp[j][x]+1-SAME);
                }
            };
            for (int j=0;j<3;++j){
                for (int k=j+1;k<3;++k){
                    if (v[j]==v[k]){
                        two_same(j,k);
                    }
                }
            }

            auto one_same=[&](int p){
                int x=v[p];
                vector<int> rest;
                for (int j=0;j<3;++j){
                    if (p!=j) rest.emplace_back(v[j]);
                }
                chmax(DP[{rest[0],rest[1]}],dp[x][x]+1-SAME);
            };
            for (int j=0;j<3;++j) one_same(j);

            for (int j=1;j<=N;++j){
                for (int k=0;k<3;++k){
                    chmax(DP[{j,v[k]}],Max_rest[j]-SAME);
                }
            }

            for (int j=0;j<3;++j){
                for (int k=j+1;k<3;++k){
                    chmax(DP[{v[j],v[k]}],Max-SAME);
                }
            }

            for (auto p:DP){
                int x=p.first.first,y=p.first.second;
                chmax(dp[x][y],p.second);
                chmax(Max_rest[x],dp[x][y]);
                chmax(Max_rest[y],dp[x][y]);
            }
        }
        for (int j=1;j<=N;++j) chmax(Max,Max_rest[j]);
    }

    int ans=0;
    for (int i=1;i<=N;++i){
        for (int j=1;j<=N;++j){
            chmax(ans,dp[i][j]+(i==A[3*N-1]&&j==A[3*N-1]));
        }
    }
    cout << ans+same << '\n';
}

