        ans = 1+ dp(id+1, angka[0], angka[4]);
    }
    if(angka[4] == angka[3] && angka[3] == angka[2]){
        flag = 1;
        ans = 1+ dp(id+1, angka[0], angka[1]);
    }
    //cout << id << ' ' << x << " " << y << " " << flag << endl;
    if(!flag){
        FOR(i, 0, 5){
            FOR(j, i+1, 5){
                ans = max(ans, dp(id+1, angka[i], angka[j]));
            }
        }
    }
    return memo[mp(id, mp(x, y))] = ans;
}

