const int inf = 2e3+9,MX = 1e9+9;
int n,a[3*inf],dp[inf*3][inf*3],Ans,Total;
int Last[inf],Next[inf];
vector<int> Group;

//we only start in positions like 3,6,9 and we have 2 left elements
int NearestStart(int x){
    return x/3 *3;
}

int CostGroupExcept(int Left1,int Left2){

    set<int> s;
    for(auto o:Group)
        if(o != Left1 && o != Left2)
            s.insert( a[o] );
    return (s.size() == 1);
}

void Transitions(int Left1,int Left2,int Cur){
    // we have a[Left1] and a[Left2] from the last group of 3 we processed
    // and the current group is a[Cur] , a[Cur+1] , a[Cur+2]
    Group = {Left1,Left2,Cur,Cur+1,Cur+2};

    if(Cur > 3*n)
        return;

    if(Cur == 3*n)
        return void( Ans = max( Ans , dp[Left1][Left2] + CostGroupExcept(Cur+1,Cur+2) ) );

    for(int i = 0; i < 5; i++){
        for(int j=1; j < 5 ; j++){
            int NextLeft1 = Group[i];
            int NextLeft2 = Group[j];
            dp[ NextLeft1 ][ NextLeft2 ] = max( dp[ NextLeft1 ][ NextLeft2 ]
                                               , dp[Left1][Left2] + CostGroupExcept(NextLeft1,NextLeft2) );
        }
    }
}

int main(){


    scanf("%d",&n);
    for(int i=1;i<=3*n;i++)
        scanf("%d",a+i),Last[i] = 3*n + 1;

    bool Change = 1;
    while(Change){
        Change = 0;
        for(int i=3;i +2 <=3*n;i+=3){
            if(!(a[i] == a[i+1] && a[i] == a[i+2]))
                break;

                Change = 1;
                Total++;
                for(int j=i+3;j <= 3*n;j++)
                    a[j-3] = a[j];
                n--;
                break;
        }
    }
    for(int i=3*n;i>=1;i--)
        Next[ i ] = Last[ a[i] ],
        Last[ a[i] ] = i;

    for(int i=0;i<3*inf;i++)
        for(int j=0;j<3*inf;j++)
            dp[i][j] = -MX;
    dp[1][2] = 0;

    for(int i=1;i<=3*n;i++){
        for(int j=i+1;j<=3*n;j++){
            // we choose j+3 so we guarantee that NearestStart(j) < NearestStart(j+3);
            Transitions( i , j , NearestStart( j+3 ) );
            // we look for the Next occurrence a[i]
            if( NearestStart(j) < NearestStart( Next[i] ) )
                Transitions( i , j , NearestStart ( Next[i] ) );
            // we look for the Next occurrence a[j]
            if( NearestStart(j) < NearestStart( Next[j] ) )
                Transitions( i , j , NearestStart ( Next[j] ) );
        }
    }
    printf("%d\n",Ans+Total);
}

