constexpr int kN = int(2E3 + 10);

int a[kN * 3], cnt[kN], na[kN * 3];
bool one[kN];

int solve(int n) {
	int n3 = n * 3, ans = 0;
	for (int i = 1; i <= n; i++) cnt[i] = 0;
	for (int i = 1; i <= n; i++) one[i] = false;
	cnt[a[1]]++, cnt[a[2]]++;
	for (int i = 3; i < n3; i += 3) {
		sort(a + i, a + i + 3);
		if (a[i] == a[i + 2]) ans++;
		else if (a[i] == a[i + 1]) {
			if (cnt[a[i]] == 1) {
				for (int j = 1; j <= n; j++) if (cnt[j]) one[j] = true;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i + 2]]++;
				ans++;
			}
			else if (one[a[i]]) {
				for (int j = 1; j <= n; j++) one[j] = false;
				for (int j = 1; j <= n; j++) if (cnt[j]) one[j] = true;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i + 2]]++;
				ans++;
			}
			else if (cnt[a[i + 2]] == 2 || (cnt[a[i + 2]] == 1 && one[a[i + 2]])) {
				for (int j = 1; j <= n; j++) one[j] = false;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i]]++;
				cnt[a[i + 1]]++;
				ans++;
			}
			else {
				cnt[a[i]]++;
				cnt[a[i + 1]]++;
				cnt[a[i + 2]]++;
			}
		}
		else if (a[i + 1] == a[i + 2]) {
			if (cnt[a[i + 1]] == 1) {
				for (int j = 1; j <= n; j++) if (cnt[j]) one[j] = true;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i]]++;
				ans++;
			}
			else if (one[a[i + 1]]) {
				for (int j = 1; j <= n; j++) one[j] = false;
				for (int j = 1; j <= n; j++) if (cnt[j]) one[j] = true;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i]]++;
				ans++;
			}
			else if (cnt[a[i]] == 2 || (cnt[a[i]] == 1 && one[a[i]])) {
				for (int j = 1; j <= n; j++) one[j] = false;
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				cnt[a[i + 2]]++;
				cnt[a[i + 1]]++;
				ans++;
			}
			else {
				cnt[a[i]]++;
				cnt[a[i + 1]]++;
				cnt[a[i + 2]]++;
			}
		}
		else {
			if (cnt[a[i]] == 2 || cnt[a[i + 1]] == 2 || cnt[a[i + 2]] == 2) {
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				for (int j = 1; j <= n; j++) one[j] = false;
				ans++;
			}
			else if ((one[a[i]] && cnt[a[i]] == 1) || (one[a[i + 1]] && cnt[a[i + 1]] == 1) || (one[a[i + 2]] && cnt[a[i + 2]] == 1)) {
				for (int j = 1; j <= n; j++) cnt[j] = 0;
				for (int j = 1; j <= n; j++) one[j] = false;
				ans++;
			}
			cnt[a[i]]++;
			cnt[a[i + 1]]++;
			cnt[a[i + 2]]++;
		}
	}
	cnt[a[n3]]++;
	if (cnt[a[n3]] == 3 || (one[a[n3]] && cnt[a[n3]] == 2)) ans++;
	return ans;
}
