  cin.tie(nullptr);
  int n;
  cin>>n;
  vecint a(3*n);
  for(auto&&e:a){
    cin>>e;
    --e;
  }
  unordered_map<int, int> dp;
  auto idx = [&] (int x, int y) {
    return x * n + y;
  };
  auto tpl = [&] (int v) {
    return make_tuple(v / n, v % n);
  };
  dp[idx(a[0], a[1])] = 0;
  REP(i,n-1) {
    unordered_map<int, int> nxt = dp;
    for (auto&&[rem, score]: dp) {
      auto [e0, e1] = tpl(rem);
      vecint v = {e0, e1, a[3*i+2], a[3*i+3], a[3*i+4]};
      sort(ALL(v));
      int mid = v[2];
      if (count(ALL(v), mid) >= 3) {
        vecint ok;
        int cnt = 0;
        REP(j,5) {
          if (v[j] != mid) ok.push_back(v[j]);
          else {
            if (cnt >= 3) ok.push_back(v[j]);
            ++cnt;
          }
        }
        auto t = idx(ok[0], ok[1]);
        nxt[t] = max(nxt[t], score + 1);
      }
      REP(j,5)REP(k,j) {
        auto t = idx(v[k], v[j]);
        nxt[t] = max(nxt[t], score);
      }
    }
    int mx = 0;
    for(auto&&[_, score]:nxt) {
      mx = max(mx, score);
    }
    for (auto itr = begin(nxt); itr != end(nxt);) {
      if (itr->second < mx - 1) {
        itr = nxt.erase(itr);
      } else {
        ++itr;
      }
    }
    swap(dp, nxt);
  }
  int mx = 0;
  for(auto&&[rem, score]:dp) {
    auto [e0, e1] = tpl(rem);
    if (e0 == e1 && e0 == a.back()) ++score;
    mx = max(mx, score);
  }
  cout<<mx<<endl;
  return 0;
}

