int solve(){
    vector<map<int, map<int, int> > > dp;
    dp.resize(N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[1][A[0]][A[1]] = 0;
    dp[1][A[1]][A[0]] = 0;
    int dp_max = 0;
    vector<int> dp_maxk(N+1,0);
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1]){
            dp[i+1] = dp[i];
            for(auto &[p,mp]:dp[i+1]){
                for(auto &[x,c]:mp){
                    c++;
                    chmax(dp_max,c);
                    chmax(dp_maxk[x],c);
                    chmax(dp_maxk[p],c);
                }
            }
        }
        else if(A[3*i-1]==A[3*i] || A[3*i]==A[3*i+1] || A[3*i+1]==A[3*i-1]){
            int p, q;
            if(A[3*i-1]==A[3*i]){
                p = A[3*i-1];
                q = A[3*i+1];
            }
            else if(A[3*i]==A[3*i+1]){
                p = A[3*i];
                q = A[3*i-1];
            }
            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            else{
                p = 0, q = 0;
            }
            dp[i+1] = dp[i];
            chmax(dp[i+1][p][p], dp_max);
            chmax(dp[i+1][p][q], dp_max);
            chmax(dp[i+1][q][p], dp_max);
            chmax(dp_maxk[p], dp_max);
            chmax(dp_maxk[q], dp_max);

            if(dp[i].find(p)!=dp[i].end()){
                for(auto [k,c]:dp[i][p]){
                    chmax(dp[i+1][k][q], c + 1);
                    chmax(dp[i+1][q][k], c + 1);
                    chmax(dp_max, c + 1);
                    chmax(dp_maxk[k], c + 1);
                    chmax(dp_maxk[q], c + 1);
                }
            }

            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()){
                    int c = dp[i][q][q];
                    chmax(dp[i+1][p][p], c + 1);
                    chmax(dp_max, c + 1);
                    chmax(dp_maxk[p], c + 1);
                }
            }

        }
        else{
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];

            // for (int k = 1; k <= N; k++)
            // {
            //     if(dp[i].find(k)!=dp[i].end()){
            for(auto [k,mp]:dp[i]){
                chmax(dp[i+1][p][k], max(dp_maxk[k], dp_maxk[p]) );
                chmax(dp[i+1][q][k], max(dp_maxk[k], dp_maxk[q]) );
                chmax(dp[i+1][r][k], max(dp_maxk[k], dp_maxk[r]) );
                chmax(dp[i+1][k][p], max(dp_maxk[k], dp_maxk[p]) );
                chmax(dp[i+1][k][q], max(dp_maxk[k], dp_maxk[q]) );
                chmax(dp[i+1][k][r], max(dp_maxk[k], dp_maxk[r]) );
            }
            //     }
            // }

            dp[i+1] = dp[i];
            chmax(dp[i+1][p][q], dp_max);
            chmax(dp[i+1][p][r], dp_max);
            chmax(dp[i+1][q][p], dp_max);
            chmax(dp[i+1][q][r], dp_max);
            chmax(dp[i+1][r][q], dp_max);
            chmax(dp[i+1][r][p], dp_max);
            chmax(dp_maxk[p], dp_max);
            chmax(dp_maxk[q], dp_max);
            chmax(dp_maxk[r], dp_max);



            if(dp[i].find(p)!=dp[i].end()) {
                if(dp[i][p].find(p)!=dp[i][p].end()) {
                    int c = dp[i][p][p];
                    chmax(dp[i+1][q][r], c + 1);
                    chmax(dp[i+1][r][q], c + 1);
                    chmax(dp_max, c + 1);
                    chmax(dp_maxk[r], c + 1);
                    chmax(dp_maxk[q], c + 1);
                }
            }
            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()) {
                    int c = dp[i][q][q];
                    chmax(dp[i+1][p][r], c + 1);
                    chmax(dp[i+1][r][p], c + 1);
                    chmax(dp_max, c + 1);
                    chmax(dp_maxk[r], c + 1);
                    chmax(dp_maxk[p], c + 1);
                }
            }
            if(dp[i].find(r)!=dp[i].end()) {
                if(dp[i][r].find(r)!=dp[i][r].end()) {
                    int c = dp[i][r][r];
                    chmax(dp[i+1][p][q], c + 1);
                    chmax(dp[i+1][q][p], c + 1);
                    chmax(dp_max, c + 1);
                    chmax(dp_maxk[p], c + 1);
                    chmax(dp_maxk[q], c + 1);
                }
            }
        }
        dp[i].clear();
    }
    int ans = dp_max;
    int last = A[3*N-1];
    chmax(ans, dp[N][last][last] + 1);
    cout << ans << endl;
    return 0;
} 

