            chmax(dp[i+1][p][p], M);
            chmax(dp[i+1][p][q], M);
            chmax(dp[i+1][q][p], M);
            for (int k = 1; k <= N; k++)
            {
                if(dp[i].find(k)!=dp[i].end()) {
                    if(dp[i][k].find(p)!=dp[i][k].end()) {
                        chmax(dp[i+1][k][q], dp[i][k][p] + 1);
                        chmax(dp[i+1][q][k], dp[i][k][p] + 1);
                    }
                }
            }
            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()){
                    chmax(dp[i+1][p][p], dp[i][q][q] + 1);
                }
            }

        }
        else{
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];
            int M = 0;
            for(auto [x,mp]:dp[i]){
