                    chmax(dp[i+1][p][k], M);
                    chmax(dp[i+1][q][k], M);
                    chmax(dp[i+1][r][k], M);
                    chmax(dp[i+1][k][p], M);
                    chmax(dp[i+1][k][q], M);
                    chmax(dp[i+1][k][r], M);
                }
            }            

            if(dp[i].find(p)!=dp[i].end() && dp[i][p].find(p)!=dp[i][p].end()) chmax(dp[i+1][q][r], dp[i][p][p] + 1), chmax(dp[i+1][r][q], dp[i][p][p] + 1);
            if(dp[i].find(q)!=dp[i].end() && dp[i][q].find(q)!=dp[i][q].end()) chmax(dp[i+1][p][r], dp[i][q][q] + 1), chmax(dp[i+1][r][p], dp[i][q][q] + 1);
            if(dp[i].find(r)!=dp[i].end() && dp[i][r].find(r)!=dp[i][r].end()) chmax(dp[i+1][p][q], dp[i][r][r] + 1), chmax(dp[i+1][q][p], dp[i][r][r] + 1);
        }
        dp[i].clear();
    }
    int ans = 0;
