using namespace std;

int n;

long long h(int a, int b) {
  return 1ll * min(a, b) * n + max(a, b);
}

pair<int, int> uh(long long h) {
  return {h / n, h % n};
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  cin >> n;
  vector<int> a(3 * n);
  for (int i = 0; i < 3 * n; ++i) cin >> a[i], --a[i];
  unordered_map<long long, int> dp;
  dp[h(a[0], a[1])] = 0;
  vector<int> cnt(n);
  int mx = 0;
  for (int i = 2; i + 3 < 3 * n; i += 3) {
    unordered_map<long long, int> ndp;
    vector<int> p = {a[i], a[i + 1], a[i + 2]};
    for (int x : p) ++cnt[x];
    for (auto [hsh, res] : dp) {
      auto [x, y] = uh(hsh);
      ++cnt[x], ++cnt[y];
      p.push_back(x), p.push_back(y);
      for (int j = 0; j < 4; ++j) {
        for (int k = j + 1; k < 5; ++k) {
          long long hh = h(p[j], p[k]);
          int cur = res + ((k == 4 ? (j == 3 ? cnt[p[2]] : cnt[p[3]]) : cnt[p[4]]) == 3);
          if (cur + 2 > mx) {
            ndp[hh] = max(ndp[hh], cur);
            mx = max(mx, cur);
          }
        }
      }
      --cnt[x], --cnt[y];
      p.pop_back(), p.pop_back();
    }
    for (int x : p) --cnt[x];
    dp = ndp;
  }
  int ans = 0;
  for (auto [h, res] : dp) {
    ans = max(ans, res);
  }
  ans = max(ans, 1 + dp[h(a.back(), a.back())]);
  cout << ans;

  return 0;
}

