// を持っている
void solve(long long N, std::vector<long long> A) {
  std::map<pair<int, int>, int> cur;
  if (N == 1) {
    if (A[0] == A[1] && A[1] == A[2]) {
      cout << 1 << endl;
      return;
    }
    cout << 0 << endl;
    return;
  }
  rep(i, 5) rep(j, i) {
    rep(k, j) {
      int res = 0;
      if (A[i] == A[j] && A[j] == A[k])
        res = 1;
      vector<int> p;
      rep(l, 5) if (l != i && l != j && l != k) p.push_back(A[l]);
      sort(p.begin(), p.end());
      assert(p.size()==2);
      cur[{p[0], p[1]}] = res;
    }
  }
  rep(I, N - 2) {
    // 決まってる [3*i+3, 3*i+4,
    // dp [ 3*i+5, 3*i+6, 3*i+7]

    std::map<pair<int, int>, int> next;
    vector<int> can_use;
    int ma = 0;
    rep(j, 3) can_use.push_back(A[3 * I + 5 + j]);
    for (auto a : cur) {
      chmax(ma, a.second);
    }
    for (auto a : cur) {
      auto [p1, p2] = a.first;

      if (a.second + N - 1 - I < ma) {
        continue;
      }
      auto AA = can_use;
      AA.push_back(p1);
      AA.push_back(p2);
      rep(i, 5) rep(j, i) {
        rep(k, j) {
          int res = 0;
          if (AA[i] == AA[j] && AA[j] == AA[k])
            res = 1;
          vector<int> p;
          rep(l, 5) if (l != i && l != j && l != k) p.push_back(AA[l]);
          assert(p.size()==2);
          sort(p.begin(), p.end());
          next[{p[0], p[1]}] = res + a.second;
        }
      }
    }
    cur = std::move(next);
  }
  lli res = 0;
  for (auto s : cur) {
    if (A.back() == s.first.first && A.back() == s.first.second) {
      chmax(res, s.second + 1);
    } else {
      chmax(res, s.second);
    }
  }
  cout << res << endl;
}

