	int operator()(vi&a) {
		int ans=0;
		int n=a.size()/3;
		if(n<=2) return n;

		vi last(n+1);
		vi b(n*3);
		for(int i=0;i<3*n;i++)
		{
			last[a[i]]=i;
		}
		for(int i=0;i<3*n;i++)
