int main() {
	scanf("%d", &n);
	for(int i = 1; i <= 3 * n; i++) scanf("%d", &a[i]);
	for(int i = 1; i <= 3 * n; i++) {
		for(int j = 0; j <= n; j++)
			for(int o = 0; o < 2; o++) dp[i][j][o] = -kInf;
	}
	dp[3][a[1]][a[1] == a[2]] = 0;
	dp[3][a[2]][a[1] == a[2]] = 0;

	for(int i = 3; i <= 3 * n; i += 3) {
		for(int j = 1; j <= n; j++) {
			for(int o = 0; o < 2; o++) {
				if(dp[i][j][o] == -kInf) continue;
				int now = dp[i][j][o];
				//printf("dp[%d][%d][%d] = %d\n", i, j, o, now);
				int v = a[i + 0] ^ a[i + 1] ^ a[i + 2];
				if(a[i + 0] == a[i + 1] && a[i + 1] == a[i + 2]) {
					dp[i + 3][j][o] = max(dp[i + 3][j][o], now + 1);
				}
				else if(v == a[i + 0] || v == a[i + 1] || v == a[i + 2]) {

					int x;
					if(v == a[i + 0]) x = a[i + 1];
					else x = a[i + 0];
					if(x == j) {
						dp[i + 3][v][o] = max(dp[i + 3][v][o], now + 1);
					}
					else {
						dp[i + 3][x][1] = max(dp[i + 3][x][1], now);
						dp[i + 3][x][0] = max(dp[i + 3][x][0], now);
						dp[i + 3][v][0] = max(dp[i + 3][v][0], now);
						dp[i + 3][j][0] = max(dp[i + 3][j][0], now);
					}
					if(o == 1 && v == j) {
						dp[i + 3][x][1] = max(dp[i +3][x][1], now + 1);
					}
				}
				else {
					if(o == 0) {
						dp[i + 3][j][0] = max(dp[i + 3][j][0], now);
						dp[i + 3][a[i + 0]][0] = max(dp[i + 3][a[i + 0]][0], now);
						dp[i + 3][a[i + 1]][0] = max(dp[i + 3][a[i + 1]][0], now);
						dp[i + 3][a[i + 2]][0] = max(dp[i + 3][a[i + 2]][0], now);
					}
					else {
						if(a[i + 2] == j) {
							dp[i + 3][a[i + 1]][0] = max(dp[i + 3][a[i + 1]][0], now + 1);
							dp[i + 3][a[i + 2]][0] = max(dp[i + 3][a[i + 2]][0], now + 1);
						}
						else if(a[i + 1] == j) {
							dp[i + 3][a[i + 0]][0] = max(dp[i + 3][a[i + 0]][0], now + 1);
							dp[i + 3][a[i + 2]][0] = max(dp[i + 3][a[i + 2]][0], now + 1);
						}
						else if(a[i + 2] == j) {
							dp[i + 3][a[i + 0]][0] = max(dp[i + 3][a[i + 0]][0], now + 1);
							dp[i + 3][a[i + 1]][0] = max(dp[i + 3][a[i + 1]][0], now + 1);
						}
						else {
							dp[i + 3][j][1] = max(dp[i + 3][j][1], now);
							dp[i + 3][a[i + 0]][1] = max(dp[i + 3][a[i + 0]][1], now);
							dp[i + 3][a[i + 1]][1] = max(dp[i + 3][a[i + 1]][1], now);
							dp[i + 3][a[i + 2]][1] = max(dp[i + 3][a[i + 2]][1], now);
						}
					}
				}

			}
		} 
	}
	int ans = 0;
	for(int j = 1; j <= n; j++)
		for(int o = 0; o < 2; o++) ans = max(ans, dp[3 * n][j][o] + (o == 1 && j == a[3 * n]));
	printf("%d\n", ans);
	return 0;
}

