        scanf("%d",&a[i]);
    memset(maxx,-1,sizeof(maxx));
    memset(maxval,-1,sizeof(maxval));
    maxx[min(a[1],a[2])][max(a[1],a[2])]=0;
    maxval[a[1]]=maxval[a[2]]=0;
    int add=0;
    for(int i=1;i<n;i++)
    {
        memset(nxtval,-1,sizeof(nxtval));
        int u=a[i*3],v=a[i*3+1],w=a[i*3+2];
        int x=min(u,min(v,w)),y=max(min(u,max(v,w)),min(v,w)),z=max(u,max(v,w));
        if(x==y&&y==z) {add++; continue;}
        else if(x==y||y==z)
        {
            int p=y,q=x+y+z-2*p;
            x=y=p; z=q;
            for(int nxt=1;nxt<=n;nxt++)
            {
                if(nxt==p||nxt==q) continue;
                int pre=maxx[min(x,nxt)][max(x,nxt)];
                if(pre==-1) continue;
                int &now=maxx[min(z,nxt)][max(z,nxt)];
                now=max(now,pre+1);
                nxtval[z]=max(nxtval[z],now);
                nxtval[nxt]=max(nxtval[nxt],now);
            }
            int tmp=maxx[min(p,q)][max(p,q)];
            if(maxx[p][p]!=-1)
                maxx[min(p,q)][max(p,q)]=max(maxx[min(p,q)][max(p,q)],maxx[p][p]+1);
            int pre=maxx[z][z];
            if(pre!=-1)
            {
                int &now=maxx[x][y];
                now=max(now,pre+1);
                nxtval[x]=max(nxtval[x],now);
            }
            if(tmp!=-1)
                maxx[q][q]=max(maxx[q][q],tmp+1);
            nxtval[p]=max(nxtval[p],max(maxx[min(p,q)][max(p,q)],maxx[p][p]));
            nxtval[q]=max(nxtval[q],max(maxx[min(p,q)][max(p,q)],maxx[q][q]));
        }
        else
        {
            int &now1=maxx[x][y];
            if(maxx[z][z]!=-1)
            {
                now1=max(now1,maxx[z][z]+1);
                nxtval[x]=max(nxtval[x],now1);
                nxtval[y]=max(nxtval[y],now1);
            }
            int &now2=maxx[x][z];
            if(maxx[y][y]!=-1)
            {
                now2=max(now2,maxx[y][y]+1);
                nxtval[x]=max(nxtval[x],now2);
                nxtval[z]=max(nxtval[z],now2);
            }
            int &now3=maxx[y][z];
            if(maxx[x][x]!=-1)
            {
                now3=max(now3,maxx[x][x]+1);
                nxtval[y]=max(nxtval[y],now3);
                nxtval[z]=max(nxtval[z],now3);
            }
        }
        for(int nxt=1;nxt<=n;nxt++)
        {
            int &up1=maxx[min(u,nxt)][max(u,nxt)];
            up1=max(up1,maxval[nxt]);
            nxtval[u]=max(nxtval[u],up1);
            int &up2=maxx[min(v,nxt)][max(v,nxt)];
            up2=max(up2,maxval[nxt]);
            nxtval[v]=max(nxtval[v],up2);
            int &up3=maxx[min(w,nxt)][max(w,nxt)];
            up3=max(up3,maxval[nxt]);
            nxtval[w]=max(nxtval[w],up3);
        }
        maxx[min(u,v)][max(u,v)]=max(maxx[min(u,v)][max(u,v)],0);
        maxx[min(u,w)][max(u,w)]=max(maxx[min(u,w)][max(u,w)],0);
        maxx[min(w,v)][max(w,v)]=max(maxx[min(w,v)][max(w,v)],0);
        nxtval[u]=max(nxtval[u],0);
        nxtval[v]=max(nxtval[v],0);
        nxtval[w]=max(nxtval[w],0);
        for(int j=1;j<=n;j++)
            maxval[j]=max(maxval[j],nxtval[j]);
    }
    int ans=0;
    for(int i=1;i<=n;i++)
        for(int j=i;j<=n;j++)
            if(maxx[i][j]!=-1)
                ans=max(ans,maxx[i][j]+(i==a[3*n]&&j==a[3*n]));
    printf("%d\n",ans+add);
    return 0;
}
