void solve() {
    cin >> n;
    assert(n <= 300);
    vec x(3*n);
    for (int i = 0; i < 3 * n; i++) {
        cin >> x[i];
    }
    for (int i = 0; i < n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int k = 1; k <= n; k++) {
                dp[i][j][k] = -INF;
            }
        }
    }
    dp[0][x[0]][x[1]] = dp[0][x[1]][x[0]] = 0;
    int bonus = 0;
    for (int i = 0; i < n - 1; i++) {
        // time: i -> i + 1
        vec y;
        for (int j = 1; j <= n; j++) {
            for (int k = 1; k <= n; k++) {
                y.clear();
                y.pb(j); y.pb(k);
                y.pb(x[3 * i + 2]); y.pb(x[3 * i + 3]); y.pb(x[3 * i + 4]);
                sort(y.begin(), y.end());
                for (int u1 = 0; u1 < 5; u1++) {
                    for (int u2 = u1 + 1; u2 < 5; u2++) {
                        for (int u3 = u2 + 1; u3 < 5; u3++) {
                            int gain = (y[u1] == y[u2] && y[u2] == y[u3]) ? 1 : 0;
                            vec unuse;
                            for(int ii=0;ii<5;ii++){
                                if (u1 != ii && u2 != ii && u3 != ii) unuse.pb(y[ii]);
                            }
                            dp[i+1][unuse[0]][unuse[1]] = max(dp[i+1][unuse[0]][unuse[1]], dp[i][j][k] + gain);
                        }
                    }
                }
            }
        }
    }
    ll ans = 0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            int gain = 0;
            if (i == j && j == x[3*n-1]) gain = 1;
            ans = max(dp[n-1][i][j] + gain, ans);
        }
    }
    p(ans);
    return;
}

