template<class T> constexpr T INF = ::numeric_limits<T>::max()/32*15+208;
template <class T, class U>
vector<T> make_v(U size, const T& init){ return vector<T>(static_cast<size_t>(size), init); }

template<class... Ts, class U>
auto make_v(U size, Ts... rest) { return vector<decltype(make_v(rest...))>(static_cast<size_t>(size), make_v(rest...)); }

template<class T> void chmin(T &a, const T &b){ a = (a < b ? a : b); }
template<class T> void chmax(T &a, const T &b){ a = (a > b ? a : b); }
int main() {
    int n;
    cin >> n;
    vector<int> v(3*n);
    for (auto &&i : v) scanf("%d", &i), i--;
    auto dp = make_v(n, n, -1);
    stack<tuple<int, int, int>> Q;
    dp[v[0]][v[1]] = 0;
    int aans = 0, vval = 0;
    vector<int> dpp(n, -1);
    dpp[v[0]] = 0;
    dpp[v[1]] = 0;
    for (int w = 0; w < n - 1; ++w) {
        int a = v[3*w+2], b = v[3*w+3], c = v[3*w+4];
        if(a == b && b == c) aans++;
        else if(a == b){
            for (int i = 0; i < n; ++i) {
                if(dp[i][a] >= 0) Q.emplace(c, i, dp[i][a]+1);
                if(dp[a][i] >= 0) Q.emplace(c, i, dp[a][i]+1);
            }
        } else if(a == c){
            for (int i = 0; i < n; ++i) {
                if(dp[i][a] >= 0) Q.emplace(b, i, dp[i][a]+1);
                if(dp[a][i] >= 0) Q.emplace(b, i, dp[a][i]+1);
            }
        } else if(b == c){
            for (int i = 0; i < n; ++i) {
                if(dp[i][c] >= 0) Q.emplace(a, i, dp[i][c]+1);
                if(dp[c][i] >= 0) Q.emplace(a, i, dp[c][i]+1);
            }
        }
        if(dp[a][a] >= 0) Q.emplace(b, c, dp[a][a]+1);
        if(dp[b][b] >= 0) Q.emplace(a, c, dp[b][b]+1);
        if(dp[c][c] >= 0) Q.emplace(a, b, dp[c][c]+1);
        Q.emplace(a, b, vval);
        Q.emplace(a, c, vval);
        Q.emplace(b, c, vval);
        for (int i = 0; i < n; ++i) {
            if(dpp[i] >= 0){
                Q.emplace(a, i, dpp[i]);
                Q.emplace(b, i, dpp[i]);
                Q.emplace(c, i, dpp[i]);
            }
        }
        while(!Q.empty()){
            auto [p, q, r] = Q.top(); Q.pop();
            chmax(dp[p][q], r);
            chmax(dpp[p], r);
            chmax(dpp[q], r);
            chmax(vval, r);
        }
    }
    cout << max(vval, dp[v.back()][v.back()]+1)+aans << "\n";
    return 0;
}

#include <stdio.h>
#include <algorithm>
#include <vector>
using namespace std;

int N, A[6666], D[2222][2222], R[2222], M;

int main()
{
	scanf ("%d", &N);
	for (int i = 0; i < N * 3; i++) scanf ("%d", &A[i]);
	for (int i = 1; i <= N; i++){
		for (int j = 1; j <= N; j++) D[i][j] = -1e9;
		R[i] = -1e9;
	}
	M = -1e9;

	D[A[0]][A[1]] = D[A[1]][A[0]] = 0;
	R[A[0]] = R[A[1]] = M = 0;

	int base = 0;
	for (int i = 2; i + 3 < N * 3; i += 3){
		sort(A + i, A + i + 3);

		if (A[i] == A[i + 2]){ base++; continue; }

		struct inst{
			int x, y, c;
		};
		vector<inst> upd;

		int w = -1, v = -1, u = -1;
		if (A[i] == A[i + 1]) w = A[i], v = A[i + 2];
		if (A[i + 1] == A[i + 2]) w = A[i + 2], v = A[i];

		if (w != -1){
			for (int p = 1; p <= N; p++) upd.push_back({p, v, D[w][p] + 1});
			upd.push_back({ w, w, D[v][v] + 1 });
			upd.push_back({ w, w, M });
			upd.push_back({ w, v, D[w][w] + 1 });
			upd.push_back({ w, v, M });
		}
		else{
			for (int k = 0; k < 3; k++){
				if (k == 0) w = A[i + 1], v = A[i + 2];
				if (k == 1) w = A[i], v = A[i + 2];
				if (k == 2) w = A[i], v = A[i + 1];
				u = A[i + k];

				for (int p = 1; p <= N; p++) upd.push_back({p, u, R[p]});
				upd.push_back({ w, v, D[u][u] + 1 });
				upd.push_back({ w, v, M });
			}
		}

		for (auto& t : upd){
			int x = t.x, y = t.y;
			D[x][y] = max(D[x][y], t.c);
			R[x] = max(R[x], t.c);
			M = max(M, t.c);
			swap(x, y);
			D[x][y] = max(D[x][y], t.c);
			R[x] = max(R[x], t.c);
		}
	}

	int ans = max(M, D[A[3 * N - 1]][A[3 * N - 1]] + 1) + base;
	printf ("%d\n", ans);
	return 0;
}

