      t[i + n] = a[i];
    }
    for (int i = n - 1; i; --i)
      t[i] = min(t[i<<1], t[i<<1|1]);
  }
  void modify(int p, int v) {
    for (t[p += n] = v; p > 1; p >>= 1)
      t[p >> 1] = min(t[p], t[p ^ 1]);
  }
  int query(int l, int r) {
    int ret = n + 1;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) ret = min(ret, t[l++]);
      if (r&1) ret = min(ret, t[--r]);
    }
    return ret;
  }
} seg;
int main() {
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  n *= 3;
  vector<int> a(n);
  for (int &x : a) {
    cin >> x;
  }
  unordered_map<int, int> m;
  vector<int> r(n + 1, n);
  for (int i = n - 1; i >= 0; --i) {
    if (m.count(a[i])) {
      r[i] = m[a[i]];
    }
    m[a[i]] = i;
  }

  vector<int> b(n);
  for (int i = 0; i < n; ++i) {
    b[i] = r[r[i]];
    cout << b[i] << ' ';
  }
  cout << endl;
  seg.build(b);
  vector<int> dp(n + 1);
  dp[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    if (b[i] < n) {
      dp[i] = dp[b[i] + 1] + 1;
    }
    if (r[i] < n) {
      seg.modify(r[i], n);
    }
    if (b[i] < n) {
      seg.modify(b[i], n);
    }
    for (int j = i, k = 2;;++k) {
      int mi = seg.query(j + 1, b[i]);
      if (mi == j + 4) {
        dp[i] = max(dp[i], dp[max(mi, b[i]) + 1] + k);
        j = mi + 1;
      } else {
        break;
      }
    }
    if (r[i] < n) {
      seg.modify(r[i], b[r[i]]);
    }
    if (b[i] < n) {
      seg.modify(b[i], b[b[i]]);
    }
  }
  cout << dp[0] << endl;
  return 0;
}

