typedef pair<int,int> P;
P f(int a,int b){
  if(a>b)swap(a,b);
  return P(a,b);
}

int main(){
  int n;cin>>n;
  int N=n*3;
  vector<int> v(N);
  for(int i=0;i<N;i++)cin>>v[i];
  v.push_back(N);
  v.push_back(N);
  set<P> s,t;
  int now=2;
  s.insert(f(v[0],v[1]));
  int ans=0;
  for(int i=0;i<n;i++){
    if(v[now]==v[now+1]&&v[now+1]==v[now+2]){
      ans++;now+=3;
      continue;
    }
    if(v[now]==v[now+2])swap(v[now+1],v[now+2]);
    if(v[now+1]==v[now+2])swap(v[now],v[now+2]);
    bool ok=false;
    if(v[now]==v[now+1])for(P p:s)ok|=(p.first==v[now]||p.second==v[now]);
    else for(P p:s)ok|=(p.first==p.second&&(p.first==v[now]||p.first==v[now+1]||p.first==v[now+2]));
    if(ok){
      ans++;
      if(v[now]==v[now+1])
        for(P p:s)
          if(p.first==v[now])t.insert(f(p.second,v[now+2]));
          else if(p.second==v[now])t.insert(f(p.first,v[now+2]));
      else
        for(P p:s){
          if(p.first!=p.second)continue;
          if(p.first==v[now])t.insert(f(v[now+1],v[now+2]));
          if(p.first==v[now+1])t.insert(f(v[now],v[now+2]));
          if(p.first==v[now+2])t.insert(f(v[now+1],v[now]));
        }
    }
    else
      for(P p:s){
        v[now-1]=p.first;
        v[now-2]=p.second;
        for(int i=now-2;i<now+3;i++)for(int j=now-2;j<i;j++)t.insert(f(v[i],v[j]));
      }
    s.clear();
    swap(s,t);
    now+=3;
  }
  cout<<ans<<endl;
}

