		// use 1 card

		for(int q=lx;q<rx;q++){
			if(dp[arr[q]][arr[q]]!=-1e9){
				// find 3 card

				int s1 = -1,s2 = -1;
				for(int r=lx;r<rx;r++){
					if(q==r) continue;
					if(s1==-1) s1 = arr[r];
					else s2 = arr[r];
				}
				if(s1>s2) swap(s1,s2);
				v.push_back(mk(mk(s1,s2),dp[arr[q]][arr[q]] + 1 - tt));
			}
			// no gain

			for(int r=1;r<=n;r++){
				if(dp2[r]!=-1e9){
					v.push_back(mk(mk(min(r,arr[q]),max(r,arr[q])),dp2[r] - tt));
				}
			}
		}

		// use 2 card
		for(int q=lx;q<rx;q++){
			for(int r=q+1;r<rx;r++){
				if(arr[r]==arr[q]){
					int s1 = -1;
					for(int p=lx;p<rx;p++){
						if(p==q||r==p) continue;
						s1 = arr[p];
					}
					for(int p=1;p<=n;p++){
						if(dp[min(p,arr[q])][max(p,arr[q])]!=-1){
							v.push_back(mk(mk(min(p,s1),max(p,s1)),dp[min(p,arr[q])][max(p,arr[q])] + 1 - tt));
						}
					}
				}
				//v.push_back(mk(mk(min(arr[q],arr[r]),max(arr[q],arr[r])),mm - tt));
			}
		}
		for(int e=0;e<sz(v);e++){
			int f1 = v[e].x.x;
			int f2 = v[e].x.y;
			int wei = v[e].y;
			mm = max(mm,wei);
			dp2[f1] = max(dp2[f1],wei);
			dp2[f2] = max(dp2[f2],wei);
			dp[f1][f2] = max(dp[f1][f2],wei);
		}
	}
	int lastn = arr[3*n - 1];
	if(dp[lastn][lastn]!=-1e9) dp[lastn][lastn]++;
	int ans = 0;
	for(int e=1;e<=n;e++) for(int p=1;p<=n;p++) if(dp[e][p]!=-1e9){
		ans = max(ans,dp[e][p] + tt);
	}
	printf("%d",ans);
	return 0;
}

