        else if(v[0] == v[1]){
            REP(k, N){
                ls.pb(PPi(Pii(k, v[2]), dp[k][v[0]] + 1));
            }
        }else if(v[1] == v[2]){
            REP(k, N){
                ls.pb(PPi(Pii(k, v[0]), dp[k][v[1]] + 1));
            }
        }
        REP(k, 3){
            ls.pb(PPi(Pii(v[(k + 1) % 3], v[(k + 2) % 3]), dp[v[k]][v[k]] + 1));

            REP(l, N) ls.pb(PPi(Pii(l, v[k]), dpMAX[l]));
            ls.pb(PPi(Pii(v[(k + 1) % 3], v[(k + 2) % 3]), allMAX));
