            chmax(dpMAX[q.fi.fi], q.se);
            chmax(dpMAX[q.fi.se], q.se);
            chmax(allMAX, q.se);
        }
    }

    int ans = 0;
    REP(i, N) REP(j, N) chmax(ans, dp[i][j] + (i == A[3 * N - 1] && j == A[3 * N - 1]));
    ans += offset;
    Out(ans);

    return 0;
}

