std::map<PAIR, int> dp[2003];

bool same(int x, int y, int z) {
	return x == y && y == z;
}

int slow(int n, V<int> a) {
	REP(i, n) dp[i].clear();

	if (n == 1) EOUT(same(a[0], a[1], a[2]));

	VV<int> X, Y;
	REP(i, 5) FOR(j, i + 1, 5) {
		X.push_back({ i, j });
		Y.emplace_back();
		REP(k, 5) if (k != i && k != j) Y.back().emplace_back(k);
	}

	REP(k, X.size()) {
		int s = a[X[k][0]], t = a[X[k][1]];
		if (s > t) std::swap(s, t);
		dp[0][PAIR(s, t)] = same(a[Y[k][0]], a[Y[k][1]], a[Y[k][2]]);
	}

	REP(i, n - 1) for (auto pa : dp[i]) {
		PAIR p = pa.first;
		int val = pa.second;
		if (i == n - 2) {
			if (same(p.first, p.second, a[i * 3 + 5])) CHMAX(dp[i + 1][PAIR(-1, -1)], val + 1);
			else CHMAX(dp[i + 1][PAIR(-1, -1)], val);
		}
		else {
			V<int> v({ p.first, p.second, a[i * 3 + 5], a[i * 3 + 6], a[i * 3 + 7] });
			REP(k, X.size()) {
				int s = v[X[k][0]], t = v[X[k][1]];
				if (s > t) std::swap(s, t);
				CHMAX(dp[i + 1][PAIR(s, t)], val + same(v[Y[k][0]], v[Y[k][1]], v[Y[k][2]]));
			}
		}
	}

	return dp[n - 1][PAIR(-1, -1)];
}

int slow2(int n, V<int> a) {
	REP(i, n) dp[i].clear();

	if (n == 1) EOUT(same(a[0], a[1], a[2]));

	VV<int> X, Y;
	REP(i, 5) FOR(j, i + 1, 5) {
		X.push_back({ i, j });
		Y.emplace_back();
		REP(k, 5) if (k != i && k != j) Y.back().emplace_back(k);
	}

	REP(k, X.size()) {
		int s = a[X[k][0]], t = a[X[k][1]];
		if (s > t) std::swap(s, t);
		dp[0][PAIR(s, t)] = same(a[Y[k][0]], a[Y[k][1]], a[Y[k][2]]);
	}

	int ma = 0;
	REP(i, n - 1) for (auto pa : dp[i]) {
		PAIR p = pa.first;
		int val = pa.second;
		CHMAX(ma, val);
		if (val + 1 < ma) continue;
		if (i == n - 2) {
			if (same(p.first, p.second, a[i * 3 + 5])) CHMAX(dp[i + 1][PAIR(-1, -1)], val + 1);
			else CHMAX(dp[i + 1][PAIR(-1, -1)], val);
		}
		else {
			V<int> v({ p.first, p.second, a[i * 3 + 5], a[i * 3 + 6], a[i * 3 + 7] });
			REP(k, X.size()) {
				int s = v[X[k][0]], t = v[X[k][1]];
				if (s > t) std::swap(s, t);
				CHMAX(dp[i + 1][PAIR(s, t)], val + same(v[Y[k][0]], v[Y[k][1]], v[Y[k][2]]));
			}
		}
	}

	return dp[n - 1][PAIR(-1, -1)];
}

