constexpr int MINF = -10;

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;
  vector<int> A(3*n); for (auto& a:A) cin>>a;

  vector<vector<int>> dp(n+1, vector<int>(n, MINF));
  vector<int> max_arr(n+1, MINF);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      dp[i][j] = MINF;
    }
    max_arr[i] = MINF;
  }
  {
    auto a=A[0], b=A[1];
    dp[a][b] = 0;
    dp[b][a] = 0;
    max_arr[a] = max_arr[b] = 0;
  }
  int max_dp = 0;

  int skip = 0;
  for (int i = 0; i < n-1; i++) {
    auto c = A[i*3+2];
    auto d = A[i*3+3];
    auto e = A[i*3+4];
    if (c == d and d == e) {
      skip++;
      continue;
    }

    array<int, 3> cde={c, d, e};
    map<pair<int,int>, int> upm;
    int nmax_dp = max_dp;
    auto nmax_arr = max_arr;
    auto s2 = [&](int x, int y, int z) {
      if (x != y)
        return;
      for (int i = 1; i <= n; i++) {
        if (dp[i][x] == MINF and dp[x][i] == MINF)
          continue;
        auto upd = max({upm[{i,z}],  upm[{z,i}], dp[i][x]+1, dp[x][i]+1});
        nmax_dp = max(nmax_dp, upd);
        upm[{i,z}] = upd;
        upm[{z,i}] = upd;
        nmax_arr[z] = upd;
        nmax_arr[i] = upd;
      }
    };
    auto s1 = [&](int x, int y, int z) {
      if (dp[x][x] == MINF)
        return;
      auto upd = max({upm[{y,z}], dp[x][x]+1});
      nmax_dp = max(nmax_dp, upd);
      upm[{y,z}] = upd;
      nmax_arr[z] = max(nmax_arr[z], upd);
    };
    auto u2 = [&](int x, int y, int z) {
      auto upd = max(max_dp, upm[{x,y}]);
      nmax_dp = max(nmax_dp, upd);
      upm[{x,y}] = upd;
      nmax_arr[y] = max(nmax_arr[y], upd);
    };
    auto u1 = [&](int x, int y, int z) {
      for (int i = 1; i <= n; i++) {
        auto upd = max({upm[{i,x}], upm[{x,i}], max_arr[i]});
        nmax_dp = max(nmax_dp, upd);
        upm[{i,x}] = upd;
        upm[{x,i}] = upd;
        nmax_arr[x] = max(nmax_arr[x], upd);
        nmax_arr[i] = max(nmax_arr[i], upd);
      }
    };
    for (int s = 0; s < 3; s++) {
      for (int t = 0; t < 3; t++) {
        if (s == t) continue;
        for (int u = 0; u < 3; u++) {
          if (u == s or u == t) continue;
          s2(cde[s], cde[t], cde[u]);
          s1(cde[s], cde[t], cde[u]);
          u2(cde[s], cde[t], cde[u]);
          u1(cde[s], cde[t], cde[u]);
        }
      }
    }

    for (auto [k, v] : upm) {
      auto [a,b] = k;
      dp[a][b] = v;
    }
    max_arr = nmax_arr;
    max_dp = nmax_dp;
  }
  {
    auto a = A[3*n-1];
    max_dp = max(max_dp, dp[a][a]+1);
  }
  cout << max_dp + skip << endl;

  return 0;
}

