int n, a[6000];

int cnt[2001];

int solve(){
  if(n==3) return a[0]==a[1] && a[1]==a[2];

  int ret = 0, fix = 2, f[2] = {a[0],a[1]};
  cnt[a[0]]++, cnt[a[1]]++;

  auto chk = [&](int x,int sz){
    if(fix==2) return sz = (f[0]==x) + (f[1]==x);
    if(fix==1) return sz = (f[0]==x) + cnt[x];
    return sz = (cnt[x]==sz);
  };

  for(int i=2;i+2<n;i+=3){
    sort(a+i,a+i+3);
    if(a[i]==a[i+2]){
      ret++;
    }else if(a[i]==a[i+1] && chk(a[i],1)){
      ret++;
      fix = 1, f[0] = a[i];
    }else if(a[i+1]==a[i+2] && chk(a[i+1],1)){
      ret++;
      fix = 1, f[0] = a[i+1];
    }else if(chk(a[i],2)){
      ret++;
      fix = 2, f[0] = a[i+1], f[1] = a[i+2];
      for(int i=1;i<=n/3;++i) cnt[i] = 0; 
    }else if(chk(a[i+1],2)){
      ret++;
      fix = 2, f[0] = a[i], f[1] = a[i+2];
      for(int i=1;i<=n/3;++i) cnt[i] = 0; 
    }else if(chk(a[i+2],2)){
      ret++;
      fix = 2, f[0] = a[i], f[1] = a[i+1];
      for(int i=1;i<=n/3;++i) cnt[i] = 0; 
    }else{
      cnt[a[i]]++, cnt[a[i+1]]++, cnt[a[i+2]]++;
    }
  }
  if(chk(a[n-1],2)) ret++;
  return ret;
}

