        for(int k=0;k<5;k++) if(k!=i && k!=j) rest.push_back(tmp[k]);
        int earn = rest[0] == rest[1] && rest[0] == rest[2];
        earn += solve(idx+3, tmp[i], tmp[j]);
        res = max(earn, res);
    }
    return dp[idx][last1][last2] = res;
}

