#include <bits/stdc++.h>
using namespace std;

void solve(int N, vector<int> A)
{
    vector<int> rest(N + 1);
    rest.at(A.at(0))++;
    rest.at(A.at(1))++;

    int res = 0;
    for (int l = 0; l < N - 1; l++)
    {
        int i = l * 3 + 2, j = l * 3 + 3, k = l * 3 + 4;

        if (A.at(i) == A.at(j) && A.at(j) == A.at(k))
        {
            res++;
            continue;
        }

        if (A.at(i) == A.at(k))
            swap(A.at(j), A.at(k));
        if (A.at(j) == A.at(k))
            swap(A.at(i), A.at(k));
        if (A.at(i) == A.at(j))
        {
            int a = A.at(i);
            if (rest.at(a) > 0)
            {
                res++;
                rest.at(a)--;
                for (int n = 1; n <= N; n++)
                {
                    if (rest.at(n) > 0)
                        rest.at(n) = 1;
                }
                rest.at(A.at(k))++;
                continue;
            }
        }

        if (rest.at(A.at(i)) >= 2)
        {
            res++;
            for (int n = 1; n <= N; n++)
                rest.at(n) = 0;
            rest.at(A.at(j))++;
            rest.at(A.at(k))++;
        }
        else if (rest.at(A.at(j)) >= 2)
        {
            res++;
            for (int n = 1; n <= N; n++)
                rest.at(n) = 0;
            rest.at(A.at(i))++;
            rest.at(A.at(k))++;
        }
        else if (rest.at(A.at(i)) >= 2)
        {
            res++;
            for (int n = 1; n <= N; n++)
                rest.at(n) = 0;
            rest.at(A.at(i))++;
            rest.at(A.at(j))++;
        }
        else
        {
            rest.at(A.at(i))++;
            rest.at(A.at(j))++;
            rest.at(A.at(k))++;
        }
    }

    if (rest.at(A.at(3 * N - 1)) >= 2)
        res++;

    cout << res << endl;
}

int main()
{
    int N;
    cin >> N;
    vector<int> A(3 * N);
    for (int i = 0; i < 3 * N; i++)
    {
        cin >> A.at(i);
    }
    solve(N, move(A));
    return 0;
}

