map <int, int> SSS;
multiset <int> S[2010];

int Query() {
	return (--SSS.end())->fi;
}

int query(int x) {
	return *(--S[x].end());
}

void modify(int x, int y) {
	if (dp[x][y] == ndp[x][y]) return ;
	S[x].erase(S[x].find(dp[x][y]));
	S[x].insert(ndp[x][y]);
	if ((--SSS[dp[x][y]]) == 0) SSS.erase(dp[x][y]);
	SSS[ndp[x][y]]++;
	dp[x][y] = ndp[x][y];
}

bool check(int a, int b, int c) {
	return a == b && b == c;
}

int main () {
	int n; scanf("%d", &n);
	for (int i = 0; i < 3 * n; i++) {
		scanf("%d", &a[i]);
		a[i]--;
	}
