int solve(int pos, vector<int> v){
	int sz = v.size();
	if(sz == 3){
		if(v[0] == v[1] && v[1] == v[2])
			return 1;
		return 0;
	}

	if(dp[pos].count(v))
		return dp[pos][v];

	int ans = 0;
	for(int i = 0; i < sz; i++){
		for(int j = i + 1; j < sz; j++){
			for(int k = j + 1; k < sz; k++){
				int add = 0;
				if(v[i] == v[j] && v[j] == v[k])
					add = 1;

				vector<int> w;
				for(int l = 0; l < sz; l++)
					if(l != i && l != j && l != k)
						w.emplace_back(v[l]);

				for(int l = pos + 1; l <= min(n, pos + 3); l++)
					w.emplace_back(a[l]);

				sort(w.begin(), w.end());
				ans = max(ans, add + solve(min(n, pos + 3), w));
			}
		}
	}

	return dp[pos][v] = ans;
}

