int main()
{
    ll N;
    cin >> N;
    vec A(3 * N);
    cin >> A;

    deque<ll> deq(ALL(A));

    map<P, ll> mp;

    rep(i, 5) rep(j, 5) if(i < j){
        set<ll> st;
        rep(k, 5) if(i != k and j != k) st.insert(A[k]);
        if(len(st) == 1) mp[{A[i], A[j]}] = 1;
        else mp[{A[i], A[j]}] = 0;
    }

    rep(_, 5) deq.pop_front();

    rep(i, N - 2) {
        map<ll, ll> tmp;
        set<ll> tp;
        rep(_, 3) ++tmp[deq.front()], tp.insert(deq.front()), deq.pop_front();
        if(len(tmp) == 1){
            for(auto& [key, val] : mp) ++val;
            continue;
        }

        map<P, ll> next;
        for(auto [key, val] : mp){
            auto [x, y] = key;
            if(tmp[x] >= 2){
                for(auto t : tp) if(t != x) next[{y, t}] = val + 1;
            }
            else if(tmp[y] >= 2){
                for(auto t : tp) if(t != y) next[{x, y}] = val + 1;
            }
            else for(auto t : tp) next[{x, t}] = val, next[{y, t}] = val, next[{x, y}] = val;
        }
        mp = next;
    }

    ll ans = 0;
    for(auto [key, val] : mp){
        if(key.first == deq.front() and key.second == deq.front()) ++val;
        chmax(ans, val);
    }
    print(ans);

    return 0;
}

