void solve()
{
    int n;
    cin>>n;
    vi v(3*n);
    rep(i,3*n)
        cin>>v[i];
    int ans=0;
    set<pair<pii, int>> s1, s2;
    {
        int x1=v[0], x2=v[1];
        if(x1>x2)
            swap(x1,x2);
        s1.insert(mp(mp(x1,x2),0));
    }
    repu(i,1,n-1)
    {
        for(auto k=s1.begin();k!=s1.end();k++)
        {
            vi vv(5);
            vv[1]=k->fi.fi;
            vv[0]=k->fi.se;
            vv[2]=v[3*i-1];
            vv[3]=v[3*i];
            vv[4]=v[3*i+1];
            int cnt=3;
            while(cnt<32)
            {
                int x=-1, f=1, x1=-1, x2=-1;
                rep(j,5)
                {
                    if((cnt&(1<<j)))
                    {
                        if(x1==-1)
                            x1=vv[j];
                        else
                            x2=vv[j];
                    }
                    else
                    {
                        if(x==-1)
                            x=vv[j];
                        else
                        {
                            if(x==vv[j]);
                            else
                            {
                                f=0;
                            }
                        }
                    }
                }
                int ans1=0;
                if(f==1)
                {
                    ans1=1;
                }
                ans1+=k->se;
                if(x2<x1)
                    swap(x1,x2);
                auto aa=s2.lower_bound(mp(mp(x1,x2), 0));
                if(aa!=s2.end() && aa->fi==mp(x1,x2))
                {
                    ans1=max(ans1,aa->se);
                    s2.erase(aa);
                    s2.insert(mp(mp(x1,x2),ans1));
                }
                else
                {
                    s2.insert(mp(mp(x1,x2),ans1));
                }
                cnt+=(cnt&(-cnt));
                if(__builtin_popcount(cnt)==1)
                    cnt+=1;
            }
        }
        s1.clear();
        for(auto k=s2.begin();k!=s2.end();k++)
        {
            s1.insert((*k));
        }
        s2.clear();
    }
    for(auto i=s1.begin(); i!=s1.end();i++)
    {
        if(i->fi.fi==i->fi.se && i->fi.fi==v[3*n-1])
            ans=max(ans,i->se+1);
        else
            ans=max(ans,i->se);
    }
    cout<<ans<<endl;
}

