int N, A[101010];
int memo[2020][2020];

void solve() {
    //vector<vi> memo(N, vi(N, -INF));
    Fill(memo, -INF);
    vi MAX(N, -INF);
    memo[A[0]][A[1]] = 0;
    memo[A[1]][A[0]] = 0;
    chmax(MAX[0], 0ll);
    chmax(MAX[1], 0ll);
    int SUM_ALL = 0;
    int ans = 0;
    for (int k = 0; k < N; k++) {
        vector<pair<pair<int, int>, int>> update;
        update.reserve(N * 10);
        if (k != N - 1) {
            int x = k * 3 + 2;  //A[x],A[x+1],A[x+2]
            if (A[x] == A[x + 1] && A[x + 1] == A[x + 2]) {
                SUM_ALL++;
                continue;
            }
            int MAX_ALL = 0;
            for (int i = 0; i < N; i++) {
                chmax(MAX_ALL, MAX[i]);
            }
            update.emplace_back(make_pair(A[x], A[x + 1]), MAX_ALL);
            update.emplace_back(make_pair(A[x], A[x + 2]), MAX_ALL);
            update.emplace_back(make_pair(A[x + 1], A[x + 2]), MAX_ALL);
            for (int i = 0; i < N; i++) {
                update.emplace_back(make_pair(A[x], i), MAX[i]);
                update.emplace_back(make_pair(A[x + 1], i), MAX[i]);
                update.emplace_back(make_pair(A[x + 2], i), MAX[i]);
            }
            for (int i = 0; i < 3; i++) {
                update.emplace_back(make_pair(A[x + ((i + 1) % 3)], A[x + ((i + 2)) % 3]), memo[A[x]][A[x]] + 1);
                if (A[x + ((i + 1) % 3)] == A[x + ((i + 2) % 3)]) {
                    int a = A[x + ((i + 1) % 3)];
                    for (int j = 0; j < N; j++) {
                        update.emplace_back(make_pair(j, A[x]), memo[a][j] + 1);
                    }
                }
            }
            for (auto& p : update) {
                int a = p.first.first, b = p.first.second, scr = p.second;
                chmax(memo[a][b], scr);
                chmax(memo[b][a], scr);
                chmax(MAX[a], scr);
                chmax(MAX[b], scr);
            }
        } else {
            int x = k * 3 + 2;  //A[x]
            for (int i = 0; i < N; i++) {
                chmax(ans, MAX[i]);
            }
            chmax(ans, memo[A[x]][A[x]] + 1);
        }
    }
    cout << ans + SUM_ALL << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> N;
    for (int i = 0; i < N * 3; i++) {
        cin >> A[i];
        A[i]--;
    }

    solve();
    return 0;
}

