			res++;
			continue;
		}
		for (int i : vec)
			del[i] = 0;
		vec.clear();
		k = -1;
		for (int i = 1; i <= 3 * n; i++) {
			if (!del[i] && a[i] == col)
				vec.pb(i);
			lft[i] += SZ(vec);
			if (SZ(vec) == 3) {
				int x = vec.back();
				for (int j = x; j <= 3 * n; j++)
					has[j]--;
				k = i;
				break;
			}
		}
		for (int i = k + 1; i <= 3 * n; i++)
			lft[i] += 3;
		pop();
	}
	cout << res;
}

