        for(int j=0;j<N;j++){
          if(dp[min(tar,j)][max(tar,j)]==ma){
            chmax(dp[min(j,A[now])][max(j,A[now])],ma+1);
          }
        }
      }
      if(val!=-INF) chmax(dp[tar][tar],val+1);
      for(int j=now;j<=now+2;j++){
        for(int m=0;m<j;m++){
          chmax(dp[min(A[j],A[m])][max(A[j],A[m])],0);
