		dp[two2one(a[0], a[1])]=0;
		vi w(5);
		for(int i=0;i<n-1;i++)
		{
			map<int,int> ndp;
			int x=i*3+2;

			for(auto&m:dp)
			{
				tie(w[0], w[1])=one2two(m.first);
				copy(a.begin()+x, a.begin()+x+3, w.begin()+2);
//dump(w, m.second);
				int r=is_3card(w);
				if(r>0)
				{
					ndp[r]=m.second+1;
					continue;
				}

				for(int j=0;j<5;j++)
				{
					for(int k=j+1;k<5;k++)
					{
						ndp[two2one(w[j], w[k])]=m.second;
					}
				}
			}
			dp.swap(ndp);
		}

		int ans=0;
		for(auto&m:dp)
		{
			max_u(ans, m.second);
		}
		max_u(ans, dp[two2one(a.back(), a.back())]+1);

		return ans+ans_add;
	}
};

