template<typename T>
struct lazysegtree{
	using F=function<T(T,T)>;
	using G=function<T(T,T,int,int)>;
	const F calcfn,lazycalcfn;
	const G updatefn;
	int n;
	T defvalue,lazydefvalue;
	vector<T>dat,lazy;
	vector<bool>lazyflag;
	lazysegtree(int n_=0,T defvalue_=0,
		const F calcfn_=[](T a,T b){return a<b?b:a;},
		const F lazycalcfn_=[](T a,T b){return a+b;},
		const G updatefn_=[](T a,T b,int l,int r){return a+b;},
		T lazydefvalue_=0
	):defvalue(defvalue_),lazydefvalue(lazydefvalue_),
		calcfn(calcfn_),lazycalcfn(lazycalcfn_),updatefn(updatefn_)
	{
		n=1;
		while(n<n_)n<<=1;
		dat.assign(2*n-1,defvalue);
		lazy.assign(2*n-1,lazydefvalue);
		lazyflag.assign(2*n-1,false);
	}
	void copy(const vector<T>&v)
	{
		for(int i=0;i<v.size();i++)dat[i+n-1]=v[i];
		for(int i=n-2;i>=0;i--)dat[i]=calcfn(dat[2*i+1],dat[2*i+2]);
	}
	void eval(int i,int l,int r)
	{
		if(lazyflag[i])
		{
			dat[i]=updatefn(dat[i],lazy[i],l,r);
			if(r-l>1)
			{
				lazy[2*i+1]=lazycalcfn(lazy[2*i+1],lazy[i]);
				lazy[2*i+2]=lazycalcfn(lazy[2*i+2],lazy[i]);
				lazyflag[2*i+1]=lazyflag[2*i+2]=true;
			}
			lazy[i]=lazydefvalue;
			lazyflag[i]=false;
		}
	}
	void update(int a,int b,T x,int k=0,int l=0,int r=-1)//[a,b)
	{
		if(r<0)r=n;
		eval(k,l,r);
		if(b<=l||r<=a)return;
		else if(a<=l&&r<=b)
		{
			lazy[k]=lazycalcfn(lazy[k],x);
			lazyflag[k]=true;
			eval(k,l,r);
		}
		else
		{
			update(a,b,x,2*k+1,l,(l+r)/2);
			update(a,b,x,2*k+2,(l+r)/2,r);
			dat[k]=calcfn(dat[2*k+1],dat[2*k+2]);
		}
	}
	T query(int a,int b,int k=0,int l=0,int r=-1)//[a,b)
	{
		if(r<0)r=n;
		eval(k,l,r);
		if(b<=l||r<=a)return defvalue;
		else if(a<=l&&r<=b)return dat[k];
		else return calcfn(
			query(a,b,2*k+1,l,(l+r)/2),
			query(a,b,2*k+2,(l+r)/2,r)
		);
	}
};
int N;
int A[6060];
vector<pair<int,int> >ONE[2020];
int ans;
main()
{
	cin>>N;
	for(int i=0;i<3*N;i++)cin>>A[i];
	lazysegtree<int>P(N);
	vector<stack<int> >ids(N+1);
	ids[A[0]].push(0);
	ids[A[1]].push(1);
	for(int i=1;i<N;i++)
	{
		int x=i*3-1,y=i*3,z=i*3+1;
		bool xy=A[x]==A[y],yz=A[y]==A[z],zx=A[z]==A[x];
		if(xy&&yz)
		{
			ans++;
			A[x]=A[y]=A[z]=0;
		}
		else if(xy&&!ids[A[x]].empty()&&P.query((ids[A[x]].top()+1)/3,i)<=1)
		{
			int id=ids[A[x]].top();ids[A[x]].pop();
			ans++;
			P.update((id+1)/3,i,1);
			ids[A[z]].push(z);
			ONE[A[x]].push_back(make_pair((id+1)/3,i));
			A[x]=A[y]=A[id]=0;
		}
		else if(yz&&!ids[A[y]].empty()&&P.query((ids[A[y]].top()+1)/3,i)<=1)
		{
			int id=ids[A[y]].top();ids[A[y]].pop();
			ans++;
			P.update((id+1)/3,i,1);
			ids[A[x]].push(x);
			ONE[A[y]].push_back(make_pair((id+1)/3,i));
			A[y]=A[z]=A[id]=0;
		}
		else if(zx&&!ids[A[z]].empty()&&P.query((ids[A[z]].top()+1)/3,i)<=1)
		{
			int id=ids[A[z]].top();ids[A[z]].pop();
			ans++;
			P.update((id+1)/3,i,1);
			ids[A[y]].push(y);
			ONE[A[z]].push_back(make_pair((id+1)/3,i));
			A[z]=A[x]=A[id]=0;
		}
		else
		{
			ids[A[x]].push(x);
			ids[A[y]].push(y);
			ids[A[z]].push(z);
		}
	}
	while(true)
	{
		bool now=false;
		for(int i=1;i<=N;i++)while(!ids[i].empty())ids[i].pop();
		for(int fst=0;fst<2;fst++)if(A[fst]!=0)ids[A[fst]].push(fst);
		for(int i=1;i<=N;i++)
		{
			for(int di=-1;di<=(i==N?-1:1);di++)
			{
				int z=i*3+di;
				if(A[z]==0)continue;
				if(ids[A[z]].size()<2)continue;
				int y=ids[A[z]].top();ids[A[z]].pop();
				int x=ids[A[z]].top();ids[A[z]].pop();
				if(P.query((x+1)/3,(y+1)/3)>1)
				{
					ids[A[z]].push(x);
					ids[A[z]].push(y);
					continue;
				}
				vector<pair<int,int> >tmp1,tmp2;
				for(pair<int,int>p:ONE[A[z]])
				{
					if((y+1)/3<=p.first&&p.second<=i)
					{
						tmp2.push_back(p);
					}
					else
					{
						tmp1.push_back(p);
					}
				}
				int q=(y+1)/3;
				bool ok=true;
				for(pair<int,int>p:tmp2)
				{
					if(P.query(q,p.first)>0)
					{
						ok=false;
						break;
					}
					q=p.second;
				}
				if(P.query(q,i)>0)
				{
					ok=false;
				}
				if(!ok)
				{
					ids[A[z]].push(x);
					ids[A[z]].push(y);
					continue;
				}
				ans++;
				now=true;
				ONE[A[z]]=tmp1;
				P.update((x+1)/3,(y+1)/3,1);
				q=(y+1)/3;
				for(pair<int,int>p:tmp2)
				{
					P.update(q,p.first,2);
					P.update(p.first,p.second,-1);
					q=p.second;
				}
				P.update(q,i,2);
				A[x]=A[y]=A[z]=0;
				break;
			}
			for(int di=-1;di<=1;di++)
			{
				if(A[i*3+di]!=0)ids[A[i*3+di]].push(i*3+di);
			}
		}
		if(!now)break;
	}
	cout<<ans<<endl;
}

