using namespace std;

class FenwickTree {
    public:
        FenwickTree(int n) : N(n), data(n, 0) {

        }

        void put(int x ,int v) {
            for (; x < N; x |= x + 1) {
                data[x] += v;
            }
        }

        int get(int x) {
            int res = 0;
            for (; x >= 0; x = (x & (x + 1)) - 1) {
                res += data[x];
            }
            return res;
        }

    private:
        int N;
        vector<int> data;
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(12);

    int n;
    cin >> n;
    vector<int> A(3 * n, 0);
    for (int i = 0; i < 3 * n; ++i) {
        cin >> A[i];
        --A[i];
    }


    vector<vector<int>> pos(n + 1);
    for (int i = 0; i < A.size(); ++i) {
        pos[A[i]].push_back(i);
    }
    pos[n].push_back(3 * n);
    pos[n].push_back(3 * n + 1);

    int res = 0;
    vector<int> indices(n, 0);
    const int INF = 1 << 20;

    FenwickTree ft(3 * n + 123);
    int mx = 3 * n - 1;

    vector<int> V(3, -1);


    auto ok = [&](int x, vector<int>& X) {
        if (x < X[0]) {
            if ((X[1] + 1) / 3 == (X[2] + 1) / 3) {
                return true;
            } else {
                return false;
            }
        } else if (x < X[1]) {
            if ((X[1] + 1) / 3 == (X[2] + 1) / 3) {
                return true;
            } else {
                return false;
            }
        } else if (x < X[2]) {
            if ((x + 1) / 3 == (X[2] + 1) / 3) {
                return true;
            }
            return false;
        }
        return true;
    };

    while (true) {
        pair<int,int> best(INF, n);
        for (int i = 0; i < n; ++i) {
            if (indices[i] + 3 <= pos[i].size()) {
                best = min(best, make_pair(pos[i][indices[i] + 3 - 1], i));
            }
        }

        // cout << best.first << " " << best.second << endl;
        if (best.first >= 3 * n) {
            break;
        }
        ++res;

        int v = best.second;
        for (int i = 0; i < 3; ++i) {
            int x = pos[v][indices[v]++];
            // ft.put(mx - 1 - x, 1);
            V[i] = x;
        }


        for (int i = 0; i < n; ++i) {
            while (indices[i] < pos[i].size()) {
                int x = pos[i][indices[i]];
                if (!ok(x, V)) {
                    ++indices[i];
                } else {
                    break;
                }
            }

            for (int _ = 0; _ < 2; ++_) {
                if (indices[i] + 2 <= pos[i].size()) {
                    int x = pos[i][indices[i]];
                    int y = pos[i][indices[i] + 1];
                    if (ok(x, V) && ok(y, V) && (y + 1) / 3 <= (V[2] + 1) / 3) {
                        if ((y + 1) / 3 != (V[2] + 1) / 3) {
                            if ((V[0] + 1) / 3 != (V[2] + 1) / 3) {
                                ++indices[i];
                            }
                        }
                    }
                }
            }
        }
    }


    cout << res << '\n';

    return 0;
}

