bool iseq(int* a, int i, int j){
    int s = -1;
    for(int k = 0; k < 5; ++k)
        if(i != k && j != k){
            if(s == -1)
                s = a[k];
            else if(s != a[k])
                return false;
        }
    return true;
}

int myhash(int i, int j){
    if(i != j && cnt[i] <= 1 && cnt[j] <= 1)
        return 0;
    if(i == j && cnt[i] == 0)
        return 0;
    if(i <= j)
        return i * 4000 + j;
    else
        return j * 4000 + i;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    unordered_map<int, int> map[2];
    for(int i = 0; i < 3 * n; ++i){
        cin >> a[i];
        ++cnt[a[i]];
    }
    for(int i = 1; i <= n; ++i)
        for(int j = 1; j <= n; ++j)
            f[1][i][j] = -1;
    for(int i = 0; i < 5; ++i)
        --cnt[a[i]];
    for(int i = 0; i < 5; ++i)
        for(int j = i + 1; j < 5; ++j){
            bool eq = iseq(a, i, j);
            if(eq)
                map[1][myhash(a[i], a[j])] = 1;
            else
                map[1][myhash(a[i], a[j])] = max(0, map[1][myhash(a[i], a[j])]);
        }
    int k = 0;
    int b[5];
    for(int s = 5; s < 3 * n - 1; s += 3){
        map[k].clear();
        for(int k = 0; k < 3; ++k){
            b[k] = a[s + k];
            --cnt[a[s + k]];
        }
        for(auto it = map[1-k].begin(); it != map[1-k].end(); ++it){
            b[3] = it->first / 4000;
            b[4] = it->first % 4000;
            for(int i = 0; i < 5; ++i)
                for(int j = i + 1; j < 5; ++j){
                    bool eq = iseq(b, i, j);
                    if(eq){
                        if(map[k].find(myhash(b[i], b[j])) != map[k].end()){
                            map[k][myhash(b[i], b[j])] = max(map[k][myhash(b[i], b[j])], it->second + 1);
                        }else{
                            map[k][myhash(b[i], b[j])] = it->second + 1;
                        }
                    }else{
                        if(map[k].find(myhash(b[i], b[j])) != map[k].end()){
                            map[k][myhash(b[i], b[j])] = max(map[k][myhash(b[i], b[j])], it->second);
                        }else{
                            map[k][myhash(b[i], b[j])] = it->second;
                        }
                    }
                }
        }
        k = 1 - k;
    }

    int ans = 0;
    for(auto it = map[1-k].begin(); it != map[1-k].end(); ++it){
        int x = it->first / 4000;
        int y = it->first % 4000;
        if(x == y && x == a[3 * n - 1] && ans < it->second + 1)
            ans = it->second + 1;
        else if(ans < it->second)
            ans = it->second;
    }
    cout << ans << "\n";
    return 0;
}

