    // FOR(i,1,N)FOR(j,i,N) cout<<"dp("<<i<<","<<j<<") = "<<dp[i][j]<<endl;
    // FOR(i,1,N) cout<<"max("<<i<<") = "<<maxi[i]<<endl;
    // cout<<"--------------"<<endl;
    rep(i,N-1){
        int *v = &a[i*3];
        if (v[0]==v[1] && v[1]==v[2]){
            extra++;
            continue;
        }
        sort(v,v+3);
        bool aab = (v[0]==v[1]);
        bool abb = (v[1]==v[2]);
        int vsum=v[0]+v[1]+v[2];
        // cout<<"input: "<<v[0]<<" "<<v[1]<<" "<<v[2]<<endl;
        queue<P> que;
        rep(j,3)FOR(k,1,N){
            int value = maxi[k];
            if (aab && j==2){
                int s = min(k,v[0]);
                int t = max(k,v[0]);
                chmax(value,dp[s][t]+1);
            }
            if (abb && j==0){
                int s = min(k,v[2]);
                int t = max(k,v[2]);
                chmax(value,dp[s][t]+1);
            }
            rep(x,3)FOR(y,x+1,2){
                if ((v[x]==k&&y==j) || (x==j&&v[y]==k)){
                    int z = vsum-v[x]-v[y];
                    chmax(value,max(dp[z][z]+1,Max));
                }
            }
            que.push({v[j],k,value});
        }
        while(!que.empty()){
            int s,t,score;
            tie(s,t,score) = que.front(); que.pop();
            if (s>t) swap(s,t);
            chmax(dp[s][t],score);
            chmax(Max,dp[s][t]);
            chmax(maxi[s],dp[s][t]);
            chmax(maxi[t],dp[s][t]);
        }
        // FOR(i,1,N)FOR(j,i,N) cout<<"dp("<<i<<","<<j<<") = "<<dp[i][j]<<endl;
        // FOR(i,1,N) cout<<"max("<<i<<") = "<<maxi[i]<<endl;
        // cout<<"--------------"<<endl;
    }
    int ans=0;
    rep(i,N+1)rep(j,N+1){
        chmax(ans,dp[i][j]+(i==j&&j==z));
    }
    ans+=extra;
    cout<<ans<<endl;
    return 0;
}

