	for(int i=a.size()-1;i>s+2;i--)
	{
		if(a[i]==a[s+0]) a[i]|=a_invalid;
		if(a[i]==a[s+1]) a[i]|=a_invalid;
		if(a[i]==a[s+2]) a[i]|=a_invalid;
	}
	return false;
}


struct solve
{
	solve(){}
	int operator()(vi&a) {
		int ans=0;
		int n=a.size()/3;
		if(n<=2) return n;

		vi last(n+1);
		vi b(n*3);
		for(int i=0;i<3*n;i++)
		{
			last[a[i]]=i;
		}
		for(int i=0;i<3*n;i++)
		{
			b[i]=last[a[i]];
		}
//dump(b);
		for(int i=0;i<n-1;i++)
		{
			if(check(b, i*3)) ans++;
		}
		int x=(n-1)*3;
		if(b[x]==b[x+1] && b[x]==b[x+2]) ans++;
//dump(b);

		return ans;
	}
};

