                cnt1[z]++,cnt2[x]++;
                continue;
            }
            if(cnt1[z] >= 2) {
                ans++;
                cnt1 = cnt3;
                cnt2 = cnt3;
                cnt1[x]++,cnt2[y]++;
                continue;
            }
        }
        {
            cnt1[x]++,cnt1[y]++,cnt3[z]++;
        }
    }
    int last = A[3*N-1];
    if((cnt1[last] >= 1 && cnt2[last] >= 1) || cnt1[last] >= 2) {
        ans++;
    }
    cout << ans << endl;
    return 0;
}

