        cin >> A[i];
        A[i]--;
    }
    memset(sdp, -1, sizeof(sdp));
    memset(fdp, -1, sizeof(fdp));
    memset(f2dp, -1, sizeof(f2dp));
    memset(dp, -1, sizeof(dp));
    memset(dpM, -1, sizeof(dpM));
    memset(dpR, -1, sizeof(dpR));
    cout << solve(0, 1) << endl;
}

