map<i64, i64> met;


void upd2(i64 dup, i64 left) {
    if (!met.count(dup)) {
        return;
    }

    for (auto t : met) {
        i64 card = t.first;
        i64 val = dp[dup][card];
        ndp[left][card] = max(ndp[left][card], val + 1);
        ndp[card][left] = max(ndp[card][left], val + 1);
    }
}

void upd1(i64 main, i64 left1, i64 left2) {
    if (!met.count(main) || met[main] < 2) {
        return;
    }

    i64 val = dp[main][main];
    ndp[left1][left2] = max(ndp[left1][left2], val + 1);
    ndp[left2][left1] = max(ndp[left2][left1], val + 1);
}

