        }

        if (q[0] == q[1]) {
            upd2(q[0], q[2]);
        }
        if (q[1] == q[2]) {
            upd2(q[2], q[0]);
        }

        upd1(q[0], q[1], q[2]);
        upd1(q[1], q[0], q[2]);
