		{
			if (CNT[j] == 3)
			{
				ti = j;
			}
		}
		if (ti != -1)
		{
			ans++;
			CNT[ti] = 0;
		}
		else
		{
			int rem = 3;
			while (rem > 0)
			{
				pii ma = mp(0, -1);
				rep(j, 0, N)
				{
					if (CNT[j] > 0)
					{
						if (chmax(ma.first, RP[j]))
						{
							ma.second = j;
						}
					}
				}
				if (ma.second == -1)break;
				int t = min(rem, CNT[ma.second]);
				rem -= t;
				CNT[ma.second] -= t;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

