map<pa3,int> ma;

int solve(int bl,int dame,int tugi){
	if(bl>=N)return 0;
	if(dame>tugi)swap(dame,tugi);
//	cout<<bl<<" "<<dame<<" "<<tugi<<endl;
	if(tugi<3*bl-2) tugi=-1;
	if(!(3*bl-2<=dame && dame<=3*bl))dame=-1;
	pa3 yyy=(pa3){bl,dame,tugi};

	if(ma.count(yyy))return ma[yyy];

	int noko[3]={};
	for(int i=3*bl-2;i<=3*bl;i++){
		if(i==dame||i==tugi)continue;
		noko[i-(3*bl-2)]=1;
	}
	int ans=solve(bl+1,dame,tugi);


	for(int r=1;r<8;r++){
		bool baka=0;
		int pp=-1;
		for(int i=0;i<3;i++)if(r&(1<<i)){
			if(noko[i]==0){
				baka=1;
				break;
			}
			if(pp==-1)pp=V[3*bl-2+i];
			else if(pp!=V[3*bl-2+i]){
				baka=1;
				break;
			}

		}
		if(baka)continue;
	//	cout<<r<<endl;
		if(r==7){
			ans=max(ans,solve(bl+1,dame,tugi)+1);
			continue;
		}
		else if(r==6 || r==5 || r==3){
			int z;
			if(r!=3)z=nx(3*bl);
			else z=nx(3*bl-1); 
			if(z==inf)continue;
			int A=(z+2)/3;
			int B=(tugi+2)/3;
			if(A==bl)continue;
			if(tugi==-1){
				ans=max(ans,hani(bl+1,A)+solve(A,z,tugi)+1);
			}
			else if(A<B){
				ans=max(ans,hani(bl+1,A)+solve(A,z,tugi)+1);
			}
			else if(A==B){
				ans=max(ans,hani(bl+1,A)+solve(A,z,tugi)+1);
			}
			else if(A>B){
				ans=max(ans,hani(bl+1,B)+solve(B,tugi,z)+1);	
			}
		}
		else{
			int B=(tugi+2)/3;
			if(bl<B)continue;
			int z;
			if(r==1)z=nx(3*bl-2);
			if(r==2)z=nx(3*bl-1);
			if(r==4)z=nx(3*bl);
			//cout<<z<<endl;
			if(z==inf)continue;
			int z2=nx(z);
			if(z2==inf)continue;

			int A1=(z+2)/3;
			int A2=(z2+2)/3;
			if(A1==bl ){
				continue;
			}
			if(A1==A2){
				ans=max(ans,hani(bl+1,A1)+solve(A1,z,z2)+1);
			}
			else{
				ans=max(ans,hani(bl+1,A1)+solve(A1,z,z2)+1);		
			}
		}

	}
	ma[yyy]=ans;
//	cout<<yyy.x<<" "<<yyy.y<<" "<<yyy.z<<" "<<ans<<endl;
	return ans;
}


