					q.emplace_back(a,x,now);
				}
			}
			{
				int now = max(dp[n][n],dp[z][z]+1);
				q.emplace_back(x,y,now);
			}
			swap(x,y); swap(y,z);
		}
		for (auto t:q) {
			int i,j,x;
			tie(i,j,x) = t;
			upd(i,j,x);
		}
	}
	int ans = dp[n][n];
	int l =A[n3-1];
	chmax(ans,dp[l][l]+1);
	ans += base;
	cout << ans << endl;
	return 0;
}

