S ll cnts[2005][2005];
S ll maxcnts[2005];

void f_cnts(ll idx0, ll idx1, ll val)
{
    cnts[idx0][idx1] = max(cnts[idx0][idx1], val);
    maxcnts[idx0] = max(maxcnts[idx0], val);
    cnts[idx1][idx0] = max(cnts[idx1][idx0], val);
    maxcnts[idx1] = max(maxcnts[idx1], val);
}

void f_updated(map<t2, ll> &updated, ll idx0, ll idx1, ll val)
{
    if (updated.find(t2(idx0, idx1)) == updated.end()) {
        updated[t2(idx0, idx1)] = val;
        updated[t2(idx1, idx0)] = val;
        return;
    }
    updated[t2(idx0, idx1)] = max(updated[t2(idx0, idx1)], val);
    updated[t2(idx1, idx0)] = max(updated[t2(idx1, idx0)], val);
}

void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, 3LL * n);

    rep (i, 2005) rep (j, 2005) cnts[i][j] = -1e18;
    rep (i, 2005) maxcnts[i] = -1e18;
    f_cnts(alist[0], alist[1], 0);

    ll bonus = 0;

    rep (i, n-1) {
        debug_printf("-------------\n");
        debug_printf("---- cnts[1]\n");
        debug_print(cnts[1], 3);
        debug_printf("---- cnts[2]\n");
        debug_print(cnts[2], 3);

        ll a0 = alist[i*3+2];
        ll a1 = alist[i*3+3];
        ll a2 = alist[i*3+4];

        if (a0 == a1 && a1 == a2) {
            bonus++;
            continue;
        }

        ll allmax = -1e18;
        rep (j, 2005) allmax = max(allmax, maxcnts[j]);

        map<t2, ll> updated;
        V<ll> as;
        as.pb(a0);
        as.pb(a1);
        as.pb(a2);

        rep (j, 3) {
            ll discard = as[j];
            ll remain0 = as[(j+1)%3];
            ll remain1 = as[(j+2)%3];
            ll newval = max(cnts[discard][discard] + 1LL, allmax);
            f_updated(updated, remain0, remain1, newval);
        }

        rep (j, 3) {
            ll remain = as[j];
            ll discard0 = as[(j+1)%3];
            ll discard1 = as[(j+2)%3];
            rep (b, 2005) f_updated(updated, remain, b, maxcnts[b]);
            if (discard0 == discard1) {
                rep (b, 2005) f_updated(updated, remain, b, cnts[b][discard0] + 1LL);
            }
        }

        for (auto item : updated) {
            ll idx0 = get<0>(item.first);
            ll idx1 = get<1>(item.first);
            ll newcnt = item.second;
            f_cnts(idx0, idx1, newcnt);
        }
    }

    debug_printf("-------------\n");
    debug_printf("---- cnts[1]\n");
    debug_print(cnts[1], 3);
    debug_printf("---- cnts[2]\n");
    debug_print(cnts[2], 3);

    ll la = alist[3*n-1];
    cnts[la][la]++;

    ll ans = -1e18;
    rep (i, 2005) rep (j, 2005) ans = max(ans, cnts[i][j]);
    ans += bonus;

    debug_printf("-------- ans\n");
    cout << ans << endl;
}

