#include <bits/stdc++.h>
using namespace std;

using lint = long long;
const int MAXN = 6005;
const int INF = 1e5;

int N;
int A[MAXN];

int ans = 0;
int base = 0;
int nxt[MAXN];
int dp[MAXN][MAXN];

vector<int> Group;

int CostGroupExcept(int Left1,int Left2){

    int cur = 0;
    for(auto o:Group){
        if(o != Left1 && o != Left2){
            if(cur == 0)
                cur = A[o];
            else if(A[o] != cur)
                return 0;
        }
    }
        return 1;

}

void Transition(int Left1,int Left2,int Cur){

    Group = {Left1,Left2,Cur,Cur+1,Cur+2};

    if(Cur > 3*N)
        return;

    if(Cur == 3*N)
        return void( ans = max( ans , dp[Left1][Left2] + CostGroupExcept(Cur+1,Cur+2) ) );

    for(int i = 0; i < 5; i++){
        for(int j=1; j < 5 ; j++){
            int NextLeft1 = Group[i];
            int NextLeft2 = Group[j];
            dp[ NextLeft1 ][ NextLeft2 ] = max( dp[ NextLeft1 ][ NextLeft2 ]
                                               , dp[Left1][Left2] + CostGroupExcept(NextLeft1,NextLeft2) );
        }
    }
}


int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  cin >> N;
  for (int i = 1; i <= 3 * N; i++) {
    cin >> A[i];
  }

  while (true) {
    bool change = false;
    for (int i = 3; i + 2 <= 3 * N; i += 3) {
      if (A[i] == A[i + 1] && A[i + 1] == A[i + 2]) {
        base += 1;
        for (int j = i + 3; j <= 3 * N; j++) {
          A[j - 3] = A[j];
        }
        N -= 1;
        change = true;
        break;
      }
    }
    if (!change) {
      break;
    }
  }

  vector<int> last(3 * N + 1, 3 * N + 1);
  for (int i = 3 * N; i > 0; i--) {
    nxt[i] = last[A[i]];
    last[A[i]] = i;
  }
  for (int i = 0; i < MAXN; i++) {
    for (int j = 0; j < MAXN; j++) {
      dp[i][j] = -INF;
    }
  }
  dp[1][2] = 0;
  for (int i = 1; i <= 3 * N; i++) {
    for (int j = i + 1; j <= 3 * N; j++) {
      Transition(i, j, (j + 3) / 3 * 3);
      // Find next occurrence of A[i]
      if (j / 3 * 3 < nxt[i] / 3 * 3) {
        Transition(i, j, nxt[i] / 3 * 3);
      }
      // Find next occurrence of A[j]
      if (j / 3 * 3 < nxt[j] / 3 * 3) {
        Transition(i, j, nxt[j] / 3 * 3);
      }
    }
  }

  cout << ans + base << "\n";
  return 0;
}

