                chmax(dp[j][v[2]], dp0[j] + 1);
                chmax(ns[v[2]], dp[v[2]][j]);
                chmax(ns[j], dp[v[2]][j]);
                chmax(nmx, dp[v[2]][j]);
            }
            chmax(nmx, dp[v[0]][v[1]]);
            chmax(nmx, dp[v[0]][v[2]]);
        }
        else if(v[1] == v[2]) {
            auto dp2 = dp[v[2]];
            chmax(dp[v[1]][v[2]], max(mx, dp[v[0]][v[0]] + 1));
            chmax(dp[v[0]][v[2]], max(mx, dp2[v[2]] + 1));
            chmax(dp[v[2]][v[0]], max(mx, dp2[v[2]] + 1));
            for (int j = 0; j < n; j++) {
                chmax(dp[v[0]][j], dp2[j] + 1);
                chmax(dp[j][v[0]], dp2[j] + 1);
                chmax(ns[v[0]], dp[v[0]][j]);
                chmax(ns[j], dp[v[0]][j]);
                chmax(nmx, dp[v[0]][j]);
            }
            chmax(nmx, dp[v[1]][v[2]]);
            chmax(nmx, dp[v[0]][v[2]]);
        }
        chmax(nmx, f(v[0], v[1], v[2], pp, qq, rr, ns));
        chmax(nmx, f(v[1], v[2], v[0], qq, rr, pp, ns));
        chmax(nmx, f(v[2], v[0], v[1], rr, pp, qq, ns));
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < n; k++) {
                chmax(dp[v[j]][k], s[k]);
                chmax(dp[k][v[j]], s[k]);
                chmax(nmx, dp[k][v[j]]);
            }
        }
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                chmax(ns[v[j]], dp[v[j]][v[k]]);
                chmax(ns[v[j]], dp[v[j]][v[k]]);
                chmax(ns[v[j]], dp[v[j]][v[k]]);
            }
        }
        mx = nmx;
        s = ns;
    }
    int P = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            chmax(P, dp[i][j] + (i == j and i == a[3 * n - 1]));
        }
    }
    cout << ans + P << endl;
    return 0;
}

