  int ex = 0;

  for(int i=2; i < n3-2; i+=3){
    int x = a[i];
    int y = a[i+1];
    int z = a[i+2];

    //新しい3枚が一致していたとき
    if(x == y && y == z){ 
      ++ex;
      continue;
    }

    vector<T> t;
    //古い2枚と新しい1枚
    //古いのを2枚捨てるからその時点の最大値maxabと比較。
    rep(j,3){
      int m = max(maxab, dp[z][z]+1);
      t.emplace_back(x,y,m);
      swap(x,y); swap(y,z);
    }

    //古い1枚と新しい2枚
    //古いものを1枚捨てる
    rep(j,3){
