      maxa[nb] = max(maxa[nb], s);

      maxab = max(maxab, s);
    }   
  }

  int ans = maxab;
  int al = a[n3-1];
  ans = max(ans, dp[al][al]+1);
  ans += ex;
  cout << ans << endl;

  return 0;
}

