    cout.tie(0);

    cin>>n;
    n*=3;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    memset(dp,0x80,sizeof(dp));
    dp[a[1]][a[2]]=mx=0;
    for(int i=3;i+2<=n;i+=3){
        if(a[i]==a[i+1]&&a[i]==a[i+2]){
            three++;
            continue;
        }
        map<pair<int,int>,int> mp;
        if(a[i]==a[i+1]||a[i+1]==a[i+2]||a[i]==a[i+2]){
            const int &p=a[i]==a[i+1]?a[i]:a[i+2],&q=a[i]+a[i+1]+a[i+2]-p*2;
            for(int k=1;k<=n/3;k++){
                mp[make_pair(k,q)]=max(dp[p][k],dp[k][p])+1;
            }
        }
        const int &p=a[i],&q=a[i+1],&r=a[i+2];
        if(mp.find(make_pair(q,r))==mp.end())mp[make_pair(q,r)]=max(mx,dp[p][p]+1);
        else mp[make_pair(q,r)]=max(mp[make_pair(q,r)],max(mx,dp[p][p]+1));
        if(mp.find(make_pair(p,r))==mp.end())mp[make_pair(p,r)]=max(mx,dp[q][q]+1);
        else mp[make_pair(p,r)]=max(mp[make_pair(p,r)],max(mx,dp[q][q]+1));
        if(mp.find(make_pair(p,q))==mp.end())mp[make_pair(p,q)]=max(mx,dp[r][r]+1);
        else mp[make_pair(p,q)]=max(mp[make_pair(p,q)],max(mx,dp[r][r]+1));
        for(int k=1;k<=n/3;k++){
            if(mp.find(make_pair(k,p))==mp.end())mp[make_pair(k,p)]=mx;
            else mp[make_pair(k,p)]=max(mp[make_pair(k,p)],mx);
            if(mp.find(make_pair(k,q))==mp.end())mp[make_pair(k,q)]=mx;
            else mp[make_pair(k,q)]=max(mp[make_pair(k,q)],mx);
            if(mp.find(make_pair(k,r))==mp.end())mp[make_pair(k,r)]=mx;
            else mp[make_pair(k,r)]=max(mp[make_pair(k,r)],mx);
        }
        for(pair<const pair<int,int>,int> &p:mp){
            dp[p.first.first][p.first.second]=max(dp[p.first.first][p.first.second],p.second);
            mx=max(mx,p.second);
        }
    }
    int ans=dp[a[n]][a[n]]+1;
    for(int i=1;i<=n/3;i++){
        ans=max(ans,*max_element(dp[i]+1,dp[i]+1+n/3));
    }
    cout<<ans+three<<endl;

    return 0;
}

