int main() {
  cin.tie(nullptr)->sync_with_stdio(false);
  cout << fixed << setprecision(20);
  int n;
  cin >> n;
  vector<int> a(3 * n);
  for (auto&& e : a) cin >> e, --e;

  vector dp(n, vector(n, -inf<int>));
  vector max_dp(n, -inf<int>);
  int offset = 0;

  vector<array<int, 3>> v;
  auto lazy_update = [&](int p, int q, int val) -> void {
    v.push_back({p, q, val});
  };
  auto push_all = [&]() -> void {
    while (sz(v)) {
      auto [p, q, val] = v.back();
      chmax(dp[p][q], val);
      chmax(dp[q][p], val);
      chmax(max_dp[p], val);
      chmax(max_dp[q], val);
      v.pop_back();
    }
  };

  lazy_update(a[0], a[1], 0);
  push_all();

  for (int i = 0; i < n - 1; ++i) {
    sort(begin(a) + (i * 3 + 2), begin(a) + (i * 3 + 5));
    int x = a[i * 3 + 2];
    int y = a[i * 3 + 3];
    int z = a[i * 3 + 4];
    if (x == z) {
      ++offset;
      continue;
    }
    if (x == y) {
      for (int p = 0; p < n; ++p) lazy_update(p, z, dp[p][y] + 1);
    }
    if (y == z) {
      for (int p = 0; p < n; ++p) lazy_update(p, x, dp[p][y] + 1);
    }
    for (int e : {x, y, z}) {
      for (int p = 0; p < n; ++p) lazy_update(p, e, max_dp[p]);
    }
    auto max_all = *max_element(ALL(max_dp));
    lazy_update(x, y, max_all);
    lazy_update(x, z, max_all);
    lazy_update(y, z, max_all);
    lazy_update(y, z, dp[x][x] + 1);
    lazy_update(x, z, dp[y][y] + 1);
    lazy_update(x, y, dp[z][z] + 1);
    push_all();
  }

  int res = -inf<int>;
  for (int p = 0; p < n; ++p)
    for (int q = 0; q < n; ++q)
      chmax(res, offset + dp[p][q] + (p == q and q == a.back()));
  cout << res << '\n';
}

