	scanf("%d",&n);
	for(int i=1;i<=n;++i){
		mxr[i]=-inf;
		for(int j=1;j<=n;++j){
			f[i][j]=-inf;
		}
	}
	int x,y,z;scanf("%d%d",&x,&y);
	f[x][y]=f[y][x]=0;mxr[x]=mxr[y]=0;

	for(int i=3;i+2<=3*n;i+=3){
