inline int L(int j){
    int ret = j+1;
    while(ret%3 != 2) ret++;
    return ret;
}

inline int gl(int k){
    if(k%3 == 2) return k+1;
    if(k%3 == 0) return k-1;
    if(k%3 == 1) return k-2;
}

inline int gr(int k){
    if(k%3 == 2) return k+2;
    if(k%3 == 0) return k+1;
    if(k%3 == 1) return k-1;
}

int fdp[6001][2001];
int find(int l, int a){
    if(fdp[l][a] != -1) return fdp[l][a];
    if(l+2 >= 3*N) return INT_MAX;
    int cnt = 0;
    if(A[l] == a) cnt++;
    if(A[l+1] == a) cnt++;
    if(A[l+2] == a) cnt++;
    if(cnt < 2) return fdp[l][a] = find(l+3, a);
    else{
        if(A[l] != a) return fdp[l][a] = l;
        if(A[l+1] != a) return fdp[l][a] = l+1;
        if(A[l+2] != a) return fdp[l][a] = l+2;
        return fdp[l][a] = l+2;
    }
}

int f2dp[6001][2001];
int find2(int l, int a){
    if(f2dp[l][a] != -1) return f2dp[l][a];
    if(l >= 3*N) return INT_MAX;
    if(A[l] == a) return f2dp[l][a] = l;
    return f2dp[l][a] = find2(l+1, a);
}

