int dpM[6001];
int solMax(int l){
    if(l == 3*N) return 0;
    if(dpM[l] != -1) return dpM[l];
    return dpM[l] = max(solve(gl(l), gr(l)) + sum(L(gr(l))-3), solMax(l+1));
}

int solve(int i, int j){
    if(dp[i][j] != -1) return dp[i][j];
    int l = L(j);
    if(l == 3*N-1){
        return (A[i] == A[j] && A[j] == A[3*N-1]);
    }
    if(l > 3*N-1) return 0;

    int ret = 0;

    /*for(int k=l; k<3*N-1; k++){
        ret = max(ret, solve(j, k) + sum(L(k)-3) - sum(l));
        ret = max(ret, solve(i, k) + sum(L(k)-3) - sum(l));
    }*/
    ret = max(ret, rmq[j].query(l, 3*N-1) - sum(l));
    ret = max(ret, rmq[i].query(l, 3*N-1) - sum(l));
    int I = find(l, A[i]);
    if(I != INT_MAX) ret = max(ret, solve(j, I) + sum(L(I)-3) - sum(l) + 1);
    int J = find(l, A[j]);
    if(J != INT_MAX) ret = max(ret, solve(i, J) + sum(L(J)-3) - sum(l) + 1);

    /*for(int k=l; k<3*N; k++){
        ret = max(ret, solve(gl(k), gr(k)) + sum(L(gr(k))-3) - sum(l));
    }*/
    ret = max(ret, solMax(l) - sum(l));
    if(A[i] == A[j]){
        int K = find2(l, A[i]);
        if(K != INT_MAX) ret = max(ret, solve(gl(K), gr(K)) + sum(L(gr(K))-3) - sum(l) + 1);
    }

    return dp[i][j] = ret;
}

