			f[i][j] = -INF;
	}

	if(3 * n >= 5)
	{
		for(int i = 1; i <= 5; i++)
			for(int j = i + 1; j <= 5; j++)
			{
				int lst = 0;
				bool flag = true;
				for(int k = 1; k <= 5; k++)
					if(k != i && k != j)
					{
						if(lst && A[k] != lst) flag = false;
						lst = A[k];
					}
				if(flag) chkmx(A[i], A[j], 1);
				else chkmx(A[i], A[j], 0);
			}
	}

	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= n; j++)
			mx = max(mx, f[i][j]);

