		res.push_back( Node(a, c, max(mx, f[b][b] + 1)) );
		res.push_back( Node(b, c, max(mx, f[a][a] + 1)) );

		for(int j = 1; j <= n; j++)
		{
			if(b == c) res.push_back( Node(a, j, max(g[j], f[j][c] + 1)) );
