			else res.push_back( Node(b, j, g[j]) );
			if(a == b) res.push_back( Node(c, j, max(g[j], f[j][b] + 1)) );
			else res.push_back( Node(c, j, g[j]) );
		}

		for(int i = 0; i < res.size(); i++)
			chkmx(res[i].x, res[i].y, res[i].v);
