int N;
deque<int> A;
void input(){
    fast_io();
    cin >> N;
    for (int i = 0; i < 3*N; i++)
    {
        int a; cin >> a;
        A.push_back(a);
    }
}

int solve(){
    int ans = 0;
    for (int i = 0; i < N-1; i++)
    {
        vector<int> V;
        map<int, int> cnt; 
        int k = 5;
        while(k--){
            int a = A.front();
            V.push_back(a);
            cnt[a]++;
            A.pop_front();
        }
        int cmax = 0;
        for(auto [x,c]:cnt) cmax = max(cmax, c);
        if(cmax >= 3){
            ans++;
            int cx = 0;
            for(auto [x,c]:cnt) if(c==cmax) cx = x;
            int k = 0;
            for(auto vx:V){
                if(vx!=cx || k>=3){
                    A.push_front(vx);
                }
                else{
                    k++;
                }
            }
        }
        else{
            // Vのうち残す2つを、Aから探索して決める。
            vector<int> Res;
            for(auto a:A){
                cnt[a]++;
                if(cnt[a]==3){
                    for(auto x:V){
                        if(x==a) {
                            Res.push_back(x);
                            if(Res.size()>=2) break;
                        }
                    }
                }
                if(Res.size()>=2) break;
            }
            if(Res.size()==0){
                Res.push_back(0);
                Res.push_back(0);
            }
            else if(Res.size()==1){
                Res.push_back(0);
            }
            for(auto r:Res){
                A.push_front(r);
            }
        }
    }
    DBG(A)
    if(A[0]==A[1] && A[1]==A[2]) ans++;
    cout << ans << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

