// FUNCTIONS
// Binary exponentation
ll binpow(ll a, ll b){
    ll res = 1;
    while (b > 0)
    {
        res *= a * (ll)(b & 1LL);
        a *= a;
        b /= 2;
    }
    return res;
}

// Binary search
template <class T, class S>
int search(T a, S el, int n = 0){
    n = n ? n : a.size();
    int i = 0;
    for (int b = n / 2; b > 0; b /= 2)
        while (i + b < n && a[i] <= el)
            i += b;
    return i;
}

// Comparisions
template <class T> bool umin(T &a, const T &b){
    return a > b ? a = b, 1 : 0;
}
