    return a < b ? a = b, 1 : 0;
}

// GCD / LCM
int gcd(int a, int b){
    return b ? gcd(b, a%b) : a;
}
int lcm(int a, int b){
    return a * b / gcd(a, b);
}
int egcd(int a, int b, int& x, int& y){
    if (b==0){
        x=1;
        y=0;
        return a;
    }
    int x1, y1;
    int d=egcd(b, a%b, x1, y1);
    x=y1;
    y=x1 - y1*(a/b);
    return d;
}


