				ONE[A[y]].push_back(make_pair((id+1)/3,i));
				A[y]=A[z]=A[id]=0;
				now=true;
			}
			else if(zx&&!ids[A[z]].empty()&&P.query((ids[A[z]].top()+1)/3,i)<=1)
			{
				int id=ids[A[z]].top();ids[A[z]].pop();
				ans++;
				P.update((id+1)/3,i,1);
				ids[A[y]].push(y);
				ONE[A[z]].push_back(make_pair((id+1)/3,i));
				A[z]=A[x]=A[id]=0;
				now=true;
			}
			else
			{
				for(int di=-1;di<=1;di++)if(A[i*3+di]!=0)ids[A[i*3+di]].push(i*3+di);
			}
		}
		for(int i=1;i<=N;i++)while(!ids[i].empty())ids[i].pop();
		for(int fst=0;fst<2;fst++)if(A[fst]!=0)ids[A[fst]].push(fst);
		for(int i=1;i<=N;i++)
