using namespace std;


int solve(vector<int> & as, int p, int n, pair<int, int> sel)
{
	auto selc = sel;
	//cout << p << " " << sel.first << " " << sel.second << endl;
	if (p == n - 1) {
		if (sel.first == sel.second && sel.first == as[n * 3 - 1]) {
			//cout << "f1" << endl;
			return 1;
		}
		else {
			//cout << "f0" << endl;
			return 0;
		}
	}

	static vector<unordered_map<int, int>> map(2001);
	int idx = sel.first * 2010 + sel.second;
	{
		auto it = map[p].find(idx);
		if (it != map[p].end()) {
			return it->second;
		}
	}

	int ans = 0;
	int vs[3] = { as[p * 3 + 2], as[p * 3 + 3], as[p * 3 + 4] };
	if (sel.first != 0 && sel.first == sel.second) {
		FOR_LT(i, 0, 3) {
			if (sel.first == vs[i]) {
				ans++;
				sel.first = 0;
				sel.second = 0;
				vs[i] = 0;
				break;
			}
		}
	}
	else {
		if (sel.first != 0) {
			int nc = 0;
			FOR_LT(i, 0, 3) {
				if (vs[i] == sel.first) nc++;
			}
			if (2 <= nc) {
				ans++;
				FOR_LT(i, 0, 3) {
					if (vs[i] == sel.first) {
						vs[i] = 0;
						nc--;
					}
					if (nc == 0) break;
				}
				sel.first = 0;
				//cout << "take first" << endl;
			}
		}
		if (sel.second != 0) {
			int nc = 0;
			FOR_LT(i, 0, 3) {
				if (vs[i] == sel.second) nc++;
			}
			if (2 <= nc) {
				ans++;
				FOR_LT(i, 0, 3) {
					if (vs[i] == sel.second) {
						vs[i] = 0;
						nc--;
					}
					if (nc == 0) break;
				}
				sel.second = 0;
				//cout << "take second" << endl;
			}
		}

		if (sel.first == 0 && sel.second != 0) {
			swap(sel.first, sel.second);
		}
	}

	if (vs[0] != 0 && vs[0] == vs[1] && vs[1] == vs[2]) {
		//cout << p << " " << "OK" << endl;
		ans++;
		vs[0] = 0;
		vs[1] = 0;
		vs[2] = 0;
	}

	int ca = 0;
	//cout << "\t" << sel.first << " " << sel.second << " " << ans << endl;
	if (sel.first == 0) {
		ca = max(ca, solve(as, p + 1, n, sel));
		FOR_LT(i, 0, 3) {
			if (vs[i] != 0) {
				ca = max(ca, solve(as, p + 1, n, { vs[i], 0 }));
			}
		}
		FOR_LT(i, 0, 3) {
			FOR_LT(j, i + 1, 3) {
				if (vs[i] != 0 && vs[j] != 0) {
					ca = max(ca, solve(as, p + 1, n, { vs[i], vs[j] }));
				}
			}
		}
	}
	else if (sel.second == 0) {
		ca = max(ca, solve(as, p + 1, n, sel));
		FOR_LT(i, 0, 3) {
			if (vs[i] != 0) {
				ca = max(ca, solve(as, p + 1, n, { sel.first, vs[i] }));
			}
		}
	}
	else {
		ca = max(ca, solve(as, p + 1, n, sel));
	}
	ans += ca;

	//cout << p << " " << selc.first << " " << selc.second << " " << ans << " " << ca << endl;
	map[p].insert({ idx, ans });
	return ans;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;
	vector<int> as(n * 3);
	FOR_LT(i, 0, n * 3) {
		cin >> as[i];
	}

	int ans = 0;
	{
		ans = max(ans, solve(as, 0, n, { 0, 0 }));
		ans = max(ans, solve(as, 0, n, { as[0], 0 }));
		ans = max(ans, solve(as, 0, n, { as[1], 0 }));
		ans = max(ans, solve(as, 0, n, { as[0], as[1] }));
	}
	cout << ans << endl;

	return 0;
}

