                int y=v[j],z=v[3-i-j];
                dp_new[x][y]=max({dp_new[x][y],dp[x][y],ans,dp[z][z]+1});
                if(y==z){
                    for(int t=1;t<=n;t++){
                        dp_new[x][t]=max({dp_new[x][t],dp[x][t],dp[y][t]+1});
