            int pos = 1e9;
            for (int j = index + 5; j < 3 * n; ++j) {
                if (a[j] == have[ind]) --need;
                if (need == 0) pos = j - 4;
            }
            for (int j = 0; j < ptr - ind; ++j) cands.push_back({pos, have[ind]});
            ind = ptr;
        }
