		if (y == z)REP(j, n)update.push_back({ j,x,dp[y][j] + 1});
		if (x == z)REP(j, n)update.push_back({ j,y,dp[z][j] + 1 });
		update.push_back({ x,y,dp[z][z] + 1 });
		update.push_back({ y,z,dp[x][x] + 1 });
		update.push_back({ x,z,dp[y][y] + 1 });
		update.push_back({ x,y,mx });
		update.push_back({ y,z,mx });
		update.push_back({ x,z,mx });
		REP(j, n)update.push_back({ j,x,p[j] });
		REP(j, n)update.push_back({ j,y,p[j] });
		REP(j, n)update.push_back({ j,z,p[j] });
		for (auto [u, v, c] : update) {
			chmax(dp[u][v], c);
			chmax(dp[v][u], c);
			chmax(p[u], c);
			chmax(p[v], c);
		}
	}
	REP(i, n)REP(j, n) {
		chmax(ans, dp[i][j]);
		if (i == j && i == a.back())chmax(ans, dp[i][j] + 1);
	}

	cout << ans + tmp << "\n";




	return 0;
}

