int a[6005];
int dp[2005][2005];
int maxa[2005]; //要素にiを持つ場合の最大値

int main(){
  int n;
  cin >> n;
  int n3 = n*3;

  rep(i,n3) cin >> a[i],--a[i];
  rep(i,n)rep(j,n) dp[i][j] = -1;
  rep(i,n) maxa[i] = -1;


  dp[a[0]][a[1]] = 0;
  dp[a[1]][a[0]] = 0;
  maxa[a[0]] = maxa[a[1]] = 0;
  int maxab = 0; //その時点での最大値
  int ex = 0;

  for(int i=2; i < n3-2; i+=3){
    int x = a[i];
    int y = a[i+1];
    int z = a[i+2];

    //新しい3枚が一致していたとき
    if(x == y && y == z){ 
      ++ex;
      continue;
    }

    vector<T> t;
    //古い2枚と新しい1枚
    //古いのを2枚捨てるからその時点の最大値maxabと比較。
    rep(j,3){
      int m = max(maxab, dp[z][z]+1);
      t.emplace_back(x,y,m);
      swap(x,y); swap(y,z);
    }

    //古い1枚と新しい2枚
    //古いものを1枚捨てる
    rep(j,3){
      rep(k,n){
        int m = maxa[k];
        if(x == y) m = max(m, dp[x][k]+1);
        t.emplace_back(z,k,m);
      }
      swap(x,y); swap(y,z);
    }

    for(auto upd : t){
      int na, nb, s;
      tie(na, nb, s) = upd;

      dp[na][nb] = max(dp[na][nb], s);
      dp[nb][na] = max(dp[nb][na], s);
      maxa[na] = max(maxa[na], s);
      maxa[nb] = max(maxa[nb], s);

      maxab = max(maxab, s);
    }   
  }

  int ans = 0;
  int al = a[n3-1];
  rep(i,n)rep(j,n){
    if(i == al && j == al) ++dp[i][j];
    ans = max(ans, dp[i][j]);
  }
  ans += ex;
  cout << ans << endl;

  return 0;
}

