#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define ld long double
#define pb push_back
#define all(x) begin(x), end(x)
#define SZ(x) (int)(x).size()
#define cps(x) sort(all(x)), (x).erase(unique(all(x)), end(x))
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

const int n0 = 6003;
int n, a[n0], has[n0], lft[n0], del[n0], done[n0], res;

vector <int> vec;

bool check() {
	for (int i = 5; i <= 3 * n; i += 3) {
		if (has[i] + lft[i] / 3 < i / 3) return false;
	}
	return true;
}

void pop() {
	vec.clear();
	int k = -1;
	for (int i = 1; i <= 3 * n; i++) {
		if (!del[i])
			vec.pb(i);
		lft[i] -= SZ(vec);
		if (SZ(vec) == 3) {
			for (int j : vec)
				del[j] = 1;
			int x = vec.back();
			for (int i = x; i <= 3 * n; i++)
				has[i]++;
			k = i;
			break;
		}
	}
	assert(k != -1);
	for (int i = k + 1; i <= 3 * n; i++)
		lft[i] -= 3;
}

int cur[n0];

int main() {
	ios_base::sync_with_stdio(false), cin.tie(NULL);
	cin >> n;
	for (int i = 1; i <= 3 * n; i++)
		cin >> a[i], lft[i] = i;
	while (true) {
		memset(& cur, 0, sizeof(cur));
		int col = -1, count = 0;
		for (int i = 1; i <= 3 * n; i++) {
			if (del[i]) continue;
			count++;
			cur[a[i]]++;
			if (cur[a[i]] == 3) {
				col = a[i];
				break;
			}
		}
		if (count == 0) break;
		if (col == -1) {
			pop();
			continue;
		}
		vec.clear();
		int k = -1;
		for (int i = 1; i <= 3 * n; i++) {
			if (!del[i] && a[i] == col)
				vec.pb(i);
			lft[i] -= SZ(vec);
			if (SZ(vec) == 3) {
				for (int j : vec)
					del[j] = 1;
				int x = vec.back();
				for (int i = x; i <= 3 * n; i++)
					has[i]++;
				k = i;
				break;
			}
		}
		assert(k != -1);
		for (int i = k + 1; i <= 3 * n; i++)
			lft[i] -= 3;
		if (check()) {
			res++;
			continue;
		}
		for (int i : vec)
			del[i] = 0;
		vec.clear();
		k = -1;
		for (int i = 1; i <= 3 * n; i++) {
			if (!del[i] && a[i] == col)
				vec.pb(i);
			lft[i] += SZ(vec);
			if (SZ(vec) == 3) {
				int x = vec.back();
				for (int i = x; i <= 3 * n; i++)
					has[i]--;
				k = i;
				break;
			}
		}
		assert(k != -1);
		for (int i = k + 1; i <= 3 * n; i++)
			lft[i] += 3;
		pop();
	}
	cout << res;
}

