        map<P, int> next;
        if (c[0] == c[1]){
            REP(j,n){
                next[P(j, c[2])] = next[P(c[2], j)] = dp[c[0]][j] + 1;
            }
        }else if (c[1] == c[2]){
            REP(j,n){
                next[P(j, c[0])] = next[P(c[0], j)] = dp[c[1]][j] + 1;
            }
        }
        VI v(c);
        v.push_back(n);
        for (int x : v) for (int y : v){
            if (dp[x][y] == -INF) continue;
            VI p;
            if (x != n) p.push_back(x);
            if (y != n) p.push_back(y);
            for (int tmp : c) p.push_back(tmp);
            sort(ALL(p));
            do{
                chmax(next[P(p[0], n)], dp[x][y]);
                chmax(next[P(p[0], p[1])], dp[x][y]);
                if (p[0] == p[1] && p[1] == p[2]){
                    chmax(next[P(n, n)], dp[x][y] + 1);
                    chmax(next[P(p[3], n)], dp[x][y] + 1);
                    chmax(next[P(p[3], p[4])], dp[x][y] + 1);
                }
            }while (next_permutation(ALL(p)));
        }
        for (auto tmp : next){
            int x = tmp.first.first;
            int y = tmp.first.second;
            chmax(dp[x][y], tmp.second);
        }
        // REP(i,n+1){
        //     REP(j,n+1) cout << dp[i][j] << " ";
        //     cout << endl;
        // }
    }
    int ans = 0;
    REP(i,n) REP(j,n) chmax(ans, dp[i][j]);
    chmax(ans, dp[a.back()][a.back()] + 1);
    ans += base;
    cout << ans << endl;
    return 0;
}

