void upd(int x,int y,int v){
	chmax(dp[x][y],v);
	chmax(dp[y][x],v);
	chmax(dp[x][n],v);
	chmax(dp[n][x],v);
	chmax(dp[n][y],v);
	chmax(dp[y][n],v);
	chmax(dp[n][n],v);
} 
struct node{
	int x;
	int y;
	int v;
	node(int _x=0,int _y=0,int _v=0):x(_x),y(_y),v(_v){}
};
int main(){
	cin>>n;
