		for(int j=0;j<=n;++j){
			dp[i][j]=-2e9;
		}
	}
	upd(a[0],a[1],0);
	int cnt=0;
	for(int i=2;i<nn-1;i+=3){
		int x=a[i],y=a[i+1],z=a[i+2];
		if(x==y&&y==z){
			cnt++;
			continue;
		}
		vector<node> v;
		for(int j=0;j<3;++j){
			{
				for(int k=0;k<=n;++k){
					int now=dp[k][n];
					if(y==z){
						chmax(now,dp[k][y]+1);
					}
					v.push_back(node(k,x,now));
				}
			}
			{
				int now=max(dp[n][n],dp[z][z]+1);
				v.push_back(node(x,y,now));
			}
			swap(x,y);
			swap(y,z);
		}
		for(node nd:v){
			int x=nd.x;
			int y=nd.y;
			int v=nd.v;
			upd(x,y,v);
		}
	}
	int ans=dp[n][n];
	int l=a[nn-1];
	chmax(ans,dp[l][l]+1);
	ans+=cnt;
	cout<<ans<<'\n';
	return 0;
}

