	b[++m]=a[1];
	b[++m]=a[2];
	for(int i=3;i<3*n;i+=3){
		if(a[i]==a[i+1]&&a[i+1]==a[i+2]){
			add++;
		}else{
			b[++m]=a[i];
			b[++m]=a[i+1];
			b[++m]=a[i+2];
		}
	}
	b[++m]=a[3*n];
	n=m;
	for(int i=n-1;i>=1;i--){
		nxt[i]=last[b[i]];
		last[b[i]]=i;
	}
	f[1][2]=0;
	for(int j=2;j<n;j++){
		for(int i=1;i<j;i++){
			if(f[i][j]!=-1){
				ans=max(ans,f[i][j]+check(i,j,n));
				dp(i,j);
			}
		}
	}
	printf("%d\n",add+ans);
	return 0;
}

