class MaxRange {
public:
  ll max_range;
  set<RNG> rngs;

  MaxRange():max_range(0){}

  void add(const RNG& rng){
    ll nl = rng.l, nr = rng.r;

    auto bgn = rngs.lower_bound((RNG){nl-1,nl-1});
    auto it = bgn;
    for(; it != rngs.end(); it++){
      if(it->l <= rng.r+1){
        nl = min(nl, it->l);
        nr = max(nr, it->r);
      }else{
        break;
      }
    }

    rngs.erase(bgn, it);
    rngs.insert((RNG){nl,nr});
    max_range = max(max_range, nr+1-nl);
  }

  ll get_max(){
    return max_range;
  }
};

