			b[k] = a[index + k];
		}
		if (b[0] == b[1] && b[0] == b[2]) {
			++offset;
			continue;
		}
		updates.clear();
		for (int i = 0; i < 3; i++) {
			for (int j = i + 1; j < 3; j++) {
				int k = 3 - i - j;
				updates.push_back(make_pair(make_pair(b[i], b[j]), opt));
				updates.push_back(make_pair(make_pair(b[i], b[j]), f[b[k]][b[k]] + 1));
			}
