using namespace std;

using VI = vector <int>;
using VVI = vector <VI>;
using VS = vector < set<int> >;

inline int getNextIdx(VS& vs, int val, int npos) {
    auto iter = vs[val].upper_bound(npos);

    if (iter == vs[val].end()) {
        return -1;
    }

    return *iter;
}

inline int getBlockStart(VS& vs, int val, int npos) {
    int pos = getNextIdx(vs, val, npos);
    int nextBlock = (npos+1-2)/3 * 3 + 2;
    return pos < 0 ? nextBlock : (pos-2)/3*3 + 2;
}

int checkEqual(VI& A, int i, int j, int k){
    return A[i] == A[k] && A[i] == A[j];
}

int checkValid(VI& A, int i, int j, int l1, int l2, int l3){
    return (i > l1 || A[i] != A[l1])
        && (i > l2 || A[i] != A[l2])
        && (i > l3 || A[i] != A[l3])
        && (j > l1 || A[j] != A[l1])
        && (j > l2 || A[j] != A[l2])
        && (j > l3 || A[j] != A[l3]);
}

void solve(VVI& dp, VI& A, int i, int j, int s) {
    if (s+2 < A.size()) {
        if (checkValid(A, i, s+0, j, s+1, s+2)) {
            dp[i][s+0] = max(dp[i][s+0], dp[i][j] + checkEqual(A, j, s+1, s+2));
        }

        if (checkValid(A, i, s+1, j, s+0, s+2)) {
            dp[i][s+1] = max(dp[i][s+1], dp[i][j] + checkEqual(A, j, s+0, s+2));
        }

        if (checkValid(A, i, s+2, j, s+0, s+1)) {
            dp[i][s+2] = max(dp[i][s+2], dp[i][j] + checkEqual(A, j, s+0, s+1));
        }

        if (checkValid(A, j, s+0, i, s+1, s+2)) {
            dp[j][s+0] = max(dp[j][s+0], dp[i][j] + checkEqual(A, i, s+1, s+2));
        }

        if (checkValid(A, j, s+1, i, s+0, s+2)) {
            dp[j][s+1] = max(dp[j][s+1], dp[i][j] + checkEqual(A, i, s+0, s+2));
        }

        if (checkValid(A, j, s+2, i, s+0, s+1)) {
            dp[j][s+2] = max(dp[j][s+2], dp[i][j] + checkEqual(A, i, s+0, s+1));
        }

        if (checkValid(A, s+0, s+1, i, j, s+2)) {
            dp[s+0][s+1] = max(dp[s+0][s+1], dp[i][j] + checkEqual(A, i, j, s+2));
        }

        if (checkValid(A, s+0, s+2, i, j, s+1)) {
            dp[s+0][s+2] = max(dp[s+0][s+2], dp[i][j] + checkEqual(A, i, j, s+1));
        }

        if (checkValid(A, s+1, s+2, i, j, s+0)) {
            dp[s+1][s+2] = max(dp[s+1][s+2], dp[i][j] + checkEqual(A, i, j, s+0));
        }
    } else {
        if (s < A.size()) {
            dp[A.size()][A.size()] = max(dp[A.size()][A.size()], dp[i][j] + checkEqual(A, i, j, s));
        }
    }
}

int main() {
    int N;
    cin >> N;

    // iteration, number, num
    VI A(3*N);
    VS vs(N+1);

    for (int i = 0; i < 3*N; ++i) {
        cin >> A[i];
        vs[A[i]].insert(i);
    }

    VVI dp(3*N+1, VI(3*N+1, -1));
    int ans = 0;
    dp[0][1] = 0;

    for (int i= 0; i < A.size(); ++i) {
       for (int j = i+1; j < A.size(); ++j) {
            if (dp[i][j] == -1) {
                continue;
            }

            ans = max(ans, dp[i][j]);
            solve(dp, A, i, j, (j+1-2)/3*3+2);

            // match i
            solve(dp, A, i, j, getBlockStart(vs, A[i], j));

            // match j
            solve(dp, A, i, j, getBlockStart(vs, A[j], j));
       }
    }

    cout << max(ans, dp[A.size()][A.size()]) << endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
short Memo[900200100];
int X[6060];
int Tmp[6060];
inline int hsh(int pos,int x1,int x2)
{
	int hash=pos*2001*2001+x1*2001+x2;
	return hash%900100100;
}
int N;
int dfs(int x)
{
	if(x>=N)
		return 0;
	if(Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])]!=-1)
		return Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])];
	if(x==N-1)
		return (Tmp[x*3]==Tmp[x*3+1])&&(Tmp[x*3+1]==X[x*3+2]);
	int ans=0;
	int ttmp[5]={0,0,0,0,0};
	ttmp[0]=Tmp[x*3];
	ttmp[1]=Tmp[x*3+1];
	if(!x)
		ttmp[0]=X[0],
		ttmp[1]=X[1];
	for(int i=2;i<5;i++)
		ttmp[i]=X[x*3+i];
	sort(ttmp,ttmp+5);
	do
	{
		Tmp[x*3+3]=ttmp[3];
		Tmp[x*3+4]=ttmp[4];
		ans=max(ans,((ttmp[0]==ttmp[1])&&(ttmp[1]==ttmp[2]))+dfs(x+1));
	}
	while(next_permutation(ttmp,ttmp+5));
	return Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])]=ans;
}
int main()
{
	memset(Memo,-1,sizeof(Memo));
	cin>>N;
	for(int i=0;i<N+N+N;i++)
		cin>>X[i];
	cout<<dfs(0)<<endl;
	return 0;
}

