    vii dp(N+1,vi(N+1,-inf));
    ll ans=0;
    dp[A[0]][A[1]]=dp[A[1]][A[0]]=0;
    vi max(N+1);
    max[A[0]]=max[A[1]]=0;
    rep(i,1,N){
        if(A[i*3]==A[i*3+1]&&A[i*3]==A[i*3+2]){
