        }
        rep(j,0,3){
            ll X=A[i*3+j];
            REP(k,1,N){
                ll Y=max[k];
                dp[X][k]=std::max(dp[X][k],Y);
                dp[k][X]=std::max(dp[k][X],Y);
                max[k]=std::max(max[k],dp[k][X]);
                max[X]=std::max(dp[k][X],max[X]);
            }
        }
        std::map<ll,ll> cnt;
        rep(j,0,3) cnt[A[i*3+j]]++;
        for(auto p:cnt){
