                    max[k]=std::max(max[k],dp[k][X]);
                    max[X]=std::max(max[X],dp[k][X]);
                }
            }
        }
    }
    dp[A[3*N-1]][A[3*N-1]]++;
    ll memo=0;
    REP(i,1,N){
        REP(j,1,N) memo=std::max(memo,dp[i][j]);
    }
    cout<<ans+memo<<endl;
}

