map<pair<ll,pi>, ll> m;

ll dp(ll pos, ll c1, ll c2){
	//cout << pos << " " << c1 << " " << c2 << endl;
	if (m.find(MP(pos, MP(c1, c2))) != m.end()) return m[MP(pos, MP(c1, c2))];
	if (pos == 3*n - 1){
		if (arr[pos] == c1 && c1 == c2) return 1;
		return 0;
	}

	int bb[5];
	bb[0] = c1;
	bb[1] = c2;
	bb[2] = arr[pos];
	bb[3] = arr[pos + 1];
	bb[4] = arr[pos + 2];
	sort(bb, bb + 5);
	if (bb[0] == bb[1] && bb[1] == bb[2]){
		return m[MP(pos, MP(c1, c2))] = 1 + dp(pos + 3, bb[3], bb[4]);
	} else if (bb[1] == bb[2] && bb[2] == bb[3]){
		return m[MP(pos, MP(c1, c2))] = 1 + dp(pos + 3, bb[0], bb[4]);
	} else if (bb[2] == bb[3] && bb[3] == bb[4]){
		return m[MP(pos, MP(c1, c2))] = 1 + dp(pos + 3, bb[0], bb[1]);
	}

	ll ans = 0;
	REP(i, 0, 5){
		REP(j, i + 1, 5){
			int newx, newy;
			if (i == 3){
				newx = c1;
			} else if (i == 4){
				newx = c2;
			} else {
				newx = arr[pos + i]; 
			}
			if (j == 3){
				newy = c1;
			} else if (j == 4){
				newy = c2;
			} else {
				newy = arr[pos + j];
			}
			if (newx > newy) swap(newx, newy);
			ans = max(ans, dp(pos + 3, newx, newy));
		}
	}
	return m[MP(pos, MP(c1, c2))] = ans;
}

