short Memo[100100100];
int X[6060];
int Tmp[6060];
inline int hsh(int pos,int x1,int x2)
{
	long long hash=pos*2020ll*2020ll+x1*2020ll+x2;
	return hash%100100100;
}
int N;
int dfs(int x)
{
	if(Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])]!=-1)
		return Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])];
	if(x==N-1)
		return (Tmp[x*3]==Tmp[x*3+1])&&(Tmp[x*3+1]==X[x*3+2]);
	int ans=0;
	int ttmp[5];
	ttmp[0]=Tmp[x*3];
	ttmp[1]=Tmp[x*3+1];
	if(!x)
		ttmp[0]=X[0],
		ttmp[1]=X[1];
	for(int i=2;i<5;i++)
		ttmp[i]=X[x*3+i];
	sort(ttmp,ttmp+5);
	do
	{
		Tmp[x*3+3]=ttmp[3];
		Tmp[x*3+4]=ttmp[4];
		ans=max(ans,((ttmp[0]==ttmp[1])&&(ttmp[1]==ttmp[2]))+dfs(x+1));
	}
	while(next_permutation(ttmp,ttmp+5));
	return Memo[hsh(x,Tmp[x*3],Tmp[x*3+1])]=ans;
}
