    rep(i, n - 1) {
        int st = i * 3 + 5;
        int laz = 0;
        if(a[st] == a[st + 1] and a[st] == a[st + 2]) laz = 1, lazy++;
        int nxt = ma;
        rep2(j, st, st + 2) {
            int t = -1, s;
            rep2(k, st, st + 2) if(k != j) {
                if(t == -1)
                    t = a[k];
                else
                    s = a[k];
            }
            chmax(nxt, dp[a[j]][a[j]] + 1 - laz);
            int K = max({ma - laz, dp[a[j]][a[j]] + 1 - laz, dp[a[t]][a[s]]});
            mem.eb(t, s, K);
            mem.eb(s, t, K);
        }
        rep(j, 3) b[j] = a[st + j];
        sort(b, b + 3);
        do {
            if(b[0] == b[1]) {
                rep2(i, 1, n) {
