                    int K = max(ma - laz, dp[i][b[2]]);
                    mem.eb(i, b[2], K);
                    mem.eb(b[2], i, K);
                }
            }
        } while(next_permutation(b, b + 3));
        for(auto [e, f, g] : mem) dp[e][f] = g;
