#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

int a[6001];
int d[2][6001][6001];
int n;

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin >> n;
    n *= 3;
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }

    int s = 2;
    queue<pair<int, int>> q;
    q.push({a[0], a[1]});
    int ans = 0;

    for (int i = 0; i < n / 3; i++)
    {
        int t = i % 2;
        int len = q.size();

        for (int j = 0; j <len; j++)
        {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();
            vector<int> v;
            if(s == n - 1){
                if(x == y && y == a[s]){
                    ans = max(ans, d[t][x][y] + 1);
                }
                continue;
            }
            v.push_back(x);
            v.push_back(y);
            v.push_back(a[s]);
            v.push_back(a[s + 1]);
            v.push_back(a[s + 2]);

            for (int k = 1; k < (1 << 5); k++)
            {
                int cnt = 0;
                vector<int> tmp;
                vector<int> tmp2;
                for (int r = 0; r < 5; r++)
                {
                    if (k & (1 << r))
                    {
                        cnt += 1;
                        tmp.push_back(v[r]);
                    }
                    else
                        tmp2.push_back(v[r]);
                }
                if (cnt == 2)
                {
                    if (tmp2[0] == tmp2[1] && tmp2[1] == tmp2[2])
                    {
                        d[1 - t][tmp[0]][tmp[1]] = max(d[1 - t][tmp[0]][tmp[1]], d[t][x][y] + 1);
                    }
                    else
                        d[1 - t][tmp[0]][tmp[1]] = max(d[1 - t][tmp[0]][tmp[1]], d[t][x][y]);

                    ans = max(ans, d[1-t][tmp[0]][tmp[1]]);
                    q.push({tmp[0], tmp[1]});
                }
            }
        }
        s += 3;
    }

    cout << ans <<'\n';

}

