	Int n; cin >> n;
	vector<Int> a(3*n);
	for(auto &i:a) cin >> i;
	for(auto &i:a) --i;
	vector<vector<Int>> dp(n, vector<Int>(n, -1e9));
	Int m = -1e9;
	vector<Int> mx(n, -1e9);
	vector<Int> my(n, -1e9);

	dp[a[0]][a[1]] = 0;
	m = 0;
	mx[a[0]] = 0;
	my[a[1]] = 0;
	Int ans = 0;
	for(int i=0; i<n-1; ++i){
		Int nm = m;
		vector<Int> nmx(mx);
		vector<Int> nmy(my);
		queue<tuple<Int, Int, Int>> qu;
		Int p = a[3*i+2], q = a[3*i+3], r = a[3*i+4];

		if(p==q && q==r){
			++ans;
			continue;
		}

		qu.push(make_tuple(p, q, max({dp[p][1], dp[r][r]+1, m})));
		nm = max(nm, dp[p][q]);
		nmx[p] = max(nmx[p], dp[p][q]);
		nmy[q] = max(nmy[q], dp[p][q]);
		qu.push(make_tuple(q, p, max({dp[q][p], dp[r][r] + 1, m})));
		nm = max(nm, dp[q][p]);
		nmx[q] = max(nmx[q], dp[q][p]);
		nmy[p] = max(nmy[p], dp[q][p]);
		qu.push(make_tuple(q, r, max({dp[q][r], dp[p][p] + 1, m})));
		nm = max(nm, dp[q][r]);
		nmx[q] = max(nmx[q], dp[q][r]);
		nmy[r] = max(nmy[r], dp[q][r]);
		qu.push(make_tuple(r, q, max({dp[r][q], dp[p][p] + 1, m})));
		nm = max(nm, dp[r][q]);
		nmx[r] = max(nmx[r], dp[r][q]);
		nmy[q] = max(nmy[q], dp[r][q]);
		qu.push(make_tuple(r, p, max({dp[r][p], dp[q][q] + 1, m})));
		nm = max(nm, dp[r][p]);
		nmx[r] = max(nmx[r], dp[r][p]);
		nmy[p] = max(nmy[p], dp[r][p]);
		qu.push(make_tuple(p, r, max({dp[p][r], dp[q][q] + 1, m})));
		nm = max(nm, dp[p][r]);
		nmx[p] = max(nmx[p], dp[p][r]);
		nmy[r] = max(nmy[r], dp[p][r]);

		for(int x=0; x<n; ++x){
			if(q == r){
				qu.push(make_tuple(x, p, max(dp[x][p], max(my[q], my[r]) + 1)));
				nm = max(nm, dp[x][p]);
				nmx[x] = max(nmx[x], dp[x][p]);
				nmy[p] = max(nmy[p], dp[x][p]);
				qu.push(make_tuple(p, x, max(dp[p][x], max(my[q], my[r]) + 1)));
				nm = max(nm, dp[p][x]);
				nmx[p] = max(nmx[p], dp[p][x]);
				nmy[x] = max(nmy[x], dp[p][x]);
			}
			if(r == p){
				qu.push(make_tuple(x, q, max(dp[x][q], max(my[r], my[p]) + 1)));
				nm = max(nm, dp[x][q]);
				nmx[x] = max(nmx[x], dp[x][q]);
				nmy[q] = max(nmy[q], dp[x][q]);
				qu.push(make_tuple(q, x, max(dp[q][x], max(my[r], my[p]) + 1)));
				nm = max(nm, dp[q][x]);
				nmx[q] = max(nmx[q], dp[q][x]);
				nmy[x] = max(nmy[x], dp[q][x]);
			}
			if(p == q){
				qu.push(make_tuple(x, r, max(dp[x][r], max(my[p], my[q]) + 1)));
				nm = max(nm, dp[x][r]);
				nmx[x] = max(nmx[x], dp[x][r]);
				nmy[r] = max(nmy[r], dp[x][r]);
				qu.push(make_tuple(r, x, max(dp[r][x], max(my[p], my[q]) + 1)));
				nm = max(nm, dp[r][x]);
				nmx[r] = max(nmx[r], dp[r][x]);
				nmy[x] = max(nmy[x], dp[r][x]);
			}
		}
		for(int y=0; y<n; ++y){
			if(q == r){
				qu.push(make_tuple(y, p, max(dp[y][p], max(mx[q], mx[r]) + 1)));
				nm = max(nm, dp[y][p]);
				nmx[y] = max(nmx[y], dp[y][p]);
				nmy[p] = max(nmy[p], dp[y][p]);
				qu.push(make_tuple(p, y, max(dp[p][y], max(mx[q], mx[r]) + 1)));
				nm = max(nm, dp[p][y]);
				nmx[p] = max(nmx[p], dp[p][y]);
				nmy[y] = max(nmy[y], dp[p][y]);
			}
			if(r == p){
				qu.push(make_tuple(y, q, max(dp[y][q], max(mx[r], mx[p]) + 1)));
				nm = max(nm, dp[y][q]);
				nmx[y] = max(nmx[y], dp[y][q]);
				nmy[q] = max(nmy[q], dp[y][q]);
				qu.push(make_tuple(q, y, max(dp[q][y], max(mx[r], mx[p]) + 1)));
				nm = max(nm, dp[q][y]);
				nmx[q] = max(nmx[q], dp[q][y]);
				nmy[y] = max(nmy[y], dp[q][y]);
			}
			if(p == q){
				qu.push(make_tuple(y, r, max(dp[y][r], max(mx[p], mx[q]) + 1)));
				nm = max(nm, dp[y][r]);
				nmx[y] = max(nmx[y], dp[y][r]);
				nmy[r] = max(nmy[r], dp[y][r]);
				qu.push(make_tuple(r, y, max(dp[r][y], max(mx[p], mx[q]) + 1)));
				nm = max(nm, dp[r][y]);
				nmx[r] = max(nmx[r], dp[r][y]);
				nmy[y] = max(nmy[y], dp[r][y]);
			}
		}

		while(!qu.empty()){
			tuple<Int, Int, Int> t = qu.front();
			qu.pop();
			dp[get<0>(t)][get<1>(t)] = max(dp[get<0>(t)][get<1>(t)], get<2>(t));
		}
		m = nm;
		mx.swap(nmx);
		my.swap(nmy);
	}

	Int ma = 0;
	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j)
			ma = max(ma, dp[i][j] + (i==j && j==a[3*n-1]));
	ans += ma;
	cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int n;
int a[6005];
int pos[2005];
int nxt[6005], prv[6005];
int cur[5] = {0, 1, 2, 3, 4};
bool isIn[6005], isSmaller[6005];
int ans;

bool comp(int l, int r) {
	int curl, curr;
	if (isIn[cur[l]]) {
		if (isSmaller[cur[l]]) curl = nxt[nxt[cur[l]]];
		else curl = nxt[cur[l]];
	} else curl = nxt[nxt[cur[l]]];
	if (isIn[cur[r]]) {
		if (isSmaller[cur[r]]) curr = nxt[nxt[cur[r]]];
		else curr = nxt[cur[r]];
	} else curr = nxt[nxt[cur[r]]];
	return curl > curr;
}

int main() {
	scanf("%d", &n);
	for (int i = 0; i < 3 * n; i++) {
		scanf("%d", &a[i]);
	}
	memset(pos, -1, sizeof pos);
	for (int i = 3 * n - 1; i >= 0; i--) {
		nxt[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	memset(pos, -1, sizeof pos);
	for (int i = 0; i < 3 * n; i++) {
		prv[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	int ptr = 5;
	for (int i = 1; i < n; i++) {
		bool done = false;
		for (int j = 0; j < 5; j++) for (int k = j + 1; k < 5; k++) for (int l = k + 1; l < 5; l++) {
			if (a[cur[j]] == a[cur[k]]  && a[cur[k]] == a[cur[l]]) {
				ans++;
				cur[j] = ptr++;
				cur[k] = ptr++;
				cur[l] = ptr++;
				done = true;
			}
		}
		if (done) continue;

		for (int j = 0; j < 5; j++) for (int k = j + 1; k < 5; k++) if (nxt[cur[j]] == cur[k]) {
			isIn[cur[j]] = true, isIn[cur[k]] = true;
			if (cur[j] < cur[k]) isSmaller[cur[j]] = true;
			else isSmaller[cur[k]] = true;
		}

		sort(cur, cur + 5, comp);
		for (int j = 0; j < 3; j++) {
			nxt[prv[cur[j]]] = nxt[cur[j]];
			cur[j] = ptr++;
		}
	}
	bool toadd = true;
	int val = -1;
	for (int i = 0; i < 5; i++) {
		if (cur[i] < 3 * n) {
			if (val == -1) {
				val = a[cur[i]];
				continue;
			}
			if (val != a[cur[i]]) {
				toadd = false;
				break;
			}
		}
	}
	if (toadd) ans++;
	printf("%d\n", ans);
	return 0;
}

