            dp[z][z]=max(dp[z][z],dp[y][y]+1);
            rep(k,n+1){
                if(k==z) continue;
                dp[k][y]=max(dp[k][y],dp[k][z]+1);
                dp[k][y]=max(dp[k][y],dp[z][k]+1);
            }
            ma[z]=max(ma[z],dp[z][z]);
            rep(k,n+1) {
                ma[k]=max(ma[k],dp[k][y]);
                ma[y]=max(ma[y],dp[k][y]);
                M=max(M,ma[k]);
            }
        }
        else{
            dp[y][z]=M;
            dp[x][z]=M;
            dp[x][y]=M;
            dp[y][z]=max(dp[y][z],dp[x][x]+1);
            dp[x][z]=max(dp[x][z],dp[y][y]+1);
            dp[x][y]=max(dp[x][y],dp[z][z]+1);
            rep(k,n+1){
                dp[k][x]=max(dp[k][x],ma[k]);
                dp[k][y]=max(dp[k][y],ma[k]);
                dp[k][z]=max(dp[k][z],ma[k]);
            }
            ma[x]=max(ma[x],dp[x][y]);
            ma[y]=max(ma[x],dp[x][y]);
            ma[y]=max(ma[x],dp[y][z]);
            ma[z]=max(ma[x],dp[y][z]);
            ma[z]=max(ma[x],dp[x][z]);
            ma[x]=max(ma[x],dp[x][z]);
            M=max(M,ma[x]);
            M=max(M,ma[y]);
            M=max(M,ma[z]);
        }
        // rep(i,n+1){
        //     rep(j,n+1){
        //         cout << i << " " << j << " " << dp[i][j] << endl;
        //     }
        // }
    }
    int ans=0;
    rep(i,n+1){
        rep(j,n+1){
            ans=max(ans,c+dp[i][j]);
        }
    }
    cout << ans << endl;
}

