      dp[i][j] = -INF;
  dp[1][2] = 0;
  for (int i = 1; i <= 3 * N; i++) {
    for (int j = i + 1; j <= 3 * N; j++) {
      Transition(i, j, (j + 3) / 3 * 3);
      if (j / 3 * 3 < nxt[i] / 3 * 3)
        Transition(i, j, nxt[i] / 3 * 3);
      if (j / 3 * 3 < nxt[j] / 3 * 3)
        Transition(i, j, nxt[j] / 3 * 3);
    }
  }
  cout << ans + base << "\n";
  return 0;
}

