int a[N * 3], f[N][N], g[N], gt[N], ans;
void update(int x, int y, int t) {
    f[x][y] = max(f[x][y], t);
    ans = max(ans, t);
    gt[x] = max(gt[x], t);
    gt[y] = max(gt[y], t);
}
int main() {
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= 3 * n; i++) scanf("%d", &a[i]);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) f[i][j] = -INF;
    for (int i = 1; i <= n; i++) gt[i] = -INF;
    update(a[1], a[2], 0);
    for (int j = 1; j <= n; j++) g[j] = gt[j];
    int cnt = 0;
    for (int i = 1; i < n; i++) {
        int x = a[i * 3], y = a[i * 3 + 1], z = a[i * 3 + 2];
        if (x == y && x == z) {
            cnt++;
            continue;
        }
        for (int j = 1; j <= n; j++) {
            update(j, x, g[j]);
            update(j, y, g[j]);
            update(j, z, g[j]);
        }
        update(x, y, ans);
        update(x, z, ans);
        update(y, z, ans);
        if (x == y || x == z || y == z) {
            if (x == z) swap(y, z);
            if (y == z) swap(x, z);
            for (int j = 1; j <= n; j++) {
                update(j, z, max(f[j][x], f[x][j]) + 1);
