        update(x, z, f[y][y] + 1);
        update(y, z, f[x][x] + 1);
        for (int j = 1; j <= n; j++) g[j] = gt[j];
    }
    ans = max(ans, f[a[n * 3]][a[n * 3]] + 1);
    printf("%d\n", ans + cnt);
