  }
  for(int i = 0; i < N; ++i)
    reverse(B[i].begin(), B[i].end());
  sort(B.begin(), B.end());

  auto f = [](int a, int b){
    return max(a,b);
  };
  auto g = [](int a, int b){
    return a+b;
  };
  LazySegmentTree st(f,g,g,0,0);
  vector<int> ini(N);
