void upd(int a, int b, int c, int N, int bst) {
    //replace (i, j) with (a, b)
    //replace 2
    tdp[b][a] = tdp[a][b] = max({tdp[a][b], bst, dp[c][c] + 1});
    //replace 1
    for (int i = 1; i <= N; i++) {
        //replace x in (x, i) with a
        int offs = 0;
        if (b == c) offs = 1;
        tdp[a][i] = tdp[i][a] = max({tdp[a][i], bst1[i], dp[b][i] + offs});
    }
}



int main() {
    int N;
    scanf("%d", &N);
    for (int i = 0; i < 3 * N; i++)
        scanf("%d", &A[i]);
    for (int i = 0; i <= N; i++) {
        bst1[i] = -INF;
        for (int j = 0; j <= N; j++)
            dp[i][j] = -INF;
    }
    dp[A[1]][A[0]] = dp[A[0]][A[1]] = 0;
    bst1[A[0]] = bst1[A[1]] = 0;
    int bst = 0, offs = 0;
    for (int i = 0; i < N - 1; i++) {
        int a = A[3 * i + 2], b = A[3 * i + 3], c = A[3 * i + 4];
        if (a == b && b == c) {
            offs++;
            continue;
        }
        upd(a, b, c, N, bst);
        upd(b, c, a, N, bst);
        upd(c, a, b, N, bst);
        for (int i = 1; i <= N; i++) {
            bst = max({bst, tdp[a][i], tdp[b][i], tdp[c][i]});
            dp[a][i] = dp[i][a] = tdp[a][i];
            dp[b][i] = dp[i][b] = tdp[b][i];
            dp[c][i] = dp[i][c] = tdp[c][i];
            bst1[i] = max({bst1[i], tdp[a][i], tdp[b][i], tdp[c][i]});
        }
        for (int i = 1; i <= N; i++) {
            tdp[a][i] = tdp[i][a] = -INF;
            tdp[b][i] = tdp[i][b] = -INF;
            tdp[c][i] = tdp[i][c] = -INF;
        }
    }
    int ans = 0;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++) {
            //printf("i = %d j = %d dp = %d\n", i, j, dp[i][j]);
            ans = max(ans, dp[i][j]);
        }
    printf("%d\n", max(ans, dp[A[3 * N - 1]][A[3 * N - 1]] + 1) + offs);
    return 0;
}
