#include<bits/stdc++.h>
using namespace std;
const int N=6006;
int n,ans,u,a[N];
multiset<int>s[2];
multiset<int>::iterator it;
bool cou(int u,int x)
{
    return s[u].size()&&s[u].count(x);
}
bool cou2(int u,int x)
{
    if(s[u].size()<=1||!s[u].count(x)) return false;
    s[u].erase(s[u].find(x));
    bool ans=s[u].count(x);
    s[u].insert(x);
    return ans;
}
vector<int>v;
void sol2()
{
    int sum=0,pos=-1;
    for(int i=0;i<v.size();i++)
        if(cou2(u,v[i]))
        sum++,pos=i;
    ans+=sum>=1;
    if(sum>=1)
    {
        s[u].clear();s[u^1].clear();
        for(int i=0;i<v.size();i++)
            if(pos!=i) s[u].insert(v[i]);
    }
    else
    {
        for(int i=0;i<v.size();i++)
            s[u].insert(v[i]);
    }
}
void sol1()
{
    if(v[1]==v[2]) swap(v[0],v[2]);
    if(cou(u^1,v[0])&&cou(u,v[0]))
    {
        ans++;
        s[u^1].erase(v[0]);
        s[u].insert(v[2]);
    }
    else if(cou(u^1,v[0]))
    {
        ans++;
        s[u^1].clear();
        s[u].insert(v[2]);
    }
    else if(cou(u,v[0]))
    {
        ans++;
        s[u].erase(s[u].find(v[0]));
        for(it=s[u].begin();it!=s[u].end();it++)
            s[u^1].insert(*it);
        s[u].clear();
        s[u].insert(v[2]);
    }
    else sol2();
}
void sol()
{
    for(int i=6;i<=n*3;i+=3)
        if(i==n*3)
        {
            if(cou(u,a[i])&&cou(u^1,a[i])) ans++;
            else if(cou2(u,a[i])) ans++;
        }
        else
        {
            v.clear();
            v.push_back(a[i]);
            v.push_back(a[i+1]);
            v.push_back(a[i+2]);
            sort(v.begin(),v.end());
            if(v[0]==v[1]&&v[1]==v[2]) ans++;
            else if(v[0]==v[1]||v[1]==v[2]) sol1();
            else sol2();
        }
}
