{
    scanf("%d",&n);
    for(int i=1;i<=n*3;i++)
        scanf("%d",&a[i]);
    if(n==1)
    {
        printf("%d\n",a[1]==a[2]&&a[2]==a[3]);
        return 0;
    }
    vector<int>v;
    for(int i=1;i<=5;i++)
        v.push_back(a[i]);
    sort(v.begin(),v.end());
    bool vis[6];memset(vis,false,sizeof(vis));
    for(int i=0;i<=2;i++)
        if(v[i]==v[i+1]&&v[i+1]==v[i+2])
    {
        vis[i]=vis[i+1]=vis[i+2]=true;
        break;
    }
    for(int i=0;i<v.size();i++)
        if(!vis[i]) s[u].insert(v[i]);
    ans+=s[u].size()==2;
    sol();
    printf("%d\n",ans);
}

