bool comp(int l, int r) {
	int curl, curr;
	if (isIn[l]) {
		if (isSmaller[l]) curl = nxt[nxt[l]];
		else curl = nxt[l];
	} else curl = nxt[nxt[l]];
	if (isIn[r]) {
		if (isSmaller[r]) curr = nxt[nxt[r]];
		else curr = nxt[r];
	} else curr = nxt[nxt[r]];
	return curl > curr;
}

