	for (int i = 0; i < 3 * n; i++) {
		scanf("%d", &a[i]);
	}
	for (int i = 1; i <= n; i++) pos[i] = 3 * n + 1;
	for (int i = 3 * n - 1; i >= 0; i--) {
		nxt[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	for (int i = 1; i <= n; i++) pos[i] = 3 * n + 1;
	for (int i = 0; i < 3 * n; i++) {
		prv[i] = pos[a[i]];
		pos[a[i]] = i;
	}
