		for (int j = 0; j < 5; j++) for (int k = j + 1; k < 5; k++) if (nxt[cur[j]] == cur[k]) {
			isIn[cur[j]] = true, isIn[cur[k]] = true;
			if (cur[j] < cur[k]) isSmaller[cur[j]] = true;
			else isSmaller[cur[k]] = true;
		}

		sort(cur, cur + 5, comp);
		for (int j = 0; j < 3; j++) {
			nxt[prv[cur[j]]] = nxt[cur[j]];
			cur[j] = ptr++;
