                chmax({j,D[0]},dp[j][D[2]]+1);
            }
        }
        //パターン3 (来たやつ全部違う)
        if(D[0]!=D[1] && D[1]!=D[2] && D[2]!=D[0]){
            chmax({D[1],D[2]},dp[D[0]][D[0]]+1);
            chmax({D[0],D[2]},dp[D[1]][D[1]]+1);
            chmax({D[0],D[1]},dp[D[2]][D[2]]+1);
        }


        //ここからは得にならない遷移
        //パターン4 (来たやつそのまま受け流す(ナベアツ))
        //in-placeにつきコード不要

        //パターン5 (来たやつ1つ受け取る)
        REP(j,maxA){
            REP(k,3){
                chmax({j,D[k]},mx[j]);
            }
        }
        //パターン6 (来たやつ2つ受け取る)
        chmax({D[0],D[1]},mxa);
        chmax({D[0],D[2]},mxa);
        chmax({D[1],D[2]},mxa);

        reflect();

    }
    //最後の1回
    dp[r][r]++;
    mx[r]=max(mx[r],dp[r][r]);
    mxa=max(mxa,mx[r]);

    cout << mxa+Ans << endl;

    return 0;
}

