		printf("%d\n", a[0] == a[1] && a[1] == a[2]);
		return 0;
	}	

	mx = -0x3f3f3f3f;
	FOR(i, 0, n) FOR(j, 0, n)
		dp[i][j] = -0x3f3f3f3f;
	FOR(i, 0, n)
		cmx[i] = -0x3f3f3f3f;
