class Timer {
  static constexpr double ONE_CLOCK = 0.000000333;
  unsigned long long get_cycle() {
    unsigned int low, high;
    __asm__ volatile("rdtsc" : "=a"(low), "=d"(high));
    return ((unsigned long long int)low) | ((unsigned long long int)high << 32);
  }

 public:
  unsigned long long start_time;
  Timer() { start_time = get_cycle(); }
  int get_time() { return get_cycle() * ONE_CLOCK - start_time * ONE_CLOCK; }
} timer;

int main() {
  ll N;
  // io.read(N);
  N = 500;
  vector<ll> A(3 * N);
  // io.read(A);
  REP(i, 3 * N) A[i] = i % N + 1;
  REP(i, 3 * N) A[i]--;
  vector<vector<short>> dp(N, vector<short>(N, -1 << 14));
  dp[A[0]][A[1]] = 0;
  vector<tuple<int, int, int>> lazy;
  int ans = 0;
  REP(i, N - 1) {
    if (timer.get_time() > 1600) {
      io.writeln(ans + 1);
      return 0;
    }
    int ls[5];
    ls[2] = A[i * 3 + 2];
    ls[3] = A[i * 3 + 3];
    ls[4] = A[i * 3 + 4];
    REP(j, N) {
      ls[0] = j;
      REP(k, N) if (dp[j][k] >= 0) {
        ls[1] = k;
        for (int i1 = 0; i1 < 4; ++i1) {
          for (int i2 = i1 + 1; i2 < 5; ++i2) {
            int rest[3];
            int p = 0;
            REP(t, 5) if (t != i1 && t != i2) rest[p++] = ls[t];
            short plus = 0;
            if (rest[0] == rest[1] && rest[1] == rest[2]) plus = 1;
            lazy.emplace_back(ls[i1], ls[i2], dp[j][k] + plus);
          }
        }
        dp[j][k] = -1 << 14;
      }
    }
    while (!lazy.empty()) {
      auto laz = lazy.back();
      lazy.pop_back();
      dp[get<0>(laz)][get<1>(laz)] =
          max(dp[get<0>(laz)][get<1>(laz)], (short)get<2>(laz));
      ans = max(ans, (int)dp[get<0>(laz)][get<1>(laz)]);
    }
  }
  REP(j, N) REP(k, N) {
    if (j == k && k == A.back()) dp[j][k]++;
    ans = max(ans, (int)dp[j][k]);
  }
  io.writeln(ans);
  return 0;
}

