int solve(int l1, int l2, int i)
{
  if (i == n - 1)
  {
    int ans = l1 == l2 && l2 == v[i];
    //cout << "dp[" << l1 << "][" << l2 << "][" << i << "] = " << ans << endl;
    return ans;
  }
  if (dp.count(mt(l1, l2, i)))
    return dp[mt(l1, l2, i)];
  int &ans = dp[mt(l1, l2, i)];

  ans = -1;
  vector<int> choose;
  choose.pb(l1);
  choose.pb(l2);
  for (int x = i; x < i + 3; x++)
    choose.pb(v[x]);

  rep(n1, 0, 5, 1)
  {
    rep(n2, n1 + 1, 5, 1)
    {
      int rem = -1;
      int cnt = 0;
      for (int x = 0; x < choose.size(); x++)
      {
        if (x == n1 || x == n2)
          continue;
        if (rem != choose[x])
        {
          rem = choose[x];
          cnt = 1;
        }
        else
        {
          cnt++;
        }
      }
      ans = max(ans, solve(choose[n1], choose[n2], i + 3) + (cnt == 3));
    }
  }
  //cout << "dp[" << l1 << "][" << l2 << "][" << i << "] = " << ans << endl;
  return ans;
}

