            if(erased<3){
                ll d = min(3-erased,mp[val[j].second]);
                mp[val[j].second]-=d;
                erased+=d;
            }
            if(erased>3){
                return -1;
            }
        }
    }
    mp[A.back()]++;
    for(auto itr = mp.begin();itr != mp.end();itr++){
        // cerr <<"itr.first=" <<itr->first <<" second =" << itr->second << endl;
            if(itr->second >=3){
                mp[itr->first] -= 3;
                ans++;
                break;
            }
    }
    cout << ans << endl;

    return 0;
}

