			}
			dp[a[i]][a[j]] = dp[a[j]][a[i]] = minj == maxj;
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			MAXJ = max(MAXJ, dp[i][j]);
			row[i] = max(row[i], dp[i][j]);
		}
