		if (x == y && y == z) {
			base++;
			for (int j = 0; j < n; j++) {
				ndp[x][j] = ndp[j][x] = max(dp[x][j], max(query(j) - 1, dp[j][x]));
			}
			ndp[x][x] = max(ndp[x][x], Query() - 1);
		} else {
			if (x == z) swap(z, y);
			if (y == z) swap(x, z);
			if (x == y) {
				for (int j = 0; j < n; j++) {
					ndp[z][j] = ndp[j][z] = max(dp[z][j], max(query(j), dp[j][x] + 1));
					ndp[x][j] = ndp[j][x] = max(dp[x][j], query(j));
				}
