				ndp[x][x] = max(ndp[x][x], max(Query(), dp[z][z] + 1));
			} else {
				for (int j = 0; j < n; j++) {
					ndp[x][j] = ndp[j][x] = max(dp[x][j], query(j));
					ndp[y][j] = ndp[j][y] = max(dp[y][j], query(j));
