				ndp[x][z] = ndp[z][x] = max(ndp[x][z], max(Query(), dp[y][y] + 1));
				ndp[y][z] = ndp[z][y] = max(ndp[y][z], max(Query(), dp[x][x] + 1));
			}
		}
		for (int j = 0; j < n; j++) {
			modify(x, j), modify(j, x);
