			additionalPoint++;
			continue;
		}

		vector<tiii> changeQueue;

		do {
			int a = nxt[0], b = nxt[1], c = nxt[2];
			// dp[i][x][y] -> dp[i + 1][x][a]
			rep(x, 1, N + 1) {
