int main() {
	int N;
	cin >> N;
	vector<int> A(3*N + 3, 0);
	int baseScore = 1;
	cin >> A[1];
	cin >> A[2];
	for (int i = 1; i < N; i++){
		int a1, a2, a3;
		cin >> a1 >> a2 >> a3;
		if(a1 == a2 && a2 == a3){
			baseScore++;
			i--;
			N--;
		}else{
			A[3*i  ] = a1;
			A[3*i+1] = a2;
			A[3*i+2] = a3;
		}
	}
	cin >> A[3*N];

	vector<vector<int> > dp(N+1,vector<int>(N+1,0));
	vector<int> maxScore(N+2,0);
	vector<vector<int> > maxLeft(N+2,vector<int>(N+1,0)); // i,aのmax
	dp[A[1]][A[2]] = baseScore;
	dp[A[2]][A[1]] = baseScore;
	maxScore[1] = baseScore;
	maxLeft[1][A[1]] = baseScore;
	maxLeft[1][A[2]] = baseScore;
	for(int i = 1; i <= N; i++){
		// i+1のレイヤーを考える。
		int x = A[3*i];
		int y = A[3*i+1];
		int z = A[3*i+2];
		// dp[z][z], dp{x][x], dp[y][y] をとっておく}
		int dpzz =dp[z][z];
		int dpxx =dp[x][x];
		int dpyy =dp[y][y];
		// a,b 残しはすでに値が入っている。
		// a,x 残し
		int maxLeftMax = 0;
		for(int j = 1; j <= N; j++){
			int p = maxLeft[i][j];
			maxLeftMax = (p < maxLeftMax ? maxLeftMax : p);
			dp[j][x] = p;
			dp[j][y] = p;
			dp[j][z] = p;
			dp[x][j] = p;
			dp[y][j] = p;
			dp[z][j] = p;
			maxLeft[i+1][j] = p;
		}
		maxLeft[i+1][x] = maxLeftMax;
		maxLeft[i+1][y] = maxLeftMax;
		maxLeft[i+1][z] = maxLeftMax;
		// 但し、x=y, y=z, z=xのときのみ加算がある。
		if(x == y || y == z || z == x){
			int xx = (x == y ? x : 0) + (y == z ? y : 0) + (z == x ? z : 0);
			int zz = (x == y ? z : 0) + (y == z ? x : 0) + (z == x ? y : 0);
			if(maxLeft[i][xx] > 0){
				for(int j = 1; j <= N; j++){
					if(xx != j && dp[xx][j] > 0){
						dp[j][zz] = dp[xx][j] + 1;
						dp[zz][j] = dp[xx][j] + 1;
						maxLeft[i+1][zz] = ( maxLeft[i][xx] < dp[zz][j] ? dp[zz][j] : maxLeft[i][xx]);
					}
				}
			}
		}
		// (x,y), (y,z), (z,x)
		dp[x][y] = ( maxScore[i] < dpzz + 1 ? dpzz + 1 : maxScore[i]);
		dp[y][x] = ( maxScore[i] < dpzz + 1 ? dpzz + 1 : maxScore[i]);
		dp[y][z] = ( maxScore[i] < dpxx + 1 ? dpxx + 1 : maxScore[i]);
		dp[z][y] = ( maxScore[i] < dpxx + 1 ? dpxx + 1 : maxScore[i]);
		dp[z][x] = ( maxScore[i] < dpyy + 1 ? dpyy + 1 : maxScore[i]);
		dp[x][z] = ( maxScore[i] < dpyy + 1 ? dpyy + 1 : maxScore[i]);
		maxScore[i+1] = (maxScore[i] < dp[x][y] ? dp[x][y] : maxScore[i]);
		maxScore[i+1] = (maxScore[i+1] < dp[y][z] ? dp[y][z] : maxScore[i+1]);
		maxScore[i+1] = (maxScore[i+1] < dp[z][x] ? dp[z][x] : maxScore[i+1]);
	}

	cout << maxScore[N+1] - 1 << endl;
	return(0);
}

