            int x = up[j].x, y = up[j].y;
            L[x][y] = L[y][x] = dp[x][y];
            Max = max(Max, dp[x][y]), S[x] = max(S[x], dp[x][y]), S[y] = max(S[y], dp[x][y]);
        }
    }
    printf("%d", max(Max, dp[a[n * 3]][a[n * 3]] + 1) + ans);
    return 0;
}

