    vector<int> A(3*N); cin >> A;
    if (N==1){
        cout << (A[0]==A[1]&&A[1]==A[2]) << '\n';
        return 0;
    }

    vector<vector<int>> dp(N+1,vector<int>(N+1,-INF));
    dp[0][0]=0;
    vector<int> Max_rest(N+1,-INF);
    int same=0,Max=0;
    for (int i=0;i<N-1;++i){
        if (!i){
            for (int j=0;j<5;++j){
                for (int k=j+1;k<5;++k){
                    set<int> s;
                    for (int l=0;l<5;++l){
                        if (l!=j&&l!=k){
                            s.emplace(A[l]);
                        }
                    }
                    chmax(dp[A[j]][A[k]],(s.size()==1));
                    chmax(Max_rest[A[j]],dp[A[j]][A[k]]);
                    chmax(Max_rest[A[k]],dp[A[j]][A[k]]);
                }
            }
        } else {
            vector<int> v={A[3*i+2],A[3*i+3],A[3*i+4]};
            if (v[0]==v[1]&&v[1]==v[2]){++same; continue;}
            vector<int> nxt(N+1,0);
            map<pair<int,int>,int> DP;
            auto f=[&](int x,int y,int z){
                if (!DP.count({x,y})) DP[{x,y}]=-INF;
                chmax(DP[{x,y}],z);
            };
            auto two_same=[&](int p,int q){
                int x=v[p],rest=v[3-p-q];
                for (int j=1;j<=N;++j){
                    f(j,rest,dp[x][j]+1);
                    f(j,rest,dp[j][x]+1);
                }
            };
            for (int j=0;j<3;++j){
                for (int k=j+1;k<3;++k){
                    if (v[j]==v[k]){
                        two_same(j,k);
                    }
                }
            }

            auto one_same=[&](int p){
                int x=v[p];
                vector<int> rest;
                for (int j=0;j<3;++j){
                    if (p!=j) rest.emplace_back(v[j]);
                }
                f(rest[0],rest[1],dp[x][x]+1);
            };
            for (int j=0;j<3;++j) one_same(j);

            for (int j=1;j<=N;++j){
                for (int k=0;k<3;++k){
                    f(j,v[k],Max_rest[j]);
                }
            }

            for (int j=0;j<3;++j){
                for (int k=j+1;k<3;++k){
                    f(v[j],v[k],Max);
                }
            }

            for (auto p:DP){
