inline void chmax(int &x,int y){x=max(x,y);}

inline void update(int x,int y,int t){
//	printf("upd %d %d %d\n",x,y,t);
	chmax(dp[x][y],t);
	chmax(dp[y][x],t);
	chmax(mx[x],t);
