			if(nY[c]<now)nY[c]=now;
		}
		for(int j=0;j<3;j++)for(int k=0;k<3;k++)if(j!=k)
		{
			int a=A[j],b=A[k];
			int now=dp[a][b]=max(dp[a][b],MX);
			if(nX[a]<now)nX[a]=now;
			if(nY[b]<now)nY[b]=now;
		}
		for(int j=0;j<N;j++)
		{
			for(int k=0;k<3;k++)
			{
