	for(map<pair<int,int>,int>::iterator it=dp[n-1].begin();it!=dp[n-1].end();it++)
	{
		int x=it->first.first,y=it->first.second;
		ans=max(ans,it->second+(x==y && x==a[3*n-1] && y==a[3*n-1]));
	}
	cout<<ans<<endl;
	return 0;
}

