using namespace std;
int main()
{
	long long N;
	cin >> N;

	map<long long, long long> numbers;
	vector<long long> cards;
	for (long long i = 0u; i < N*3; ++i)
	{
		long long n;
		cin >> n;
		cards.push_back(n);
		if (numbers.find(n) == numbers.end())
		{
			numbers[n] == 1;
		}
		else
		{
			numbers[n]++;
		}
	}

	long long idx = 0;
	long long result = 0;
	while (idx < N * 3 - 3)
	{
		map<long long, long long> tempN;
		bool is3Exists = false;
		long long foundNum = 0;
		for (long long i = idx; i < idx + 5; ++i)
		{
			if (tempN.find(cards[i]) == tempN.end())
			{
				tempN[cards[i]] = 1;
			}
			else
			{
				tempN[cards[i]]++;
				if (tempN[cards[i]] == 3)
				{
					is3Exists = true;
					foundNum = cards[i];
					break;
				}
			}
		}

		if (is3Exists)
		{
			vector<bool> isTarget(5, false);
			for (long long i = idx; i < idx + 5; ++i)
			{
				if (cards[i] == foundNum)
				{
					isTarget[i - idx] = true;
				}
				else
				{
					isTarget[i - idx] = false;
				}
			}

			for (long long i = idx + 3; i < idx + 5; ++i)
			{
				if (isTarget[i - idx])
				{
					for (long long j = 0; j < 3; ++j)
					{
						if (!isTarget[j])
						{
							long long temp = cards[idx + j];
							cards[idx + j] = cards[i];
							cards[i] = temp;
						}
					}
				}
			}

			result += 1;
		}

		idx += 3;
	}

	if ((cards[idx] == cards[idx + 1]) && (cards[idx] == cards[idx + 2]))
	{
		result += 1;
	}

	cout << result << endl;
}

