	}
	FOR(i,1,6)
	FOR(j,i+1,6){
		vector<int>g;
		FOR(k,1,6)if(k!=i && k!=j)g.push_back(a[k]);
		if(g[0]==g[1] && g[1]==g[2])dp[min(a[i],a[j])][max(a[i],a[j])]=1,mx[a[i]]=mx[a[j]]=1;else dp[min(a[i],a[j])][max(a[i],a[j])]=0,mx[a[i]]=max(mx[a[i]],0),mx[a[j]]=max(mx[a[j]],0);
	}
	FOR(i,1,6){
		if(inlis[a[i]])continue;
		inlis[a[i]]=1;
		lis.push_back(a[i]);
	}
	int i=6;
	while(i+2<=3*n){
		vector<Node>g;
		if(a[i]==a[i+1] && a[i+1]==a[i+2]){
			if(!inlis[a[i]]){
				inlis[a[i]]=1;
				lis.push_back(a[i]);
				FOR(j,0,lis.size()){
					dp[min(lis[j],a[i])][max(lis[j],a[i])]=max(mx[lis[j]],0);
					mx[lis[j]]=max(mx[lis[j]],dp[min(lis[j],a[i])][max(lis[j],a[i])]);
					mx[a[i]]=max(mx[a[i]],dp[min(lis[j],a[i])][max(lis[j],a[i])]);
				}
			}
			ans++;
			i+=3;
			continue;
		}
		else if(a[i]==a[i+1]){
			swap(a[i],a[i+2]);
		}else if(a[i]==a[i+2]){
			swap(a[i],a[i+1]);
		}
		if(a[i+1]==a[i+2]){
			FOR(j,1,n+1)g.push_back(Node{min(j,a[i]),max(j,a[i]),max(dp[min(j,a[i])][max(j,a[i])],dp[min(a[i+1],j)][max(a[i+1],j)]+1)});
			g.push_back(Node{a[i+1],a[i+1],max(dp[a[i+1]][a[i+1]],dp[a[i]][a[i]]+1)});
			if(!inlis[a[i+1]]){
				inlis[a[i+1]]=1;
				lis.push_back(a[i+1]);
				FOR(j,0,lis.size()){
					g.push_back(Node{min(lis[j],a[i+1]),max(lis[j],a[i+1]),max(mx[lis[j]],0)});
				}
			}
			if(!inlis[a[i]]){
				inlis[a[i]]=1;
				lis.push_back(a[i]);
				FOR(j,0,lis.size()){
					g.push_back(Node{min(lis[j],a[i]),max(lis[j],a[i]),max(mx[lis[j]],0)});
				}
			}
		}else{
			g.push_back(Node{min(a[i+1],a[i+2]),max(a[i+1],a[i+2]),max(dp[min(a[i+1],a[i+2])][max(a[i+1],a[i+2])],dp[a[i]][a[i]]+1)});
			g.push_back(Node{min(a[i],a[i+1]),max(a[i],a[i+1]),max(dp[min(a[i],a[i+1])][max(a[i],a[i+1])],dp[a[i+2]][a[i+2]]+1)});
			g.push_back(Node{min(a[i],a[i+2]),max(a[i],a[i+2]),max(dp[min(a[i],a[i+2])][max(a[i],a[i+2])],dp[a[i+1]][a[i+1]]+1)});
			FOR(j,0,3){
				if(!inlis[a[i+j]]){
					inlis[a[i+j]]=1;
					lis.push_back(a[i+j]);
					FOR(k,0,lis.size()){
						g.push_back(Node{min(lis[k],a[i+j]),max(lis[k],a[i+j]),max(mx[lis[k]],0)});
					}
				}
			}
		}
		FOR(j,0,g.size())dp[g[j].u][g[j].v]=max(dp[g[j].u][g[j].v],g[j].w),mx[g[j].u]=max(mx[g[j].u],dp[g[j].u][g[j].v]),mx[g[j].v]=max(mx[g[j].v],dp[g[j].u][g[j].v]);
		i+=3;
	}
	dp[a[3*n]][a[3*n]]++;
	int as=0;
	FOR(i,1,n+1)
	FOR(j,i,n+1){
		as=max(as,dp[i][j]);
	}
	ans+=as;
	wrn(ans);
}

#include <bits/stdc++.h>

using namespace std;

const int N = 3 * 2005;

int n, a[N];

int mx_ind[N];
int mx_color[N];
int mx_ic[N][N];

// get max val(index, anything)
// get max val(index, color)
// get max val(color, color)
// lazy increment

int lz;

int get_ind(int i) {
	return mx_ind[i] + lz;
}

int get_ind_col(int i, int c) {
	return mx_ic[i][c] + lz;
}

int get_col_col(int c) {
	return mx_color[c] + lz;
}

void add(int i, int j, int val) {
	val -= lz;
	mx_ind[i] = max(mx_ind[i], val);
	mx_ind[j] = max(mx_ind[j], val);
	if(a[i] == a[j]) {
		mx_color[ a[i] ] = max(mx_color[ a[i] ], val);
	}
	mx_ic[i][ a[j] ] = max(mx_ic[i][ a[j] ], val);
	mx_ic[j][ a[i] ] = max(mx_ic[j][ a[i] ], val);
}
void lazy_inc() {
	lz++;
}

int dp[N][3];
int dp2[3][3];

int main() {
	memset(mx_ind, -7, sizeof mx_ind);
	memset(mx_color, -7, sizeof mx_color);
	memset(mx_ic, -7, sizeof mx_ic);
	scanf("%d", &n);

	n *= 3;

	for(int i = 0; i < n; i++) scanf("%d", a + i);

	add(0, 1, 0);

	for(int i = 2; i + 2 < n; i += 3) {
		for(int pos = 0; pos < 3; pos++) {
			int b = 0, c = 0;
			while(b == pos) b++;
			while(c == pos or c == b) c++;
			b += i, c += i;
			for(int j = 0; j < i; j++) {
				int &ans = dp[j][pos];
				ans = 0;
				if(a[b] == a[c]) {
					ans = max(ans, get_ind_col(j, a[b]) + 1);
				}
				ans = max(ans, get_ind(j));
			}
		}
		for(int p1 = 0; p1 < 3; p1++) for(int p2 = p1 + 1; p2 < 3; p2++) {
			int p3 = 0;
			while(p3 == p1 or p3 == p2) p3++;
			int &ans = dp2[p1][p2];
			ans = 0;
			ans = max(ans, get_col_col(a[i + p3]) + 1);
		}

		if(a[i] == a[i + 1] and a[i + 1] == a[i + 2]) lazy_inc();
		for(int pos = 0; pos < 3; pos++) {
			for(int j = 0; j < i; j++) {
				add(j, i + pos, dp[j][pos]);
			}
		}
		for(int p1 = 0; p1 < 3; p1++) for(int p2 = p1 + 1; p2 < 3; p2++) {
			add(i + p1, i + p2, dp2[p1][p2]);
		}
	}

	int ans = 0;

	ans = max(ans, get_col_col(a[n - 1]) + 1);
	for(int i = 0; i < n - 1; i++) {
		ans = max(ans, get_ind(i));
	}

	printf("%d\n", ans);
}

