const long double EPS = 1e-8;

void solve(long long N, std::vector<long long> A){
    vector<vector<int>> dp(N+1, vector<int>(N+1, INT_MIN));
    vector<int> maxDp(N+1, INT_MIN);
    dp[A[0]][A[1]] = dp[A[1]][A[0]] = 0;
    maxDp[A[0]] = maxDp[A[1]] = 0;
    int answer = 0, maxAns = 0;
    rep(i,0,N-1) {
        int p = A[3*i+2], q = A[3*i+3], r = A[3*i+4];
        map<pair<int, int>, int> updates;
        if (p == q && q == r) {
            answer++;
            continue;
        }
        if (p == q || q == r || r == p) {
            // make sure p == q
            if (q == r) swap(p, r);
            if (r == p) swap(q, r);
            rep(j,1,N+1) {
                if (dp[p][j] == INT_MIN) continue;
                updates[{r, j}] = max(updates[{r, j}], dp[p][j]+1);
            }
        }
        // use 2 from p, q, r
        updates[{p, q}] = max(maxAns, updates[{p, q}]);
        updates[{q, r}] = max(maxAns, updates[{q, r}]);
        updates[{r, p}] = max(maxAns, updates[{r, p}]);

        // use 1 from p, q, r
        for (auto v : {p, q, r}) {
            rep(j,1,N+1) {
                if (dp[v][j] == INT_MIN) continue;
                updates[{v, j}] = max(updates[{v, j}], maxDp[v]);
            }
        }
        for (auto [key, value] : updates) {
            if (value == INT_MIN) continue;
            assert(dp[key.first][key.second] == dp[key.second][key.first]);
            dp[key.first][key.second] = max(dp[key.first][key.second], value);
            dp[key.second][key.first] = dp[key.first][key.second];
            maxDp[key.first] = max(maxDp[key.first], dp[key.first][key.second]);
            maxDp[key.second] = max(maxDp[key.second], dp[key.first][key.second]);
            maxAns = max(max(maxAns, maxDp[key.first]), maxDp[key.second]);
        }
    }
    maxAns = max(maxAns, dp[A.back()][A.back()]+1);
    answer += maxAns;
    cout << answer << endl;
}

