namespace atcoder {

    struct two_sat {
    public:
        two_sat() : _n(0), scc(0) {}
        two_sat(int n) : _n(n), _answer(n), scc(2 * n) {}

        void add_clause(int i, bool f, int j, bool g) {
            assert(0 <= i && i < _n);
            assert(0 <= j && j < _n);
            scc.add_edge(2 * i + (f ? 0 : 1), 2 * j + (g ? 1 : 0));
            scc.add_edge(2 * j + (g ? 0 : 1), 2 * i + (f ? 1 : 0));
        }
        bool satisfiable() {
            auto id = scc.scc_ids().second;
            for (int i = 0; i < _n; i++) {
                if (id[2 * i] == id[2 * i + 1]) return false;
                _answer[i] = id[2 * i] < id[2 * i + 1];
            }
            return true;
        }
        std::vector<bool> answer() { return _answer; }

    private:
        int _n;
        std::vector<bool> _answer;
        internal::scc_graph scc;
    };

}  // namespace atcoder

const int mod=1000000007,MAX=2005,INF=1<<30;
struct dat{
    int x;
    int y;
    int z;
};

vector<dat> change;

int dp[MAX][MAX],ma[MAX];
int ans=0,bonus=0;

void update(int x1,int y1,int x2,int y2,int p){
    change.push_back({x1,y1,dp[x2][y2]+p});
    change.push_back({y1,x1,dp[x2][y2]+p});
}

void update(int x1,int y1,int d){
    change.push_back({x1,y1,d});
    change.push_back({y1,x1,d});
}

void eval(){
    for(auto u:change){
        chmax(dp[u.x][u.y],u.z);
        chmax(ma[u.x],u.z);
        chmax(ma[u.y],u.z);
        chmax(ans,u.z);
    }

    change.clear();
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;cin>>N;
    vector<int> A(3*N);
    for(int i=0;i<3*N;i++){
        cin>>A[i];
        A[i]--;
    }

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++) dp[i][j]=-INF;
        ma[i]=-INF;
    }
    change.push_back({A[0],A[1],0});
    change.push_back({A[1],A[0],0});

    eval();

    for(int t=0;t<N-1;t++){
        int p=A[3*t+2],q=A[3*t+3],r=A[3*t+4];
        if(p>q) swap(p,q);
        if(p>r) swap(p,r);
        if(q>r) swap(q,r);

        if(p==q&&q==r){
            bonus++;
            continue;
        }

        if(p==q){
            for(int i=0;i<N;i++){
                update(i,r,p,i,1);
            }
        }

        if(q==r){
            for(int i=0;i<N;i++){
                update(i,p,q,i,1);
            }
        }

        update(q,r,p,p,1);
        update(p,r,q,q,1);
        update(p,q,r,r,1);

        update(q,r,ans);
        update(p,r,ans);
        update(p,q,ans);

        for(int i=0;i<N;i++){
            update(i,p,ma[i]);
            update(i,q,ma[i]);
            update(i,r,ma[i]);
        }

        eval();
    }

    ans=0;

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            if(i==A.back()&&j==A.back()) chmax(ans,dp[i][j]+1);
            else chmax(ans,dp[i][j]);
        }
    }

    cout<<ans+bonus<<endl;

}

