#include <bits/stdc++.h>
using namespace std;
struct HashPair {
    size_t operator()(const pair<int, int> &p) const {
        return p.first * 3000 + p.second;
    }
};
int a[6000];
int fst[5][5][5];
int snd[5][5][5];
int main(void) {
    int n;
    cin >> n;
    for (int i = 0; i < 3 * n; ++i) cin >> a[i];
    if (n == 1) {
        int x = a[0], y = a[1], z = a[2];
        int ans = (x == y) && (y == z) ? 1 : 0;
        cout << ans << endl;
        return 0;
    }
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 4; j++) {
            for (int k = j + 1; k < 5; k++) {
                fst[i][j][k] = -1;
                snd[i][j][k] = -1;
                for (int l = 0; l < 5; l++) {
                    if (l != i && l != j && l != k) {
                        if (fst[i][j][k] < 0) fst[i][j][k] = l;
                        else snd[i][j][k] = l;
                    }
                }
            }
        }
    }
    int mx = 0;
    unordered_map<pair<int, int>, int, HashPair> mp;
    pair<int, int> p = make_pair(a[0], a[1]);
    mp[p] = 0;
    for (int x = 0; x < n - 1; ++x) {
        unordered_map<pair<int, int>, int, HashPair> nxt;
        int m = mx;
        unordered_map<pair<int, int>, int, HashPair>::iterator iterator;
        for (iterator = mp.begin(); iterator != mp.end(); iterator++) {
            pair<pair<int, int>, int> e = *iterator;
            pair<int, int> pr = e.first;
            int score = e.second;
            if (score <= m - 2 || score + 1 <= mx - 2) continue;
            for (int i = 0; i < 3; i++) {
                int vi = i == 0 ? pr.first : i == 1 ? pr.second : a[3 * x + i];
                for (int j = i + 1; j < 4; j++) {
                    int vj = j == 1 ? p.second : a[3 * x + j];
                    for (int k = j + 1; k < 5; k++) {
                        int vk = a[3 * x + k];
                        int s = score;
                        if (vi == vj && vj == vk) {
                            ++s;
                            mx = max(mx, s);
                        }
                        int fs = fst[i][j][k];
                        int sn = snd[i][j][k];
                        int vf = fs == 0 ? pr.first : fs == 1 ? pr.second : a[3 * x + fs];
                        int vs = sn == 0 ? pr.first : sn == 1 ? pr.second : a[3 * x + sn];
                        pair<int, int> q = make_pair(vf, vs);
                        if (nxt.find(q) != nxt.end()) {
                            nxt[q] = s;
                        } else {
                            int qs = nxt[q];
                            if (qs <= s && s >= mx - 2) {
                                nxt[q] = s;
                            }
                        }
                    }
                }
            }
        }
        mp.swap(nxt);
    }
    unordered_map<pair<int, int>, int, HashPair>::iterator iterator;
    for (iterator = mp.begin(); iterator != mp.end(); iterator++) {
        pair<pair<int, int>, int> e = *iterator;
        pair<int, int> pr = e.first;
        int score = e.second;
        if (pr.first == pr.second && pr.first == a[3 * n - 1]) {
            mx = max(mx, score + 1);
        }
    }
    cout << mx << endl;
    return 0;
}

