inline void chmax(int &a, const int& b){if(a<b) a=b;}

int solve(){
    // vector<map<int, map<int, int> > > dp;
    // dp.resize(N+1);
    vector<vector<int> > dp(N+1,vector<int>(N+1,-1e7));
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[A[0]][A[1]] = 0;
    dp[A[1]][A[0]] = 0;
    int dp_max = 0;
    int all = 0;
    vector<int> dp_maxk(N+1,-1e7);
    dp_maxk[A[0]] = 0;
    dp_maxk[A[1]] = 0;
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1])
        {
            // 全部一致
            // dp = sv_dp;
            all++;
        }
        else if(A[3*i-1]==A[3*i] || A[3*i]==A[3*i+1] || A[3*i+1]==A[3*i-1])
        {
            // 二つ一致
            int p, q;
            if(A[3*i-1]==A[3*i]){
                p = A[3*i-1];
                q = A[3*i+1];
            }
            else if(A[3*i]==A[3*i+1]){
                p = A[3*i];
                q = A[3*i-1];
            }
            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            else{
                p = 0, q = 0;
            }
            vector<vector<int> > sv_dp = dp;
            // dp = sv_dp;
            for (int k = 1; k <= N; k++)
            {
                chmax(dp[k][q], dp_maxk[k]);
                chmax(dp[q][k], dp_maxk[k]);
                chmax(dp[k][p], dp_maxk[k]);
                chmax(dp[p][k], dp_maxk[k]);
            }

            chmax(dp[p][p], dp_max);
            chmax(dp[p][q], dp_max);
            chmax(dp[q][p], dp_max);
            chmax(dp_maxk[p], dp_max);
            chmax(dp_maxk[q], dp_max);

            for (int k = 1; k <= N; k++)
            {
                int c = sv_dp[k][p];
                chmax(dp[k][q], c + 1);
                chmax(dp[q][k], c + 1);
                chmax(dp_max, c + 1);
                chmax(dp_maxk[k], c + 1);
                chmax(dp_maxk[q], c + 1);
            }

            int c = sv_dp[q][q];
            chmax(dp[p][p], c + 1);
            chmax(dp_max, c + 1);
            chmax(dp_maxk[p], c + 1);

        }
        else
        {
            // 全部ばらばら
            vector<vector<int> > sv_dp = dp;
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];

            for(int k = 1; k<=N; k++){
                chmax(dp[p][k], dp_maxk[k]);
                chmax(dp[q][k], dp_maxk[k]);
                chmax(dp[r][k], dp_maxk[k]);
                chmax(dp[k][p], dp_maxk[k]);
                chmax(dp[k][q], dp_maxk[k]);
                chmax(dp[k][r], dp_maxk[k]);
            }

            chmax(dp[p][q], dp_max);
            chmax(dp[p][r], dp_max);
            chmax(dp[q][p], dp_max);
            chmax(dp[q][r], dp_max);
            chmax(dp[r][q], dp_max);
            chmax(dp[r][p], dp_max);
            chmax(dp_maxk[p], dp_max);
            chmax(dp_maxk[q], dp_max);
            chmax(dp_maxk[r], dp_max);

            int c = sv_dp[p][p];
            chmax(dp[q][r], c + 1);
            chmax(dp[r][q], c + 1);
            chmax(dp_max, c + 1);
            chmax(dp_maxk[r], c + 1);
            chmax(dp_maxk[q], c + 1);

            c = sv_dp[q][q];
            chmax(dp[p][r], c + 1);
            chmax(dp[r][p], c + 1);
            chmax(dp_max, c + 1);
            chmax(dp_maxk[r], c + 1);
            chmax(dp_maxk[p], c + 1);

            c = sv_dp[r][r];
            chmax(dp[p][q], c + 1);
            chmax(dp[q][p], c + 1);
            chmax(dp_max, c + 1);
            chmax(dp_maxk[p], c + 1);
            chmax(dp_maxk[q], c + 1);
        }
    }
    int ans = dp_max;
    int last = A[3*N-1];
    chmax(ans, dp[last][last] + 1);
    cout << (ans+all) << "\n";
    return 0;
} 

