int main() {
	int N;
	cin >> N;
	vector<int> A(3*N + 3, 0);
	for (int i = 1; i <= 3*N + 1; i++){
		cin >> A[i];
	}
	vector<vector<vector<int> > > dp(N+1,vector<vector<int> >(N+1,vector<int>(N+1,0)));
	set<pair<int,int> > P;

	P.insert(pair<int,int>(A[1],A[2]));
	dp[1][A[1]][A[2]] = 1;
	int lastScore = 0;
	for(int i = 1; i <= N; i++){
		set<pair<int,int> > Q;
		while(P.size() > 0){
			map<int,int> B;
			multiset<int> C;
			B[A[3*i  ]]++;
			B[A[3*i+1]]++;
			B[A[3*i+2]]++;
			B[P.begin()->first]++;
			B[P.begin()->second]++;
			C.insert(A[3*i  ]);
			C.insert(A[3*i+1]);
			C.insert(A[3*i+2]);
			C.insert(P.begin()->first);
			C.insert(P.begin()->second);
			int s = dp[i][P.begin()->first][P.begin()->second];
			int r = 0;
			for(auto it = B.begin(); it != B.end(); it++){
				if(it->second >= 3) r = it->first;
			}
			if(r > 0){
				B[r] -= 3;
				if(B[r] == 0){
					B.erase(r);
				}
				int x = B.begin()->first;
				int y;
				if(B.begin()->second >= 2){
					y = x;
				} else{
					y = (++B.begin())->first;
				}
				if(x > y) swap(x,y);
				if(i < N){
					int t = dp[i+1][x][y];
					dp[i+1][x][y] = (t < s + 1 ? s + 1 : t);
					Q.insert(pair<int,int>(x,y));
				}else{
					lastScore = (lastScore < s + 1 ? s + 1 : lastScore);
				}
			}else{
				for(auto it = C.begin(); it != C.end(); it++){
					auto kt = it;
					kt++;
					for(auto jt = kt; jt != C.end(); jt++){
						if(i < N){
							int t = dp[i+1][*it][*jt];
							dp[i+1][*it][*jt] = (t < s ? s : t);
							Q.insert(pair<int,int>(*it,*jt));
						}else{
							lastScore = (lastScore < s ? s : lastScore);
						}
					}
				}
			}
			P.erase(P.begin());
		}
		P = Q;
	}
	cout << lastScore - 1 << endl;
	return(0);
}

