void getdp1(int x,int y,int z){
	if(dp[x][y]<maxval) v.pb(mp(mp(x,y),maxval));
	if(dp[x][y]<dp[z][z]+1) v.pb(mp(mp(x,y),dp[z][z]+1));
}

void getdp2(int na,int nb,int nc,int x){
	if(nb==nc&&dp[x][nb]+1>dp[na][x]) v.pb(mp(mp(na,x),dp[x][nb]+1));
	if(f[x]>dp[na][x]) v.pb(mp(mp(na,x),f[x]));
}

