			}
			//cout << i << ' ' << j <<  ' ' << tmp[0] << ' ' << tmp[1] << ' ' << tmp[2] << '\n';
			if(tmp[0]==tmp[1] && tmp[0]==tmp[2])
			{
				dp[s[i]][s[j]] = 1;
			}
			else
			{
				dp[s[i]][s[j]] = 0;
			}
		}
	}

	int idx = 5;
	for(int i=3;i<=n;i++)
	{
		memcpy(Prev,dp,sizeof(dp));
		memset(dp,-1,sizeof(dp));
		for(int a=1;a<=n;a++)
		{
			for(int b=a;b<=n;b++)
			{
				if(Prev[a][b]==-1)
				{
					continue;
				}
				vector <int> s;
				s.push_back(a);
				s.push_back(b);
				for(int k=idx;k<idx+3;k++)
				{
					s.push_back(v[k]);
				}
				sort(s.begin(),s.end());
				for(int i=0;i<s.size();i++)
				{
					for(int j=i+1;j<s.size();j++)
					{
						vector <int> tmp;
						for(int k=0;k<s.size();k++)
						{
							if(k!=i && k!=j)
							{
								tmp.push_back(s[k]);
							}
						}
						if(tmp[0]==tmp[1] && tmp[0]==tmp[2])
						{
							dp[s[i]][s[j]] = max(dp[s[i]][s[j]],Prev[a][b] + 1);
						}
						else
						{
							dp[s[i]][s[j]] = max(dp[s[i]][s[j]],Prev[a][b]);
						}
					}
				}				
			}
		}
		idx += 3;
	}

	if(dp[v[idx]][v[idx]]!=-1)
	{
		dp[v[idx]][v[idx]] += 1;
	}

	int res = 0;

	for(int i=1;i<=n;i++)
	{
		for(int j=i;j<=n;j++)
		{
			res = max(res,dp[i][j]);
		}
	}

	cout << res << '\n';

	return 0;
}

