int N, M, K, T, Q, H, W;
signed main() {
	cin >> N;
	vector< int > A(3 * N);
	rep(i, 3 * N) cin >> A[i];
	vector< vector< int > > dp(N + 1, vector< int >(N + 1, -LINF));
	int ans = 0;
	int tmp = 0;
	int maxdp = 0;
	dp[A[0]][A[1]] = 0;
	dp[A[1]][A[0]] = 0;
	vector< int > imax(N + 1, -LINF);
	vector< int > jmax(N + 1, -LINF);
	imax[A[0]] = 0;
	imax[A[1]] = 0;
	jmax[A[1]] = 0;
	jmax[A[0]] = 0;
	rep(i, N) {
		if (i < N - 1) {
			int a = i * 3 + 2;
			int b = a + 1, c = b + 1;
			if (A[a] == A[b] && A[b] == A[c]) {
				tmp++;
				continue;
			}
			int p = A[a], q = A[b], r = A[c];
			vector< int > ps(3);
			ps[0] = p;
			ps[1] = q;
			ps[2] = r;
			map< pii, int > next;
			auto f = [&](int i, int j, int val) -> void {
				if (next.count(pii(i, j))) {
					chmax(next[pii(i, j)], val);
				} else {
					next[pii(i, j)] = val;
				}
			};
			f(q, r, dp[p][p] + 1);
			f(r, q, dp[p][p] + 1);
			f(r, p, dp[p][p] + 1);
			f(p, r, dp[q][q] + 1);
			f(p, q, dp[p][p] + 1);
			f(q, p, dp[r][r] + 1);
			if (p == q || q == r || r == p) {
				int y, z;
				if (p == q) {
					y = p, z = r;
				} else if (q == r) {
					y = q, z = p;
				} else {
					y = r, z = q;
				}
				for (int x = 1; x <= N; x++) {
					f(x, z, dp[x][y] + 1);
					f(x, z, dp[y][x] + 1);
					f(z, x, dp[y][x] + 1);
					f(z, x, dp[x][y] + 1);
				}
			}
			f(p, q, maxdp);
			f(q, p, maxdp);
			f(r, q, maxdp);
			f(q, r, maxdp);
			f(p, r, maxdp);
			f(r, p, maxdp);
			for (auto p : ps) {
				for (int l = 1; l <= N; l++) {
					f(p, l, jmax[l]);
					f(l, p, imax[l]);
				}
			}
			for (auto p : next) {
				int i = p.first.first;
				int j = p.first.second;
				int val = p.second;
				chmax(dp[i][j], val);
				chmax(maxdp, dp[i][j]);
				chmax(imax[i], dp[i][j]);
				chmax(jmax[j], dp[i][j]);
			}
		} else {
			for (int i = 1; i <= N; i++)
				for (int j = 1; j <= N; j++) {
					int tmp = dp[i][j];
					if (i == j && j == A.back()) {
						tmp++;
					}
					chmax(ans, tmp);
				}
		}
	}
	cout << ans + tmp << endl;

	return 0;
}

