template <typename T>
inline void readin(T &x) {
	x = 0;
	T fh = 1;
	char ch = getchar();
	for (; !isdigit(ch); ch = getchar()) if (ch == '-') fh = -1;
	for (; isdigit(ch); ch = getchar()) x = (x << 1) + (x << 3) + (ch ^ 48);
	x *= fh;
}
inline void d_read(double &x) {
	x = 0.0;
	int fh = 1;
	char ch = getchar();
	for (; !isdigit(ch); ch = getchar()) if (ch == '-') fh = -1;
	for (; isdigit(ch); ch = getchar()) x = x * 10 + (ch ^ 48);
	if (ch == '.') {
		double num = 1.0;
		ch = getchar();
		for (; isdigit(ch); ch = getchar()) x = x + (num /= 10) * (ch ^ 48);
	}
	x *= fh;
}

template <typename T>
inline void wt(T x) {
	if (x > 9) wt(x / 10);
	putchar(x % 10 + 48);
}
template <typename T>
inline void writeln(T x, char c) {
	if (x < 0) {
		putchar('-');
		x = -x;
	}
	wt(x);
	putchar(c);
}
int a[6005], b[2005], c[2005];
int main() {
	int n;
	readin(n);
	n *= 3;
	for (int i = 1; i <= n; i ++) {
		readin(a[i]);
	}
	c[a[1]] ++;
	c[a[2]] ++;
	int ans = 0, id;
	for (int i = 3; i <= n; i += 3) {
		id = i;
		memset(b, 0, sizeof(b));
		for (int j = 0; j <= 2; j ++) {
			b[a[i + j]] ++;
			c[a[i + j]] ++;
		}
		int cnt = -1, res = 0, pos;
		for (int j = 1; j <= n; j ++) {
			if (c[j] >= 3) {
				if (b[j] - 1 > cnt) {
					cnt = b[j] - 1;
					pos = j;
				}
				res = 1;
			}
		}
		if (res) {
			c[pos] -= 3;
			for (int j = 0; j <= 2; j ++) {
				c[a[i + j]] --;
			}
			for (int j = 1; j <= n; j ++) {
				c[j] = min(c[j], cnt);
			}
			for (int j = 0; j <= 2; j ++) {
				if (a[i + j] != pos) c[a[i + j]] ++;
			}
			ans ++;
		}
	}
	for (int i = id + 1; i <= n; i ++) {
		c[a[i]] ++;
	}
	for (int i = 1; i <= n; i ++) {
		if (c[i] >= 3) {
			writeln(ans + 1, '\n');
			return 0;
		}
	}
	writeln(ans, '\n');
	return 0;
}

