        }
        while (A.size() >= 3) {
            int aSize = A.size();
            if (A[aSize-1] == A[aSize-2] && A[aSize-1] == A[aSize-3]) {
                A.pop_back();
                A.pop_back();
                A.pop_back();
                ++ans;
            } else {
                break;
            }
        }
    }
    VVI dp(A.size()+1, VI(A.size()+1, -1));
    VI curPos(N+1, -1);
