    }
    dp[0][1] = 0;
    for (int i= 0; i < A.size(); ++i) {
       for (int j = i+1; j < A.size(); ++j) {
            if (dp[i][j] == -1) {
                continue;
            }
            solve(dp, A, i, j, getBlockStart(j+1, j));
            solve(dp, A, i, j, getBlockStart(nextPos[i], j));
            solve(dp, A, i, j, getBlockStart(nextPos[j], j));
       }
    }
    if (!A.empty())
        cout << ans + dp[A.size()][A.size()] << endl;
	else
        cout << ans << endl;
    return 0;
}

