void update(ll time, ll a, ll b, ll value) {
    dp[time%2][a][b] = dp[time%2][b][a] = max(dp[time%2][a][b], value);
    max_table[time][a] = max(max_table[time][a], value);
    max_table[time][b] = max(max_table[time][b], value);
    all_max[time] = max(all_max[time], dp[time%2][a][b]);
    all_max[time] = max(all_max[time], all_max[time-1]);
    return;
}

void solve() {
    cin >> n;
    vec x(3 * n);
    for (int i = 0; i < 3 * n; i++) {
        cin >> x[i];
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dp[0][i][j] = dp[1][i][j] = -INF;
        }
        max_table[0][i] = -INF;
        all_max[i] = -INF;
    }
    dp[0][x[0]][x[1]] = 0;
    dp[0][x[1]][x[0]] = 0;
    all_max[0] = 0;
    max_table[0][x[0]] = max_table[0][x[1]] = 0;

    int bonus = 0;
    for (int i = 0; i < n - 1; i++) {
        vec y(3);
        y[0] = x[2 + 3 * i], y[1] = x[3 + 3 * i], y[2] = x[4 + 3 * i];
        sort(y.begin(), y.end());
        a = y[0], b = y[1], c = y[2];
        if (a == b && b == c) {
            bonus ++;
        } else if (a < b && b < c) {
            update(i+1, a, b, max(dp[i%2][c][c] + 1, all_max[i]));
            update(i+1, b, c, max(dp[i%2][a][a] + 1, all_max[i]));
            update(i+1, a, c, max(dp[i%2][b][b] + 1, all_max[i]));
            for (int j = 1; j <= n; j++) {
                // 片方がjであるようなものの最大値を持ってくる
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
                update(i+1, b, j, maxi);
                update(i+1, c, j, maxi);
            }
        } else if (a == b && b < c) {
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
            }

            for (int j = 1; j <= n; j++) {
                // (a, j) -> (c, j) への遷移
                update(i+1, c, j, dp[i%2][a][j] + 1);
            }

            for (int j = 1; j <= n; j++) {
                // (*, j) -> (c, j) への遷移
                ll maxi = max_table[i][j];
                update(i+1, c, j, maxi);
            }
        } else if (a < b && b == c) {
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, b, j, maxi);
            }
            for (int j = 1; j <= n; j++) {
                update(i+1, a, j, dp[i%2][c][j] + 1);
            }
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
            }
        }
    }
    ll last = x.back();
    all_max[n-1] = max(all_max[n-1], dp[(n-1)%2][last][last] + 1);
    p(all_max[n-1] + bonus);

    return;
}

