		vector<int> cs = {A[i], A[i+1], A[i+2]};
		std::sort(cs.begin(), cs.end());
		if(cs[0] == cs[1] && cs[0] == cs[2]){
			for(int a=1; a<=N; a++){
				for(int b=a; b<=N; b++){
					if(dp[a][b] >= 0){
						dpt[a][b]++;
					}
				}
			}

		}else if(cs[0] == cs[1]){
			int c = cs[0], b = cs[2];
			int tmp = dp[b][b];

			for(int a=1; a<=N; a++){
				int p = dp[min(a, c)][max(a, c)];
				if(p < 0) continue;

				dpt[min(a,b)][max(a,b)] = max(dpt[min(a,b)][max(a,b)], p + 1); 
			}

			if(tmp >= 0){
				dpt[c][c] = max(dpt[c][c], tmp + 1);
			}


		}else if(cs[1] == cs[2]){
			int c = cs[1], b = cs[0];
			int tmp = dp[b][b];

			for(int a=1; a<=N; a++){
				int p = dp[min(a, c)][max(a, c)];
				if(p < 0) continue;

				dpt[min(a,b)][max(a,b)] = max(dpt[min(a,b)][max(a,b)], p + 1); 
			}

			if(tmp >= 0){
				dpt[c][c] = max(dpt[c][c], tmp + 1);
			}

		}else{
			for(int j=0; j<3; j++){
				int a = cs[j];
				int p = dp[a][a];
				if(p < 0) continue;

				vector<int> cs2;
				for(int k=0; k < 3; k++){
					if(k != j){
						cs2.push_back(cs[k]);
					}
				}
				int b = cs2[0], c = cs2[1];
				dpt[b][c] = max(dpt[b][c], p + 1);
			}

		}

		for(int a=1; a<=N; a++){
			if(vis[a] == 0) continue;
			for(int c : cs){
				dpt[min(a, c)][max(a, c)] = max(dpt[min(a, c)][max(a, c)], 0);
			}
		}
		for(int i=0; i<3; i++){
			for(int j=i+1; j<3; j++){
				dpt[cs[i]][cs[j]] = max(dpt[cs[i]][cs[j]], 0);
			}
		}

		dp = dpt;
	}

	for (int a = 1; a <= N; a++)
	{
		for (int b = 1; b <= N; b++)
		{
			ans = max(ans, dp[a][b]);
		}
	}

	ans = max(ans, dp[0][0]);
	return ans;
}

