		ll c = A[3 * i + 2];

		map<pair<ll, ll>, ll> mp;

		repn(j, N) {
			if (R[j] < 0) { continue; }

			mp[{j, a}] = R[j];
			if (b == c) { mp[{j, a}] = max(mp[{j, a}], dp[j][b] + S + 1); }

			mp[{j, b}] = max(mp[{j, b}], R[j]);
			if (c == a) { mp[{j, b}] = max(mp[{j, b}], dp[j][c] + S + 1); }
			mp[{j, c}] = max(mp[{j, c}], R[j]);
			if (a == b) { mp[{j, c}] = max(mp[{j, c}], dp[j][a] + S + 1); }
