			if (mp.count({ y,x })) { dp[x][y] = max(mp[{y, x}] - S,dp[x][y]); }
			dp[y][x] = dp[x][y];
			R[x] = max(R[x], p.second);
			R[y] = max(R[y], p.second);
			M = max(M, p.second);
