void upd2(i64 dup, i64 left) {
    if (!met.count(dup)) {
        return;
    }

    for (auto t : met) {
        i64 card = t.first;
        i64 val = dp[dup][card];
        upd[{left, card}] = max(upd[{left, card}], val + 1);
        upd[{card, left}] = max(upd[{card, left}], val + 1);
    }
}

void upd1(i64 main, i64 left1, i64 left2) {
    if (!met.count(main) || met[main] < 2) {
        return;
    }

    i64 val = dp[main][main];
    upd[{left1, left2}] = max(upd[{left1, left2}], val + 1);
    upd[{left2, left1}] = max(upd[{left2, left1}], val + 1);
}

void do_upd() {
    for (auto t : upd) {
        i64 card1 = t.first.first;
        i64 card2 = t.first.second;
        i64 val = t.second;

        dp[card1][card2] = max(dp[card1][card2], val);
    }

    upd.clear();
}

