    met[a[0]] += 1;
    met[a[1]] += 1;

    i64 R = 0;

    for (i64 x = 0; x < n - 1; x++) {
        vector<i64> q;
        q.push_back(a[x * 3 + 2]);
        q.push_back(a[x * 3 + 3]);
        q.push_back(a[x * 3 + 4]);
        sort(q.begin(), q.end());

        if (q[0] == q[2]) {
            R += 1;
            continue;
        }

        if (q[0] == q[1]) {
            upd2(q[0], q[2]);
        }
        if (q[1] == q[2]) {
            upd2(q[2], q[0]);
        }

        upd1(q[0], q[1], q[2]);
        upd1(q[1], q[0], q[2]);
        upd1(q[2], q[0], q[1]);

        for (i64 i = 0; i < 3; i++) {
            met[q[i]] += 1;
