vector<int> r;

void update(int k1, int k2, int v) {
	if (dp[index(k1, k2)] < v) {
		dp[index(k1, k2)] = v;

		r[k1] = max(r[k1], v);
		r[k2] = max(r[k2], v);
	}
}

int getmax(int k) {
	return r[k];
}

