	r[A[1]] = 0;

	int combo3 = 0;
	for (int i = 0; i < N - 1; ++i) {
		int ind = 2 + 3 * i;

		if (A[ind] == A[ind + 1] && A[ind + 1] == A[ind + 2]) {
			combo3++;
			continue;
		}

		int a, b, c;
		c = -1;
		if (A[ind] == A[ind + 1]) {
			a = A[ind];
			b = A[ind + 2];
		}
		else if (A[ind + 1] == A[ind + 2]) {
			a = A[ind+1];
			b = A[ind];
		}
		else if (A[ind + 2] == A[ind]) {
			a = A[ind];
			b = A[ind + 1];
		}
		else {
			a = A[ind];
			b = A[ind + 1];
			c = A[ind + 2];
		}

		if (c != -1) {
