const int MAXN = 6005;
const int INF = 1e5;

int N;
int A[MAXN];

int ans = 0;
int base = 0;
int nxt[MAXN];
int dp[MAXN][MAXN];

vector<int> Group;

int CostGroupExcept(int Left1,int Left2){

    int mn = INF,mx = 0;
    if(Group[0] != Left1 && Group[0] != Left2)
        mn = min(mn,Group[0]),mx = max(mx,Group[0]);

    if(Group[1] != Left1 && Group[1] != Left2)
        mn = min(mn,Group[1]),mx = max(mx,Group[1]);

    if(Group[2] != Left1 && Group[2] != Left2)
        mn = min(mn,Group[2]),mx = max(mx,Group[2]);

    if(Group[3] != Left1 && Group[3] != Left2)
        mn = min(mn,Group[3]),mx = max(mx,Group[3]);

    if(Group[4] != Left1 && Group[4] != Left2)
        mn = min(mn,Group[4]),mx = max(mx,Group[4]);
    return (mn == mx);
}

void Transition(int Left1,int Left2,int Cur){

    Group = {Left1,Left2,Cur,Cur+1,Cur+2};

    if(Cur > 3*N)
        return;

    if(Cur == 3*N)
        return void( ans = max( ans , dp[Left1][Left2] + CostGroupExcept(Cur+1,Cur+2) ) );

    for(int i = 0; i < 5; i++){
        for(int j=i+1; j < 5 ; j++){
            int NextLeft1 = Group[i];
            int NextLeft2 = Group[j];
            dp[ NextLeft1 ][ NextLeft2 ] = max( dp[ NextLeft1 ][ NextLeft2 ]
                                               , dp[Left1][Left2] + CostGroupExcept(NextLeft1,NextLeft2) );
        }
    }
}


