int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N;
  cin >> N;
  int N3 = 3 * N;
  V<int> A(N3);
  REP(i, N3) cin >> A[i];
  const int INF = 1e8;

  int ans = [&]() -> i64 {
    if (N == 1) {
      if (A[0] == A[1] && A[1] == A[2]) return 1;
      return 0;
    }

    V<V<V<int>>> dp = make_vec(N, N + 1, N + 1, -INF);
    int a0 = min(A[0], A[1]);
    int a1 = max(A[0], A[1]);
    dp[0][a0][a1] = 0;
    for (int i = 1; i < N; ++i) {
      for (int j = 1; j <= N; ++j) {
        for (int k = j; k <= N; ++k) {
          if (dp[i - 1][j][k] == INF) continue;
          int hand[5];
          REP(p, 3) { hand[p] = A[3 * i - 1 + p]; }
          hand[3] = j;
          hand[4] = k;
          sort(hand, hand + 5);

          int ok = -1;
          REP(p, 3) {
            if (hand[p] == hand[p + 1] && hand[p] == hand[p + 2]) {
              ok = p;
              break;
            }
          }

          for (int p = 0; p < 4; ++p) {
            for (int q = p + 1; q < 5; ++q) {
              chmax(dp[i][hand[p]][hand[q]], dp[i - 1][j][k]);
            }
          }

          if (ok >= 0) {
            V<int> tmp;
            REP(p, 5) {
              if (p < ok || p >= ok + 3) tmp.push_back(hand[p]);
            }
            chmax(dp[i][tmp[0]][tmp[1]], dp[i - 1][j][k] + 1);
          }
        }
      }
    }

    REP(i, N) REP(j, N + 1) { DEBUG(i, j, dp[i][j]); }

    int ans = -INF;
    REP(i, N + 1) REP(j, N + 1) {
      int bonus = 0;
      if (i == j && j == A[N3 - 1]) bonus = 1;
      int res = dp[N - 1][i][j] + bonus;
      if (ans < res) {
        DEBUG(res, i, j, bonus);
        ans = res;
      }
    }
    return ans;
  }();
  cout << ans << endl;
}

