			nxt[f].insert(mp(nx[fir[i]],nx[sec[i]]));
			dp[f][nx[fir[i]]][nx[sec[i]]]=max(dp[f][nx[fir[i]]][nx[sec[i]]],dp[1-f][a][b]+1);
		}
	}
	for(int i=0;i<5;i++)
		for(int j=i;j<5;j++)
		{
			if(j==i || nx[j]!=nx[j-1])
			{
				//cout<<k<<" "<<nx[i]<<" "<<nx[j]<<endl;
				nxt[f].insert(mp(nx[i],nx[j]));
				dp[f][nx[i]][nx[j]]=max(dp[f][nx[i]][nx[j]],dp[1-f][a][b]);
			}
		}
