          chmax(nexmva[A[j]],mva[m]);
        }
      }
      for(int j=now;j<=now+2;j++) for(int m=now;m<j;m++){
          chmax(nexmva[A[j]],0);
          chmax(nexmva[A[m]],0);
      }
      mva=nexmva;
    }
  }

  int ans=0;
  for(int i=0;i<N;i++) for(int j=0;j<N;j++){
    if(dp[i][j]==-INF) continue;
    int last=0;
    if(i==j&&i==A.back()) last=1;
    chmax(ans,dp[i][j]+last);
  }
  ans+=all;
  cout<<ans<<endl;

  return 0;
}

