  vector<int> max_arr(n+1, MINF);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      dp[i][j] = MINF;
    }
    max_arr[i] = MINF;
  }
  {
    auto a=A[0], b=A[1];
    dp[a][b] = 0;
    dp[b][a] = 0;
    max_arr[a] = max_arr[b] = 0;
  }
  int max_dp = 0;
  for (int i = 1; i <= n; i++) {
