    }

    array<int, 3> cde={c, d, e};
    auto ndp = dp;
    int nmax_dp = max_dp;
    auto nmax_arr = max_arr;
    auto s2 = [&](int x, int y, int z) {
      if (x != y)
        return;
      for (int i = 1; i <= n; i++) {
        auto upd = max({ndp[i][z], ndp[z][i], dp[i][x]+1, dp[x][i]+1});
        nmax_dp = max(nmax_dp, upd);
        ndp[i][z] = upd;
        ndp[z][i] = upd;
        nmax_arr[z] = upd;
        nmax_arr[i] = upd;
      }
    };
    auto s1 = [&](int x, int y, int z) {
      auto upd = max({ndp[y][z], dp[x][x]+1});
      nmax_dp = max(nmax_dp, upd);
      ndp[y][z] = upd;
      nmax_arr[z] = max(nmax_arr[z], upd);
    };
    auto u2 = [&](int x, int y, int z) {
      auto upd = max(max_dp, ndp[x][y]);
      nmax_dp = max(nmax_dp, upd);
      ndp[x][y] = upd;
      nmax_arr[y] = max(nmax_arr[y], upd);
    };
    auto u1 = [&](int x, int y, int z) {
