const int MAXN = 2010;

int a[MAXN * 3];
int f[MAXN][MAXN];
int g[MAXN];

void solve()
{
	int n;
	read(n);
	input(a + 1, a + 3 * n + 1);

	const int INF = 1000000000;
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 1; j <= n; ++j)
			f[i][j] = -INF;
		g[i] = -INF;
	}
	int res = 0, special = 0;

	auto go = [&](int x, int y, int c)
	{
		if (f[x][y] < c)
		{
			f[x][y] = f[y][x] = c;
			freshmax(g[x], c);
			freshmax(g[y], c);
			freshmax(res, c);
		}
	};

	go(a[1], a[2], 0);
	for (int i = 3; i < 3 * n; i += 3)
	{
		int j = i + 1, k = i + 2;
		if (a[i] == a[j] && a[j] == a[k])
		{
			special += 1;
			continue;
		}
		vector<tuple<int, int, int>> q;
		for (int x = i; x < i + 3; ++x)
			for (int y = i; y < i + 3; ++y) if (x != y)
			{
				int z = 3 * i + 3 - x - y;
				q.push_back({ a[x], a[y], max(f[a[z]][a[z]] + 1, res) });
			}
		for (int x = i; x < i + 3; ++x)
		{
			int y = x + 1; if (y == i + 3) y = i;
			int z = y + 1; if (z == i + 3) z = i;
			for (int c = 1; c <= n; ++c)
			{
				q.push_back({ a[x], c, max(g[c], f[c][a[y]] + (a[y] == a[z])) });
			}
		}
		for (auto [x, y, c] : q)
		{
			go(x, y, c);
		}
	}
	freshmax(res, f[a[3 * n]][a[3 * n]] + 1);
	writeln(res + special);
}

