						g.push_back(Node{lis[j],i+1,mx[a[lis[j]]]});
					}
					lis.push_back(i+1);
				}else {
					FOR(j,0,lis.size()){
						if(!cnt[a[i]])g.push_back(Node{lis[j],i,mx[a[lis[j]]]});
						g.push_back(Node{lis[j],i,d(lis[j],i+1)+1});
					}
					if(cnt[a[i]]==1){
						g.push_back(Node{i,i,mx[a[i]]});
						g.push_back(Node{i,i,d(i,i+1)+1});
					}
