				FOR(j,0,3){
					if(!cnt[a[cg[j]]]){
						FOR(k,0,lis.size())g.push_back(Node{lis[k],cg[j],mx[a[lis[k]]]});
					}
					if(cnt[a[cg[j+1]]]>=2){
						g.push_back(Node{cg[j+2],cg[j],d(cg[j+1],cg[j+1])+1});
					}
					if(cnt[a[cg[j+2]]]>=2){
						g.push_back(Node{cg[j+1],cg[j],d(cg[j+2],cg[j+2])+1});
					}
				}
				FOR(j,0,3){
					if(!cnt[i+j])lis.push_back(i+j);
					FOR(k,j+1,3)if(!cnt[i+j] && !cnt[i+k])g.push_back(Node{i+j,i+k,mxas});
				}
			}
		}
		FOR(j,0,3)cnt[a[i+j]]++;
		i+=3; 
		FOR(j,0,g.size())up(g[j].u,g[j].v,g[j].w);
	}
	if(cnt[a[3*n]]>=2)up(3*n,3*n,d(3*n,3*n)+1);
	ans+=mxas;
	wrn(ans); 
}

