    bitset<2000> keep;
    for(int i = 2; i + 2 < N * 3; i += 3){
        keep = 0;
        if(a[i] == a[i + 1] && a[i + 1] == a[i + 2]){
            ++ans;
            continue;
        }
        bool plus = false, swapped = false;
        if(a[i + 1] == a[i + 2]){
            swapped = true;
            swap(a[i], a[i + 2]);
