const int N = 2e3 + 5;
const int oo = 1e9 + 5;
const LL ooll = (LL)1e18 + 5;
const int MOD = 1e9 + 7;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
#define rand(l, r) uniform_int_distribution<int>(l, r)(rng)

clock_t start = clock();

int dp[N][N], t[N][N], mxdp[N], n, add, mdp[N], ovmx;

void upd(int x, int y, int z) {
    assert(x <= y && y <= z);
    int go = (x == y) && (y == z);

    for (int i=1;i<=n;++i) {
        t[i][x] = t[i][y] = t[i][z] = -oo;
        t[x][i] = t[y][i] = t[z][i] = -oo;
    }

    vector<int> v({x, y, z});

    do {
        int x = v[0]; y = v[1]; z = v[2];
        for (int i=1;i<=n;++i) {
            t[i][z] = max(t[i][z], mxdp[i] + add);
            if (x == y) {
                t[i][z] = max(t[i][z], dp[i][x] + 1 + add);
            }

            t[z][i] = max(t[z][i], mdp[i] + add);
            if (x == y) {
                t[z][i] = max(t[z][i], dp[x][i] + 1 + add);
            }

            t[x][y] = max(t[x][y], ovmx + add);
            t[x][y] = max(t[x][y], dp[z][z] + add + 1);
        }
    } while(next_permutation(v.begin(), v.end()));

    add += go;
    for (int i=1;i<=n;++i) {
        dp[i][x] = max(dp[i][x], t[i][x] - go);
        dp[i][y] = max(dp[i][y], t[i][y] - go);
        dp[i][z] = max(dp[i][z], t[i][z] - go);

        mxdp[i] = max(mxdp[i], dp[i][x]);
        mxdp[i] = max(mxdp[i], dp[i][y]);
        mxdp[i] = max(mxdp[i], dp[i][z]);
        ovmx = max(ovmx, mxdp[i]);

        dp[x][i] = max(dp[x][i], t[x][i] - go);
        dp[y][i] = max(dp[y][i], t[y][i] - go);
        dp[z][i] = max(dp[z][i], t[z][i] - go);

        mdp[i] = max(mdp[i], dp[x][i]);
        mdp[i] = max(mdp[i], dp[y][i]);
        mdp[i] = max(mdp[i], dp[z][i]);
    }
}

int v[N];

void solve() {  
    int n;
    cin >> n;
    for (int i=1;i<=3*n;++i) {
        cin >> v[i];
    }
    if (n == 1) {
        cout << (v[1] == v[2] && v[2] == v[3]) << '\n';
        return;
    }

    for (int i=1;i<=n;++i) {
        mxdp[i] = mdp[i] = -oo;
    }
    ovmx = -oo;
    add = 0;

    for (int i=1;i<=n;++i) {
        for (int j=1;j<=n;++j) {
            dp[i][j] = -oo;
        }
    }

    dp[v[1]][v[2]] = (v[3] == v[4]) && (v[4] == v[5]);
    dp[v[2]][v[1]] = (v[3] == v[4]) && (v[4] == v[5]);

    dp[v[1]][v[3]] = (v[2] == v[4]) && (v[4] == v[5]);
    dp[v[3]][v[1]] = (v[2] == v[4]) && (v[4] == v[5]);

    dp[v[1]][v[4]] = (v[2] == v[3]) && (v[3] == v[5]);
    dp[v[4]][v[1]] = (v[2] == v[3]) && (v[3] == v[5]);

    dp[v[1]][v[5]] = (v[2] == v[4]) && (v[4] == v[3]);
    dp[v[5]][v[1]] = (v[2] == v[4]) && (v[4] == v[3]);

    dp[v[2]][v[3]] = (v[1] == v[4]) && (v[4] == v[5]);
    dp[v[3]][v[2]] = (v[1] == v[4]) && (v[4] == v[5]);

    dp[v[2]][v[4]] = (v[1] == v[3]) && (v[3] == v[5]);
    dp[v[4]][v[2]] = (v[1] == v[3]) && (v[3] == v[5]);

    dp[v[2]][v[5]] = (v[1] == v[4]) && (v[4] == v[3]);
    dp[v[5]][v[2]] = (v[1] == v[4]) && (v[4] == v[3]);

    dp[v[3]][v[4]] = (v[1] == v[2]) && (v[2] == v[5]);
    dp[v[4]][v[3]] = (v[1] == v[2]) && (v[2] == v[5]);

    dp[v[3]][v[5]] = (v[1] == v[4]) && (v[4] == v[2]);
    dp[v[5]][v[3]] = (v[1] == v[4]) && (v[4] == v[2]);

    dp[v[4]][v[5]] = (v[1] == v[2]) && (v[2] == v[3]);
    dp[v[5]][v[4]] = (v[1] == v[2]) && (v[2] == v[3]);

    for (int i=6;i<n;i+=3) {
        upd(v[i], v[i+1], v[i+2]);
    }

    int ans = 0;
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
        ans = max(ans, dp[i][j] + ((i == j) && (j == v[n])) + add);
    }

    cout << ans << '\n';
}

