	FOR(i, 0, n * 3)
		scanf("%d", a + i), --a[i];

	if(n == 1){
		printf("%d\n", a[0] == a[1] && a[1] == a[2]);
		return 0;
	}	

	REP(i, 0, n) REP(j, 0, n)
		dp[i][j] = -0x3f3f3f3f;
	init();

	REP(i, 1, n - 2){
//		printf("i = %d\n", i);
//		print();

		int x = a[i * 3 + 2], y = a[3 * i + 3], z = a[3 * i + 4];
		upd.clear();

		p2p(x, y, z);
		p2p(x, z, y);
		p2p(y, z, x);

		if(x == y)
			r2r(x, z);
		if(x == z)
			r2r(x, y);
		if(y == z)
			r2r(y, x);
		r2p(x);
		r2p(y);
		r2p(z);

		if(x == y && y == z)
			++dlt;
		FOR(j, 0, upd.size()){
			update(upd[j]);
		}
	}

	FOR(i, 0, n) FOR(j, 0, n){
		umax(ans, dp[i][j] + dlt + (i == j && i == a[3 * n - 1]));
	}

	printf("%d\n", ans);
	return 0;
}

