pii p2(int a, int b){
    if(a<b) swap(a,b);
    return make_pair(a,b);
}

void chmax(int &a, int b){if(a<b) a=b;}

int solve(){
    vector<map<int, map<int, int> > > dp;
    dp.resize(N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[1][A[0]][A[1]] = 0;
    dp[1][A[1]][A[0]] = 0;
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1]){
            dp[i+1] = dp[i];
            for(auto &[p,mp]:dp[i+1]){
                for(auto &[x,c]:mp)
                    c++;
            }
        }
        else if(A[3*i-1]==A[3*i] || A[3*i]==A[3*i+1] || A[3*i+1]==A[3*i-1]){
            int p, q;
            if(A[3*i-1]==A[3*i]){
                p = A[3*i-1];
                q = A[3*i+1];
            }
            else if(A[3*i]==A[3*i+1]){
                p = A[3*i];
                q = A[3*i-1];
            }
            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            else{
                p = 0, q = 0;
            }
            // auto M = *max_element(dp[i].begin(),dp[i].end(),[](pair<int,pair<int,int>> a, pair<int,pair<int,int>> b){return a.second.second < b.second.second;});
            int M = 0;
            for(auto [x,mp]:dp[i]){
                auto Mx = *max_element(mp.begin(),mp.end(),[](pii a, pii b){return a.second < b.second;});
                chmax(M, Mx.second);
            }
            dp[i+1] = dp[i];

            chmax(dp[i+1][p][p], M);
            chmax(dp[i+1][p][q], M);
            chmax(dp[i+1][q][p], M);
            if(dp[i].find(p)!=dp[i].end()){
                for (int k = 1; k <= N; k++)
                {
                    if(dp[i][p].find(k)!=dp[i][p].end()){
                        chmax(dp[i+1][k][q], dp[i][p][k] + 1);
                        chmax(dp[i+1][q][k], dp[i][p][k] + 1);
                    }
                }

            }
            // for (int k = 1; k <= N; k++)
            // {
            //     if(dp[i].find(k)!=dp[i].end()) {
            //         if(dp[i][k].find(p)!=dp[i][k].end()) {
            //             chmax(dp[i+1][k][q], dp[i][k][p] + 1);
            //             chmax(dp[i+1][q][k], dp[i][k][p] + 1);
            //         }
            //     }
            // }
            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()){
                    chmax(dp[i+1][p][p], dp[i][q][q] + 1);
                }
            }

        }
        else{
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];
            auto M = max_element(dp[i].begin(),dp[i].end(),[](pair<int,map<int,int>> a, pair<int,map<int,int>> b){
                return (*max_element(a.second.begin(),a.second.end(),[](pii c, pii d){return c.second < d.second;})).second < \
                (*max_element(b.second.begin(),b.second.end(),[](pii c, pii d){return c.second < d.second;})).second;
            });
            auto T = max_element(M->second.begin(),M->second.end(),[](pii a, pii b){return a.second < b.second;});
            auto Mx = T->second;
            dp[i+1] = dp[i];
            chmax(dp[i+1][p][q], Mx);
            chmax(dp[i+1][q][p], Mx);
            chmax(dp[i+1][q][r], Mx);
            chmax(dp[i+1][r][q], Mx);
            chmax(dp[i+1][r][p], Mx);
            chmax(dp[i+1][p][r], Mx);


            for (int k = 1; k <= N; k++)
            {
                if(dp[i].find(k)!=dp[i].end()){
                    auto Mx = *max_element(dp[i][k].begin(),dp[i][k].end(),[](pii a, pii b){return a.second < b.second;});
                    int Mk = Mx.second;
                    chmax(dp[i+1][p][k], Mk);
                    chmax(dp[i+1][q][k], Mk);
                    chmax(dp[i+1][r][k], Mk);
                    chmax(dp[i+1][k][p], Mk);
                    chmax(dp[i+1][k][q], Mk);
                    chmax(dp[i+1][k][r], Mk);
                }
            }            

            if(dp[i].find(p)!=dp[i].end()) {if(dp[i][p].find(p)!=dp[i][p].end()) {chmax(dp[i+1][q][r], dp[i][p][p] + 1), chmax(dp[i+1][r][q], dp[i][p][p] + 1);}}
            if(dp[i].find(q)!=dp[i].end()) {if(dp[i][q].find(q)!=dp[i][q].end()) {chmax(dp[i+1][p][r], dp[i][q][q] + 1), chmax(dp[i+1][r][p], dp[i][q][q] + 1);}}
            if(dp[i].find(r)!=dp[i].end()) {if(dp[i][r].find(r)!=dp[i][r].end()) {chmax(dp[i+1][p][q], dp[i][r][r] + 1), chmax(dp[i+1][q][p], dp[i][r][r] + 1);}}
        }
        dp[i].clear();
    }
    int ans = 0;
    for(auto [a,mp]:dp[N]){
        for(auto [b,c]:mp){
            if((a==b) && (b==A[3*N-1])) ans = max(ans, c + 1);
            else ans = max(ans, c);
        }
    }
    cout << ans << endl;
    return 0;
} 

int main()
{
    input();
    solve();
    return 0;
}

