struct Node{
    int i,j;
    int value;
    Node(){}
    Node(int i,int j,int value):i(i),j(j),value(value){}
    bool operator < (const Node& other)const{
        return value<other.value;
    }
};
int a[6005];
Node wait[10000005];

int max(int a,int b){ return a>b?a:b; }

int getExtra(int a,int b,int c){
    return a==b && a==c;
}

int isGood(int left[3]){
    if(left[0]==left[1] && left[0]==left[2]) return 1;
    else return 0;
}

int main(){
    int n;
    scanf("%d",&n);
    for(int i = 1; i <= 3*n; i++) scanf("%d",&a[i]);
    std::priority_queue<Node>Q;
    Q.push(Node(a[1],a[2],0));
    int ans = 0;
    for(int i = 3; i <= 3*n; i+=3){
        int maxn = -1, nextMaxn = -1, size = 0;
        while(Q.size()!=0){
            Node u = Q.top(); Q.pop();
            if(u.value+2<maxn || u.value+1+2<nextMaxn){
                while(Q.size()!=0) Q.pop();
            }
            else{
                int x = u.i, y = u.j;
                if(i==3*n){
                    int offer = u.value;
                    if(x==y && x==a[i]) offer++;
                    ans = max(ans,offer);
                }
                else{
                    //no
                    int offer = u.value;
                    if(a[i]==a[i+1] && a[i]==a[i+2]) offer++;
                    if(offer+2>=nextMaxn){
                        nextMaxn = max(offer+2,nextMaxn);
                        wait[++size] = Node(x,y,offer);
                    }
                    //1
                    for(int j = 0; j < 3; j++){
                        int left[3] = {-1,-1,-1}; int cnt = 0;
                        for(int k = 0; k < 3; k++){
                            if(j!=k) left[cnt++] = a[i+k];
                        }
                        left[2] = x;
                        int offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait[++size] = Node(y,a[i+j],offer);
                        }
                        left[2] = y;
                        offer = u.value+isGood(left);
