int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    int n;
    cin >> n;
    vl a(n * 3 + 2);
    rep(i, n * 3) {
        cin >> a[i];
        a[i]--;
    }
    a[n * 3] = n;
    a[n * 3 + 1] = n;

    mat<ll> dp(n + 1, vl(n + 1, -inf));
    vl mx(n + 1, -inf);

    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    mx[a[0]] = 0;
    mx[a[1]] = 0;

    ll lazy = 0;
    rep(i, n) {
        vl s = {a[i * 3 + 2], a[i * 3 + 3], a[i * 3 + 4]};
        unordered_map<ll, unordered_map<ll, ll>> tmp;
        sort(all(s));
        if (s[0] == s[1] && s[1] == s[2]) {
            lazy++;
        } else if (s[0] == s[1] || s[1] == s[2]) {
            int b = s[0];
            int c = s[2];
            if (c == s[1]) swap(b, c);

            rep(j, n + 1) {
                tmp[j][b] = mx[j];
                tmp[j][c] = mx[j];
                chmax(tmp[j][c], dp[j][b] + 1);

                chmax(tmp[b][b], mx[j]);
                chmax(tmp[b][c], mx[j]);
                chmax(tmp[c][b], mx[j]);
            }
            chmax(tmp[b][b], dp[c][c] + 1);
            chmax(tmp[b][c], dp[b][b] + 1);
            chmax(tmp[c][b], dp[b][b] + 1);
        } else {
            //一枚だけ変更
            rep(j, 3) {
                rep(k, n + 1) chmax(tmp[k][s[j]], mx[k]);
                //人組プラス
                rep(k, 3) {
                    if (j == k) continue;
                    chmax(tmp[s[k]][s[j]], dp[s[k]][s[k]] + 1);
                }
            }
            //二枚とも変更
            rep(j, 3) {
                rep(k, 3) {
                    if (j == k) continue;
                    rep(l, n + 1) chmax(tmp[s[j]][s[k]], mx[l]);
                    // 1組プラス
                    chmax(tmp[s[j]][s[k]], dp[3 - j - k][3 - j - k] + 1);
                }
            }
        }
        for (auto [x, line] : tmp) {
            for (auto [y, value] : line) {
                chmax(dp[x][y], value);
                chmax(mx[x], dp[x][y]);
            }
        }
    }
    print(lazy + vmax(mx));
}

