int main()
{
    int n;
    cin >> n;
    auto a = vector<int>(3 * n);
    for (auto& a_i : a) {
        cin >> a_i;
    }

    auto score = 0LL;
    auto pending_cards = multiset<int>{};
    auto fixed_cards = multiset<int>{};
    auto draw_cards = array<int, 3>{};

    fixed_cards.insert(a[0]);
    fixed_cards.insert(a[1]);

    const auto two_from_draw = [&](int a, int b, int c) -> bool {
        assert(a == b);

        // one from fixed card set
        if (auto itr = fixed_cards.find(a); itr != fixed_cards.end()) {
            fixed_cards.erase(itr);
            fixed_cards.insert(c);
            score++;
            return true;
        }

        // or, one from pending card set
        if (auto itr = pending_cards.find(a); itr != pending_cards.end()) {
            pending_cards.erase(itr);
            fixed_cards.insert(c);
            score++;
            return true;
        }

        return false;
    };

    const auto one_from_draw = [&](int a, int b, int c) -> bool {
        assert(fixed_cards.size() <= 2);

        // two from fixed card set
        if (fixed_cards.size() == 2) {
            auto f1 = *fixed_cards.begin();
            auto f2 = *fixed_cards.rbegin();
            if (f1 == f2 && f1 == a) {
                fixed_cards.clear();
                fixed_cards.insert(b);
                fixed_cards.insert(c);
                pending_cards.clear();
                score++;
                return true;
            }
            return false;
        }

        // or, one from fixed card set and another from pending
        if (fixed_cards.size() == 1) {
            if (*fixed_cards.begin() == a) {
                auto itr = pending_cards.find(a);
                if (itr != pending_cards.end()) {
                    fixed_cards.clear();
                    fixed_cards.insert(b);
                    fixed_cards.insert(c);
                    pending_cards.clear();
                    score++;
                    return true;
                }
            }
            return false;
        }

        // or, two from pending card set
        if (fixed_cards.size() == 0) {
            auto itr = pending_cards.find(a);
            if (itr != pending_cards.end()) {
                auto itr2 = itr;
                ++itr2;
                if (itr2 != pending_cards.end() && *itr2 == a) {
                    fixed_cards.clear();
                    fixed_cards.insert(b);
                    fixed_cards.insert(c);
                    pending_cards.clear();
                    score++;
                    return true;
                }
            }
            return false;
        }

        return false;
    };

#ifdef NDEBUG
#  define dump() static_cast<void>(0)
#else
    const auto dump = [&]() {
        cerr << "pending {";
        for (auto x : pending_cards) cerr << " " << x;
        cerr << " }";
        cerr << " fixed {";
        for (auto x : fixed_cards) cerr << " " << x;
        cerr << " }";
        cerr << " draw {";
        for (auto x : draw_cards) cerr << " " << x;
        cerr << " }\n";
    };
#endif


    for (int i = 0; i < n - 1; ++i) {
        assert((fixed_cards.size() == 2 && pending_cards.size() == 0) ||
               (fixed_cards.size() == 1 && pending_cards.size() >= 1) ||
               (fixed_cards.size() == 0 && pending_cards.size() >= 2));

        for (int j = 0; j < 3; ++j) {
            draw_cards[j] = a[2 + 3 * i + j];
        }

        // sort cards: A <= B <= C
        sort(draw_cards.begin(), draw_cards.end());
        dump();
        // use these cards greedily

        if (draw_cards[0] == draw_cards[2]) { // Three-cards: A = B = C
            score++;
            continue;
        }

        if (draw_cards[0] == draw_cards[1]) { // 1-pair: A = B < C
            if (two_from_draw(draw_cards[0], draw_cards[1], draw_cards[2])) {
                continue;
            }
        }
        if (draw_cards[1] == draw_cards[2]) { // 1-pair: A < B = C
            if (two_from_draw(draw_cards[1], draw_cards[2], draw_cards[0])) {
                continue;
            }
        }
        if (one_from_draw(draw_cards[0], draw_cards[1], draw_cards[2]) ||
            one_from_draw(draw_cards[1], draw_cards[2], draw_cards[0]) ||
            one_from_draw(draw_cards[2], draw_cards[0], draw_cards[1]) ) {
            continue;
        }

        // Move cards to pending ones.
        for (auto x : draw_cards) pending_cards.insert(x);
        for (auto x : fixed_cards) pending_cards.insert(x);
        fixed_cards.clear();
        draw_cards = {-1, -1, -1};
    }

    // Handle the last card.
    draw_cards = {a.back(), -1, -2};
    dump();
    one_from_draw(draw_cards[0], draw_cards[1], draw_cards[2]);



    cout << score << endl;
    return 0;
}

