struct SegmentTree {
    int N;
    vector<Int> A;
    SegmentTree(int n) {
        N = 1;
        while (N < n) N *= 2;
        A.resize(2 * N);
    }
    void set(int idx, Int val) {
        idx += N;
        A[idx] = val;
        idx >>= 1;
        while (idx > 0) {
            A[idx] = max(A[2*idx+0], A[2*idx+1]);
            idx >>= 1;
        }
    }
    Int get(int idx) {
        return A[idx + N];
    }
    void chmax(int idx, Int val) {
        if (get(idx) < val) set(idx, val);
    }
    Int maxrange(int L, int R) {
        L += N, R += N;
        Int ans = -1e18;
        while (L < R) {
            if (L & 1) ans = max(ans, A[L++]);
            if (R & 1) ans = max(ans, A[--R]);
            L >>= 1, R >>= 1;
        }
        return ans;
    }
};
