            int two = 0, one = 0;
            if (B[0] == B[1]) two = B[0], one = B[2];
            if (B[1] == B[2]) two = B[1], one = B[0];
            if (B[2] == B[0]) two = B[2], one = B[1];
            vector<int> two_j(N), j_max(N);
            for (int j = 0; j < N; j++) {
                two_j[j] = st[two].get(j);
