int main() {
  cin.tie(nullptr)->sync_with_stdio(false);
  int64_t n;
  cin >> n;
  vector<int> a(3 * n);
  for (auto&& e : a) cin >> e, --e;
  __gnu_pbds::gp_hash_table<int64_t, int> mp;
  array<int, 5> v;
  auto f = [&](auto&& self, int x, int y, int i) -> int {
    if (i == 3 * n - 1) return x == y and y == a[i];
    auto k = x + n * (y + n * i);
    if (mp.find(k) != end(mp)) return mp[k];
    v = {x, y, a[i], a[i + 1], a[i + 2]};
    sort(begin(v), end(v));
    if (v[0] == v[2]) return mp[k] = self(self, v[3], v[4], i + 3);
    if (v[1] == v[3]) return mp[k] = self(self, v[0], v[4], i + 3);
    if (v[2] == v[4]) return mp[k] = self(self, v[0], v[1], i + 3);
    int res = 0;
    for (int _ = 3; _--;) {
      shuffle(begin(v), end(v), rng);
      res = max(res, self(self, v[3], v[4], i + 3));
    }
    return mp[k] = res;
  };
  cout << f(f, a[0], a[1], 2) << '\n';
}

