int N, A[6005];

int solve(){
	int ans = 0;
	vector<vector<int>> dp(N+1, vector<int>(N+1, -1));
	int all = 0;
	dp[min(A[0], A[1])][max(A[0], A[1])] = 0;

	for(int i=2; i<N*3; i+=3){
		if(A[i] == A[i+1] && A[i] == A[i+2]){
			all++;
			continue;
		}

		vector<int> cs = {A[i], A[i+1], A[i+2]};
		sort(cs.begin(), cs.end());

		if(cs[0] == cs[1]){
			int t = cs[0], a = cs[2];
			dp[t][t] = max(dp[t][t], dp[a][a] >= 0 ?  dp[a][a] + 1 : -1);
			for(int b=1; b<=N; b++){
				int p = dp[min(t,b)][max(t, b)];
				dp[min(a, b)][max(a,b)] = max(dp[a][b], p>=0 ? p + 1 : -1);
			}
			continue;
		}

		if(cs[1] == cs[2]){
			int t = cs[1], a = cs[0];
			dp[t][t] = max(dp[t][t], dp[a][a] >= 0 ?  dp[a][a] + 1 : -1);
			for(int b=1; b<=N; b++){
				int p = dp[min(t,b)][max(t, b)];
				dp[min(a, b)][max(a,b)] = max(dp[a][b], p>=0 ? p + 1 : -1);
			}
			continue;
		}

		int a = cs[0], b = cs[1], c = cs[2];
		dp[a][b] = max(dp[a][b], dp[c][c] + 1);
		dp[b][c] = max(dp[b][c], dp[a][a] + 1);
		dp[a][c] = max(dp[a][c], dp[b][b] + 1);


	}

	for(int a=1; a<=N; a++){
		for(int b=1; b<=N; b++){
			ans = max(ans, dp[a][b]);
		}
	}
	ans = max(ans, dp[0][0]);
	return ans + all;
}


