        vector<int> X{i, j, n};
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (i == j && X[i] != n) {
                    continue;
                }
                dp[X[i]][X[j]] = max(dp[X[i]][X[j]], v);
            }
        }
    };

