    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) t[i][j] = -oo;
    vector<int> v({x, y, z});
    do {
        x = v[0]; y = v[1]; z = v[2];
        for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
            t[i][j] = max(t[i][j], dp[i][j] + ((x == y) && (y == z)));
            t[x][y] = max(t[x][y], dp[i][j] + ((i == j) && (j == z)));
            t[i][z] = max(t[i][z], dp[i][j] + ((x == y) && (y == j)));
        }
    } while(next_permutation(v.begin(), v.end()));

    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) dp[i][j] = t[i][j];
}

