const int N = 6005;
int n, a[N], now, ans, v[N];

bool cmp(int a, int b) {
	return v[a] <= v[b];
}
bool cmp1(int a, int b) {
	return a > b;
}

int main() {
    cin >> n;
    now = 1;
    for (int i = 1; i <= 3 * n; i++) scanf("%d", &a[i]), v[a[i]]++;
    for (int i = 1; i < n; i++) {
        int sum1 = 0, sum2 = 0, q[6] = {};
        for (int i = now; i <= now + 4; i++) q[i - now] = a[i];
        sort(q, q + 5);
    	if (q[0] == q[0 + 1] && q[1] == q[0 + 2]) sum1++;
    	for (int i = now; i <= now + 4; i++) q[i - now] = a[i];
    	sort(q, q + 5, cmp1);
    //    for (int i = 0; i <= 4; i++) printf("%d ", q[i]);
      //  puts("");
        if (q[0] == q[0 + 1] && q[1] == q[0 + 2]) sum2++;
        //printf("%d %d\n", sum1, sum2);
        if (q[1] == q[2] && q[2] == q[3]) {
        	ans+=1;
        	for (int i = now; i <= now + 4; i++) q[i - now] = a[i];
        	a[now + 3] = q[0];
            a[now + 4] = q[4];
            now += 3;
            continue;
        }
        if (q[2] == q[3] && q[4] == q[3]) {
        	ans+=1;
        	for (int i = now; i <= now + 4; i++) q[i - now] = a[i];
        	a[now + 3] = q[1];
            a[now + 4] = q[0];
            now += 3;
            continue;
        }
        if (!sum1 && !sum2) {
            sort(a + now, a + now + 5, cmp);
        } else {
        	if (sum1==1) sort(a + now, a + now + 5);
        	else sort(a + now, a + now + 5, cmp1);
        	ans += 1;
        }
        for (int i = now; i <= now + 2; i++) v[a[i]]--;
        now += 3;
    }
    if (a[now] == a[now + 1] && a[now + 1] == a[now + 2]) ans++;
    printf("%d\n", ans);
}

