                        }
                        else if(mp.size()==1){
                            mp.push_back(cnt_max.first);
                        }
                        // sort(mp.begin(),mp.end(),greater<int>());
                        dp[i+3][mp[0]][mp[1]] = c+1;
                    }
                    else{
                        dp[i+3] = dp[i];
                        dp[i+3][vec[0]][vec[1]] = c;
                        dp[i+3][vec[0]][vec[2]] = c;
                        dp[i+3][vec[1]][vec[2]] = c;

                        dp[i+3][a][vec[0]] = c;
                        dp[i+3][a][vec[1]] = c;
                        dp[i+3][a][vec[2]] = c;

                        dp[i+3][b][vec[0]] = c;
                        dp[i+3][b][vec[1]] = c;
                        dp[i+3][b][vec[2]] = c;
                    }
                    // do
                    // {
                    //     if(combi[0] < combi[1]) continue;
                    //     if(combi[2]==combi[3] && combi[3]==combi[4]){
                    //         dp[i+3][combi[0]][combi[1]] = c+1;
