void solve() {
  int N;
  in(N);
  vi A(3 * N);
  in(A);
  each(x, A) x--;
  int ans = 0;
  vi used(N, 0);
  {
    vi cnt(N);
    int lim = 5;
    rep(i, 3 * N) {
      if (i == lim) break;
      if (++cnt[A[i]] == 3) {
        lim += 3;
        ans++;
        used[A[i]] = 1;
      }
    }
  }
  vi l(3 * N, 3 * N), r(3 * N, -1);
  rep(i, 3 * N) {
    amin(l[A[i]], i);
    amax(r[A[i]], i);
  }

  vp v;
  rep(i, N) {
    if (!used[i]) v.eb(l[i], r[i]);
  }
  sort(all(v), [](P a, P b) { return a.second < b.second; });

  int R = -1;
  rep(i, sz(v)) {
    while (i != sz(v) and R >= v[i].first) i++;
    if (i == sz(v)) break;
    ans++;
    R = v[i].second;
  }
  out(ans);
}

