int main()
{
    int N;
    cin >> N;

    vector<int> A(N * 3);
    for (auto& a : A) { cin >> a; }

    vector< map<int, map<int, int> > > dp(N);
    queue< tuple<int, int, int> > Q;

    const auto update = [&](int index, int x, int y, int a, int b, int c, int score)
    {
        const auto xx = x < y ? x : y;
        const auto yy = x < y ? y : x;

        const auto newScore = score + (a == b && b == c ? 1 : 0);
        if (newScore <= dp[index][xx][yy]) { return; }

        dp[index][xx][yy] = newScore;
        Q.emplace(index, xx, yy);
    };

    update(0, A[0], A[1], 1, 2, 3, 1);

    int ans = 0;

    while (!Q.empty())
    {
        const auto& node = Q.front();
        const auto index = get<0>(node);
        const auto a1    = get<1>(node);
        const auto a2    = get<2>(node);
        const auto a3    = A[index * 3 + 2];
        Q.pop();

        const auto score = dp[index][a1][a2];

        if (index >= N - 1)
        {
            ans = max(ans, score + (a1 == a2 && a2 == a3 ? 1 : 0) - 1);
            continue;
        }

        const auto a4 = A[index * 3 + 3];
        const auto a5 = A[index * 3 + 4];

        update(index + 1, a1, a2, a3, a4, a5, score);
        update(index + 1, a1, a3, a2, a4, a5, score);
        update(index + 1, a1, a4, a2, a3, a5, score);
        update(index + 1, a1, a5, a2, a3, a4, score);

        update(index + 1, a2, a3, a1, a4, a5, score);
        update(index + 1, a2, a4, a1, a3, a5, score);
        update(index + 1, a2, a5, a1, a3, a4, score);

        update(index + 1, a3, a4, a1, a2, a5, score);
        update(index + 1, a3, a5, a1, a2, a4, score);

        update(index + 1, a4, a5, a1, a2, a3, score);
    }

    cout << ans << endl;

    return 0;
}

