	int N;
	cin >> N;

	vector<int> A(3 * N);
	REP(i, 3 * N) scanf("%d", &A[i]), --A[i];

	set<pii> ss;
	set<int> ss_k;
	int ans = 0;

	ss.emplace(A[0], A[1]);
	ss_k.insert(A[0]);
	ss_k.insert(A[1]);

	REP(i, N - 1) {
		set<pii> nex;
		set<int> nex_k;
		int idx = i * 3 + 2;

		bool cp = false;
		FOR(s, 1, 1 << 3) {
			vector<int> v, ev;
			REP(j, 3) {
				if (s >> j & 1) v.emplace_back(A[idx + j]);
				else ev.emplace_back(A[idx + j]);
			}

			if (v.size() == 1) {
				if (ss.find(pii(v[0], v[0])) != ss.end()) {
					nex.emplace(ev[0], ev[1]);
					nex_k.insert(ev[0]);
					nex_k.insert(ev[1]);
				}
			}
			else if (v.size() == 2) {
				if (v[0] != v[1]) continue;
				for (int j : ss_k) {
					if (ss.find(pii(v[0], j)) != ss.end()
						|| ss.find(pii(j, v[0])) != ss.end()) {
							nex.emplace(j, ev[0]);
							nex_k.insert(j);
							nex_k.insert(ev[0]);
					}
				}
			}
			else if (v.size() == 3) {
				if (v[0] != v[1] || v[1] != v[2]) continue;
				cp = true;
			}
		}

		if (cp || !nex.empty()) ++ans;
		else {
			FOR(s, 1, 1 << 3) {
				vector<int> ev;
				REP(j, 3) if (~s >> j & 1) ev.emplace_back(A[idx + j]);

				if (ev.size() == 0) {
					cp = true;
				}
				else if (ev.size() == 1) {
					for (int c : ss_k) {
						nex.emplace(ev[0], c);
						nex_k.insert(ev[0]);
						nex_k.insert(c);
					}
				}
				else if (ev.size() == 2) {
					nex.emplace(ev[0], ev[1]);
					nex_k.insert(ev[0]);
					nex_k.insert(ev[1]);
				}
			}
		}
		if (cp) {
			for (pii c : nex) {
				ss.emplace(c);
				ss_k.insert(c.first);
				ss_k.insert(c.second);
			}
		}
		else {
			ss = std::move(nex);
			ss_k = std::move(nex_k);
		}
	}
	if (ss.find(pii(A[3 * N - 1], A[3 * N - 1])) != ss.end()) ++ans;
	cout << ans << endl;
	return 0;
}

