	value() {}
	value(int a, int b, int val) {
		this->a = a, this->b = b, this->val = val;
	}
};
vector<value> dat;

bool inline all_same(int a, int b, int c) {
	return a == b && b == c;
}

void inline upd(int a, int b, int val) {
	dat.push_back({a, b, val});
}

void inline upd_all() {
	for (auto&[a, b, val] : dat) {
		f[a][b] = max(f[a][b], val);
		f[b][a] = max(f[b][a], val);
		mx[a] = max(mx[a], val);
		mx[b] = max(mx[b], val);
		maxi = max(maxi, val);
	}
	dat.clear();
}

