	memset(mx, -inf, sizeof(mx));
	maxi = -inf;
	upd(a[1], a[2], 0);
	upd_all();
	loop (rnd, n) {
		int i = rnd * 3 + 3;
		sort(a + i, a + i + 3);
		if (a[i] == a[i + 2]) { ans += 1; continue; }
		upd(a[i + 0], a[i + 1], maxi);
		upd(a[i + 0], a[i + 2], maxi);
		upd(a[i + 1], a[i + 2], maxi);
