			upd(a[i + 1], a[i + 2], f[k][k] + all_same(k, k, a[i + 0]));
		}
		cont (k, n) {
			upd(k, a[i + 0], mx[k]);
			if (a[i + 1] == a[i + 2]) upd(k, a[i + 0], f[k][a[i + 1]] + 1);
			upd(k, a[i + 1], mx[k]);
			if (a[i + 0] == a[i + 2]) upd(k, a[i + 1], f[k][a[i + 0]] + 1);
			upd(k, a[i + 2], mx[k]);
			if (a[i + 0] == a[i + 1]) upd(k, a[i + 2], f[k][a[i + 0]] + 1);
		}
		upd_all();
	}
	ans += maxi;
	printf("%d\n", ans);
}

