int main()
{

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int n; cin >> n;
	vector<int> a(n * 3); for (int i = 0; i < n * 3; i++) cin >> a[i], a[i]--;
	dp.assign(n, vector<int>(n, -1));
	dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
	int pl = 0;
	for (int i = 2; i + 2 < 3 * n; i += 3) {
		if (a[i] == a[i + 1] and a[i + 1] == a[i + 2]) {
			pl++;
			continue;
		}
		for (int kkt = 0; kkt < 3; kkt++) {
			vector<int> v;
			int r = a[i + kkt];
			for (int j = 0; j < 3; j++) if (j != kkt) v.emplace_back(a[i + j]); 
			if(dp[r][r] != -1) st(v[0], v[1], dp[r][r] + 1);
			if (v[0] == v[1]) {
				for (int j = 0; j < n; j++) if (dp[v[0]][j] != -1) st(r, j, dp[v[0]][j] + 1);
			}
			else {
				for (int j = 0; j < n; j++) st(r, j, max(dp[v[0]][j],dp[v[1]][j]));
			}
		}
		upd();
	}
	int res = 0; 
	for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
		if (i == j and i == a.back()) {
			chmax(res, dp[i][j] + 1);
		}
		else {
			chmax(res, dp[i][j]);
		}
	}
	res += pl;
	cout << res << endl;
}

