bool check(vi&a, int s)
{
	sort(a.begin()+s, a.begin()+s+5);
	if(a[s]==a[s+2]) return true;

	swap(a[s], a[s+4]);
	swap(a[s+1], a[s+3]);

	if(a[s+2]==a[s+3])
	{
		swap(a[s+3], a[s+1]);
	}
	for(int i=a.size()-1;i>s+2;i--)
	{
		if(a[i]==a[s+0]) a[i]+=a.size();
		if(a[i]==a[s+1]) a[i]+=a.size();
		if(a[i]==a[s+2]) a[i]+=a.size();
	}
	return false;
}


