vector<vector<int>> build(int D, const vector<vector<pint>> &dpe)
{
    vector<vector<int>> ret(D, vector<int>(D + 1));
    REP(i, ret.size())
    {
        FOR(j, i, ret[i].size() - 1)
        {
            for (auto [k, adv] : dpe[j])
            {
                chmax(ret[i][k], ret[i][j] + adv);
            }
            chmax(ret[i][j + 1], ret[i][j]);
        }
    }
    return ret;
}

