  arr[i] = a, arr[i + 1] = b;

  int ans = 0;
  for (int j = 0; j < 5; j++)
    for (int k = j + 1; k < 5; k++)
    {
      int other = 0, cnt = 0;
      for (int hehe = 0; hehe < 5; hehe++)
        if (hehe != j && hehe != k)
        {
          if (other == 0) other = arr[i + hehe];
          if (arr[i + hehe] == other)
            cnt++;
        }
      ans = max(ans, (cnt == 3) + solve(i + 3, arr[i + j], arr[i + k]));
    }

  arr[i] = prv, arr[i + 1] = prv2;

  return memo[i][a][bdiv][kind] = ans;
}

