int q(int N, vi A) {
  int ans = 0;
  vp v;
  vi used(N * 3);
  vvi memo(N);
  rep(i, 3 * N) {
    if (used[i]) continue;
    memo[A[i]].pb(i);
    if (sz(memo[A[i]]) >= 3) {
      int s = sz(memo[A[i]]);
      int l = memo[A[i]][s - 3];
      int r = memo[A[i]][s - 1];
      v.emplace_back(l, r);
    }
  }

  sort(all(v), [](P a, P b) { return a.second < b.second; });

  int R = -1;
  rep(i, sz(v)) {
    while (i != sz(v) and R >= v[i].first) i++;
    if (i == sz(v)) break;
    ans++;
    R = v[i].second;
  }

  return ans;
}

void solve() {
  int N;
  in(N);
  vi A(3 * N);
  in(A);
  each(x, A) x--;
  int ans = 0;

  vi used(N * 3);
  {
    int lim = 5;
    vvi memo(N);
    rep(i, 3 * N) {
      if (i == lim) break;
      memo[A[i]].pb(i);
      if (sz(memo[A[i]]) >= 3) {
        rep(_, 3) {
          used[memo[A[i]].back()] = 1;
          memo[A[i]].pop_back();
        }
        lim += 3;
        ++ans;
      }
    }
  }
  trc(used);

  vi B;
  rep(i, 3 * N) if (!used[i]) B.push_back(A[i]);
  swap(A, B);
  trc(A);
  if (sz(A) < 5) die(ans);
  trc(ans, A);

  int bns = 0;
  sort(begin(A), begin(A) + 5);
  do {
    amax(bns, q(sz(A) / 3, A));
  } while (next_permutation(begin(A), begin(A) + 5));
  out(ans + bns);
}

