			y[tb][ta] = max(y[tb][ta], tc);
			mx[ta] = max(mx[ta], tc);
			mx[tb] = max(mx[tb], tc);
			mxx = max(mxx, tc);
		}
	}
	y[x[n * 3 - 1]][x[n * 3 - 1]]++;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			ans = max(ans, y[i][j]);
	printf("%d\n", ans + add);
}

