int main() {
	int N;
	cin >> N;
	vector<int> A(3 * N + 3, 0);
	map<int,set<int> > P; // (書かれている数字, {場所})
	for (int i = 1; i <= 3 * N + 1; i++){
		cin >> A[i];
		P[A[i]].insert(i);
	}

	int c = 0; // score count
	map<int,int> B; // current mybag
	B[A[1]]++; P[A[1]].erase(1);
	B[A[2]]++; P[A[2]].erase(2);
	for(int i = 3; i <= 3*N; i += 3){
		B[A[i  ]]++; P[A[i  ]].erase(i  );
		B[A[i+1]]++; P[A[i+1]].erase(i+1);
		B[A[i+2]]++; P[A[i+2]].erase(i+2);
		map<int,int> S; // cost,number
		int slide = 1;
		for(auto it = B.begin(); it != B.end(); it++){
			if(it->second >= 3){
				S[0] = it->first;
			}else{
				if(it->second == 2){
					if(P[it->first].size() >= 1){
						S[*P[it->first].begin()] = it->first;
					}else{
						S[3*N+slide] = it->first;
						slide++;
					}
				}else{ // it->second == 1
					if(P[it->first].size() >= 2){
						S[*(P[it->first].begin()++)] = it->first;
					}else{
						S[3*N+slide] = it->first;
						slide++;
					}
				}
			}
		}
		if(S.find(0) != S.end()){
			B[S[0]] -= 3;
			c++;
			if(B[S[0]] == 0){
				B.erase(S[0]);
			}
			continue;
		}
		int r = 3;
		for(auto it = S.rbegin(); it != S.rend(); it++){
			int d = (r <= B[it->second] ? r : B[it->second]);
			B[it->second] -= d;
			r -= d;
			if(B[it->second] == 0){
				B.erase(it->second);
			}
			if(r == 0){
				break;
			}
		}
	}
	cout << c << endl;
	return(0);
}

