const int N = 2e3+1;
int dp[N][N];

void solve() {
	int n; cin >> n;

	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= n; j++) {
			dp[i][j] = -n;
		}
	}
	int a[n*3+1], ans = 0;
	for(int i = 1; i <= n*3; i++)
		cin >> a[i];

	dp[a[1]][a[2]] = dp[a[2]][a[1]] = 0;

	auto same = [&](int x, int y) {
		std::vector<pair<pii, int> > v;
		v.pb(mp(mp(x, x), max(dp[x][x], dp[y][y]+1))) ;
		for(int i = 1; i <= n; i++) {
			v.pb(mp(mp(i, y), max({dp[i][y], dp[i][x]+1, dp[x][i]+1})));
			v.pb(mp(mp(y, i), max({dp[y][i], dp[i][x]+1, dp[x][i]+1})));
		}
		for(auto u : v) {
			dp[u.F.F][u.F.S] = u.S;
		}
	};

	for(int i = 1; i < n; i++) {
		int x = a[i*3], y = a[i*3+1], z = a[i*3+2];

		if(x == y && x == z) {
			ans++;
			continue;
		}
		else if(x == y) same(x, z);
		else if(x == z) same(x, y);
		else if(y == z) same(y, x);
		else {
			dp[x][y] = max(dp[x][y], dp[z][z]+1);
			dp[y][x] = max(dp[y][x], dp[z][z]+1);
			dp[x][z] = max(dp[x][z], dp[y][y]+1);
			dp[z][x] = max(dp[z][x], dp[y][y]+1);
			dp[z][y] = max(dp[z][y], dp[x][x]+1);
			dp[y][z] = max(dp[y][z], dp[x][x]+1);
		} 
	}
	int mx = 0;
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= n; j++)
			mx = max(mx, dp[i][j]+ans+(i == j && i == a[n*3]));
	}
	cout << mx << endl;
}

