const int INF = 1<<29;
int solve(int N) {
    int offset = 0;
    int a, b, end;
    cin >> a >> b;
    --a, --b;
    vector<vector<int>> A;
    for (int i = 0; i < N-1; ++i) {
        vector<int> v(3);
        for (int j = 0; j < 3; ++j) cin >> v[j], --v[j];
        sort(v.begin(), v.end());
        if (v[0] == v.back()) ++offset;
        else A.push_back(v);
    }
    cin >> end;
    --end;
    vector<vector<int>> dp(N, vector<int>(N, -INF));
    dp[a][b] = dp[b][a] = 0;
    int ma = -INF, nma;
    vector<int> vma(N, -INF), nvma;
    vma[a] = vma[b] = 0;

    auto func = [&](int a, int b, int val) {
        chmax(dp[a][b], val);
        chmax(dp[b][a], val);
        chmax(nma, val);
        chmax(nvma[a],val);
        chmax(nvma[b], val);
    };
    for (auto v : A) {
        nma = ma;
        nvma = vma;

        // 前の 2 個が一緒
        for (int i = 0; i < 3; ++i) {
            for (int p = 0; p < N; ++p) {
                func(v[i], p, dp[p][p] + 1);
            }
        }

        // 3 つのうち 2 つが一緒のとき
        if (v[0] == v[1]) {
            func(v[0], v[2], vma[v[0]] + 1);
        }
        else if (v[1] == v[2]) {
            func(v[0], v[2], vma[v[2]] + 1);
        }

        // 前の 2 個を共に捨てる
        for (int i = 0; i < 3; ++i) {
            for (int j = i+1; j < 3; ++j) {
                func(v[i], v[j], ma);
            }
        }

        // 前のうち 1 個を捨てる
        for (int i = 0; i < 3; ++i) {
            for (int p = 0; p < N; ++p) {
                func(v[i], p, vma[p]);
            }
        }
        ma = nma;
        vma = nvma;
/*
        cout << "-----------" << endl;
        COUT(v);
        for (int a = 0; a < N; ++a) {
            for (int b = 0; b < N; ++b) {
                if (dp[a][b] >= 0) {
                    cout << a << ", " << b << ": " << dp[a][b] << endl;
                }
            }
        }
     */   
    }
    int res = 0;
    for (int a = 0; a < N; ++a) {
        for (int b = 0; b < N; ++b) {
            if (a == end && b == end) chmax(res, dp[a][b] + 1);
            else chmax(res, dp[a][b]);
        }
    }
    return res + offset;
}

int main() {
    int N;
    while (cin >> N) cout << solve(N) << endl;
}

