vector <Info> updates;

inline int get(int n,int pos)
{
	return a[n*3-2+pos];
}

inline void update()
{
	int x=1,y=2,v=3;
	for(auto info:updates)
	{
		x=info.x;
		y=info.y;
		v=info.v;
		chmax(dp1[x][y],v);
		chmax(dp1[y][x],v);
		chmax(dp2[x],v);
		chmax(dp2[y],v);
		chmax(dp3,v);
	}
	updates.clear();
}

