    cin >> a[i];
  }
  reverse(a + 1, a + n + 1);
  for (int i = 1; i <= n; i++)
    where[a[i]].push_back(i);

  while (n >= 5) {
    map<int, int> f;
    vector<int> vals;
    for (int j = 0; j < 5; j++) vals.push_back(a[n - j]);
    for (auto &it : vals) f[it]++;
    bool fo = 0;
    for (auto &it : f) {
      if (it.second >= 3) {
        fo = 1;
        it.second -= 3;
      }
    }
    if (fo) {
      sol++;
