{
  int n; cin >> n;
  vector<int> a(3*n);
  rep(i,3*n) {
    cin >> a[i];
    a[i]--;
  }
  a.push_back(n);
  a.push_back(n);  

  using vi = vector<int>;
  using vii = vector<vi>;
  vii dp(n+1, vi(n+1, -1));
  int res = 0;
  dp[a[0]][a[1]] = 0;
  rep(i,n) {
    map<pi,int> ndp;
    int k = 3*i + 2;
    if(a[k] == a[k+1] && a[k+1] == a[k+2]) {
      res++;
      continue;
    }
    else if(a[k] == a[k+1]) {
      rep(j,n) {
	if(dp[a[k]][j] >= 0) {
	  chmax(ndp[{a[k+2], j}], dp[a[k]][j] + 1);
	  chmax(ndp[{j, a[k+2]}], dp[a[k]][j] + 1);
	}
	if(dp[j][a[k]] >= 0) {
	  chmax(ndp[{a[k+2], j}], dp[j][a[k]] + 1);
	  chmax(ndp[{j, a[k+2]}], dp[j][a[k]] + 1);
	}	
      }
    }
    else if(a[k+1] == a[k+2]) {
      rep(j,n) {
	if(dp[a[k+1]][j] >= 0) {
	  chmax(ndp[{a[k], j}], dp[a[k+1]][j] + 1);
	  chmax(ndp[{j, a[k]}], dp[a[k+1]][j] + 1);
	}
	if(dp[j][a[k+1]] >= 0) {
	  chmax(ndp[{a[k], j}], dp[j][a[k+1]] + 1);
	  chmax(ndp[{j, a[k]}], dp[j][a[k+1]] + 1);
	}	
      }
    }
    else if(a[k] == a[k+2]) {
      rep(j,n) {
	if(dp[a[k]][j] >= 0) {
	  chmax(ndp[{a[k+1], j}], dp[a[k]][j] + 1);
	  chmax(ndp[{j, a[k+1]}], dp[a[k]][j] + 1);
	}
	if(dp[j][a[k]] >= 0) {
	  chmax(ndp[{a[k+1], j}], dp[j][a[k]] + 1);
	  chmax(ndp[{j, a[k+1]}], dp[j][a[k]] + 1);
	}	
      }
    }
    if(dp[a[k]][a[k]] >= 0) chmax(ndp[{a[k+1], a[k+2]}], dp[a[k]][a[k]] + 1);
    if(dp[a[k+1]][a[k+1]] >= 0) chmax(ndp[{a[k], a[k+2]}], dp[a[k+1]][a[k+1]] + 1);
    if(dp[a[k+2]][a[k+2]] >= 0) chmax(ndp[{a[k], a[k+1]}], dp[a[k+2]][a[k+2]] + 1);      

    rep(j,n) {
      if(dp[a[k]][j] >= 0) {
	chmax(ndp[{a[k], j}], dp[a[k]][j]);
	chmax(ndp[{j, a[k]}], dp[a[k]][j]);
      }
      if(dp[a[k+1]][j] >= 0) {
	chmax(ndp[{a[k+1], j}], dp[a[k+1]][j]);
	chmax(ndp[{j, a[k+1]}], dp[a[k+1]][j]);
      }
      if(dp[a[k+2]][j] >= 0) {
	chmax(ndp[{a[k+2], j}], dp[a[k+2]][j]);
	chmax(ndp[{j, a[k+2]}], dp[a[k+2]][j]);
      }
      if(dp[j][a[k]] >= 0) {
	chmax(ndp[{a[k], j}], dp[j][a[k]]);
	chmax(ndp[{j, a[k]}], dp[j][a[k]]);
      }
      if(dp[j][a[k+1]] >= 0) {
	chmax(ndp[{a[k+1], j}], dp[j][a[k+1]]);
	chmax(ndp[{j, a[k+1]}], dp[j][a[k+1]]);
      }
      if(dp[j][a[k+2]] >= 0) {
	chmax(ndp[{a[k+2], j}], dp[j][a[k+2]]);
	chmax(ndp[{j, a[k+2]}], dp[j][a[k+2]]);
      }                        
    }
    for(auto val: ndp) {
      int x = val.F.F, y = val.F.S, z = val.S;
      chmax(dp[x][y], z);
    }
  }

  int tmp = 0;
  rep(i,n+1) rep(j,n+1) {
    chmax(tmp, dp[i][j]);
  }
  cout << res + tmp << "\n";

  return 0;
}

