#    define SHOW(...) static_cast<void>(0)
int main()
{
    const auto N = in.val<int>();
    auto as      = in.vec<int>(3 * N, 1);
    as.push_back(N), as.push_back(N);
    auto dp  = nd_array({N + 1, N + 1}, -inf_v<int>);
    auto mdp = nd_array({N + 1}, -inf_v<int>);

    dp[as[0]][as[1]] = dp[as[1]][as[0]] = 0;
    mdp[as[0]] = mdp[as[1]] = 0;
    int offset              = 0;
    for (int i = 0; i < 3 * N; i += 3) {
        int pqr[] = {as[i + 2], as[i + 3], as[i + 4]};
        std::sort(pqr, pqr + 3);
        const auto [p, q, r] = pqr;
        SHOW(p, q, r);

        if (p == r) {
            offset++;
            continue;
        }

        using pii = std::pair<int, int>;
        std::map<pii, int> changes;
        if (p == q) {
            for (int a = 0; a < N; a++) { chmax(changes[std::minmax(a, r)], dp[a][p] + 1); }
        } else if (q == r) {
            for (int a = 0; a < N; a++) { chmax(changes[std::minmax(a, p)], dp[a][q] + 1); }
        }
        chmax(changes[std::minmax(q, r)], dp[p][p] + 1);
        chmax(changes[std::minmax(r, p)], dp[q][q] + 1);
        chmax(changes[std::minmax(p, q)], dp[r][r] + 1);

        int totmax = -inf_v<int>;
        for (int a = 0; a < N; a++) { chmax(totmax, mdp[a]); }
        chmax(changes[std::minmax(p, q)], totmax);
        chmax(changes[std::minmax(q, r)], totmax);
        chmax(changes[std::minmax(r, p)], totmax);

        chmax(changes[std::minmax(q, r)], dp[p][p] + 1);
        chmax(changes[std::minmax(r, p)], dp[q][q] + 1);
        chmax(changes[std::minmax(p, q)], dp[r][r] + 1);

        for (int a = 0; a < N; a++) {
            chmax(changes[std::minmax(a, p)], mdp[a]);
            chmax(changes[std::minmax(a, q)], mdp[a]);
            chmax(changes[std::minmax(a, r)], mdp[a]);
        }
        for (const auto& [pos, v] : changes) {
            const auto [a, b] = pos;
            chmax(dp[a][b], v), chmax(dp[b][a], v);
            chmax(mdp[a], dp[a][b]), chmax(mdp[b], dp[b][a]);
        }
    }
    int ans = 0;
    for (int a = 0; a <= N; a++) {
        for (int b = 0; b <= N; b++) { chmax(ans, dp[a][b]); }
    }
    ans += offset;
    out.ln(ans);
    return 0;
}

