int main(){
    int N;
    cin >> N;
    vector<int> A(3*N);
    for(int i=0; i<3*N; i++) cin >> A[i], A[i]--;

    static bitset<2000> dp[2001][2000], dp_sub[2001][2000];
    dp[0][A[0]][A[1]] = dp[0][A[1]][A[0]] = 1;
    int mx = 0, fix = 0;
    for(int i=0; i<N-1; i++){
        map<int, int> mp;
        vector<int> vs;
        for(int k=0; k<3; k++){
            int v = A[3*i+k+2];
            mp[v]++;
            vs.push_back(v);
        }
        if(mp.size() == 1){
            fix++;
            continue;
        }

        int mx2 = mx;
        for(int m=mx; m>=mx-1; m--) if(m >= 0){
            for(auto [v, num] : mp){
                if(num == 2){
                    int r = 0;
                    for(auto [v2, _] : mp) if(v != v2) r = v2;
                    for(int j=0; j<N; j++) if(dp[m][v][j]){
                        mx2 = max(mx2, m+1);
                        dp[m+1][j][r] = dp[m+1][r][j] = 1;
                    }
                }
                if(num == 1){
                    vector<int> rs;
                    for(auto& [v2, num2] : mp) if(v2 != v) for(int k=0; k<num2; k++) rs.push_back(v2);
                    int r1 = rs[0], r2 = rs[1];
                    if(dp[m][v][v]){
                        mx2 = max(mx2, m+1);
                        dp[m+1][r1][r2] = dp[m+1][r2][r1] = 1;
                    }
                }
            }
        }

        for(int m=mx; m>=mx-1; m--) if(m >= 0){
            for(int j=0; j<N; j++) dp_sub[m][j].reset();
            for(int k=0; k<3; k++){
                bitset<2000> tmp;
                for(int a=0; a<3; a++) if(a != k) tmp[vs[a]] = 1;
                for(int i=0; i<N; i++) if(dp[m][i].count()) tmp[i] = 1;
                dp_sub[m][vs[k]] |= tmp;
            }
            bitset<2000> tmp;
            for(int v : vs) tmp[v] = 1;
            for(int i=0; i<N; i++) dp[m][i] |= tmp | dp_sub[m][i];
        }

        mx = mx2;
    }

    cerr << fix << endl;

    int L = A.back();
    int ans = mx + fix;
    if(dp[mx][L][L]) ans++;
    cout << ans << endl;
    return 0;
}

