#include <bits/stdc++.h>

const int MAX_N = 2005;
const int MAX_N3 = MAX_N * 3;
int cum[MAX_N][MAX_N];
int n3[MAX_N][MAX_N];
int N;
int vals[MAX_N3];
std::map<std::tuple<int, int, int>, int> mem;

int comp(int n, int v, int count_needed) {
  int lo = 0, hi = 2048;
  while (hi - lo > 1) {
    int mid = (lo + hi) / 2;
    if (mid <= n + 1) {
      lo = mid;
    } else if (mid >= N) {
      hi = mid;
    } else if (cum[mid][v] - cum[n][v] >= count_needed) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  if (cum[lo][v] - cum[n][v] >= count_needed) return lo;
  return hi;
}

int dp(int n, int a, int b) {
  if (b < a) std::swap(a, b);
  if (n == N) return 0;
  std::tuple<int, int, int> tup = {n, a, b};
  if (mem.count(tup)) return mem[tup];
  int v[5] = {vals[3 * n], vals[3 * n + 1], vals[3 * n + 2], vals[3 * n + 3], vals[3 * n + 4]};
  if (a != 0) v[0] = a;
  if (b != 0) v[1] = b;
  if (v[3] == 0) {
    mem[tup] = v[0] == v[1] && v[1] == v[2];
    return mem[tup];
  }
  int best = 0;
  std::pair<int, int> bests[5] = {};
  for (int i = 0; i < 5; ++i) {
    for (int j = i + 1; j < 5; ++j) {
      int last = 0;
      bool cando = true;
      for (int k = 0; k < 5; ++k) {
        if (k == i || k == j) continue;
        if (last == 0) last = v[k];
        if (last != v[k]) {
          cando = false;
          break;
        }
      }
      if (cando) {
        best = dp(n + 1, v[i], v[j]) + 1;
        goto end;
      }
    }
  }
  for (int i = 0; i < 3; ++i) {
    int count_needed = 2;
    if (v[i] == v[(i + 1) % 3] || v[i] == v[(i + 2) % 3]) count_needed--;
    bests[i] = {comp(n, v[i], count_needed), i};
  }
  std::sort(bests, bests + 3);
  best = dp(n + 1, v[bests[0].second], v[bests[1].second]);
  end:
  mem[tup] = best;
  return best;
}

int main() {
  scanf("%d", &N);
  int extra = 0;
  for (int i = 0; i < N; ++i) {
    scanf("%d %d %d", vals + 3 * i, vals + 3 * i + 1, vals + 3 * i + 2);
    if (vals[3*i] == vals[3*i + 1] && vals[3*i + 1] == vals[3*i + 2]) {
      extra++;
      N--;
      i--;
    }
  }
  if (N) {
    cum[0][vals[0]]++;
    cum[0][vals[1]]++;
    cum[0][vals[2]]++;
    for (int i = 1; i <= N; ++i) {
      for (int v = 0; v <= N; ++v) {
        cum[i][v] = cum[i - 1][v] + (vals[3 * i] == v) + (vals[3 * i + 1] == v) + (vals[3 * i + 2] == v);
      }
    }
  }
  printf("%d\n", dp(0, 0, 0) + extra);
}

