int main()
{
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    int N;
    cin >> N;
    vector<int> a(N * 3);
    REP(i, 0, N * 3)
    {
        cin >> a[i];
        a[i]--;
    }

    int add = 0, minf = -1e9;

    vector<vector<int>> dp(N, vector<int>(N, minf)), next_dp(N, vector<int>(N, minf));
    vector<vector<int>> max_a(2, vector<int>(N, minf)), next_max_a(2, vector<int>(N, minf));
    int max_v = 0, next_max_v = minf;
    dp[a[0]][a[1]] = 0;
    max_a[0][a[0]] = 0;
    max_a[1][a[1]] = 0;

    auto update = [&](int x, int y, int val) {
        next_dp[x][y] = max(next_dp[x][y], val);
        next_max_a[0][x] = max(next_max_a[0][x], next_dp[x][y]);
        next_max_a[1][y] = max(next_max_a[1][y], next_dp[x][y]);
        next_max_v = max(next_max_v, next_dp[x][y]);
    };

    for (int i = 2; i < N * 3 - 1; i += 3)
    {
        if (a[i] == a[i + 1] && a[i + 1] == a[i + 2])
        {
            ++add;
            continue;
        }

        vector<int> card = {a[i], a[i + 1], a[i + 2]};
        sort(card.begin(), card.end());

        REP(_, 0, 3)
        {
            REP(j, 0, N)
            {
                update(j, card[0], max_a[0][j]);
                update(card[0], j, max_a[1][j]);
            }
            update(card[0], card[1], max_v);
            update(card[0], card[2], max_v);
            update(card[1], card[2], dp[card[0]][card[0]] + 1);

            if (card[0] == card[1])
            {
                REP(j, 0, N)
                {
                    update(j, card[2], max_a[1][card[0]] + 1);
                    update(card[2], j, max_a[0][card[0]] + 1);
                }
            }
            card.emplace_back(card[0]);
            card.erase(card.begin());
        }
        REP(j, 0, N)
        REP(k, 0, N)
        dp[j][k] = max(dp[j][k], next_dp[j][k]);
        swap(max_a, next_max_a);
        max_v = next_max_v;
    }

    dp[a.back()][a.back()]++;
    int ans = 0;
    REP(i, 0, N)
    REP(j, 0, N)
    {
        ans = max(ans, dp[i][j]);
    }

    cout << ans + add << endl;
}

