int solve(int N, vi& a) {
    using P = pair<ii, ii>;
    priority_queue<P> pq;

    pq.emplace(ii(0, 0), minmax(a[0], a[1]));
    int best = 0;
    while (!pq.empty()) {
        P t = pq.top();
        pq.pop();
        int score = t.first.first, loc = t.first.second, x = t.second.first, y = t.second.second;

        if (loc == N) {
            amax(best, score);
            continue;
        }
        if (loc == N - 1) {
            if (x == y && y == a.back()) {
                pq.emplace(ii(score + 1, loc + 1), ii(0, 0));
            } else {
                pq.emplace(ii(score, loc + 1), ii(0, 0));
            }
            continue;
        }
        map<int, int> st;
        int keep0 = a[3 * loc], keep1 = a[3 * loc + 1];
        a[3 * loc] = x;
        a[3 * loc + 1] = y;
        rep(i, 5) st[a[3 * loc + i]]++;
        int use_n = -1;
        for (const ii& p : st) {
            int n = p.first, cnt = p.second;
            if (cnt >= 3) {
                use_n = n;
                st[n] -= 3;
                if (cnt == 3) st.erase(n);
                break;
            }
        }
        if (use_n >= 0) {
            vi tmp;
            tmp.reserve(2);
            for (const ii& p : st) {
                int n = p.first, cnt = p.second;
                rep(j, cnt) tmp.pb(n);
            }
            if (tmp[0] > tmp[1]) swap(tmp[0], tmp[1]);
            pq.emplace(ii(score + 1, loc + 1), ii(tmp[0], tmp[1]));
        } else {
            repC2(i, j, 5) {
                int u = a[3 * loc + i], v = a[3 * loc + j];
                pq.emplace(ii(score, loc + 1), minmax(u, v));
            }
        }
        a[3 * loc] = keep0;
        a[3 * loc + 1] = keep1;
    }
    return best;
}

int main() {
    int N;
    scanf("%d%*c", &N);
    vi a(N * 3);
    loadvec(a, N * 3);
    cout << solve(N, a) << endl;
    return 0;
}

