const int N = 2e3 + 10;
int a[N * 3];
map<array<int, 3>, int> dp;
int n;

int solve(int u, int v, int pos) {
  if (pos == 3 * n - 1) {
    return u == v && u == a[pos];
  }
  array<int, 3> cur = {u, v, pos};
  if (dp.find(cur) != dp.end()) return dp[cur];
  vector<int> x(5);
  x[0] = u; x[1] = v;
  for (int i = 0; i < 3; ++i) x[2 + i] = a[pos + i];
  int best = 0;
  for (int i = 0; i < 5; ++i) {
    for (int j = i + 1; j < 5; ++j) {
      int mi = INF, mx = -INF;
      for (int k = 0; k < 5; ++k) {
        if (k != i && k != j) {
          mi = min(mi, x[k]);
          mx = max(mx, x[k]);
        }
      }
      int cur = (mx == mi) + solve(x[i], x[j], pos + 3);
      best = max(best, cur);
    }
  }
  dp[cur] = best;
  return best;
}

int main() {
  cin >> n;
  for (int i = 0; i < n * 3; ++i) cin >> a[i];
  if (n == 1) {
    if (a[0] == a[1] && a[0] == a[2]) {
      cout << 1 << endl;
    } else {
      cout << 0 << endl;
    }
    return 0;
  }
  int best = 0;
  for (int i = 0; i < 5; ++i) {
    for (int j = i + 1; j < 5; ++j) {
      int mi = INF, mx = -INF;
      for (int k = 0; k < 5; ++k) {
        if (k != i && k != j) {
          mi = min(mi, a[k]);
          mx = max(mx, a[k]);
        }
      }
      int cur = (mi == mx) + solve(a[i], a[j], 5);
      best = max(best, cur);
    }
  }
  cout << best << endl;
  return 0;
}

