const int N=6006;
int n,ans,a[N],f[N][N],g[N][N];
int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n*3;i++)
        scanf("%d",&a[i]);
    if(n==1)
    {
        printf("%d\n",a[1]==a[2]&&a[2]==a[3]);
        return 0;
    }
    vector<int>v;
    for(int i=1;i<=5;i++)
        v.push_back(a[i]);
    sort(v.begin(),v.end());
    bool vis[6];memset(vis,false,sizeof(vis));
    bool flag=false;
    for(int i=0;i<=2;i++)
        if(v[i]==v[i+1]&&v[i+1]==v[i+2])
    {
        vis[i]=vis[i+1]=vis[i+2]=true;
        flag=true;
        break;
    }
    for(int i=0;i<5;i++)
        for(int j=i+1;j<5;j++)
        if(!vis[i]&&!vis[j])
            f[v[i]][v[j]]=f[v[j]][v[i]]=flag;
    for(int i=6;i<=n*3;i++)
    {
        if(i==n*3)
        {
            f[a[i]][a[i]]++;
        }
        else if(a[i]==a[i+1]&&a[i+1]==a[i+2]) ans++;
        else
        {
            if(a[i]==a[i+1])
            {
                for(int j=1;j<=n;j++) g[j][a[i]]=f[j][a[i]];
                for(int j=1;j<=n;j++)
                    f[j][a[i+2]]=f[a[i+2]][j]=max(f[j][a[i+2]],g[j][a[i]]+1);
            }
            else if(a[i+1]==a[i+2])
            {
                for(int j=1;j<=n;j++) g[j][a[i+1]]=f[j][a[i+1]];
                for(int j=1;j<=n;j++)
                    f[j][a[i]]=f[a[i]][j]=max(f[j][a[i]],g[j][a[i+1]]+1);
            }
            else if(a[i]==a[i+2])
            {
                for(int j=1;j<=n;j++) g[j][a[i]]=f[j][a[i]];
                for(int j=1;j<=n;j++)
                    f[j][a[i+1]]=f[a[i+1]][j]=max(f[j][a[i+1]],g[j][a[i]]+1);
            }
            else
            {
                f[a[i+1]][a[i+2]]=f[a[i+2]][a[i+1]]=max(f[a[i+2]][a[i+1]],f[a[i]][a[i]]+1);
                f[a[i]][a[i+2]]=f[a[i+2]][a[i]]=max(f[a[i+2]][a[i]],f[a[i+1]][a[i+1]]+1);
                f[a[i+1]][a[i]]=f[a[i]][a[i+1]]=max(f[a[i]][a[i+1]],f[a[i+2]][a[i+2]]+1);
            }
        }
    }
    int res=0;
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
        res=max(res,f[i][j]);
