const int BS = 300;
struct State {
  int score, card1, card2;
  const bool operator<(const State& s) const {
    return score != s.score ? score > s.score : card1 != s.card1 ? card1 < s.card1 : card2 < s.card2;
  }
  const bool operator==(const State& s) const {
    return score == s.score && card1 == s.card1 && card2 == s.card2;
  }
};
vector<State> st;
int a[6005];
const int inf = 0x3f3f3f3f;

ostream& operator<<(ostream& os, State s) {
  return os << s.score << "," << s.card1 << "," << s.card2;
}

int main() {
//	cin.tie(0)->sync_with_stdio(0);
//	cin.exceptions(cin.failbit);

  int n; read(n);
  rep(i, 0, 3 * n) {
    read(a[i]);
  }

  if (n == 1) {
    if (a[0] == a[1] && a[1] == a[2])
      die(1);
    else
      die(0);
  }

  rep(i, 0, 1 << 5) if (__builtin_popcount(i) == 3) {
    vector<int> cards, cards_left;
    rep(j, 0, 5) if (i & (1 << j)) cards.push_back(a[j]); else cards_left.push_back(a[j]);
    int score;
    if (cards[0] == cards[1] && cards[1] == cards[2])
      score = 1;
    else
      score = 0;
    st.push_back(State { score, min(cards_left[0], cards_left[1]), max(cards_left[0], cards_left[1]) });
  }

  rep(i, 0, n - 1) {
    vector<int> cards = { a[i * 3 + 5], a[i * 3 + 6], a[i * 3 + 7] };
    vector<State> nst;
    for (State s : st) {
      vector<int> allcards = { cards[0], cards[1], cards[2], s.card1, s.card2 };
      rep(i, 0, 1 << 5) if (__builtin_popcount(i) == 3) {
        vector<int> cards, cards_left;
        rep(j, 0, 5) if (i & (1 << j)) cards.push_back(allcards[j]); else cards_left.push_back(allcards[j]);
        int score = s.score;
        if (cards[0] == cards[1] && cards[1] == cards[2])
          score++;
        nst.push_back(State { score, min(cards_left[0], cards_left[1]), max(cards_left[0], cards_left[1]) });
      }
    }
    sort(all(nst));
    nst.erase(unique(all(nst)), nst.end());
    nst.resize(min((int)nst.size(), BS));
    st = nst;
  }
  write(st[0].score);
}

