int k, g;
void dfs(int u, int c1, int c2) {
    if (u == 5) {
        int v1 = d2[0], v2 = d2[1];
        if (v1 > v2) swap(v1, v2);
        f[k][{v1, v2}] = max(f[k][{v1, v2}], g + (d1[0] == d1[1] && d1[0] == d1[2]));
        return;
    }
    if (c1 < 3) {
        d1[c1] = b[u];
        dfs(u + 1, c1 + 1, c2);
    }
    if (c2 < 2) {
        d2[c2] = b[u];
        dfs(u + 1, c1, c2 + 1);
    }
}
