typedef long long ll;

const ll N = 2010;
const ll M = 100010;

ll n, f[N][N], a[N], res, target, mmax[N], cur;
ll tota[M], totb[M], totc[M], idx;

void add(ll x, ll y, ll z) {
	if (f[x][y] < z) {
		tota[idx] = x;
		totb[idx] = y;
		totc[idx++] = z;
	}
}

int main() {
	cin >> n;

	for (ll i = 1; i <= 3 * n; i++) {
		cin >> a[i];
	}

	memset(f, -1, sizeof f);
	memset(mmax, -1, sizeof mmax);

	f[a[1]][a[2]] = 0;
	f[a[2]][a[1]] = 0;
	mmax[a[1]] = 0;
	mmax[a[2]] = 0;
	cur = 0;

	for (ll i = 3; i < 3 * n; i += 3) {
		if (a[i] == a[i + 1] && a[i] == a[i + 2]) {
			target++; 
			continue;
		}

		idx = 0;
		if (a[i] > a[i + 1]) {
			swap(a[i], a[i + 1]);
		}

		if (a[i + 1] > a[i + 2]) {
			swap(a[i + 1], a[i + 2]);
		}

		if (a[i] > a[i + 1]) {
			swap(a[i], a[i + 1]);
		}

		if (a[i] == a[i + 1] || a[i + 1] == a[i + 2])for (int j = 1; j <= n; j++) {
			if (a[i] == a[i + 1]) {
				if (f[j][a[i]] >= 0) {
					add(j, a[i + 2], f[j][a[i]] + 1);
				}
			}
			else if (f[j][a[i + 1]] >= 0) {
				add(j, a[i], f[j][a[i + 1]] + 1);
			}
		}

		if (f[a[i]][a[i]] >= 0) {
			add(a[i + 1], a[i + 2], f[a[i]][a[i]] + 1);
		}

		if (f[a[i + 1]][a[i + 1]] >= 0) {
			add(a[i], a[i + 2], f[a[i + 1]][a[i + 1]] + 1);
		}

		if (f[a[i + 2]][a[i + 2]] >= 0) {
			add(a[i], a[i + 1], f[a[i + 2]][a[i + 2]] + 1);
		}

		add(a[i], a[i + 1], cur);
		add(a[i + 1], a[i + 2], cur);
		add(a[i], a[i + 2], cur);

		for (ll k = 1; k <= n; k++) {
			if (mmax[k] >= 0) {
				add(a[i], k, mmax[k]);
				add(a[i + 1], k, mmax[k]);
				add(a[i + 2], k, mmax[k]);
			}
		}

		for (ll j = 0; j < idx; j++) {
			if (f[tota[j]][totb[j]] < totc[j]) {
				f[tota[j]][totb[j]] = totc[j];
				f[totb[j]][tota[j]] = totc[j];

				mmax[tota[j]] = totc[j];
				mmax[totb[j]] = totc[j];
				cur = min(totc[j], cur);
			}
		}
	}

	for (ll i = 1; i <= n; i++) {
		for (ll j = i + 1; j <= n; j++) {
			res = max(res, f[i][j]);
		}

		if (f[i][i] >= 0) {
			if (i == a[3 * n]) {
				res = max(res, f[i][i] + 1);
			}
		}
	}

	cout << res + target << endl;

	return 0;
}

