template<class T> inline void checkmin(T &a,const T &b){if(b<a) a=b;}
template<class T> inline void checkmax(T &a,const T &b){if(b>a) a=b;}

const int maxn=2e3+10; 
const int inf=1e9+10;

int dp[maxn][maxn],n,a[maxn*3],f[maxn],maxval=0,cnt=0;
vector <pair<pair<int,int>,int> > v;

void getdp1(int x,int y,int z){
	if(dp[x][y]<maxval) v.pb(mp(mp(x,y),maxval));
	if(dp[x][y]<dp[z][z]+1) v.pb(mp(mp(x,y),dp[z][z]+1));
}

void getdp2(int na,int nb,int nc,int x){
	if(nb==nc&&dp[x][nb]+1>dp[na][x]){
		v.pb(mp(mp(na,x),dp[x][nb]+1));
		v.pb(mp(mp(x,na),dp[x][nb]+1));
	}
	if(f[x]>dp[na][x]){
		v.pb(mp(mp(na,x),f[x]));
		v.pb(mp(mp(x,na),f[x]));
	}
}

int main(){
	scanf("%d",&n);
	for(int i=0;i<3*n;i++) scanf("%d",&a[i]);
	for(int i=0;i<maxn;i++) for(int j=0;j<maxn;j++) dp[i][j]=-inf;
	for(int i=0;i<maxn;i++) f[i]=-inf;
	dp[a[0]][a[1]]=0; dp[a[1]][a[0]]=0; 
	f[a[0]]=0; f[a[1]]=0; 
	for(int i=2;i+3<=3*n;i+=3){
	//	cout<<i<<endl;
		int na=a[i],nb=a[i+1],nc=a[i+2];
	//	cout<<na<<" "<<nb<<" "<<nc<<endl;
		if(na==nb&&nb==nc){ cnt++; continue; }
		getdp1(na,nb,nc); getdp1(na,nc,nb); getdp1(nb,nc,na);
		for(int j=1;j<=n;j++) getdp2(na,nb,nc,j);
		for(int j=0;j<v.size();j++){
			int x=v[i].fst.fst,y=v[i].fst.snd,val=v[i].snd;
			checkmax(dp[x][y],val); checkmax(maxval,val);
			checkmax(f[x],val); checkmax(f[y],val);
		}
	}
	dp[a[n*3-1]][a[n*3-1]]++;
	int ans=0;
//	for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) cout<<i<<","<<j<<":"<<dp[i][j]<<endl;
	for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) checkmax(ans,dp[i][j]);
	printf("%d\n",ans+cnt);
	return 0;
}

