#include <bits/stdc++.h>
using namespace std;

int n;
int a[6005];
int pos[6005];
int nxt[6005], prv[6005];
int cur[5] = {0, 1, 2, 3, 4};
bool isIn[6005], isSmaller[6005];
int ans;

bool comp(int l, int r) {
	int curl, curr;
	if (isIn[cur[l]]) {
		if (isSmaller[cur[l]]) curl = nxt[nxt[cur[l]]];
		else curl = nxt[cur[l]];
	} else curl = nxt[nxt[cur[l]]];
	if (isIn[cur[r]]) {
		if (isSmaller[cur[r]]) curr = nxt[nxt[cur[r]]];
		else curr = nxt[cur[r]];
	} else curr = nxt[nxt[cur[r]]];
	return curl > curr;
}

int main() {
	scanf("%d", &n);
	for (int i = 0; i < 3 * n; i++) {
		scanf("%d", &a[i]);
	}
	for (int i = 1; i <= n; i++) pos[i] = 3 * n + 1;
	for (int i = 3 * n - 1; i >= 0; i--) {
		nxt[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	for (int i = 1; i <= n; i++) pos[i] = 3 * n + 1;
	for (int i = 0; i < 3 * n; i++) {
		prv[i] = pos[a[i]];
		pos[a[i]] = i;
	}
	int ptr = 5;
	for (int i = 1; i < n; i++) {
		bool done = false;
		for (int j = 0; j < 5; j++) for (int k = j + 1; k < 5; k++) for (int l = k + 1; l < 5; l++) {
			if (a[cur[j]] == a[cur[k]]  && a[cur[k]] == a[cur[l]]) {
				ans++;
				cur[j] = ptr++;
				cur[k] = ptr++;
				cur[l] = ptr++;
				done = true;
			}
		}
		if (done) continue;

		for (int j = 0; j < 5; j++) for (int k = j + 1; k < 5; k++) if (nxt[cur[j]] == cur[k]) {
			isIn[cur[j]] = true, isIn[cur[k]] = true;
			if (cur[j] < cur[k]) isSmaller[cur[j]] = true;
			else isSmaller[cur[k]] = true;
		}

		sort(cur, cur + 5, comp);
		for (int j = 0; j < 3; j++) {
			nxt[prv[cur[j]]] = nxt[cur[j]];
			cur[j] = ptr++;
		}
	}
	bool toadd = true;
	int val = -1;
	for (int i = 0; i < 5; i++) {
		if (cur[i] < 3 * n) {
			if (val == -1) {
				val = a[cur[i]];
				continue;
			}
			if (val != a[cur[i]]) {
				toadd = false;
				break;
			}
		}
	}
	if (toadd) ans++;
	printf("%d\n", ans);
	return 0;
}

