      if(ma!=-INF){
        for(int j=0;j<N;j++){
          if(dp[min(tar,j)][max(tar,j)]==ma){
            chmax(dp[min(j,A[now+1])][max(j,A[now+1])],ma+1);
            chmax(nexmva[j],ma+1);
            chmax(nexmva[A[now+1]],ma+1);
          }
        }
      }
      if(val!=-INF){
        chmax(dp[tar][tar],val+1);
        chmax(nexmva[tar],val+1);
      }
      for(int j=now;j<=now+2;j++){
        for(int m=0;m<j;m++){
          chmax(dp[min(A[j],A[m])][max(A[j],A[m])],mva[A[m]]);
          chmax(nexmva[A[j]],mva[A[m]]);
        }
      }
      mva=nexmva;
    }else if(A[now+1]==A[now+2]){
      int tar=A[now+1];
      int val=dp[A[now]][A[now]];
      int ma=-INF;
      vector<int> nexmva=mva;
      for(int j=0;j<N;j++) chmax(ma,dp[min(tar,j)][max(tar,j)]);
      if(ma!=-INF){
        for(int j=0;j<N;j++){
          if(dp[min(tar,j)][max(tar,j)]==ma){
            chmax(dp[min(j,A[now])][max(j,A[now])],ma+1);
            chmax(nexmva[j],ma+1);
            chmax(nexmva[A[now]],ma+1);
          }
        }
      }
      if(val!=-INF){
        chmax(dp[tar][tar],val+1);
        chmax(nexmva[tar],val+1);
      }
      for(int j=now;j<=now+2;j++){
        for(int m=0;m<j;m++){
          chmax(dp[min(A[j],A[m])][max(A[j],A[m])],mva[A[m]]);
