#include <bits/stdc++.h>
#define IO_OP std::ios::sync_with_stdio(0); std::cin.tie(0);
#define F first
#define S second
#define V vector
#define PB push_back
#define MP make_pair
#define EB emplace_back
#define ALL(v) (v).begin(), (v).end()
#define debug(x) cerr << #x << " is " << x << endl

using namespace std;

typedef long long ll;
typedef pair<int, int> pi;
typedef V<int> vi;

const int INF = 1e9 + 7, N = 2005;

int v[N * 3], add[N], mx = -INF, mxr[N];

map<int, int> dp[N][N];

int qry(int a, int b, int i) {
	auto it = prev(dp[a][b].end());
	if(it -> F >= i) it--;
	return it -> S + add[i];
}

signed main()
{
	IO_OP;

	for(int i = 0; i < N; i++) mxr[i] = -INF;

	int n;
	cin >> n;
	for(int i = 0; i < n * 3; i++) {
		cin >> v[i];
	}
	for(int i = 0; i < N; i++) {
		for(int j = 0; j < N; j++) {
			dp[i][j][0] = -INF;
		}
	}
	for(int i = 0; i < 5; i++) {
		for(int j = 0; j < 5; j++) {
			if(i == j) continue;
			vi tmp;
			for(int k = 0; k < 5; k++) if(k != i && k != j) tmp.PB(v[k]);
			sort(ALL(tmp));
			dp[v[i]][v[j]][0] = tmp[0] == tmp[2];
			// cerr << v[i] << " " << v[j] << ": " << dp[v[i]][v[j]][0] << endl;;
			mx = max(mx, dp[v[i]][v[j]][0]);
			mxr[v[i]] = max(mxr[v[i]], dp[v[i]][v[j]][0]);
		}
	}
	for(int i = 1; i < n - 1; i++) {
		int l = 2 + i * 3, a = v[l], b = v[l+1], c = v[l+2];
		if(a == b && b == c) add[i] = 1;
		// ab, bc, ac
		// ab
		V<pi> nw;
		dp[b][a][i] = dp[a][b][i] = qry(c, c, i-1) + 1 - add[i];
		dp[b][c][i] = dp[c][b][i] = qry(a, a, i-1) + 1 - add[i];
		dp[c][a][i] = dp[a][c][i] = qry(b, b, i-1) + 1 - add[i];
		nw.EB(a, b);
		nw.EB(b, c);
		nw.EB(a, c);
		// ya
		for(int y = 0; y < N; y++) {
			dp[y][a][i] = dp[a][y][i] = max(dp[y][a][i], mxr[y] - add[i]);
			if(b == c) {
				dp[y][a][i] = dp[a][y][i] = max(dp[y][a][i], qry(y, b, i-1) + 1 - add[i]);
			}
			nw.EB(a, y);
		}
		// yb
		for(int y = 0; y < N; y++) {
			dp[y][b][i] = dp[b][y][i] = max(dp[y][b][i], mxr[y] - add[i]);
			if(a == c) {
				dp[y][b][i] = dp[b][y][i] = max(dp[y][b][i], qry(y, c, i-1) + 1 - add[i]);
			}
			nw.EB(b, y);
		}
		// yc
		for(int y = 0; y < N; y++) {
			dp[y][c][i] = dp[c][y][i] = max(dp[y][c][i], mxr[y] - add[i]);
			if(b == a) {
				dp[y][c][i] = dp[c][y][i] = max(dp[y][c][i], qry(y, b, i-1) + 1 - add[i]);
			}
			nw.EB(c, y);
		}
		for(pi p:nw) {
			mx = max(mx, dp[p.F][p.S][i] + add[i]);
			mxr[p.F] = max(mxr[p.F],dp[p.F][p.S][i] + add[i]);
			mxr[p.S] = max(mxr[p.S],dp[p.F][p.S][i] + add[i]);
		}
	}
	int d = v[n*3-1];
	int ans = 0;
	for(int i = 0; i < N; i++) {
		for(int j = 0; j < N; j++) {
			ans = max(ans, qry(i, j, n-2)+(i==d&&j==d));
		}
	}
	cout << ans << endl;


}

