void solve()
{
    int n;
    cin >> n;
    int a[3 * n];
    for (int i = 0; i < 3 * n; i++)
    {
        cin >> a[i];
    }
    maxpq pq;
    int i = 0;
    ll res = 0;
    int x = 0;
    for (int j = 0; j < n - 1; j++)
    {
        while (pq.size() < 5)
        {
            pq.push(a[i++]);
            //cout << a[x++] << " ";
        }
        //cout << "\n";
        int c = 0;
        int req = pq.top();
        maxpq q;
        int k = 0;
        while (!pq.empty())
        {
            int curr = pq.top();
            //cout<<curr<<" ";
            q.push(curr);
            if (curr == req)
            {
                c++;
                if (c == 3)
                {
                    res++;
                    pq.pop();
                    k = 1;
                    break;
                }
            }
            pq.pop();
        }
        //cout<<k<<"\n";
        if (k == 0)
        {
            q.pop();
            while (!q.empty())
            {
                pq.push(q.top());
                q.pop();
            }
        }
    }
    //cout<<"\n";
    int cc = 0;
    int req = pq.top();
    while (i < 3 * n)
    {
        pq.push(a[i++]);
    }
    while (!pq.empty())
    {
        int curr = pq.top();
        //cout << curr << "\n";
        if (curr == req)
        {
            cc++;
            if (cc == 3)
                res++;
        }
        pq.pop();
    }
    cout << res;
}

