const double inf = 1e12;

const long double eps = 1e-8;

i64 n;
vector<i64> a;

vector<vector<i64>> dp;
//vector<vector<i64>> ndp;

map<i64, i64> met;

map<pair<i64, i64>, i64> upd;

void upd2(i64 dup, i64 left) {
    if (!met.count(dup)) {
        return;
    }

    for (auto t : met) {
        i64 card = t.first;
        i64 val = dp[dup][card];
        upd[{left, card}] = max(upd[{left, card}], val + 1);
        upd[{card, left}] = max(upd[{card, left}], val + 1);
    }
}

void upd1(i64 main, i64 left1, i64 left2) {
    if (!met.count(main) || met[main] < 2) {
        return;
    }

    i64 val = dp[main][main];
    upd[{left1, left2}] = max(upd[{left1, left2}], val + 1);
    upd[{left2, left1}] = max(upd[{left2, left1}], val + 1);
}

void do_upd() {
    for (auto t : upd) {
        i64 card1 = t.first.first;
        i64 card2 = t.first.second;
        i64 val = t.second;

        dp[card1][card2] = max(dp[card1][card2], val);
    }

    upd.clear();
}

int main(int argc, char* argv[]) {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0); cout.precision(15); cout.setf(ios::fixed); cerr.precision(15); cerr.setf(ios::fixed);

    cin >> n;
    a = vector<i64>(3 * n);
    for (i64 i = 0; i < 3 * n; i++) {
        cin >> a[i];
    }

    dp = vector<vector<i64>>(n + 1, vector<i64>(n + 1));

    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;

    met[a[0]] += 1;
    met[a[1]] += 1;

    i64 R = 0;

    for (i64 x = 0; x < n - 1; x++) {
        vector<i64> q;
        q.push_back(a[x * 3 + 2]);
        q.push_back(a[x * 3 + 3]);
        q.push_back(a[x * 3 + 4]);
        sort(q.begin(), q.end());

        if (q[0] == q[2]) {
            R += 1;
            continue;
        }

        if (q[0] == q[1]) {
            upd2(q[0], q[2]);
        }
        if (q[1] == q[2]) {
            upd2(q[2], q[0]);
        }

        upd1(q[0], q[1], q[2]);
        upd1(q[1], q[0], q[2]);
        upd1(q[2], q[0], q[1]);

        for (i64 i = 0; i < 3; i++) {
            met[q[i]] += 1;
        }

        do_upd();
    }

    i64 r = 0;
    for (auto t1 : met) {
        i64 card1 = t1.first;
        for (auto t2 : met) {
            i64 card2 = t2.first;
            r = max(r, dp[card1][card2] + ((card1 == card2 && met[card1] > 1 && a[3 * n - 1] == card1) ? 1 : 0));
        }
    }

    cout << R + r << endl;

    return 0;
}

