ll DFS(int l, vector<int>& A) {
  int n3 = A.size();
  if (l == n3) return 0;
  if (l+3 == n3) return A[l] == A[l+1] && A[l] == A[l+2];

  if (dp[l][A[l]][A[l+1]] != -1) return dp[l][A[l]][A[l+1]];
  assert(l+5 <= n3);
  int orig[5] = {A[l], A[l+1], A[l+2], A[l+3], A[l+4]};
  sort(A.begin() + l, A.begin() + l + 5);
  ll ans = 0;
  do {
    // TODO should we always keep l+4,l+5 sorted? may reduce state since i don't think it matters
    int new_score = A[l] == A[l+1] && A[l] == A[l+2];
    ans = max(ans, new_score + DFS(l+3, A));
  } while (next_permutation(A.begin() + l, A.begin() + l + 5));

  for (int i = 0; i < 5; ++i) A[l+i] = orig[i];
  return dp[l][A[l]][A[l+1]] = ans;
}

