    vector<int> tp;
    for(int i = 0; i < 5; ++i) tp.push_back(A[i]);
    sort(ALL(tp));
    int ans = 0;
    do{
        if(tp[0]==tp[1]&&tp[1]==tp[2]) {
            ans = 1;
            cnt1[tp[3]]++;
            cnt1[tp[4]]++;
            break;
        }
    }while(next_permutation(ALL(tp)));

    if(ans == 0) {
        for(int i = 0; i < 5; ++i) cnt1[A[i]]++;
    }

    for(int i = 5; i+2 < 3*N; i += 3) {
        int x=A[i],y=A[i+1],z=A[i+2];
        {
            if(x==y && y==z) {
                ans++;
                continue;
            }
        }
        {
            if(x==y && cnt2[x]>=1) {
                ans++;
                cnt2 = cnt1;
                cnt1 = init;
                cnt1[z]++;
                continue;
            }
            if(y==z && cnt2[y]>=1) {
                ans++;
                cnt2 = cnt1;
                cnt1 = init;
                cnt1[x]++;
                continue;
            }
            if(z==x && cnt2[z]>=1) {
                ans++;
                cnt2 = cnt1;
                cnt1 = init;
                cnt1[y]++;
                continue;
            }
        }
        {
            if(x==y && cnt1[x]>=1) {
                ans++;
                cnt1[x]--;
                for(int i = 0; i <= N; ++i) cnt2[i] += cnt1[i];
                cnt1 = init;
                cnt1[z]++;
                continue;
            }
            if(y==z && cnt1[y]>=1) {
                ans++;
                cnt1[y]--;
                for(int i = 0; i <= N; ++i) cnt2[i] += cnt1[i];
                cnt1 = init;
                cnt1[x]++;
                continue;
            }
            if(z==x && cnt1[z]>=1) {
                ans++;
                cnt1[z]--;
                for(int i = 0; i <= N; ++i) cnt2[i] += cnt1[i];
                cnt1 = init;
                cnt1[y]++;
                continue;
            }
        }

        {
            if(cnt1[x] >= 1 && cnt2[x] >= 1) {
                ans++;
                cnt2 = init;
                cnt1 = init;
                cnt1[y]++,cnt2[z]++;
                continue;
            }
            if(cnt1[y] >= 1 && cnt2[y] >= 1) {
                ans++;
                cnt2 = init;
                cnt1 = init;
                cnt1[z]++,cnt1[x]++;
                continue;
            }
            if(cnt1[z] >= 1 && cnt2[z] >= 1) {
                ans++;
                cnt2 = init;
                cnt1 = init;
                cnt1[x]++,cnt1[y]++;
                continue;
            }
        }

        {
            if(cnt1[x] >= 2) {
                ans++;
                cnt1 = init;
                cnt2 = init;
                cnt1[y]++,cnt1[z]++;
                continue;
            }
            if(cnt1[y] >= 2) {
                ans++;
                cnt1 = init;
                cnt2 = init;
                cnt1[z]++,cnt1[x]++;
                continue;
            }
            if(cnt1[z] >= 2) {
                ans++;
                cnt1 = init;
                cnt2 = init;
                cnt1[x]++,cnt1[y]++;
                continue;
            }
        }
        {
            cnt1[x]++,cnt1[y]++,cnt1[z]++;
        }
    }
    int last = A[3*N-1];
    if((cnt1[last] >= 1 && cnt2[last] >= 1) || cnt1[last] >= 2) {
        ans++;
    }
    cout << ans << endl;
    return 0;
}

