int main() {
  cin.tie(nullptr)->sync_with_stdio(false);
  cout << fixed << setprecision(20);
  cint n;
  vector<cint> a(3 * n);
  for (auto&& e : a) --e;

  vector dp(n, vector<cint>(n, -inf<>));
  vector<cint> max_dp(n, -inf<>);
  cint offset = 0;

  vector<array<cint, 3>> v;
  auto lazy_update = [&](cint p, cint q, cint val) -> void {
    v.push_back({p, q, val});
  };
  auto push_all = [&]() -> void {
    while (sz(v)) {
      auto [p, q, val] = v.back();
      chmax(dp[p][q], val);
      chmax(dp[q][p], val);
      chmax(max_dp[p], val);
      chmax(max_dp[q], val);
      v.pop_back();
    }
  };

  lazy_update(a[0], a[1], 0);
  push_all();
  DUMP(dp);

  for (cint i : rep(n - 1)) {
    sort(begin(a) + (i * 3 + 2), begin(a) + (i * 3 + 5));
    cint x = a[i * 3 + 2];
    cint y = a[i * 3 + 3];
    cint z = a[i * 3 + 4];
    if (x == z) {
      ++offset;
      continue;
    }
    if (x == y) {
      for (cint p : rep(n)) lazy_update(p, z, dp[p][y] + 1);
    }
    if (y == z) {
      for (cint p : rep(n)) lazy_update(p, x, dp[p][y] + 1);
    }
    for (cint e : {x, y, z}) {
      for (cint p : rep(n)) lazy_update(p, e, max_dp[p]);
    }
    auto max_all = *max_element(ALL(max_dp));
    lazy_update(x, y, max_all);
    lazy_update(x, z, max_all);
    lazy_update(y, z, max_all);
    lazy_update(y, z, dp[x][x] + 1);
    lazy_update(x, z, dp[y][y] + 1);
    lazy_update(x, y, dp[z][z] + 1);
    push_all();
    DUMP(dp);
  }

  cint res = -inf<>;
  for (cint p : rep(n))
    for (cint q : rep(n))
      chmax(res, offset + dp[p][q] + (p == q and q == a.back()));
  cout << res << '\n';
}

