void fill() {
	memset(DP, 0, sizeof DP);
	vector<tuple<int,int,int>> todo;
	addtoall = 0;
	for (int i = N-1; i >= 0; --i) {
		int idx = i*3+2;
		todo.clear();
		if (A[idx] == A[idx+1] && A[idx] == A[idx+2]) {
			++addtoall;
		} else if (A[idx] != A[idx+1] && A[idx] != A[idx+2] && A[idx+1] != A[idx+2]) {
			for (int j = 0; j < 3; ++j) {
				todo.emplace_back(A[idx+j], A[idx+j], DP[A[idx+((j+1)%3)]][A[idx+((j+2)%3)]]);
			}
		} else if (A[idx] == A[idx+1]) {
			todo.emplace_back(A[idx+2], A[idx+2], DP[A[idx]][A[idx+1]]);
			for (int v = 1; v <= N+1; ++v) {
				todo.emplace_back(A[idx], v, DP[A[idx+2]][A[v]]);
			}
		} else if (A[idx] == A[idx+2]) {
			todo.emplace_back(A[idx+1], A[idx+1], DP[A[idx]][A[idx+2]]);
			for (int v = 1; v <= N+1; ++v) {
				todo.emplace_back(A[idx], v, DP[A[idx+1]][A[v]]);
			}
		} else {
			todo.emplace_back(A[idx], A[idx], DP[A[idx+1]][A[idx+2]]);
			for (int v = 1; v <= N+1; ++v) {
				todo.emplace_back(A[idx+1], v, DP[A[idx]][A[v]]);
