        int a = A[3 * i + 2], b = A[3 * i + 3], c = A[3 * i + 4];
        if (a == b && b == c) {
            offs++;
            continue;
        }
        upd(a, b, c, N, bst);
        upd(b, c, a, N, bst);
        upd(c, a, b, N, bst);
        for (int i = 1; i <= N; i++) {
            if (dp[a][i] > tdp[a][i])
                assert(false);
            if (dp[b][i] > tdp[b][i])
                assert(false);
            if (dp[c][i] > tdp[c][i])
                assert(false);
        }
        for (int i = 1; i <= N; i++) {
            bst = max({bst, tdp[a][i], tdp[b][i], tdp[c][i]});
            dp[a][i] = dp[i][a] = tdp[a][i];
            dp[b][i] = dp[i][b] = tdp[b][i];
            dp[c][i] = dp[i][c] = tdp[c][i];
            bst1[i] = max({bst1[i], tdp[a][i], tdp[b][i], tdp[c][i]});
        }
        for (int i = 1; i <= N; i++) {
            tdp[a][i] = tdp[i][a] = -INF;
            tdp[b][i] = tdp[i][b] = -INF;
            tdp[c][i] = tdp[i][c] = -INF;
        }
    }
    int ans = 0;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++) {
            //printf("i = %d j = %d dp = %d\n", i, j, dp[i][j]);
            ans = max(ans, dp[i][j]);
        }
    printf("%d\n", max(ans, dp[A[3 * N - 1]][A[3 * N - 1]] + 1) + offs);
    return 0;
}
