			for(int j = 1; j <= n; j++){
				if(dp[a[i]][j] != 0) stx.push({ a[i + 2], j, dp[a[i]][j] + 1});
				if(dp[j][a[i]] != 0) stx.push({j, a[i + 2], dp[j][a[i]] + 1});
