bool iseq(int* a, int i, int j){
    int s = -1;
    for(int k = 0; k < 5; ++k)
        if(i != k && j != k){
            if(s == -1)
                s = a[k];
            else if(s != a[k])
                return false;
        }
    return true;
}

int myhash(int i, int j){
    if(i != j && cnt[i] <= 1 && cnt[j] <= 1)
        return 0;
    if(i == j && cnt[i] == 0)
        return 0;
    if(i != j && cnt[i] <= 1)
        return j;
    if(i != j && cnt[j] <= 1)
        return i;
    if(i <= j)
        return i * 4000 + j;
    else
        return j * 4000 + i;
}

bool eq3(int *b, unordered_map<int, int> &map, int num){
    vector<int> a;
    for(int i = 0; i < 5; ++i)
        a.push_back(b[i]);
    sort(a.begin(), a.end());
    for(int i = 0; i < 3; ++i)
        if(a[i] == a[i + 1] == a[i + 2]){
            int key = myhash(a[(i + 3)%5], a[(i + 4)%5]);
            if(map.count(key)){
                if(map[key] < num + 1)
                    map[key] = num + 1;
            }else{
                map[key] = num + 1;
            }
            return true;
        }
    return false;
}

