                        }
                        left[2] = y;
                        offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait[++size] = Node(x,a[i+j],offer);
                        }
                    }
