                        }
                        int offer = u.value+isGood(left);
                        if(offer+2>=nextMaxn){
                            nextMaxn = max(offer+2,nextMaxn);
                            wait[++size] = Node(used[0],used[1],offer);
                        }
                    }
                }
            }
        }
        for(int j = 1; j <= size; j++) Q.push(wait[j]);
