int rec(int N, vector< int > A) {

  auto dp = make_v< int >(N + 1, N + 1);
  auto dp2 = make_v< int >(N + 1);
  fill_v(dp2, -inf);
  fill_v(dp, -inf);

  dp[A[0]][A[1]] = 0;
  dp[A[1]][A[0]] = 0;
  chmax(dp2[A[0]], 0);
  chmax(dp2[A[1]], 0);

  int add = 0, pre_max = 0;
  vector< tuple< int, int, int > > upd;

  for(int i = 0; i < 3 * N; i += 3) {

    vector< int > B{A[i + 2], A[i + 3], A[i + 4]};
    sort(begin(B), end(B));


    if(B[0] == B[2]) {
      ++add;
    } else if(B[0] == B[1]) {

      // {B[0],B[1],a} -> {b, B[2]}
      for(int j = 0; j <= N; j++) upd.emplace_back(j, B[2], dp[j][B[0]] + 1);
      // {B[2],a,b}   -> {B[0],B[1]}
      upd.emplace_back(B[0], B[1], dp[B[2]][B[2]] + 1);

    } else if(B[1] == B[2]) {

      swap(B[0], B[2]);

      // {B[0],B[1],a} -> {b, B[2]}
      for(int j = 0; j <= N; j++) upd.emplace_back(j, B[2], dp[j][B[0]] + 1);
      // {B[2],a,b}   -> {B[0],B[1]}
      upd.emplace_back(B[0], B[1], dp[B[2]][B[2]] + 1);

    } else {
      upd.emplace_back(B[0], B[1], dp[B[2]][B[2]] + 1);
      upd.emplace_back(B[1], B[2], dp[B[0]][B[0]] + 1);
      upd.emplace_back(B[0], B[2], dp[B[1]][B[1]] + 1);
    }
    for(int j = 0; j <= N; j++) {
      upd.emplace_back(j, B[0], dp2[j]);
      upd.emplace_back(j, B[1], dp2[j]);
      upd.emplace_back(j, B[2], dp2[j]);
    }
    for(int j = 0; j < 3; j++) {
      for(int k = 0; k < 3; k++) {
        if(j != k) {
          chmax(dp[B[j]][B[k]], pre_max);
          chmax(dp2[B[j]], pre_max);
        }
      }
    }
    for(auto&[a, b, c] : upd) {
      chmax(dp[a][b], c);
      chmax(dp[b][a], c);
      chmax(pre_max, c);
      chmax(dp2[a], c);
      chmax(dp2[b], c);
    }
    upd.clear();
  }
  return pre_max + add;
  //cout << pre_max + add << "\n";
}

