  vector< int > A(3 * N);
  cin >> A;
  for(auto &c : A) --c;
  A.emplace_back(N);
  A.emplace_back(N);
  int p = rec(N, A);
  reverse(begin(A), end(A));
  cout << max(p, rec(N, A)) << "\n";
}

