int main() {
  ll N;
  io.read(N);
  // N = 500;
  vector<ll> A(3 * N);
  io.read(A);
  // REP(i, 3 * N) A[i] = i % N + 1;
  REP(i, 3 * N) A[i]--;
  vector<vector<short>> dp(N, vector<short>(N, -1 << 14));
  dp[A[0]][A[1]] = 0;
  vector<tuple<int, int, int>> lazy;
  REP(i, N - 1) {
    int ls[5];
    ls[2] = A[i * 3 + 2];
    ls[3] = A[i * 3 + 3];
    ls[4] = A[i * 3 + 4];
    REP(j, N) {
      ls[0] = j;
      REP(k, N) if (dp[j][k] >= 0) {
        ls[1] = k;
        for (int i1 = 0; i1 < 4; ++i1) {
          for (int i2 = i1 + 1; i2 < 5; ++i2) {
            int rest[3];
            int p = 0;
            REP(t, 5) if (t != i1 && t != i2) rest[p++] = ls[t];
            short plus = 0;
            if (rest[0] == rest[1] && rest[1] == rest[2]) plus = 1;
            lazy.emplace_back(ls[i1], ls[i2], dp[j][k] + plus);
          }
        }
        dp[j][k] = -1 << 14;
      }
    }
    while (!lazy.empty()) {
      dp[get<0>(lazy.back())][get<1>(lazy.back())] =
          max(dp[get<0>(lazy.back())][get<1>(lazy.back())],
              (short)get<2>(lazy.back()));
      lazy.pop_back();
    }
  }
  int ans = 0;
  REP(j, N) REP(k, N) {
    if (j == k && k == A.back()) dp[j][k]++;
    ans = max(ans, (int)dp[j][k]);
  }
  io.writeln(ans);
  return 0;
}

