const int maxN = 6e3, maxX = 2e3 + 1; int n;
int arr[maxN];

unordered_map<int, int> memo[maxN][maxX];
int solve(int i = 0, int a = arr[0], int b = arr[1])
{
  if (i + 2 == n - 1) return a == b && b == arr[n - 1];

  if (a > b) swap(a, b);
  if (memo[i][a].count(b)) return memo[i][a][b];

  int prv = arr[i], prv2 = arr[i + 1];
  arr[i] = a, arr[i + 1] = b;

  int ans = 0;
  for (int j = 0; j < 5; j++)
    for (int k = j + 1; k < 5; k++)
    {
      int other = 0, cnt = 0;
      for (int hehe = 0; hehe < 5; hehe++)
        if (hehe != j && hehe != k)
        {
          if (other == 0) other = arr[i + hehe];
          if (arr[i + hehe] == other)
            cnt++;
        }
      ans = max(ans, (cnt == 3) + solve(i + 3, arr[i + j], arr[i + k]));
    }

  arr[i] = prv, arr[i + 1] = prv2;

  return memo[i][a][b] = ans;
}

