const int INF = 1<<29;
long long solve(int N) {
    int offset = 0;
    int a, b, end;
    cin >> a >> b;
    --a, --b;
    vector<vector<int>> A;
    for (int i = 0; i < N-1; ++i) {
        vector<int> v(3);
        for (int j = 0; j < 3; ++j) cin >> v[j], --v[j];
        sort(v.begin(), v.end());
        if (v[0] == v.back()) ++offset;
        else A.push_back(v);
    }
    cin >> end;
    --end;
    vector<vector<int>> dp(N, vector<int>(N, -INF));
    dp[a][b] = dp[b][a] = 0;
    for (auto v : A) {
        if (v[0] < v[1] && v[1] < v[2]) {
            int a = v[0], b = v[1], c = v[2];
            chmax(dp[a][b], dp[c][c] + 1);
            chmax(dp[b][a], dp[c][c] + 1);
            chmax(dp[a][c], dp[b][b] + 1);
            chmax(dp[c][a], dp[b][b] + 1);
            chmax(dp[b][c], dp[a][a] + 1);
            chmax(dp[c][b], dp[a][a] + 1);
        }
        else if (v[0] == v[1] && v[1] < v[2]) {
            int a = v[0], b = v[2];
            int tmp = dp[b][b];
            for (int f = 0; f < N; ++f) {
                chmax(dp[b][f], dp[a][f] + 1);
                chmax(dp[f][b], dp[a][f] + 1);
            }
            chmax(dp[a][a], tmp + 1);
        }
        else if (v[0] < v[1] && v[1] == v[2]) {
            int a = v[2], b = v[0];
            int tmp = dp[b][b];
            for (int f = 0; f < N; ++f) {
                chmax(dp[b][f], dp[a][f] + 1);
                chmax(dp[f][b], dp[a][f] + 1);
            }
            chmax(dp[a][a], tmp + 1);
        }
/*
        cout << "-----------" << endl;
        COUT(v);
        for (int a = 0; a < N; ++a) {
            for (int b = a; b < N; ++b) {
                if (dp[a][b] > 0) {
                    cout << a << ", " << b << ": " << dp[a][b] << endl;
                }
            }
        }
        */
    }
    int res = 0;
    for (int a = 0; a < N; ++a) {
        for (int b = 0; b < N; ++b) {
            if (a == end && b == end) chmax(res, dp[a][b] + 1);
            else chmax(res, dp[a][b]);
        }
    }
    return res + offset;
}

