     if(A[i] == A[j]) {
       int a = hlp2[A[i]][grp];
       if(a == -1) continue;
       auto x = solver(a, A[i]);
       int ii = x.F, jj = x.S;
       dp[ii][jj] = max(dp[ii][jj], 1+dp[i][j]);
       continue;
     }

     int a = hlp[A[i]][grp];
     int b = hlp[A[j]][grp];
     if(a == -1 && b == -1) {
      continue;
     }
     if(a == -1) {
       int in = separate(b);
       dp[i][in] = max(dp[i][in], 1+dp[i][j]);
       continue;
     }
     if(b == -1) {
       int in = separate(a);
       dp[j][in] = max(dp[j][in], 1+dp[i][j]);
       continue;
     }
     if(a < b){
       int in = separate(a);
       dp[j][in] = max(dp[j][in], 1+dp[i][j]);
       continue;
     }
     int in = separate(b);
     dp[i][in] = max(dp[i][in], 1+dp[i][j]);
   }

 }

 // rep(i,3*N) {
 //   rep(j,3*N) cout<<dp[i][j] <<" ";cout<<endl;
 // }

  cout << ans+tans << endl;

 return 0;
}

