	for (int i = 2; i < N * 3; i += 3)
	{
		auto dpt = dp;
		for (int a = 1; a <= N; a++)
		{
			for (int b = a; b <= N; b++)
			{
				if (dp[a][b] >= 0)
				{
					vector<int> cs = {a, b, A[i], A[i + 1], A[i + 2]};
					vector<int> c1, c2;
					for (int j = 0; j < 5; j++)
					{
						for (int k = j + 1; k < 5; k++)
						{
							c1.clear();
							c2.clear();
							for (int t = 0; t < 5; t++)
							{
								if (t == j || t == k)
								{
									c1.push_back(cs[t]);
								}
								else
								{
									c2.push_back(cs[t]);
								}
							}
							sort(c1.begin(), c1.end());

							dpt[c1[0]][c1[1]] = max(dpt[c1[0]][c1[1]],
