        sort(y.begin(), y.end());
        a = y[0], b = y[1], c = y[2];
        if (a == b && b == c) {
            bonus ++;
        } else if (a < b && b < c) {
            update(i+1, a, b, max(dp[i%2][c][c] + 1, all_max[i]));
            update(i+1, b, c, max(dp[i%2][a][a] + 1, all_max[i]));
            update(i+1, a, c, max(dp[i%2][b][b] + 1, all_max[i]));
            for (int j = 1; j <= n; j++) {
                // 片方がjであるようなものの最大値を持ってくる
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
                update(i+1, b, j, maxi);
                update(i+1, c, j, maxi);
            }
        } else if (a == b && b < c) {
            // (a, a, c)

            update(i+1, a, b, max(dp[i%2][c][c] + 1, all_max[i]));
            update(i+1, b, c, max(dp[i%2][a][a] + 1, all_max[i]));
            update(i+1, a, c, max(dp[i%2][b][b] + 1, all_max[i]));
            // (a, c)を使う場合
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
            }

            // (a, a)を使う場合
            for (int j = 1; j <= n; j++) {
                // (a, j) -> (c, j) への遷移
                update(i+1, c, j, dp[i%2][a][j] + 1);
            }

            for (int j = 1; j <= n; j++) {
                // (*, j) -> (c, j) への遷移
                ll maxi = max_table[i][j];
                update(i+1, c, j, maxi);
            }
        } else if (a < b && b == c) {
            update(i+1, a, b, max(dp[i%2][c][c] + 1, all_max[i]));
            update(i+1, b, c, max(dp[i%2][a][a] + 1, all_max[i]));
            update(i+1, a, c, max(dp[i%2][b][b] + 1, all_max[i]));
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, b, j, maxi);
            }
            for (int j = 1; j <= n; j++) {
                update(i+1, a, j, dp[i%2][c][j] + 1);
            }
            for (int j = 1; j <= n; j++) {
                ll maxi = max_table[i][j];
                update(i+1, a, j, maxi);
            }
        }
        for(auto u : updated){
            int a = u.first, b = u.second;
            dp[i%2][a][b] = max(dp[i%2][a][b], dp[(i+1)%2][a][b]);
        }
        for(int j=1;j<=n;j++){
            max_table[i%2][j] = max_table[(i+1)%2][j];
        }
        all_max[i+2] = all_max[i+1];
        updated.clear();
