int dp[N][N], t[N][N], n, row_mx[N], col_mx[N], mx, add;

void upd(int x, int y, int z) {
    vector<int> v({x, y, z});
    sort(v.begin(), v.end());
    for (int i=1;i<=n;++i) {
        t[i][x] = t[i][y] = t[i][z] = -oo;
        t[x][i] = t[y][i] = t[z][i] = -oo;
    }
    int go = ((x == y) && (y == z));
    do {    
        int x = v[0], y = v[1], z = v[2];
        for (int i=1;i<=n;++i) {
            t[i][z] = max(t[i][z], row_mx[i] + add);
            t[z][i] = max(t[z][i], col_mx[i] + add);
            if (x == y) {
                t[i][z] = max(t[i][z], dp[i][x] + add + 1);
                t[z][i] = max(t[z][i], dp[x][i] + add + 1);
            }
            t[x][y] = max(t[x][y], mx + add);
            t[x][y] = max(t[x][y], dp[z][z] + add + 1);
        }
    } while(next_permutation(v.begin(), v.end()));
    add += go;
    for (int i=1;i<=n;++i) {
        dp[i][x] = max(dp[i][x], t[i][x] - go);
        dp[i][y] = max(dp[i][y], t[i][y] - go);
        dp[i][z] = max(dp[i][z], t[i][z] - go);
        row_mx[i] = max(row_mx[i], dp[i][x]);
        row_mx[i] = max(row_mx[i], dp[i][y]);
        row_mx[i] = max(row_mx[i], dp[i][z]);

        dp[x][i] = max(dp[x][i], t[x][i] - go);
        dp[y][i] = max(dp[y][i], t[y][i] - go);
        dp[z][i] = max(dp[z][i], t[z][i] - go);
        col_mx[i] = max(col_mx[i], dp[x][i]);
        col_mx[i] = max(col_mx[i], dp[y][i]);
        col_mx[i] = max(col_mx[i], dp[z][i]);

        mx = max(mx, row_mx[i]);
        mx = max(mx, col_mx[i]);
    }
}

int v[3*N];

void solve() {  
    cin >> n;
    for (int i=1;i<=3*n;++i) {
        cin >> v[i];
        assert(v[i] >= 1 && v[i] <= n);
    }
    if (n == 1) {
        cout << ((v[1] == v[2]) && (v[2] == v[3])) << '\n';
        return;
    }
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) dp[i][j] = -oo;

    sort(v+1, v+6);

    do {
        dp[v[1]][v[2]] = max(dp[v[1]][v[2]], (int)((v[3] == v[4]) && (v[4] == v[5])));
        dp[v[2]][v[1]] = max(dp[v[2]][v[1]], (int)((v[3] == v[4]) && (v[4] == v[5])));
    }while(next_permutation(v+1, v+6));

    mx = -oo;
    add = 0;
    for (int i=1;i<=n;++i) {
        row_mx[i] = -oo;
        col_mx[i] = -oo;
    }
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
        mx = max(mx, dp[i][j]);
        row_mx[i] = max(row_mx[i], dp[i][j]);
        col_mx[j] = max(col_mx[j], dp[i][j]);
    }

    for (int i=6;i<3*n;i+=3) {
        upd(v[i], v[i+1], v[i+2]);
    }

    int ans = 0;
    for (int i=1;i<=n;++i) for (int j=1;j<=n;++j) {
        ans = max(ans, dp[i][j] + add + ((i == j) && (j == v[3*n])));
    }

    cout << ans << '\n';
}

int main() {
    FASTIO;
    int T = 1;
    // cin >> T;
    while(T--) {
        solve();
    }
    // cerr << fixed << setprecision(10);
    // cerr << (clock() - start) / ((long double)CLOCKS_PER_SEC) << '\n';
    return 0;
}

