    for (int i=0; i<5; i++) {
        cnt2[a[i]]++;
        if (cnt2[a[i]] == 3) {
            ans++;
            cnt2[a[i]] = 0;
        }
    }
    for (int i=5; i+3<3*n; i+=3) {
        vector<int> cnt(n, 0);
        int best = 0;
        amax(best, ++cnt[a[i]]);
        amax(best, ++cnt[a[i+1]]);
        amax(best, ++cnt[a[i+2]]);
        if (best == 3) {
            ans++;
        } else if (best == 2) {
            int idx2, idx1;
            for (int j=i; j<i+3; j++) {
                if (cnt[a[j]]== 1) idx1 = a[j];
                else {
                    idx2 = a[j];
                }
            }
            if (cnt2[idx2] + cnt1[idx2] >= 1) {
                ans++;
                cnt[idx2] = 0;
                cnt1.swap(cnt2);
                cnt2.swap(cnt);
            } else {
                cnt2[idx2] += cnt[idx2];
                cnt2[idx1] += cnt[idx1];
            }
        } else {
            int idx = -1;
            for (int j=i; j<i+3; j++) {
                if (cnt2[a[j]] >= 1 && cnt2[a[j]] + cnt1[a[j]] >= 2) {
                    idx = a[j];
                }
            }
            if (idx < 0) {
                cnt2[i]   += cnt[i];
                cnt2[i+1] += cnt[i+1];
                cnt2[i+2] += cnt[i+2];
            } else {
                cnt[idx] = 0;
                cnt1.swap(cnt2);
                cnt2.swap(cnt);
            }
        }
    }
    int last = a[3*n-1];
    if (cnt2[last] >= 1 && cnt2[last] + cnt1[last] >= 2) ans++;
    cout << ans << '\n';
    return 0;
}

