void solve1(int a, int b) {
    if (m[a] >= 1 && m[b] == 2) {
        ans++;
        m[a] = 2;
        m[b] = 2;
    } else if (m[a] >= 1) {
        ans++;
        m[a] = (m[a] + 2) % 3;
        m[b]++;
    } else if (m[b] == 2) {
        ans++;
        m[a] = 2;
        m[b] = 0;
    }
}


void solve2(int a, int b, int c) {
    if (m[a] == 2 && m[b] == 2 && m[c] == 2) {
        ans++;
    } else if (m[a] == 2 && m[b] == 2) {
        ans++;
        m[c]++;
    } else if (m[a] == 2 && m[c] == 2) {
        ans++
        m[b]++;;
    } else if (m[b] == 2 && m[c] == 2) {
        ans++;
        m[a]++;
    } else if (m[a] == 2) {
        ans++;
        m[a] = 0;
        m[b]++;
        m[c]++;
    } else if (m[b] == 2) {
        ans++;
        m[b] = 0;
        m[a]++;
        m[c]++;
    } else if (m[c] == 2) {
        ans++;
        m[c] = 0;
        m[a]++;
        m[b]++;
    } else {
        m[a]++;
        m[b]++;
        m[c]++;
    }
}


