		}
	}
	vector<int> v;
	int ma=0;
	int maa[n+1]={};
	for(int i=0;i<5;++i){
		v.push_back(a[i]);
		sort(all(v));
	}
	do{
		if(v[0]==v[1]&&v[1]==v[2]){
			dp[v[3]][v[4]]=max(1,dp[v[3]][v[4]]);
			maa[v[3]]=max(maa[v[3]],dp[v[3]][v[4]]);
			maa[v[4]]=max(maa[v[4]],dp[v[3]][v[4]]);
		}
		else{
			dp[v[3]][v[4]]=max(0,dp[v[3]][v[4]]);
			maa[v[3]]=max(maa[v[3]],dp[v[3]][v[4]]);
			maa[v[4]]=max(maa[v[4]],dp[v[3]][v[4]]);
		}
		ma=max(ma,dp[v[3]][v[4]]);
	}while(next_permutation(all(v)));
	// cout<<"!"<<endl;
	int co=0;
	for(int i=5;i<3*n-1;i+=3){
		if(a[i]==a[i+1]&&a[i+1]==a[i+2]){
			++co;
			continue;
		}
		map<pair<int,int>,int> m;
		v.clear();
		v.push_back(a[i]);
		v.push_back(a[i+1]);
		v.push_back(a[i+2]);
		sort(all(v));
		do{
			m[{v[0],v[1]}]=max(m[{v[0],v[1]}],max(ma,dp[v[2]][v[2]]+1));
		}while(next_permutation(all(v)));
		for(int j=1;j<=n;++j){
			m[{j,v[0]}]=max(dp[j][v[0]],maa[j]);
			m[{v[0],j}]=max(dp[v[0]][j],maa[j]);
			if(v[1]==v[2]){
				m[{j,v[0]}]=max(m[{j,v[0]}],dp[j][v[1]]+1);
				m[{v[0],j}]=max(m[{v[0],j}],dp[j][v[1]]+1);
			}
		}
		for(int j=1;j<=n;++j){
			m[{j,v[1]}]=max(dp[j][v[1]],maa[j]);
			m[{v[1],j}]=max(dp[v[1]][j],maa[j]);
			if(v[0]==v[2]){
				m[{j,v[1]}]=max(m[{j,v[1]}],dp[j][v[0]]+1);
				m[{v[1],j}]=max(m[{v[1],j}],dp[j][v[0]]+1);
			}
		}
		for(int j=1;j<=n;++j){
			m[{j,v[2]}]=max(dp[j][v[2]],maa[j]);
			m[{v[2],j}]=max(dp[v[2]][j],maa[j]);
			if(v[0]==v[1]){
				m[{j,v[2]}]=max(m[{j,v[2]}],dp[j][v[1]]+1);
				m[{v[2],j}]=max(m[{v[2],j}],dp[j][v[1]]+1);
			}
		}
		for(auto r:m){
			dp[r.F.F][r.F.S]=max(dp[r.F.F][r.F.S],r.S);
			ma=max(ma,dp[r.F.F][r.F.S]);
			maa[r.F.F]=max(maa[r.F.F],dp[r.F.F][r.F.S]);
			maa[r.F.S]=max(maa[r.F.S],dp[r.F.F][r.F.S]);
		}
	}
	ma=max(ma,dp[a[3*n-1]][a[3*n-1]]+1);
	cout<<ma+co;
	#ifdef ANIKET_GOYAL
		// cout<<endl<<endl<<endl<<endl<<"Time elapsed: "<<(double)(clock()-clk)/CLOCKS_PER_SEC<<endl;
	#endif
