#define FOR1(i, n) for(int i=1; i<=n; i++)
#define FORI(i, n) for(int i=n-1; i>=0; i--)
template<class T, class U> void umin(T& x, const U& y){ x = min(x, (T)y);}
template<class T, class U> void umax(T& x, const U& y){ x = max(x, (T)y);}
template<class T, class U> void init(vector<T> &v, U x, size_t n) { v=vector<T>(n, (T)x); }
template<class T, class U, typename... W> void init(vector<T> &v, U x, size_t n, W... m) { v=vector<T>(n);  for(auto& a : v) init(a, x, m...); }

bool same(vector<int>& v, int i, int j){
    int x = -1;
    FOR(k, v.size()) if (k!=i && k!=j){
        if (x == -1) x = v[k];
        if (x == 0) return 0;
        else if (x != v[k]) return 0;
    }
    return 1;
}

int main(int argc, char** argv) {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0); cout << setprecision(15);
    if (argc == 2 && atoi(argv[1]) == 123456789) freopen("d:\\code\\cpp\\contests\\stdin", "r", stdin);

    int n;
    cin >> n;
    vector<int> a(3*n+10);
    FOR(i, 3*n) cin >> a[i];
    sort(a.begin(), a.begin()+5);

    //dp[n][x][1] best score if after n moves last two contain 1 x
    //dp[n][x][2] best score if after n moves last two contain 2 xs
    vector<vector<int>> dp;
    init(dp, -1, n+1, n+1);

    sort(a.begin(), a.begin()+5);
    FOR(i, 4){
        for(int j=i+1; j<5; j++){
            vector<int> v;
            FOR(k, 5) if (k!=i && k!=j){
                    v.push_back(a[k]);
                }
            bool same = 1;
            for(auto it : v) same &= it == v[0];
            dp[a[i]][a[j]] = same;
        }
    }

    for(int i=1; i<n; i++){
        vector<vector<int>> dp2;
        init(dp2, -1, n+1, n+1);

        vector<int> v = {a[5 + (i-1)*3], a[6 + (i-1)*3], a[7 + (i-1)*3]};
        FOR1(x, n){
            for(int y = x; y<=n; y++){
                if (dp[x][y] == -1) continue;
                v.push_back(x);
                v.push_back(y);

                FOR(ii, 4){
                    for(int jj = ii+1; jj < 5; jj++){
                        int uu = v[ii];
                        int vv = v[jj];
                        if (uu > vv) swap(uu, vv);
                        bool s = same(v, ii, jj);
                        umax(dp2[uu][vv], dp[x][y] + s);                    }
                }
                v.pop_back();
                v.pop_back();
            }
        }
        dp = dp2;
    }
    int sol = 0;
    FOR(x, n+1){
        FOR(y, n+1){
            umax(sol, dp[x][y]);
        }
    }
    cout << sol << endl;
    if (argc == 2 && atoi(argv[1]) == 123456789) cout << clock()*1.0/CLOCKS_PER_SEC << " sec\n";
    return 0;
}

