int solve()
{
	int ans = 0;
	vector<vector<int>> dp(N + 1, vector<int>(N + 1, -1));
	dp[min(A[0], A[1])][max(A[0], A[1])] = 0;
	vector<int> vis(N+1, 0);
	int j = 0;

	for (int i = 2; i < N * 3; i += 3)
	{
		while(j < i){
			vis[A[j]] = 1;
			j++;
		}

		vector<int> cs = {A[i], A[i+1], A[i+2]};
		std::sort(cs.begin(), cs.end());
		if(cs[0] == cs[1] && cs[0] == cs[2]){
			for(int a=1; a<=N; a++){
				for(int b=a; b<=N; b++){
					if(dp[a][b] >= 0){
						dp[a][b]++;
					}
				}
			}

		}else if(cs[0] == cs[1]){
			int c = cs[0], b = cs[2];
			if(dp[b][b] >= 0){
				dp[c][c] = max(dp[c][c], dp[b][b] + 1);
			}
			for(int a=1; a<=N; a++){
				int p = dp[min(a, c)][max(a, c)];
				if(p < 0) continue;

				dp[min(a,b)][max(a,b)] = max(dp[min(a,b)][max(a,b)], p + 1); 
			}



		}else if(cs[1] == cs[2]){
			int c = cs[1], b = cs[0];
			if(dp[b][b] >= 0){
				dp[c][c] = max(dp[c][c], dp[b][b] + 1);
			}
			for(int a=1; a<=N; a++){
				int p = dp[min(a, c)][max(a, c)];
				if(p < 0) continue;

				dp[min(a,b)][max(a,b)] = max(dp[min(a,b)][max(a,b)], p + 1); 
			}

		}else{
			for(int j=0; j<3; j++){
				int a = cs[j];
				int p = dp[a][a];
				if(p < 0) continue;

				vector<int> cs2;
				for(int k=0; k < 3; k++){
					if(k != j){
						cs2.push_back(cs[k]);
					}
				}
				int b = cs2[0], c = cs2[1];
				dp[b][c] = max(dp[b][c], p + 1);
			}

		}

		for(int a=1; a<=N; a++){
			if(vis[a] == 0) continue;
			for(int c : cs){
				dp[min(a, c)][max(a, c)] = max(dp[min(a, c)][max(a, c)], 0);
			}
		}
		for(int i=0; i<3; i++){
			for(int j=i+1; j<3; j++){
				dp[cs[i]][cs[j]] = max(dp[cs[i]][cs[j]], 0);
			}
		}
	}

	for (int a = 1; a <= N; a++)
	{
		for (int b = 1; b <= N; b++)
		{
			ans = max(ans, dp[a][b]);
		}
	}

	ans = max(ans, dp[0][0]);
	return ans;
}

