            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            // 下準備
            int dqq = dp[q][q] + 1; 
            vector<int> dpk(N+1,0);
            for (int k = 1; k <= N; k++)
            {
                if(p>k) dpk[k] = dp[p][k] + 1;
                else dpk[k] = dp[k][p] + 1;
            }

            // 以前のやつ一個だけ採用
            for (int k = 1; k <= N; k++)
            {
                update(k, q , dp_maxk[k]);
                update(k, p , dp_maxk[k]);
            }
            // 以前のやつを採用しない
            update_rc(p, p, dp_max);
            update_rc(p, q, dp_max);
            // pk,qppからpppを取った場合
            for (int k = 1; k <= N; k++)
            {
                update_rc(k, q, dpk[k]);
            }
            // qq,qppの場合
            update_rc(p, p, dqq);
        }
        else
        {
            // 全部ばらばら
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];
            int dpp = dp[p][p] + 1;
            int dqq = dp[q][q] + 1;
            int drr = dp[r][r] + 1;
            // 以前のやつ一個だけ採用
            for(int k = 1; k<=N; k++){
                update(p, k, dp_maxk[k]);
                update(q, k, dp_maxk[k]);
                update(r, k, dp_maxk[k]);
            }
            // 以前のやつを採用しない
            update_rc(p, q, dp_max);
            update_rc(q, r, dp_max);
            update_rc(r, p, dp_max);
            // +1がある.pp,pqr or qq,pqr or rr,pqr
            update_rc(q, r, dpp);
            update_rc(p, r, dqq);
            update_rc(p, q, drr);
        }
    }
    int ans = dp_max;
    int last = A[3*N-1];
    chmax(ans, dp[last][last] + 1);
    cout << (ans+all) << "\n";
    return 0;
} 

