    bool three = false;
    for (int j = 0; j < vp.size(); j++) {
      if (vp[j].second >= 3) {
        ans++;
        vp[j].second -= 3;
        three = true;
        ms.erase(vp[j].first);
      }
    }
    if (three) continue;

    vector<tuple<int, int, int>> next; // 次に揃う位置, 番号, 枚数
    for (int j = 0; j < vp.size(); j++) {
      if (vp[j].second == 0) continue;
      else if (vp[j].second == 1) {
        //if (x[xit[vp[j].first] + 2] != 1e9) {
          next.emplace_back(make_tuple(x[xit[vp[j].first] + 2], vp[j].first), vp[j].second);
        //}
      }
      else if (vp[j].second == 2) {
        //if (x[xit[vp[j].first] + 1] != 1e9) {
          next.emplace_back(make_tuple(x[xit[vp[j].first] + 1], vp[j].first), vp[j].second);
        //}
      }
    }
    sort(next.begin(), next.end());
    int choice1 = get<1>(next[0]), choice2;
    if (get<2>(next[0]) >= 2) choice2 = choice1;
    else choice2 = get<1>(next[1]);
    multiset<int> ms2;
    ms2.insert(choice1);
    ms2.insert(choice2);
    ms = ms2;
  }

  vector<int> last;
  for (auto it = ms.begin(); it != ms.end(); it++) {
    last.emplace_back(*it);
  }

  if (last[0] == last[2]) ans++;

  cout << ans << '\n';
}

