  A.push_back(-4);
  A.push_back(-5);
  A.push_back(-6);
  A.push_back(-7);
  A.push_back(-8);

  llong ans = 0;
  for (llong i = 0; i < 3 * N; i += 3) {
    map<llong, llong> m;
    vector<lpair> v;
    for (int j = i; j < i + 5; j++) {
      m[A[j]]++;
    }
    for (auto it: m) {
      v.push_back(lpair(it.second, it.first));
    }
    sort(ALL(v), greater<>());
    if (v.size() == 1) {
      ans++;
    }
    else if (v.size() == 2) {
      ans++;
      A[i + 3] = v[1].second;
      A[i + 4] = v[1].second;
    }
    else if (v.size() == 3 && v[0].first == 3) {
      ans++;
      A[i + 3] = v[1].second;
      A[i + 4] = v[2].second;
    }
    else {
      vector<llpair> next;
      for (auto vv: v) {
        llong now = vv.second;
        auto it = lower_bound(ALL(pos[now]), i);
        if (pos[now].end() - it < 3 - vv.first) continue;
        llong res = 0;
        for (int j = 0; j < 3 - vv.first; j++) {
          it++;
          res += *it - (i + 3);
        }
        next.push_back(llpair(res, lpair(now, vv.first)));
      }
      sort(ALL(next), greater<>());
      llong two = next[0].second.second != 2;
      A[i + 3] = next[0].second.first;
      A[i + 4] = next[two].second.first;
    }
  }

  cout << ans << endl;

