        for (int j = 1; j <= N; j++) {
            //printf("i = %d j = %d dp = %d\n", i, j, dp[i][j]);
            ans = max(ans, dp[i][j]);
        }
    printf("%d\n", max(ans, dp[A[3 * N - 1]][A[3 * N - 1]] + 1) + offs);
    return 0;
}
