struct sets {
	int n;
	vi A, B;
	sets(int n_) : n(n_), A(n + 1, 0), B(n + 1, 0) {}
	void moveBtoA() {
		REP(i, n + 1) {
			A[i] = min(A[i] + B[i], 1);
			B[i] = 0;
		}
	}
	void clearA() {
		fill(A.begin(), A.end(), 0);
	}
	void take_from_B(int x) {
		assert(B[x]);
		assert(B[x] <= 2);
		B[x]--;
		moveBtoA();
	}
	void take_from_A(int x) {
		assert(A[x] == 1);
		A[x]--;
		clearA();
		moveBtoA();
	}
	void take(int x) {
		if (B[x]) take_from_B(x);
		else take_from_A(x);
	}
	void put(int x) {
		B[x] = min(B[x] + 1, 2);
	}
	bool can_take(int x) {
		return A[x] || B[x];
