int N;
deque<int> A;
void input(){
    fast_io();
    cin >> N;
    for (int i = 0; i < 3*N; i++)
    {
        int a; cin >> a;
        A.push_back(a);
    }
}

pii p2(int a, int b){
    if(a<b) swap(a,b);
    return make_pair(a,b);
}

void chmax(int &a, int b){if(a<b) a=b;}

int solve(){
    vector<map<pii, int > > dp;
    dp.resize(N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[1][p2(A[0], A[1])] = 0;
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1]){
            dp[i+1] = dp[i];
            for(auto &[p,c]:dp[i+1]){
                c++;
            }
        }
        else if(A[3*i-1]==A[3*i] || A[3*i]==A[3*i+1] || A[3*i+1]==A[3*i-1]){
            int p, q;
            if(A[3*i-1]==A[3*i]){
                p = A[3*i-1];
                q = A[3*i+1];
            }
            else if(A[3*i]==A[3*i+1]){
                p = A[3*i];
                q = A[3*i-1];
            }
            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            else{
                p = 0, q = 0;
            }
            pair<pii,int> M = *max_element(dp[i].begin(),dp[i].end(),[](pair<pii,int> a, pair<pii,int> b){return a.second < b.second;});
            dp[i+1] = dp[i];
            for(auto [x,c]:dp[i]){
                chmax(dp[i+1][p2(p, x.first)],c);
                chmax(dp[i+1][p2(q, x.first)],c);

                chmax(dp[i+1][p2(p, x.second)],c);
                chmax(dp[i+1][p2(q, x.second)],c);
            }
            chmax(dp[i+1][p2(p, p)], M.second);
            chmax(dp[i+1][p2(p, q)], M.second);
            for (int k = 1; k <= N; k++)
            {
                if(dp[i].find(p2(k, p))!=dp[i].end()) chmax(dp[i+1][p2(k, q)],dp[i][p2(k, p)] + 1);
            }

        }
        else{
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];
            pair<pii,int> M = *max_element(dp[i].begin(),dp[i].end(),[](pair<pii,int> a, pair<pii,int> b){return a.second < b.second;});
            dp[i+1] = dp[i];
            for(auto [x,c]:dp[i]){
                chmax(dp[i+1][p2(p, x.first)],c);
                chmax(dp[i+1][p2(q, x.first)],c);
                chmax(dp[i+1][p2(r, x.first)],c);

                chmax(dp[i+1][p2(p, x.second)],c);
                chmax(dp[i+1][p2(q, x.second)],c);
                chmax(dp[i+1][p2(r, x.second)],c);
            }
            chmax(dp[i+1][p2(p,q)],M.second);
            chmax(dp[i+1][p2(q,r)],M.second);
            chmax(dp[i+1][p2(r,p)],M.second);

            if(dp[i].find(p2(p, p))!=dp[i].end()) chmax(dp[i+1][p2(q,r)], dp[i][p2(p, p)] + 1);
            if(dp[i].find(p2(q, q))!=dp[i].end()) chmax(dp[i+1][p2(p,r)], dp[i][p2(q, q)] + 1);
            if(dp[i].find(p2(r, r))!=dp[i].end()) chmax(dp[i+1][p2(p,q)], dp[i][p2(r, r)] + 1);
        }
        dp[i].clear();
    }
    int ans = 0;
    for(auto [p,c]:dp[N]){
        int a = p.first;
        int b = p.second;
        if((a==b) && (b==A[3*N-1])) ans = max(ans, c + 1);
        else ans = max(ans, c);
    }
    cout << ans << endl;
    return 0;
} 

int main()
{
    input();
    solve();
    return 0;
}

