int main() {
  int n;
  cin >> n;
  vector<int> a(3 * n);
  for (int i = 0; i < 3 * n; ++i)
    cin >> a[i];
  vector<int> cnt(n + 1);
  cnt[a[0]]++, cnt[a[1]]++;
  int ans = 0;
  for (int i = 2; i < 3 * (n - 1); i += 3) {
    int x = a[i], y = a[i + 1], z = a[i + 2];
    if (x == y && x == z) {
      ans++;
      continue;
    }
    if (x == y && cnt[x] >= 1) {
      ans++;
      cnt[x]--;
      for (int i = 1; i <= n; ++i)
        cnt[i] = min(cnt[i], 1);
      cnt[z]++;
    } else if (x == z && cnt[x] >= 1) {
      ans++;
      cnt[x]--;
      for (int i = 1; i <= n; ++i)
        cnt[i] = min(cnt[i], 1);
      cnt[y]++;
    } else if (y == z && cnt[y] >= 1) {
      ans++;
      cnt[y]--;
      for (int i = 1; i <= n; ++i)
        cnt[i] = min(cnt[i], 1);
      cnt[x]++;
    } else if (cnt[x] >= 2 || cnt[y] >= 2 || cnt[z] >= 2) {
      int tx = cnt[x] >= 2, ty = cnt[y] >= 2, tz = cnt[z] >= 2;
      ans++;
      int t = tx + ty + tz;
      for (int i = 1; i <= n; ++i)
        cnt[i] = 0;
      if (t >= 2) {
        cnt[x]++;
        cnt[y]++;
        cnt[z]++;
      } else {
        if (!tx)
          cnt[x]++;
        if (!ty)
          cnt[y]++;
        if (!tz)
          cnt[z]++;
      }
    } else {
      cnt[x]++;
      cnt[y]++;
      cnt[z]++;
    }
  }
  if (cnt[a[3 * n - 1]] >= 2)
    ans++;
  cout << ans;
}

