const ll SIZE = 1e6 * 2 + 10, INF = 1e9 + 10, SZ = 9000;

ll dp[SZ][SZ][2];
ll n, addAll = 0;
vector<ll> vec;

int main()
{
	fastInp;

	cin >> n;
	vec.resize(n * 3);
	ll curInd = 0;
	for (int i = 0; i < n * 3; i++) cin >> vec[i];
	for (int i = 0; i <= n; i++) {
		for (int j = 0; j <= n; j++) {
			dp[i][j][0] = -INF;
			dp[i][j][1] = -INF;
		}
	}

	dp[vec[0]][vec[1]][curInd] = 0;
	dp[vec[1]][vec[0]][curInd] = 0;

	ll ans = 0;
	ll mx = -INF;

	for (int i = 2; i < n * 3 - 1; i += 3) {
		if (vec[i] == vec[i + 1] && vec[i + 1] == vec[i + 2]) {
			addAll++;
			continue;
		}

		curInd = !curInd;
		vector<ll> vals = { vec[i], vec[i + 1], vec[i + 2] };

		for (int i = 0; i < vals.size(); i++) {
			ll y = vals[i];
			for (int j = 0; j < vals.size(); j++) {
				ll x = vals[j];
				for (int t = 0; t < vals.size(); t++) {
					ll z = vals[t];
					if (i != j && j != t && t != i) {
						dp[x][y][curInd] = max(dp[x][y][curInd], mx);
					}
				}
			}
		}

		for (int i = 0; i < vals.size(); i++) {
			ll y = vals[i];
			for (int j = 0; j < vals.size(); j++) {
				ll x = vals[j];
				for (int t = 0; t < vals.size(); t++) {
					ll z = vals[t];
					if (i != j && j != t && t != i) {
						if (x == y) {
							for (int k = 0; k <= n; k++) {
								dp[k][z][curInd] = max(dp[k][z][curInd], dp[k][x][!curInd] + 1);
								dp[z][k][curInd] = max(dp[k][z][curInd], dp[k][x][!curInd] + 1);
							}
						}
						dp[x][y][curInd] = max(dp[x][y][curInd], dp[z][z][!curInd] + 1);
						dp[y][x][curInd] = max(dp[x][y][curInd], dp[z][z][!curInd] + 1);
						mx = max(mx, dp[x][y][curInd]);
					}
				}
			}
		}
	}


	for (int k = 0; k <= n; k++) {
		for (int j = 0; j <= n; j++) {
			ll vl = 0;
			if ((vec.back() == k && vec.back() == j)) vl = 1;
			ans = max(ans, dp[k][j][curInd] + vl);
			if (ans == 2) {
				cout << "";
			}
		}
	}

	cout << ans + addAll;

	return 0;
}

