#define INF 1001001001

int main() {
  int n;
  cin >> n;
  vector< vector<int> > dp(n, vector<int>(n,-1));
  map<P,int> next;
  P maxidx = {0,0};
  vector<int> maxidx1(n), maxidx2(n); 
  int x, y, z;

  auto move = [&](P from, P to, bool plus) {
    int fx, fy, tx, ty;
    tie (fx,fy) = from;
    if (dp[fx][fy]==-1) return;
    next[to] = max(next[to],dp[fx][fy]+plus);
  };
  auto update = [&] {
    int x, y;
    for (auto m : next) {
      tie(x,y) = m.first;
      dp[x][y] = m.second;
      if (dp[x][y] > dp[maxidx.first][maxidx.second]) maxidx = {x,y};
      if (dp[x][y] > dp[maxidx1[y]][y]) maxidx1[y] = x;
      if (dp[x][y] > dp[x][maxidx2[x]]) maxidx2[x] = y;
    }
    next.clear();
  };

  cin >> x >> y; x--; y--;
  dp[x][y] = 0;
  move({x,y},{x,y},false);
  int ans = 0;
  rep(i,n-1) {
    update();
    cin >> x >> y >> z;
    x--; y--; z--;
    if (x == y && y == z) {
      ans++;
      continue;
    }
    if (x == y || x == z || y == z) {
      int p, q;
      if (x == y) p = x; q = z;
      if (x == z) p = x; q = y;
      if (y == z) p = y; q = x;
      rep(j,n) {
        move({j,p},{j,q},true);
        move({p,j},{j,q},true);
      }
    }
    move({x,x},{y,z},true);
    move({y,y},{x,z},true);
    move({z,z},{x,y},true);

    move(maxidx,{x,y},false);
    move(maxidx,{x,z},false);
    move(maxidx,{y,z},false);

    rep(j,n) {
      move({maxidx1[j],j},{j,x},false);
      move({j,maxidx2[j]},{j,x},false);
      move({maxidx1[j],j},{j,y},false);
      move({j,maxidx2[j]},{j,y},false);
      move({maxidx1[j],j},{j,z},false);
      move({j,maxidx2[j]},{j,z},false);
    }
  }
  update();
  cin >> x; x--;
  int ta = 0;
  rep(i,n) rep(j,n) {
    if (i == j && j == x) ta = max(ta,dp[i][j]+1);
    else ta = max(ta,dp[i][j]);
  }
  ans += ta;

  cout << ans << endl;

  return 0;
}

