    vvint dp(N, vint(N, -1));
    vint rmax(N, -1);
    dp[A[0]][A[1]] = dp[A[1]][A[0]] = 0;
    rmax[A[0]] = rmax[A[1]] = 0;
    rep(i, N - 1) {
        vint a = {A[3 * i + 2], A[3 * i + 3], A[3 * i + 4]};
        if (a[0] == a[1] && a[1] == a[2]) {
            bias++;
            continue;
        }
        vector<tuple<int, int, int>> query;
        rep(j, 3) {
            vint aa;
