						ad = 0;
						break;
					}
				}
			}
			chmax(dp[a[i]][a[j]], ad);
			chmax(dp[a[j]][a[i]], ad);
			chmax(mx2[a[i]], dp[a[i]][a[j]]);
			chmax(mx2[a[j]], dp[a[j]][a[i]]);
			chmax(mx, dp[a[i]][a[j]]);
		}
	}
