			vector<int> u;
			rep(k,3){
				if(j == k) continue;
				u.push_back(v[k]);
			}
			if(mp.find({u[0], u[1]}) != mp.end()){
				chmax(mp[{u[0], u[1]}], dp[v[j]][v[j]] + 1);
