int main() {
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  n *= 3;
  vector<int> a(n);
  for (int &x : a) {
    cin >> x;
  }
  unordered_map<int, int> m;
  vector<int> r(n + 1, n);
  for (int i = n - 1; i >= 0; --i) {
    if (m.count(a[i])) {
      r[i] = m[a[i]];
    }
    m[a[i]] = i;
  }
  vector<int> dp(n + 1);
  for (int i = n - 1; i >= 0; --i) {
    const int g = i % 3;
    const int rb = r[r[i]];
    if (rb < n) {
      dp[i] = max(dp[i], dp[rb + 1] + 1);
    } else {
      continue;
    }
    auto adv = [&](int x) {
      x = min(x + 1, n);
      while (x < n && (x == i || x == r[i] || x == r[r[i]])) ++x;
      return x;
    };
    int j = adv(i);
    for (int k = 0; k < (3 - g) % 3; ++k) j = adv(j);
    for (int cnt = 1; j < rb;) {
      int rj = adv(j);
      int rrj = adv(rj);
      if (rj == r[j] && rrj == r[r[j]]) {
        ++cnt;
        dp[i] = max(dp[i], cnt + dp[max(rrj, rb) + 1]);
      }
      j = adv(rrj);
    }
  }
  cout << dp[0] << endl;
  return 0;
}

