    int res = 0;

    for(int i = 0 ; i < MAXN ; i++)
    {
    	for(int j = 0 ; j < MAXN ; j++)
    	{
    		dp[i][j] += acum;

    		if(A[3*N] == i && i == j)res = max(res, dp[i][j]+1);
    		else res = max(res, dp[i][j]);
    	}
    }

