        array<ll,3> D = A[i];

        //パターン1 (来たやつ全部いっしょ)
        if(D[0]==D[2]){
            Ans++;
            continue;
        }
        //パターン2 (来たやつ2ついっしょ)
        if(D[0]==D[1]){
            REP(j,maxA){
                chmax({j,D[2]},dp[j][D[0]]+1);
            }
        }
        if(D[1]==D[2]){
            REP(j,maxA){
                chmax({j,D[0]},dp[j][D[2]]+1);
            }
        }
        //パターン3 (来たやつ全部違う)
        if(D[0]!=D[1] && D[1]!=D[2] && D[2]!=D[0]){
            chmax({D[1],D[2]},dp[D[0]][D[0]]+1);
            chmax({D[0],D[2]},dp[D[1]][D[1]]+1);
            chmax({D[0],D[1]},dp[D[2]][D[2]]+1);
        }


        //ここからは得にならない遷移
        //パターン4 (来たやつそのまま受け流す(ナベアツ))
        //in-placeにつきコード不要

