		for (auto p : mp) {
			ll x = p.first.first;
			ll y = p.first.second;
			dp[x][y] = max(dp[x][y], p.second - S);
			dp[y][x] = dp[x][y];
			R[x] = max(R[x], p.second);
			R[y] = max(R[y], p.second);
			M = max(M, p.second);
		}

	}

	M = max(M, dp[A[3 * N]][A[3 * N]] + S + 1);
	cout << M << endl;
}

