using namespace std;

const int maxN = 2e3; int n;
int arr[3*maxN];

struct State
{
  int a, b, c;
  bool operator<(const State &other) const
  {
    return a < other.a || (a == other.a && b < other.b) || (a == other.a && b == other.b && c < other.c);
  }
};
map<State, int> memo;
int solve(int i = 0, int a = -1, int b = -1)
{
  if (a > b) swap(a, b);
  if (i + 2 == n - 1) return a == b && b == arr[n - 1];

  State curr = State{i, a, b};
  if (memo.count(curr)) return memo[curr];

  if (a != -1) arr[i] = a;
  if (b != -1) arr[i + 1] = b;

  int ans = 0;

  unordered_map<int, int> cnt;
  for (int j = 0; j < 5; j++)
  {
    if (!cnt.count(arr[i + j]))
      cnt[arr[i + j]] = 0;
    cnt[arr[i + j]]++;
  }
  for (auto &p: cnt)
    if (p.second >= 3)
    {
      a = b = p.first; bool first = true;
      for (int j = 0; j < 5; j++)
        if (arr[i + j] != p.first)
          if (first)
            a = arr[i + j], first = false;
          else
            b = arr[i + j];
      ans = max(ans, 1 + solve(i + 3, a, b));
    }
  for (int j = 0; j < 5; j++)
    for (int k = j + 1; k < 5; k++)
      ans = max(ans, solve(i + 3, arr[i + j], arr[i + k]));

  return memo[curr] = ans;
}

