{
  while (scanf("%d", &n) != EOF)
  {
    n = 3*n;
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);

    memo.clear();
    int ans = solve();
    printf("%d\n", ans);
  }
  return 0;
}

