        for (int j = 1; j <= it.second; j++) a[++n] = it.first;
      }
      add2();
      continue;
    }
    int need = 3;
    while (need) {
      int mn = (int) 1e9;
      for (auto &it : f) {
        if (it.second)
        mn = min(mn, ant3(it.first));
      }
      for (auto &it : f) {
        if (it.second && ant3(it.first) == mn) {
          int t = min(it.second, need);
          need -= t;
          it.second -= t;
          break;
        }
      }
    }
    del5();
    n -= 5;
    for (auto &it : f) {
      for (int j = 1; j <= it.second; j++) a[++n] = it.first;
    }
    add2();
  }
  sol += (a[1] == a[2] && a[2] == a[3]);
  be = max(be, sol);
  }
  cout << be << "\n";
