#include <bits/stdc++.h>
using namespace std;
using VI = vector<int>;
using VVI = vector<VI>;
using VVVI = vector<VVI>;

int get_pair_card(int num_cards, int cards[])
{
    assert(num_cards == 3);
    if (cards[0] == cards[1] || cards[0] == cards[2])
        return cards[0];
    if (cards[1] == cards[2])
        return cards[1];
    return -1;
}

int get_alone_card(int num_cards, int cards[], int pair_card)
{
    for (int i = 0; i < num_cards; ++i) {
        if (cards[i] != pair_card) 
            return cards[i];
    }
    assert(false);
    return -1;
}

void update_max(VI &max_vec, int &max_score, int idx, int tmp_score)
{
    if (max_vec.at(idx) < tmp_score)
        max_vec.at(idx) = tmp_score;
    if (max_score < tmp_score)
        max_score = tmp_score;
}

int main()
{
    int N;
    cin >> N;
    VI A_vec(3 * N);
    for (int i = 0; i < 3 * N; ++i) {
        cin >> A_vec.at(i);
    }
    VVI dp(N + 1, VI(N + 1, -1));
    VI prev_max_vec(N + 1, -1);
    VI max_vec(N + 1, -1);
    dp[A_vec.at(0)][A_vec.at(1)] = 0;
    dp[A_vec.at(1)][A_vec.at(0)] = 0;
    max_vec.at(A_vec.at(0)) = 0;
    max_vec.at(A_vec.at(1)) = 0;
    prev_max_vec.at(A_vec.at(0)) = 0;
    prev_max_vec.at(A_vec.at(1)) = 0;
    int cards[3] = {};
    int auto_score = 0;
    int max_score = 0;
    int prev_max_score = 0;
    for (int i = 0; i < N - 1; ++i) {
        cards[0] = A_vec.at(3 * i + 2);
        cards[1] = A_vec.at(3 * i + 3);
        cards[2] = A_vec.at(3 * i + 4);
        if (cards[0] == cards[1] && cards[0] == cards[2]) {
            ++auto_score;
            continue;
        }
        int pair_card = get_pair_card(3, cards);
        if (pair_card > 0) {
            int p = pair_card;
            int q = get_alone_card(3, cards, pair_card);
            for (int j = 1; j <= N; ++j) {
                if (dp[p][j] == -1 && dp[j][p] == -1)
                    continue;
                dp[j][p] = dp[p][j] = max(dp[p][j], dp[j][p]);
                if (dp[q][j] < dp[p][j] + 1) {
                    dp[q][j] = dp[p][j] + 1;
                }
                dp[j][q] = dp[q][j] = max(dp[j][q], dp[q][j]);
                update_max(max_vec, max_score, j, dp[q][j]);
                update_max(max_vec, max_score, q, dp[q][j]);
            }
        } else {
            for (int j = 0; j < 3; ++j) {
                int p = cards[j];
                if (dp[p][p] == -1)
                    continue;
                int q = cards[(j + 1) % 3];
                int r = cards[(j + 2) % 3]; 
                if (dp[q][r] < dp[p][p] + 1)
                    dp[q][r] = dp[p][p] + 1;
                dp[q][r] = dp[r][q] = max(dp[q][r], dp[r][q]);
                update_max(max_vec, max_score, q, dp[q][r]);
                update_max(max_vec, max_score, r, dp[q][r]);
            }
        }
        for (int j = 0; j < 3; ++j) {
            int p = cards[j];
            int q = cards[(j + 1) % 3];
            if (dp[p][q] < prev_max_score)
                dp[p][q] = prev_max_score;
            dp[p][q] = dp[q][p] = max(dp[p][q], dp[q][p]);
            update_max(max_vec, max_score, p, dp[p][q]);
            update_max(max_vec, max_score, q, dp[p][q]);
        }
        for (int j = 0; j < 3; ++j) {
            int p = cards[j];
            for (int k = 1; k <= N; ++k) {
                if (prev_max_vec.at(k) == -1)
                    continue;
                if (dp[p][k] < prev_max_vec.at(k)) {
                    dp[p][k] = prev_max_vec.at(k);
                }
                dp[p][k] = dp[k][p] = max(dp[p][k], dp[k][p]);
                update_max(max_vec, max_score, p, dp[p][k]);
                update_max(max_vec, max_score, k, dp[p][k]);
            }
        }
        for (int i = 1; i <= N; ++i)
            prev_max_vec.at(i) = max_vec.at(i);
        prev_max_score = max_score;
    }
    for (int j = 1; j <= N; ++j) {
        for (int k = 1; k <= N; ++k) {
            if (dp[j][k] == -1)
                continue;
            if (j == k && A_vec.at(3 * N - 1) == j)
                dp[j][k] = dp[j][k] + 1;
            if (max_score < dp[j][k])
                max_score = dp[j][k];
        }
    }
    max_score += auto_score;
    cout << max_score << endl;
}

