vector<int> a;
int dp[3000][3000];
int n, ans = 0;
int cost(int i, int j, int k) {
  return a[i] == a[j] && a[j] == a[k];
}
void chmin(int &x, int val) {
  x = min(x, val);
}
void transition(int i, int j, int gid) {
  if (gid > n) return;
  if (gid == n)
    return void(ans = max(ans, dp[i][j] + cost(i, j, gid)));
  for (int c : {i, j, gid})
    if (c == gid)
      for (int u = 1; u <= 3; ++u)
        for (int v = u + 1; v <= 3; ++v)
          chmin(dp[c + u - 1][gid + v - 1], cost(i, j, gid + (u ^ v) - 1));
    else {
      chmin(dp[c][0], cost(i ^ j ^ c, 1, 2));
      chmin(dp[c][1], cost(i ^ j ^ c, 0, 2));
      chmin(dp[c][2], cost(i ^ j ^ c, 1, 1));
    }
}
void solve(std::istream &in, std::ostream &out) {
  in >> n;
  int bonus = 0;
  for (int i = 0; i < n; ++i) {
    for (int j = 0, x; j < 3; ++j) in >> x, a.push_back(x);
    if (cost(a.size() - 3, a.size() - 2, a.size() - 1) == 1) {
      ++bonus;
      for (int j = 0; j < 3; ++j) a.pop_back();
    }
  }
  n = (int) a.size() / 3;
  vector<int> nxt(3 * n, 0), last(3 * n, 3 * n);
  for (int i = 3 * n - 1; i >= 0; --i) nxt[i] = last[a[i]], last[a[i]] = i;
  for (int i = 0; i < 3 * n; ++i) for (int j = 0; j < 3 * n; ++j) dp[i][j] = numeric_limits<int>::min() / 2;
  dp[0][1] = 0;
  for (int i = 0; i < 3 * n; ++i) {
    for (int j = i + 1; j < 3 * n; ++j) {
      transition(i, j, (j + 3) / 3 * 3);
      if (j / 3 * 3 < nxt[j] / 3 * 3)
        transition(i, j, nxt[j] / 3 * 3);
      if (i / 3 * 3 < nxt[i] / 3 * 3)
        transition(i, j, nxt[i] / 3 * 3);
    }
  }
  out << ans + bonus << '\n';
}

