                dp[k][x]=max(dp[k][x],ma[k]);
                dp[k][y]=max(dp[k][y],ma[k]);
                dp[k][z]=max(dp[k][z],ma[k]);
            }
            ma[x]=max(ma[x],dp[x][y]);
            ma[y]=max(ma[x],dp[x][y]);
            ma[y]=max(ma[x],dp[y][z]);
            ma[z]=max(ma[x],dp[y][z]);
            ma[z]=max(ma[x],dp[z][x]);
            ma[x]=max(ma[x],dp[z][x]);
            M=max(M,ma[x]);
            M=max(M,ma[y]);
            M=max(M,ma[z]);
        }
        // rep(i,n+1){
        //     rep(j,n+1){
        //         cout << i << " " << j << " " << dp[i][j] << endl;
        //     }
        // }
    }
    int ans=0;
    rep(i,n+1){
        rep(j,n+1){
            ans=max(ans,c+dp[i][j]);
        }
    }
    cout << ans << endl;
}

