		for(int p=0;p<5;p++){
			if(e==p) continue;
			int ll = -1,err = 0;
			for(int q=0;q<5;q++){
				if(e==q||p==q) continue;
				if(ll==-1) ll = arr[q];
				else{
					if(ll!=arr[q]) err = 1;
				}
			}
			if(err==0){
				dp[min(arr[e],arr[p])][max(arr[e],arr[p])] = 1;
			}else{
				dp[min(arr[e],arr[p])][max(arr[e],arr[p])] = max(dp[min(arr[e],arr[p])][max(arr[e],arr[p])],0);
			}
		}
	}
