		int ll = -1,err = 0,res = 0;
		for(int q=lx;q<rx;q++){
			if(ll==-1) ll = arr[q];
			else{
				if(ll!=arr[q]) err = 1;
			}
		}
		if(err==0) tt++;
		vector<pair<pi,int> > v;
		for(int q=lx;q<rx;q++){
			if(dp[arr[q]][arr[q]]!=-1e9){
				int s1 = -1,s2 = -1;
				for(int r=lx;r<rx;r++){
					if(q==r) continue;
					if(s1==-1) s1 = arr[r];
					else s2 = arr[r];
				}
				if(s1>s2) swap(s1,s2);
				v.push_back(mk(mk(s1,s2),dp[arr[q]][arr[q]]+1+tt));
			}
			for(int r=q+1;r<rx;r++){
				if(arr[q]!=arr[r]) continue;
				int s1 = -1;
