		{
			add++;
			i=i+2;
			continue;
		}
		v.pb(a[i]);
	}
	rep(i,6005) nxt[i]=-1;
	repn(i,v.size()-1)
	{
		for(int j=i+1;j<v.size()-1;j++)
		{
			if(a[i]==a[j])
			{
				nxt[i]=j;
				break;
			}
		}
	}
	if(v.size()==1)
	{
		cout<<add<<endl;
		return 0;
	}
	rep(i,6005) rep(j,6005) dp[i][j]=-1;
	dp[1][2]=0;
	repn(i,v.size()-1) for(int j=i+1;j<v.size();j++)
	{
		if(dp[i][j]==-1) continue;//cout<<i<<' '<<j<<' '<<dp[i][j]<<' '<<nxt[i]<<' '<<nxt[j]<<endl;
		ans=max(ans,dp[i][j]);
		trans(i,j,(j+3)/3*3);
		if(nxt[i]!=-1&&nxt[i]<v.size()&&j/3*3<nxt[i]/3*3) trans(i,j,nxt[i]/3*3);
		if(nxt[j]!=-1&&nxt[j]<v.size()&&j/3*3<nxt[j]/3*3) trans(i,j,nxt[j]/3*3);
	}
	cout<<ans+add<<endl;//cout<<ans<<endl;
	//rep(i,v.size()) cout<<v[i]<<' ';
	return 0;
}

