    int N;
    cin >> N;
    vector<int> A(N * 3);
    for(int i = 0; i < N * 3; ++i){
        cin >> A[i];
        --A[i];
    }

    vector<vector<vector<int>>> dp(2, vector<vector<int>>(N + 1, vector<int>(N + 1, -1)));
    auto update = [&](int i, int j, int x) -> void {
        chmax(dp[1][i][j], x);
        chmax(dp[1][j][i], x);
        chmax(dp[1][i][N], x);
        chmax(dp[1][j][N], x);
        chmax(dp[1][N][N], x);
    };
    update(A[0], A[1], 0);
    swap(dp[0], dp[1]);

    int score = 0;
    for(int i = 2; i < N * 3 - 1; i += 3){
        int p = A[i], q = A[i + 1], r = A[i + 2];
        if(p == q && q == r){
            ++score;
            continue;
        }
        for(int loop = 0; loop < 3; ++loop){
            update(p, q, max(dp[0][N][N], dp[0][r][r] + 1));
            swap(p, q);
            swap(q, r);
        }
        for(int x = 0; x < N; ++x){
            for(int loop = 0; loop < 3; ++loop){
                update(x, r, dp[0][x][N]);
                if(p == q)  update(x, r, dp[0][x][p] + 1);
                swap(p, q);
                swap(q, r);
            }
        }
        swap(dp[0], dp[1]);
    }

    int ans = max(dp[0][N][N], dp[0][A.back()][A.back()] + 1);
    ans += score;
    cout << ans << endl;
}

