long long solve(int N, const std::vector<long long> &A) {
  int bingo = 0;
  vi ma1(N, -10000000), ma2(N, -10000000);
  vector<vi> dp(N, vi(N, -10000000));
  // 混ざらないように更新分はここで管理。
  vector<vi> tmp(N, vi(N, -10000000));
  dp[A[0]][A[1]] = 0;
  ma1[A[0]] = 0;
  ma2[A[1]] = 0;

  queue<pair<int, int>> que;

  // pが2個、qが1個
  auto same = [&](int p, int q) -> void {
    // pが2個あるので、1個取っておけばスコアが稼げる。
    REP(k, N) {
      que.push({k, q});
      chmax(tmp[k][q], dp[k][p] + 1);
      chmax(tmp[k][q], dp[p][k] + 1);
    }
  };

  FOR(i, 1, N + 1) {
    int p, q = -1, r = -1;
    p = A[3 * i - 1];
    if (i < N) {
      q = A[3 * i];
      r = A[3 * i + 1];
    }

    if (p == q && q == r) {
      bingo++;
      continue;
    } else if (q == -1) {
      // 最後の追加は一つだけ
      dp[p][p]++;
      break;
    } else if (p == q) {
      same(p, r);
    } else if (q == r) {
      same(q, p);
    } else if (r == p) {
      same(r, q);
    }

    int ma = -10000000;
    REP(i, N) {
      chmax(ma, ma1[i]);
      chmax(ma, ma2[i]);
    }

    // pに注目、q,rはこの順で並んでいる必要あり
    auto func = [&](int p, int q, int r) -> void {
      // q,rを残すとき、p pを残していれば1点増える。それ以外はk lは任意なので一番でかいものだと思ってよい
      que.push({q, r});
      chmax(tmp[q][r], dp[p][p] + 1);
      chmax(tmp[q][r], ma);

      // kとpを残す場合、kの片割れが自由になるのでそこだけ全部調べる。
      // qとrが等しい場合の処理は既にtmpに含まれているので考慮不要
      REP(k, N) {
        que.push({k, p});
        chmax(tmp[k][p], ma1[k]);
        chmax(tmp[k][p], ma2[k]);
      }
    };

    func(p, q, r);
    func(q, p, r);
    func(r, p, q);

    // tmpが触ったデータ分だけdpや最大値を更新する。それ以外は書き換えない
    // これがp,q,rを全部捨てた時の更新に当たる
    while (!que.empty()) {
      auto [x, y] = que.front();
      que.pop();
      chmax(ma1[x], tmp[x][y]);
      chmax(ma2[y], tmp[x][y]);
      chmax(dp[x][y], tmp[x][y]);
      tmp[x][y] = -10000000;
    }
  }

  int ans = 0;
  REP(k, N) {
    REP(l, N) { chmax(ans, dp[k][l]); }
  }
  return ans + bingo;
}

