ll rec(vi res)
{
    if((int) res.size() == 3) {
        return res[0] == res[1] and res[1] == res[2];
    }

    vi tmp = res; sort(tmp.begin(), tmp.end());

    ll& here = dp[tmp];

    if(here != 0) return here;

    rep(i, 0, min((int) res.size(), 5)) {
        rep(j, i + 1, min((int) res.size(), 5)) {
            rep(k, j + 1, min((int) res.size(), 5)) {
                vi util;

                rep(l, 0, res.size()) {
                    if(l == i or l == j or l == k) continue;
                    util.pb(res[l]);
                }

                ll got = (res[i] == res[j] and res[j] == res[k]) + rec(util);

                here = max(here, got);
            }
        }
    }

    return here;
}

void solve()
{   
    scn(n);

    vi a(3 * n);

    rep(i, 0, 3 * n)
    scn(a[i]);


    lprin(rec(a));
}

