void dpcalc(vv<vv<pair<ll, pll>>>& dp,vv<ll>& odp2,vv<ll>& av,ll I){
    ll i, j, k;
    vv<ll> dp2 = odp2;

    auto gtdp = [&](ll a, ll b) {
        if(a>b)
            swap(a, b);
        if(dp[a][b].se.fi!=I)
            dp[a][b].se = {I, dp[a][b].fi};
        return dp[a][b].se.se;
    };
    auto stdp = [&](ll a, ll b, ll n) {
        if(a>b)
            swap(a, b);
        if(dp[a][b].se.fi!=I)
            dp[a][b].se = {I, dp[a][b].fi};
        mxin(dp2[a], n);
        mxin(dp2[b], n);
        mxin(dp[a][b].fi, n);
    };



    rep(i,0,3){
        vv<ll> bv;
        rep(j,0,3){
            if(i!=j)
                bv.push_back(av[j]);
        }
        stdp(bv[0], bv[1], 0);
        stdp(bv[0], bv[1], gtdp(av[i], av[i]) + 1);

        rep(j,1,N+1){
            stdp(av[i], j, odp2[j]);
            if(bv[0]==bv[1])
                stdp(av[i], j, gtdp(bv[0], j) + 1);
        }
    }

    odp2 = dp2;
}

int main(){
    scanf("%lld", &N);
    N3 = N * 3;
    rep(i,0,N3){
