    Av.push_back(A[1]);
    rep(i,1,N){
        //cout << A[i * 3 - 1] << A[i * 3] << A[i * 3 + 1] << endl;
        if(A[i*3-1]==A[i*3]&&A[i*3]==A[i*3+1])
            continue;
        rep(j,-1,2){
            Av.push_back(A[i * 3 + j]);
        }
    }
    Av.push_back(A[N3 - 1]);

    vv<vv<pair<ll, pll>>> dp(N + 3, vv<pair<ll, pll>>(N + 3, {-1e15, {0, -1e15}}));
    vv<ll> dp2(N + 3, -1e15);
    if (Av[0] > Av[1])
        swap(Av[0], Av[1]);
    dp[Av[0]][Av[1]] = {N - Av.size() / 3, {0, 0}};
    dp2[Av[0]] = dp2[Av[1]] = dp[Av[0]][Av[1]].fi;

    rep(i,2,Av.size()){
        /*
        rep(j,1,N+1){
            rep(k,j,N+1){
                printf("%lld,%lld:%lld\n", j, k, dp[j][k].fi);
            }
        }*/
        if(i+3>Av.size())
            break;
        vv<ll> bv;
        rep(j,0,3){
            bv.push_back(Av[i + j]);
        }
        dpcalc(dp, dp2, bv, i);
        i += 2;

    }
    ll ans = 0;
    ll ln = Av[i];
    //printf("a%llda", i);
    rep(i,1,N+1){
        rep(j,i,N+1){
            mxin(ans, dp[i][j].fi + (i == j && i == ln));
        }
    }

    printf("%lld\n", ans);

    return 0;
}

