    if (N==1) {
        if (A[0] == A[1] && A[1] == A[2])
            cout << "1\n";
        else
            cout << "0\n";
        return;
    }
    helper1(A[0], A[1], 0, 0);
    for (int i = 1; i < N; ++i) {
        vi new_cards(3, 0);
        new_cards[A[3*i-1]]++;
        new_cards[A[3*i]]++;
        new_cards[A[3*i+1]]++;
        //cout << new_cards[0] << new_cards[1] << new_cards[2] << endl;
        for (int a = 0; a < 3; ++a) {
            for (int b = a; b < 3; ++b) {
                if (!can[i-1][a][b])
                    continue;
                vi count = new_cards;
                count[a]++; count[b]++;
                int point = dp[i-1][a][b];
                for (int k = 0; k < 3; ++k) if (count[k] >= 3) {
                    count[k] -= 3;
                    ++point;
                }
                //cout << point << endl;
                for (int j = 0; j < 3; ++j) {
                    for (int k = j; k < 3; ++k) {
                        if (j == k && count[j] >= 2)
                            helper1(j, k, point, i);
                        else if (j!=k && count[j] && count[k])
                            helper1(j, k, point, i);
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < 3; ++i) {
        for (int j = i; j < 3; ++j) {
            if (can[N-1][i][j]) {
                //cout << i << j  << A.back()<< endl;
                if (i == j && j == A.back())
                    ckmax(ans, dp[N-1][i][j]+1);
                else
                    ckmax(ans, dp[N-1][i][j]);
            }
        }
    }
    cout << ans << endl;
}


