const int INF = 1<<29;
int solve(int N) {
    int offset = 0;
    int a, b, end;
    cin >> a >> b;
    --a, --b;
    vector<vector<int>> A;
    for (int i = 0; i < N-1; ++i) {
        vector<int> v(3);
        for (int j = 0; j < 3; ++j) cin >> v[j], --v[j];
        sort(v.begin(), v.end());
        if (v[0] == v.back()) ++offset;
        else A.push_back(v);
    }
    cin >> end;
    --end;
    vector<vector<int>> dp(N, vector<int>(N, -INF));
    dp[a][b] = dp[b][a] = 0;
    int ma = -INF, nma;
    vector<int> vma(N, -INF), nvma;
    vma[a] = vma[b] = 0;

    auto func = [&](int a, int b, int val) {
        chmax(dp[a][b], val);
        chmax(dp[b][a], val);
        chmax(nma, dp[a][b]);
        chmax(nvma[a], dp[a][b]);
        chmax(nvma[b], dp[a][b]);
    };
    for (auto v : A) {
        nma = ma;
        nvma = vma;
        if (v[0] < v[1] && v[1] < v[2]) {
            int a = v[0], b = v[1], c = v[2];
            func(a, b, dp[c][c] + 1);
            func(a, c, dp[b][b] + 1);
            func(b, c, dp[a][a] + 1);
        }
        else {
            int a, b;
            if (v[1] < v[1]) a = v[0], b = v[2];
            else a = v[2], b = v[0];
            int tmp = dp[b][b];
            for (int f = 0; f < N; ++f) func(b, f, dp[a][f] + 1);
            func(a, a, tmp + 1);
        }
        for (int i = 0; i < 3; ++i) {
            for (int f = 0; f < N; ++f) {
                func(v[i], f, vma[f]);
            }
            for (int j = 0; j < 3; ++j) {
                if (i == j) continue;
                func(v[i], v[j], ma);
            }
        }
        ma = nma;
        vma = nvma;
/*
        cout << "-----------" << endl;
        COUT(v);
        for (int a = 0; a < N; ++a) {
            for (int b = 0; b < N; ++b) {
                if (dp[a][b] >= 0) {
                    cout << a << ", " << b << ": " << dp[a][b] << endl;
                }
            }
        }
     */   
    }
    int res = 0;
    for (int a = 0; a < N; ++a) {
        for (int b = 0; b < N; ++b) {
            if (a == end && b == end) chmax(res, dp[a][b] + 1);
            else chmax(res, dp[a][b]);
        }
    }
    return res + offset;
}

