int myhash(int i, int j){
    if(i != j && cnt[i] <= 1 && cnt[j] <= 1)
        return 0;
    if(i == j && cnt[i] == 0)
        return 0;
    if(i != j && cnt[i] <= 1)
        return j;
    if(i != j && cnt[j] <= 1)
        return i;
