const int MAX = 6005;
const int INF = 1e9;
int dp[MAX][MAX]; // best with i, j in knapsack
int nxt[MAX]; // next location that has max
int label[MAX]; // stores which group
vector<int> a;
vector<int> groups[MAX];
int id[MAX]; // stores which idx in loc
int n;
int ans = 0;
vector<int> loc[MAX]; // stores loc
void update(int x, int y, int val) {
    if (x > y) swap(x, y);
    assert(x < y);
    dp[x][y] = max(dp[x][y], val);
}
int check(int u, int v, int w){
    return (a[u] == a[v] && a[v] == a[w]);
}
void process(int u, int v, int w, int x, int y) {
    // fun fun fun
    assert(u < v);
    update(u, w, dp[u][v] + check(v, x, y));
    update(u, x, dp[u][v] + check(v, w, y));
    update(u, y, dp[u][v] + check(v, x, w));
    update(v, w, dp[u][v] + check(u, x, y));
    update(v, x, dp[u][v] + check(u, x, y));
    update(v, y, dp[u][v] + check(u, w, x));
    update(w, x, dp[u][v] + check(u, v, y));
    update(w, y, dp[u][v] + check(u, v, x));
    update(x, y, dp[u][v] + check(u, v, w));
}
int occur(int i) {
    if (id[i] == (int) loc[a[i]].size() - 1) {
        return -1;
    } else {
        return loc[a[i]][id[i] + 1];
    }
}
void go(int x, int y) {
    assert(x < y);
//    cout << x << " WORKING " << y  << '\n';
//    cout << label[y] << " LABEL" << '\n';
    if (label[y] == n - 1) {
        // you're done already
//        cout << "FINISH" << '\n';
        ans = max(ans, dp[x][y] + check(x, y, 3 * n - 1));
        return;
    }
    // case 1, you just move on until next instance of the same thing
    // since otherwise you would swap, there's no reason not to swap
    int rep = 0;
    int cur_x = nxt[x];
    int cur_y = nxt[y];
    while (min(label[cur_x], label[cur_y]) == label[y]) {
        if (label[cur_x] < label[cur_y]) {
            if (occur(cur_x) == -1) {
                rep = -1;
                break;
            }
            cur_x = occur(cur_x);
        } else if (label[cur_x] > label[cur_y]) {
            if (occur(cur_y) == -1) {
                rep = -1;
                break;
            }
            cur_y = occur(cur_y);
        } else {
            if (occur(cur_x) == -1 || occur(cur_y) == -1) {
                rep = -1;
                break;
            }
            cur_x = occur(cur_x);
            cur_y = occur(cur_y);
        }
    }
    int group;
    if (rep == 0) rep = min(label[cur_x], label[cur_y]);
    assert(rep != label[y]);
    if (rep != -1) {
        group = rep;
        if (group == n) {
            ans = max(ans, dp[x][y] + check(x, y, 3 * n - 1));
        } else {
//            cout << x << " " << y << " " << groups[group][0] << " " << groups[group][1] << " " << groups[group][2] << '\n';
            process(x, y, groups[group][0], groups[group][1], groups[group][2]);
        }
//        cout << group << " " << (groups[group]).size() << " HUH" << '\n';

        if (rep == label[y] + 1) return;
    }
//    cout << "YES" << '\n';
    // gotta change at least 1
    group = label[y] + 1;
    process(x, y, groups[group][0], groups[group][1], groups[group][2]);
}
