#define int long long
const int MX = 2002;
int arr[MX], curcnt[MX], tmpcnt[MX];
int32_t main() {
	ios::sync_with_stdio(0);cin.tie(0);
	int n;
	cin >> n;
	for(int i=0; i<3*n; i++) {
		cin >> arr[i];
	}
	vector<int> cur;
	auto put = [&](int t) {
		curcnt[t]++;
		cur.push_back(t);
	};
	auto remove = [&](int t) {
		curcnt[t]--;
		cur.erase(find(cur.begin(), cur.end(), t));
	};
	put(arr[0]);
	put(arr[1]);
	int ans = 0;
	for(int t=0; t<n-1; t++) {
		for(int i=0; i<3; i++) {
			put(arr[2+t*3+i]);
		}
		//assert(cur.size() == 5);
		vector<int> toerase;
		for(int i=1; i<=n; i++) {
			if(curcnt[i] >= 3) {
				for(int x=0; x<3; x++) {
					remove(i);
				}
				ans++;
				goto end;
			}
		}
		memset(tmpcnt, 0, sizeof tmpcnt);
		toerase = cur;
		for(int i=2+t*3+3; i<n; i++) {
			tmpcnt[i]++;
			if(curcnt[i] && curcnt[i] + tmpcnt[i] >= 3) {
				int k = curcnt[i];
				while(k && toerase.size() > 3) {
					toerase.erase(find(toerase.begin(), toerase.end(), i));
					k--;
				}
			}
			if(toerase.size() == 3)
				break;
		}
		while(toerase.size() > 3)
			toerase.pop_back();
		for(int er: toerase) {
			remove(er);
		}
		end:;
		//assert(cur.size() == 2);
	}
	put(arr[3*n-1]);
	sort(cur.begin(), cur.end());
	if(cur.front() == cur.back())
		ans++;
	cout << ans;
}

