		if(nb==nc) for(int j=1;j<=n;j++) v.pb(mp(mp(j,na),dp[nb][j]+1));
		v.pb(mp(mp(na,nb),dp[nc][nc]+1)); 
		v.pb(mp(mp(nb,nc),dp[na][na]+1));
		v.pb(mp(mp(na,nc),dp[nb][nb]+1)); 
