// i, j are indices of last cards taken, j came from the previous group processed
// to figure out which group index i is in, do (i + 1) / 3
// to access elements of group k, check indices 3 * k - 1, 3 * k, 3 * k + 1
int n, a[6005], dp[6005][6005], nxt[2005][2005], pref[2005];

bool has(int group, int val) {
    int l = max(3 * group - 1, 0), r = min(3 * group + 1, 3 * n - 1);
    for (int i=l; i<=r; i++)
        if (a[i] == val)
            return true;
    return false;
}

bool complete(int group) {
    if (group == n)
        return false;
    int l = 3 * group - 1, r = 3 * group + 1;
    return a[l] == a[r] && a[l] == a[l+1];
}

vector<array<int, 3>> check(int i, int j, int group) {
    if (group == n)
        return {{i, 3 * n - 1, a[i] == a[j] && a[i] == a[3*n-1]}};
    vector<array<int, 3>> ret;
    int l = 3 * group - 1, r = 3 * group + 1;
    // swap index i with something in group
    for (int k=l; k<=r; k++) {
        bool ok = true;
        for (int m=l; m<=r; m++)
            ok &= (m == k || (m != k && a[m] == a[i]));
        ret.push_back({j, k, ok});
    }
    // swap index j with something in group
    for (int k=l; k<=r; k++) {
        bool ok = true;
        for (int m=l; m<=r; m++)
            ok &= (m == k || (m != k && a[m] == a[j]));
        ret.push_back({i, k, ok});
    }
    // swap both with other pair in group
    for (int k=l; k<=r; k++)
        for (int m=k+1; m<=r; m++) {
            bool ok = (a[i] == a[j] && a[i] == a[l != k && l != m ? l : r != k && r != m ? r : l + 1]);
            ret.push_back({k, m, ok});
        }
    return ret;
}

int solve(int i, int j) {
    int group = (j + 1) / 3;
    if (group == n) {
        // we are at the final group
        return 0;
    }
    if (dp[i][j] != -1)
        return dp[i][j];
    dp[i][j] = 0;
    // case 1: make swap(s) with next group
    vector<array<int, 3>> pos = check(i, j, group + 1);
    for (auto &p : pos)
        dp[i][j] = max(dp[i][j], solve(p[0], p[1]) + p[2]);
    // case 2: make swap with group containing next occurrence of i
    if (nxt[group + 1][a[i]] != -1) {
        pos = check(i, j, nxt[group + 1][a[i]]);
        for (auto &p : pos)
            dp[i][j] = max(dp[i][j], solve(p[0], p[1]) + p[2] + pref[nxt[group + 1][a[i]] - 1] - pref[group]);
    }
    // case 3: make swap with group containing next occurrence of j
    if (nxt[group + 1][a[j]] != -1) {
        pos = check(i, j, nxt[group + 1][a[j]]);
        for (auto &p : pos)
            dp[i][j] = max(dp[i][j], solve(p[0], p[1]) + p[2] + pref[nxt[group + 1][a[j]] - 1] - pref[group]);
    }
    return dp[i][j];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    cin >> n;
    for (int i=0; i<3*n; i++)
        cin >> a[i];

    for (int j=1; j<=n; j++)
        nxt[n][j] = -1;
    for (int i=n-1; i>=0; i--)
        for (int j=1; j<=n; j++)
            nxt[i][j] = (has(i + 1, j) ? i + 1 : nxt[i+1][j]);

    for (int i=1; i<=n; i++)
        pref[i] = pref[i-1] + complete(i);

    memset(dp, -1, sizeof(dp));
    cout << solve(0, 1) << "\n";

    return 0;
}

