            mp[ara[i]] = ++id;
        }
    }
    FOR(i,1,3 * n)ara[i] = mp[ara[i]];

    int lo = 1 , hi = n , mid , ans;
    while(lo <= hi){
        mid = (lo + hi) >> 1;
        MEM(cnt,0);

        FOR(i,1,3 * n){
            if(ara[i] <= mid){
                cnt[ara[i]]++;
                if(cnt[ara[i]] == 3)loc[i] = 1;
            }
        }
        int save = 0,f = 0;
        for(int i = 1;i <= 5;i++){
            if(ara[i] <= mid)save++;
            if(loc[i] == 1)f = 1;
        }
        if(f)save = save - 3;

        if(save > 2){
            hi = mid - 1;
            continue;
        }

        bool ok = 1;
        int done = 5;
        for(int i = 8;i <= 3 * n;i += 3){
            bool found = 0;
            for(int j = done + 1;j <= i;j++){
                if(ara[j] <= mid)save++;
                if(loc[j] == 1)found = 1;
            }
            if(found){
                save = save - 3;
