pii p2(int a, int b){
    if(a<b) swap(a,b);
    return make_pair(a,b);
}

int solve(){
    vector<map<pii, int > > dp;
    dp.resize(3*N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[2][p2(A[0], A[1])] = 0;
    int i = 2;
    while(i<(3*N-1)){
        if(A[i]==A[i+1] && A[i+1]==A[i+2]){
            dp[i+3] = dp[i];
            for(auto &[p,c]:dp[i+3]){
                c++;
            }
        }
        else{
            vector<int> vec;
            vec.push_back(A[i]);
            vec.push_back(A[i+1]);
            vec.push_back(A[i+2]);
            for(auto [p,c]:dp[i]){
                int a = p.first;
                int b = p.second;
                // if(a<b) continue;
                vector<int> combi = vec;
                combi.push_back(a);
                combi.push_back(b);
                // sort(combi.begin(),combi.end());
                map<int ,int > cnt;
                for(auto c:combi) cnt[c]++;
                auto cnt_max = *max_element(cnt.begin(),cnt.end(),[](pii a, pii b){return a.second < b.second;});
                if(cnt_max.second>=3){
                    vector<int> mp;
                    for(auto c:combi) {
                        if(c!=cnt_max.first){
                            mp.push_back(c);
                        }
                    }
                    if(mp.size()==0){
                        mp.push_back(cnt_max.first);
                        mp.push_back(cnt_max.first);
                    }
                    else if(mp.size()==1){
                        mp.push_back(cnt_max.first);
                    }
                    // sort(mp.begin(),mp.end(),greater<int>());
                    dp[i+3][p2(mp[0], mp[1])] = c+1;
                }
                else{
                    dp[i+3] = dp[i];
                    dp[i+3][p2(vec[0], vec[1])] = c;
                    dp[i+3][p2(vec[0], vec[2])] = c;
                    dp[i+3][p2(vec[1], vec[2])] = c;

                    dp[i+3][p2(a, vec[0])] = c;
                    dp[i+3][p2(a, vec[1])] = c;
                    dp[i+3][p2(a, vec[2])] = c;

                    dp[i+3][p2(b, vec[0])] = c;
                    dp[i+3][p2(b, vec[1])] = c;
                    dp[i+3][p2(b, vec[2])] = c;
                }
            }
        }
        dp[i].clear();
        i += 3;
    }
    int ans = 0;
    for(auto [p,c]:dp[3*N-1]){
        int a = p.first;
        int b = p.second;
        if((a==b) && (b==A[3*N-1])) ans = max(ans, c + 1);
        else ans = max(ans, c);
    }
    cout << ans << endl;
    return 0;
} 

