int dp[2048][2048];

void solve() {
  int N;
  in(N);
  vi A(3 * N);
  in(A);
  each(x, A) x--;
  int ans = 0;

  vvi memo(N);
  vp v1;
  using ar = array<int, 3>;
  V<ar> v2;
  auto idx = [&](int i) { return (i + 1) / 3; };
  rep(i, 3 * N) {
    int a = A[i];
    memo[a].push_back(i);
    if (sz(memo[a]) >= 3) {
      int s = sz(memo[a]);
      if (idx(memo[a][s - 1]) == idx(memo[a][s - 3])) {
        ans++;
        rep(_, 3) memo[a].pop_back();
        continue;
      }
      if (idx(memo[a][s - 1]) == idx(memo[a][s - 2])) {
        v1.eb(idx(memo[a][s - 3]), idx(memo[a].back()));
      } else
        v2.push_back(
            {idx(memo[a][s - 3]), idx(memo[a][s - 2]), idx(memo[a][s - 1])});
    }
  }

  std::sort(all(v1), [](P a, P b) { return a.second < b.second; });
  rep(i, N + 1) {
    int l = i;
    rep(r, l) dp[i][r] = -10000;
    int cnt = 0;
    int n = 0;
    while (1) {
      trc(i, l, n, cnt);
      while (n != sz(v1) && l > v1[n].first) n++;
      if (n == sz(v1)) {
        int r = N + 1;
        trc(r);
        reg(j, l, r) dp[i][j] = cnt;
        break;
      }
      int r = v1[n].second;
      reg(j, l, r) dp[i][j] = cnt;
      l = r;
      cnt++;
      n++;
    }
  }

  trc(v1);
  rep(i, 3) rep(j, 3) trc(dp[i][j]);

  std::sort(all(v2), [](ar a, ar b) { return a[0] < b[0]; });
  vi bns(N + 1, 0);
  each(x, v2) {
    auto [s, t, u] = x;
    trc(s, t, u, bns[s], dp[s][t]);
    amax(bns[u], bns[s] + dp[s][t] + 1);
  }
  int cns = *max_element(all(bns));
  out(ans + cns);
}

