			a.pop_back();
			++cnt[now];
			++bcnt[now];
		}

		int cand = -1;
		int candpri = -1;

		for (auto& j : b) {
			int v = j.F;
			int app = j.S;

			if (cnt[v] >= 3) {
				bool is = 0;
				int pri = -1;

				if (app >= 3) {
					is = 1;
					pri = 4;
				}
				else if (app == 2) {
					is = 1;
					if (bcnt[v] >= 3) {
						pri = 3;
					} else {
						pri = 2;
					}
				}
				else if (app == 1) {
					if (bcnt[v] >= 2) {
						is = 1;
						pri = 1;
					}
				}

				if (!is) continue;

				if (cand == -1) {
					cand = v;
					candpri = pri;
				}
				else if (app > candpri) {
					cand = v;
					candpri = pri;
				}
			}
		}

		auto resetc = [&]() {
//			W("RESET");
			for (auto& j : cnt)
				j = 0;
		};
		auto resetbc = [&]() {
//			W("BLOCK");
			for (auto& j : bcnt)
				j = 0;
		};

//		W(cand, candpri);
//		W(cnt);
//		W(bcnt);

		if (cand != -1) {
			ans++;
			cnt[cand] -= 3;
			bcnt[cand] -= 3;

			if (candpri == 3) {
				resetbc();

				for (auto& j : b)
					if (j.F != cand)
						bcnt[j.F]++;
			}
			else if (candpri == 2) {
				cnt = bcnt;
				resetbc();

				for (auto& j : b)
					if (j.F != cand)
						bcnt[j.F]++;
			}
			else if (candpri == 1) {
				resetc();
				resetbc();

				for (auto& j : b)
					if (j.F != cand) {
						cnt[j.F] += j.S;
						bcnt[j.F] += j.S;
					}
			}
		}
	}

	W(ans);

	return 0;
}

