					if (i != j && j != t && t != i) {
						if (x == y) {
							for (int k = 0; k <= n; k++) {
								dp[k][z][curInd] = max(dp[k][z][curInd], dp[k][x][!curInd] + 1);
								dp[z][k][curInd] = max(dp[k][z][curInd], dp[k][x][!curInd] + 1);
							}

						}
						dp[x][y][curInd] = max(dp[x][y][curInd], dp[z][z][!curInd] + 1);
						dp[y][x][curInd] = max(dp[x][y][curInd], dp[z][z][!curInd] + 1);
						mx = max(mx, dp[x][y][curInd]);
					}
				}
			}
		}
	}


