        rep (j, 3) {
            ll discard = as[j];
            ll remain0 = as[(j+1)%3];
            ll remain1 = as[(j+2)%3];
            ll newval = max(cnts[discard][discard] + 1LL, allmax);
            f_updated(remain0, remain1, newval);
        }

        rep (j, 3) {
            ll remain = as[j];
            ll discard0 = as[(j+1)%3];
            ll discard1 = as[(j+2)%3];
            rep (b, 2005) f_updated(remain, b, maxcnts[b]);
            if (discard0 == discard1) {
