            int a = v[0], b = v[2];
            int tmp = dp[b][b];
            for (int f = 0; f < N; ++f) {
                chmax(dp[b][f], dp[a][f] + 1);
                chmax(dp[f][b], dp[a][f] + 1);
            }
            chmax(dp[a][a], tmp + 1);
        }
        else if (v[0] < v[1] && v[1] == v[2]) {
            int a = v[2], b = v[0];
            int tmp = dp[b][b];
            for (int f = 0; f < N; ++f) {
                chmax(dp[b][f], dp[a][f] + 1);
                chmax(dp[f][b], dp[a][f] + 1);
            }
            chmax(dp[a][a], tmp + 1);
        }
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (i == j) continue;
                chmax(dp[v[i]][v[j]], 0);
            }
            for (int f = 0; f < N; ++f) {
                chmax(dp[v[i]][f], 0);
                chmax(dp[f][v[i]], 0);
            }
        }
/*
        cout << "-----------" << endl;
        COUT(v);
        for (int a = 0; a < N; ++a) {
            for (int b = a; b < N; ++b) {
                if (dp[a][b] >= 0) {
                    cout << a << ", " << b << ": " << dp[a][b] << endl;
                }
            }
        }
        */
    }
    int res = 0;
    for (int a = 0; a < N; ++a) {
        for (int b = 0; b < N; ++b) {
            if (a == end && b == end) chmax(res, dp[a][b] + 1);
            else chmax(res, dp[a][b]);
        }
    }
    return res + offset;
}

