int n;
vi nums;
vector<vector<vi>> dp;

int solve(int p, int a, int b) {
	//cout << p << " " << a << " " << b << endl;
	if (p == n-1) {
		return nums[p] == a and a == b;
	}
	if (dp[p][a][b] != -1) return dp[p][a][b];

	vi o;
	if (p == 0) for_(i, 0, 5) o.push_back(nums[i]);
	else {
		o.push_back(a); o.push_back(b);
		for_(i, 0, 3) o.push_back(nums[p+1]);
	}

	sort(o.begin(), o.end());
	int found = -1;
	for_(i, 0, 3) if (o[i] == o[i+1] and o[i] == o[i+2]) {
		found = o[i];
		break;
	}

	int ans = -1, nxt = p + (p == 0 ? 5 : 3);

	if (found != -1) {
		int rema = -1, remb = -1;
		for (int i: o) if (i != found) {
			if (rema == -1) rema = i;
			else remb = i;
		}

		ans = 1 + solve(nxt, rema, remb);
	} else {
		for_(rema, 0, 5) for_(remb, rema+1, 5) {
			ans = max(ans, solve(nxt, rema, remb));
		}
	}

	dp[p][a][b] = ans;
	return ans;
}

