int N, A[6005];

int solve(){
	int ans = 0;
	vector<vector<int>> dp(N+1, vector<int>(N+1, -1));
	int all = 0;
	dp[min(A[0], A[1])][max(A[0], A[1])] = 0;
	vector<int> vis(N+1, 0);
	int j = 0;
	for(int i=2; i<N*3; i+=3){
		while(j < i){
			vis[A[j]]=1;
			j++;
		}

		if(A[i] == A[i+1] && A[i] == A[i+2]){
			all++;
			continue;
		}

		vector<int> cs = {A[i], A[i+1], A[i+2]};
		sort(cs.begin(), cs.end());

		if(cs[0] == cs[1]){
			int t = cs[0], a = cs[2];
			int tmp = dp[a][a];
			for(int b=1; b<=N; b++){
				int p = dp[min(t,b)][max(t, b)];
				dp[min(a, b)][max(a,b)] = max(dp[min(a,b)][max(a,b)], p>=0 ? p + 1 : -1);
			}
			dp[t][t] = max(dp[t][t], tmp >= 0 ?  tmp + 1 : -1);
			dp[t][t] = max(dp[t][t], 0);
			dp[t][a] = max(dp[t][a], 0);
			for(int b=1; b <= N; b++){
				if(vis[b] == 0) continue;
				dp[min(t,b)][max(t,b)] = max(dp[min(t,b)][max(t,b)] , 0);
				dp[min(a,b)][max(a,b)] = max(dp[min(a,b)][max(a,b)] , 0);
			}
			continue;
		}

		if(cs[1] == cs[2]){
			int t = cs[1], a = cs[0];
			int tmp = dp[a][a];
			for(int b=1; b<=N; b++){
				int p = dp[min(t,b)][max(t, b)];
				dp[min(a, b)][max(a,b)] = max(dp[min(a,b)][max(a,b)], p>=0 ? p + 1 : -1);
			}
			dp[t][t] = max(dp[t][t], tmp >= 0 ?  tmp + 1 : -1);
			dp[t][t] = max(dp[t][t], 0);
			dp[a][t] = max(dp[a][t], 0);

			for(int b=1; b <= N; b++){
				if(vis[b] == 0) continue;
				dp[min(t,b)][max(t,b)] = max(dp[min(t,b)][max(t,b)] , 0);
				dp[min(a,b)][max(a,b)] = max(dp[min(a,b)][max(a,b)] , 0);
			}
			continue;
		}

		int a = cs[0], b = cs[1], c = cs[2];
		dp[a][b] = max(dp[a][b], dp[c][c] >= 0 ? dp[c][c] + 1 : -1);
		dp[a][b] = max(dp[a][b], 0);
		dp[b][c] = max(dp[b][c], dp[a][a] >= 0 ? dp[a][a] + 1 : -1);
		dp[b][c] = max(dp[b][c], 0);
		dp[a][c] = max(dp[a][c], dp[b][b] >= 0 ? dp[b][b] + 1 : -1);
		dp[a][c] = max(dp[a][c], 0);


	}

	for(int a=1; a<=N; a++){
		for(int b=1; b<=N; b++){
			ans = max(ans, dp[a][b]);
		}
	}
	ans = max(ans, dp[0][0]);
	return ans + all;
}


