    vector<set<int> > dp(N);
    dp[a[0]].insert(a[1]);
    dp[a[1]].insert(a[0]);
    int ans = 0;
    bitset<2000> keep;
    for(int i = 2; i + 2 < N * 3; i += 3){
        keep = 0;
        if(a[i] == a[i + 1] && a[i + 1] == a[i + 2]){
            ++ans;
            continue;
        }
        bool plus = false, swapped = false;
        if(a[i + 1] == a[i + 2]){
            swapped = true;
            swap(a[i], a[i + 2]);
        }
        if(a[i] == a[i + 1]){
            bool after = dp[a[i + 2]].find(a[i + 2]) != dp[a[i + 2]].end();
            if(!dp[a[i]].empty()){
                dp[a[i + 2]] = dp[a[i]];
                keep[a[i + 2]] = true;
            }
            plus = after | keep[a[i + 2]];
            rep(j, N) if(!keep[j]) dp[j].clear();
            for(int c : dp[a[i + 2]]) dp[c].insert(a[i + 2]);
            if(after) dp[a[i]].insert(a[i]);
        }else{
            rep(k, 3){
                if(dp[a[i + k]].find(a[i + k]) != dp[a[i + k]].end()){
                    plus = true;
                    keep[a[i + k]] = true;
                }
            }
            rep(j, N){
                if(keep[j]){
                    rep(k, 3) dp[j].insert(a[i + k]);
                    dp[j].erase(j);
                }else{
                    dp[j].clear();
                }
            }
        }
        if(swapped) swap(a[i], a[i + 2]);

        ans += plus;
        if(!plus){
            rep(j, N) keep[j] = !dp[j].empty();
            rep(j, N) rep(k, 3) {
                dp[j].insert(a[i + k]);
                if(keep[j]) dp[a[i + k]].insert(j);
            }
        }
    }
    int la = *a.rbegin();
    ans += (dp[la].find(la) != dp[la].end());
    cout<<ans<<endl;
}

