          }
        }
        continue;
      }
    }
    if (equality == 1) {
      const int single = (a == b) ? c : ((b == c) ? a : b);
      const int pair = (a == b) ? a : c;
      const bool single_ok = counts[single] == 2;
      const bool pair_ok = counts[pair] >= 1;
      if (single_ok || pair_ok) {
        ++score;
        if (pair_ok) {
