        }
        if (pair_ok) {
          ++counts[single];
        }
        if (single_ok) {
          counts[pair] = 2;
        }
        continue;
      }
    }
    for (const auto n : {a, b, c}) {
      ++counts[n];
    }
  }
  score += counts[A.back()] == 2;
  std::cout << score << std::endl;
  return 0;
}

