int naive(istream& cin, ostream& cout) {

  ll N; cin >> N;
  vector<ll> A(3*N);
  for (ll i = 0; i < 3 * N; i++) {
    ll a; cin >> a; a--;
    A[i] = a;
  }

  auto dfs = [&](auto rF, ll dep, ll p, ll q, ll acc) -> ll {
    if (dep == N-1) {
      if (p == q && p == A[3*N - 1]) return acc + 1;
      else return acc;
    }
    IntComb ic(5, 2);
    vector vec({p, q, A[3*dep + 2], A[3*dep + 3], A[3*dep + 4]});
    const vector<int>& v = ic.get();
    ll ret = 0;
    do {
      vector<int> chosen(v);
      sort(chosen.begin(), chosen.end());
      ll prev = -1;
      vector<ll> pass;
      ll idx = 0;
      int fail = 0;
      for (ll j = 0; j < 5; j++) {
	if (idx < 2 && chosen[idx] == j) {
	  pass.push_back(vec[j]);
	  idx++;
	}else {
	  if (prev == -1) {
	    prev = vec[j];
	  }else if (prev != vec[j]) {
	    fail = 1;
	  }
	}
      }
      ll t = rF(rF, dep + 1, pass[0], pass[1], acc + (1 - fail));
      updMax(ret, t);
    }while (ic.next());
    return ret;
  };
  ll ans = dfs(dfs, 0, A[0], A[1], 0);
  cout << ans << endl;
  return 0;
}
int body(istream& cin, ostream& cout) {

  ll N; cin >> N;
  vector<ll> A(3*N);
  for (ll i = 0; i < 3 * N; i++) {
    ll a; cin >> a; a--;
    A[i] = a;
  }
  ll big = 1e9;
  ll tbl0 = -big;
  vector tbl1(N, -big);
  vector __tbl2(N, vector(N, -big));
  auto tbl2 = [&](ll p, ll q) -> ll& {
    if (p > q) swap(p, q);
    return __tbl2[p][q];
  };

  tbl2(A[0], A[1]) = 0;
  tbl1[A[0]] = 0;
  tbl1[A[1]] = 0;
  tbl0 = 0;

  ll threeC = 0;
  using sta = tuple<ll, ll, ll>;
  //               (newval, arg1, arg2)
  for (ll i = 0; i < N-1; i++) {
    vector<sta> updates;
    ll p = A[3*i + 2], q = A[3*i + 3], r = A[3*i + 4];
    if (p == q && q == r) {
      threeC++;
      continue;
    }
    if (p == q || q == r || p == r) {
      ll a, b;
      if      (p == q) { a = p; b = r; }
      else if (q == r) { a = q; b = p; }
      else if (p == r) { a = p; b = q; }
      else    assert(0);
      for (ll z = 0; z < N; z++) {
	ll newval = tbl2(a, z) + 1;
	updates.emplace_back(newval, z, b);
	/*
	updates.emplace_back(newval, z, -1);
	updates.emplace_back(newval, b, -1);
	updates.emplace_back(newval, -1, -1);
	*/
      }
    }
    for (ll j = 0; j < 3; j++) {
      ll s = A[3*i + 2 + j];
      ll t = A[3*i + 2 + ((j + 1) % 3)];
      ll u = A[3*i + 2 + ((j + 2) % 3)];;
      ll newval = tbl2(s, s) + 1;
      updates.emplace_back(newval, t, u);
      /*
      updates.emplace_back(newval, t, -1);
      updates.emplace_back(newval, u, -1);
      updates.emplace_back(newval, -1, -1);
      */
    }
    for (ll z = 0; z < N; z++) {
      for (ll j = 0; j < 3; j++) {
	ll s = A[3*i + 2 + j];
	updates.emplace_back(tbl1[z], s, z);
	/*
	updates.emplace_back(tbl1[z], s, -1);
	*/
      }
    }
    updates.emplace_back(tbl0, p, q);
    updates.emplace_back(tbl0, q, r);
    updates.emplace_back(tbl0, p, r);
    /*
    updates.emplace_back(tbl0, p, -1);
    updates.emplace_back(tbl0, q, -1);
    updates.emplace_back(tbl0, r, -1);
    */

    for (auto [val, a1, a2] : updates) {
      /*
      if      (a1 < 0) updMax(tbl0, val);
      else if (a2 < 0) updMax(tbl1[a1], val);
      else             updMax(tbl2(a1, a2), val);
      */
      if (a1 <= a2) updMax(__tbl2[a1][a2], val);
      else          updMax(__tbl2[a2][a1], val);
	// updMax(tbl2(a1, a2), val);
      updMax(tbl1[a1], val);
      updMax(tbl1[a2], val);
      updMax(tbl0, val);
    }
    DLOG("tbl0=", tbl0);
    DLOG("tbl1=", tbl1);
    DLOG("tbl2=", __tbl2);
  }
  ll p = A[3*N - 1];
  updMax(tbl0, tbl2(p, p) + 1);
  tbl0 += threeC;
  cout << tbl0 << endl;

  return 0;
}

