  auto settbl = [&](ll p, ll q, ll mark) -> void {
    if (p > q) swap(p, q);
    tbl2[p][q] = mark;
  };
  auto gettbl = [&](ll p, ll q) -> ll {
    if (p > q) swap(p, q);
    return tbl2[p][q];
  };

  settbl(A[0], A[1], 0);
  ll threeC = 0;
  using sta = tuple<ll, ll, ll>;
  //               (newval, arg1, arg2)
  for (ll i = 0; i < N-1; i++) {
    vector<sta> updates;
    ll p = A[3*i + 2], q = A[3*i + 3], r = A[3*i + 4];
    if (p == q && q == r) {
      threeC++;
      continue;
    }
    if (p == q || q == r || p == r) {
      ll a, b;
      if      (p == q) { a = p; b = r; }
      else if (q == r) { a = q; b = p; }
      else if (p == r) { a = p; b = q; }
      else    assert(0);
      for (ll z = 0; z < N; z++) {
	ll newval = gettbl(a, z) + 1;
	updates.emplace_back(newval, z, b);
	updates.emplace_back(newval, z, -1);
	updates.emplace_back(newval, b, -1);
	updates.emplace_back(newval, -1, -1);
      }
    }
    for (ll j = 0; j < 3; j++) {
      ll s = A[3*i + 2 + j];
      ll t = A[3*i + 2 + ((j + 1) % 3)];
      ll u = A[3*i + 2 + ((j + 2) % 3)];;
      ll newval = gettbl(s, s) + 1;
      updates.emplace_back(newval, t, u);
      updates.emplace_back(newval, t, -1);
      updates.emplace_back(newval, u, -1);
      updates.emplace_back(newval, -1, -1);
    }
    for (ll z = 0; z < N; z++) {
      for (ll j = 0; j < 3; j++) {
	ll s = A[3*i + 2 + j];
	updates.emplace_back(tbl1[z], s, z);
      }
    }
    updates.emplace_back(tbl0, p, q);
    updates.emplace_back(tbl0, q, r);
    updates.emplace_back(tbl0, p, r);

    for (auto [val, a1, a2] : updates) {
      if      (a1 < 0)               updMax(tbl0, val);
      else if (a2 < 0)               updMax(tbl1[a1], val);
      else if (gettbl(a1, a2) < val) settbl(a1, a2, val);
    }
  }
  ll p = A[3*N - 1];
  updMax(tbl0, gettbl(p, p) + 1);
  tbl0 += threeC;
  cout << tbl0 << endl;

  return 0;
}

