		}else{
			if(a[i]==a[i+1])swap(a[i],a[i+2]);
			else if(a[i]==a[i+2])swap(a[i],a[i+1]);
			if(a[i+1]==a[i+2]){
				if(!cnt[a[i+1]] && !cnt[a[i]]){
