ll a[10000];
void solve(){
	ll n,res=0;
	cin>>n;
	for(ll i=1;i<=3*n;i++)
		cin>>a[i];
	vector<ll> v;
	v.push_back(a[1]),v.push_back(a[2]);
	for(ll i=3;i<=3*n;i+=3){
		map<ll,ll> m,st;
		m[v[0]]++,m[v[1]]++;
		for(ll j=i;j<=min(i+2,3*n);j++)
			m[a[j]]++;
		v.clear();
		ll f=0;
		for(auto it=m.begin();it!=m.end();it++){
			if(it->second>=3){
				f=1,res++;
				it->second-=3;
				if(!it->second)
					m.erase(it);
				break;
			}
			st.insert({it->first,0});
		}
		if(f){
			for(auto it=m.begin();it!=m.end();it++){
				while(it->second){
					v.push_back(it->first);
					it->second--;
				}
			}
			continue;
		}
		if(i==3*n)
			break;
		for(ll j=i+3;j<=3*n;j++)
			if(st.find(a[j])!=st.end())
				st[a[j]]++;
		for(auto it=st.begin();it!=st.end();it++)
			it->second%=3;
		for(auto it=m.begin();it!=m.end();it++)
			if(it->second==2&&st[it->first]==1){
				v.push_back(it->first);
				v.push_back(it->first);
				f=1;
			}
		if(f)
			continue;
		vector<ll> g;
		for(auto it=st.begin();it!=st.end();it++)
			if(st[it->first]==2){
				g.push_back(it->first);
				m[it->first]--;
				if(!m[it->first])
					m.erase(it->first);
			}
		while(!g.empty()&&sz(v)<2){
			v.push_back(g.back());
			g.pop_back();
		}
		while(sz(v)<2){
			v.push_back(m.begin()->first);
			m.begin()->second--;
			if(!m.begin()->second)
				m.erase(m.begin());
		}
	}
	cout<<res;
}
