            threes++;
        }
        else{ 
            //2枚同じ
            if (buffer[0] == buffer[1]) {
                ll p = buffer[0];
                ll k = buffer[2];
                for (int j = 0; j < n; j++) {                    
                    chmax(dp[j][k], dp[p][j] + 1);
                    chmax(dp[j][k], dp[j][p] + 1);
                }
            }
