                for (int j = 0; j < n; j++) {
                    chmax(dp[j][k], dp[p][j] + 1);
                    chmax(dp[j][k], dp[j][p] + 1);
                }
            }
            else {
                //3枚ばらばら
                ll p = buffer[0];
                ll k = buffer[1];
                ll l = buffer[2];
                for (int j = 0; j < n; j++) {
                    chmax(dp[k][l], dp[p][p] + 1);
                }
            }            
        }
