int solve(){
    vector<map<int, map<int, int> > > dp;
    dp.resize(N+1);
    // if(A[0]<A[1]) swap(A[0], A[1]);
    dp[1][A[0]][A[1]] = 0;
    dp[1][A[1]][A[0]] = 0;
    int dp_max = 0;
    vector<int> dp_maxk(N+1,0);
    for(int i = 1; i < N; i++){
        if(A[3*i-1]==A[3*i] && A[3*i]==A[3*i+1]){
            dp[i+1] = dp[i];
            for(auto &[p,mp]:dp[i+1]){
                for(auto &[x,c]:mp){
                    c++;
                    chmax(dp_max,c);
                    chmax(dp_maxk[x],c);
                    chmax(dp_maxk[p],c);
                }
            }
        }
        else if(A[3*i-1]==A[3*i] || A[3*i]==A[3*i+1] || A[3*i+1]==A[3*i-1]){
            int p, q;
            if(A[3*i-1]==A[3*i]){
                p = A[3*i-1];
                q = A[3*i+1];
            }
            else if(A[3*i]==A[3*i+1]){
                p = A[3*i];
                q = A[3*i-1];
            }
            else if(A[3*i+1]==A[3*i-1]){
                p = A[3*i+1];
                q = A[3*i];
            }
            else{
                p = 0, q = 0;
            }
            dp[i+1] = dp[i];
            chmax(dp[i+1][p][p], dp_max);
            chmax(dp[i+1][p][q], dp_max);
            chmax(dp[i+1][q][p], dp_max);
            chmax(dp_maxk[p],dp[i+1][p][p]);
            chmax(dp_maxk[p],dp[i+1][p][q]);
            chmax(dp_maxk[q],dp[i+1][p][q]);

            if(dp[i].find(p)!=dp[i].end()){
                for (int k = 1; k <= N; k++)
                {
                    if(dp[i][p].find(k)!=dp[i][p].end()){
                        chmax(dp[i+1][k][q], dp[i][p][k] + 1);
                        chmax(dp[i+1][q][k], dp[i][p][k] + 1);
                        chmax(dp_max, dp[i+1][k][q]);
                        chmax(dp_max, dp[i+1][q][k]);
                        chmax(dp_maxk[k], dp[i+1][q][k]);
                        chmax(dp_maxk[q], dp[i+1][q][k]);
                    }
                }
            }

            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()){
                    chmax(dp[i+1][p][p], dp[i][q][q] + 1);
                    chmax(dp_max, dp[i+1][p][p]);
                    chmax(dp_maxk[p], dp[i+1][p][p]);
                }
            }

        }
        else{
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];

            dp[i+1] = dp[i];
            chmax(dp[i+1][p][q], dp_max);
            chmax(dp[i+1][q][p], dp_max);
            chmax(dp[i+1][q][r], dp_max);
            chmax(dp[i+1][r][q], dp_max);
            chmax(dp[i+1][r][p], dp_max);
            chmax(dp[i+1][p][r], dp_max);


            for (int k = 1; k <= N; k++)
            {
                if(dp[i].find(k)!=dp[i].end()){
                    chmax(dp[i+1][p][k], dp_maxk[k]);
                    chmax(dp[i+1][q][k], dp_maxk[k]);
                    chmax(dp[i+1][r][k], dp_maxk[k]);
                    chmax(dp[i+1][k][p], dp_maxk[k]);
                    chmax(dp[i+1][k][q], dp_maxk[k]);
                    chmax(dp[i+1][k][r], dp_maxk[k]);
                }
            }            

            if(dp[i].find(p)!=dp[i].end()) {
                if(dp[i][p].find(p)!=dp[i][p].end()) {
                    chmax(dp[i+1][q][r], dp[i][p][p] + 1);
                    chmax(dp[i+1][r][q], dp[i][p][p] + 1);
                    chmax(dp_max, dp[i+1][q][r]);
                    chmax(dp_max, dp[i+1][r][q]);
                    chmax(dp_maxk[r], dp[i+1][r][q]);
                    chmax(dp_maxk[q], dp[i+1][r][q]);
                }
            }
            if(dp[i].find(q)!=dp[i].end()) {
                if(dp[i][q].find(q)!=dp[i][q].end()) {
                    chmax(dp[i+1][p][r], dp[i][q][q] + 1);
                    chmax(dp[i+1][r][p], dp[i][q][q] + 1);
                    chmax(dp_max, dp[i+1][p][r]);
                    chmax(dp_max, dp[i+1][r][p]);
                    chmax(dp_maxk[r], dp[i+1][r][p]);
                    chmax(dp_maxk[p], dp[i+1][r][p]);
                }
            }
            if(dp[i].find(r)!=dp[i].end()) {
                if(dp[i][r].find(r)!=dp[i][r].end()) {
                    chmax(dp[i+1][p][q], dp[i][r][r] + 1);
                    chmax(dp[i+1][q][p], dp[i][r][r] + 1);
                    chmax(dp_max, dp[i+1][p][q]);
                    chmax(dp_max, dp[i+1][q][p]);
                    chmax(dp_maxk[p], dp[i+1][q][p]);
                    chmax(dp_maxk[q], dp[i+1][q][p]);
                }
            }
        }
        dp[i].clear();
    }
    int ans = 0;
    for(auto [a,mp]:dp[N]){
        for(auto [b,c]:mp){
            if((a==b) && (b==A[3*N-1])) ans = max(ans, c + 1);
            else ans = max(ans, c);
        }
    }
    cout << ans << endl;
    return 0;
} 

