int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    V<int> a(3 * n);
    for (int i = 0; i < 3 * n; i++) cin >> a[i];

    if (n == 1) {
        if (a[0] == a[1] == a[2]) cout << 1 << '\n';
        else cout << 0 << '\n';
        return 0;
    }

    V<int> sento = {a[0], a[1], a[2], a[3], a[4]};
    int ans = 0;
    for (int i = 5; i < 3 * n; i += 3) {
        sort(ALL(sento));
        if (sento[0] == sento[1] && sento[1] == sento[2]) {
            ans++;
            V<int> tmp = {sento[3], sento[4]};
            sento = tmp;
            for (int j = 0; j < 3; j++) if (i + j < 3 * n) sento.emplace_back(a[i + j]);
        } else if (sento[1] == sento[2] && sento[2] == sento[3]) {
            ans++;
            V<int> tmp = {sento[0], sento[4]};
            sento = tmp;
            for (int j = 0; j < 3; j++) if (i + j < 3 * n) sento.emplace_back(a[i + j]);
        } else if (sento[2] == sento[3] && sento[3] == sento[4]) {
            ans++;
            V<int> tmp = {sento[0], sento[1]};
            sento = tmp;
            for (int j = 0; j < 3; j++) if (i + j < 3 * n) sento.emplace_back(a[i + j]);
        } else {
            map<int, int> cnt;
            for (int j = 0; j < 5; j++) cnt[sento[j]]++;
            map<int, int> dis;
            for (P<int, int> c: cnt) {
                int tmp = 0;
                for (int j = i; j <= 3 * n; j++) {
                    if (a[j] == c.first) tmp++;
                    if (c.second + tmp == 3) dis[c.first] = j;
                }
            }

            sort(ALL(sento), [&](int i, int j) {
                return dis[i] > dis[j];
            });
            V<int> tmp = {sento[3], sento[4]};
            sento = tmp;
            for (int j = 0; j < 3; j++) if (i + j < 3 * n) sento.emplace_back(a[i + j]);
        }
    }
    if (sento[0] == sento[1] && sento[1] == sento[2]) ans++;
    cout << ans << '\n';
    return 0;
}

