typedef pair<int_t, int_t> pi;

#define tr(c, i) for(auto i = (c).begin(); i != (c).end(); i++)
#define pb push_back
#define sz(a) i64((a).size())
#define all(c) (c).begin(), (c).end()
#define REP(s, e, i) for(i=(s); i < (e); ++i)

int main(int argc, char *argv[]) {
  i64 N, i, j, k;
  cin >> N;
  vi A(3*N);
  REP(0, 3*N, i) {
    cin >> A[i];
    A[i]--;
  }

  if(N == 1) {
    if(A[0] == A[1] && A[0] == A[2]) {
      cout << 1 << endl;
    }
    else {
      cout << 0 << endl;
    }
    return 0;
  }

  auto to_idx = [&](const i64 &a, const i64 &b) {
    return a * N + b;
  };
  auto to_pair = [&](const i64 idx) {
    return pi(idx / N, idx % N);
  };

  unordered_map<i64, i64> M;
  // initialize
  REP(0, 5, i) {
    REP(i+1, 5, j) {
      // choice i, j
      i64 idx = to_idx(A[i], A[j]);
      if(M.find(idx) == M.end()) {
	M[idx] = 0;
      }
      i64 val = -1;
      bool same = true;
      REP(0, 5, k) {
	if(k == i || k == j) {
	  continue;
	}
	if(val == -1) {
	  val = A[k];
	}
	else {
	  if(val != A[k]) {
	    same = false;
	    break;
	  }
	}	
      }
      if(same) {
	M[idx] = 1;
      }
    }
  }

  /*
  cerr << "init" << endl;
  for(auto &m: M) {
    pi Av = to_pair(m.first);
    i64 mv = m.second;
    cerr << Av.first << ", " << Av.second << " -> " << mv << endl;
  }
  */

  i64 cur = 5;
  vi B(5);
  unordered_map<i64, i64> M_next;
  while(cur + 2 < 3*N) {
    B[0] = A[cur];
    B[1] = A[cur+1];
    B[2] = A[cur+2];
    for(auto &m: M) {
      pi Av = to_pair(m.first);
      i64 mv = m.second;

      B[3] = Av.first;
      B[4] = Av.first;
      REP(0, 5, i) {
	REP(i+1, 5, j) {
	  // choice i, j
	  i64 idx = to_idx(B[i], B[j]);
	  if(M_next.find(idx) == M_next.end()) {
	    M_next[idx] = 0;
	  }
	  i64 val = -1;
	  bool same = true;
	  REP(0, 5, k) {
	    if(k == i || k == j) {
	      continue;
	    }
	    if(val == -1) {
	      val = B[k];
	    }
	    else {
	      if(val != B[k]) {
		same = false;
		break;
	      }
	    }	
	  }

	  i64 candidate = mv;
	  if(same) {
	    candidate += 1;
	  }
	  M_next[idx] = max(M_next[idx], candidate);
	}
      }
    }

    cur += 3;
    M.swap(M_next);
  }

  i64 ans = 0;
  assert(cur == 3 * N - 1);
  for(auto &m: M) {
    pi Av = to_pair(m.first);
    i64 mv = m.second;
    if(Av.first == Av.second && Av.first == A[cur]) {
      mv += 1;
    }
    ans = max(ans, mv);
  }

  cout << ans << endl;

  return 0;
}

