constexpr int INF = 2e18;
constexpr int MOD = 1e9 + 7;
constexpr int MAXN = 2e5 + 3;

map<pair<int, map<int, int>>, int> dp;

int n;
int arr[MAXN];
int f(int idx, map<int, int> m) {
  if (idx == n)
    return 0;

  pair<int, map<int, int>> p = make_pair(idx, m);
  if (dp.count(p))
    return dp[p];

  ++m[arr[idx]];

  int cnt = 0;
  for (const auto [k, v] : m)
    cnt += v;
  // debug(idx);
  // debug(cnt);
  int &ret = dp[p];
  if (idx == n - 1 && cnt == 3) {
    for (const auto [k, v] : m) {
      ret += v / 3;
      m[k] -= v / 3 * 3;
    }
  }

  if (cnt == 5) {
    for (const auto [k, v] : m) {
      ret += v / 3;
      m[k] -= v / 3 * 3;
    }
    if (ret == 0) {
      int maxx = 0;
      map<int, int> aux = m;
      for (const auto [k1, v1] : m) {
        for (const auto [k2, v2] : m) {
          for (const auto [k3, v3] : m) {
            if (aux.count(k1)) {
              --aux[k1];
              if (aux[k1] == 0)
                aux.erase(k1);

              if (aux.count(k2)) {
                --aux[k2];
                if (aux[k2] == 0)
                  aux.erase(k2);

                if (aux.count(k3)) {
                  --aux[k3];
                  if (aux[k3] == 0)
                    aux.erase(k3);

                  maxx = max(maxx, f(idx + 1, aux));

                  ++aux[k3];
                }
                ++aux[k2];
              }
              ++aux[k1];
            }
          }
        }
      }
      ret += maxx;
    } else {
      ret += f(idx + 1, m);
    }
  } else {
    ret += f(idx + 1, m);
  }

  return ret;
}

