  cnt[xs[0]]++;
  cnt[xs[1]]++;

  int ans = 0;
  REP(k,N-1) {
    int x0 = xs[2 + k*3 + 0];
    int x1 = xs[2 + k*3 + 1];
    int x2 = xs[2 + k*3 + 2];

    if (x0 == x1 && x1 == x2) ++ans;
    else if((x0 == x1) || (x1 == x2) || x0 == x2) {
      int one = x0 ^ x1 ^ x2;
      int two = (x0 + x1 + x2 - one) / 2;

      if (cnt[two] >= 1) {
        ++ans;
        cnt[two] -= 1;
        for(auto & pp : cnt) maxi(pp.SS, 1);
        cnt[one]++;
      }
      else if(cnt[one] >= 2) {
        ++ans;
        cnt.clear();
        cnt[two] = 2;
      }
    }
    else {
      cnt[x0]++;
      cnt[x1]++;
      cnt[x2]++;
      int n = (cnt[x0] >= 3 ? 1 : 0) + (cnt[x1] >= 3 ? 1 : 0) + (cnt[x2] >= 3 ? 1 : 0);

      if (n == 1) {
        ++ans;
        int x = (cnt[x0] >= 3 ? x0 : cnt[x1] >= 3 ? x1 : x2);
        cnt.clear();
        cnt[x0]++;
        cnt[x1]++;
        cnt[x2]++;
        cnt.erase(x);
      }
      else if (n >= 2) {
        ++ans;
        cnt.clear();
        cnt[x0]++;
        cnt[x1]++;
        cnt[x2]++;
      }
    }
  }

  int last = xs[N3-1];
  if(cnt[last] >= 2) ++ans;

  cout << ans << endl;

  return 0;
}

