template<typename T>
void cnt(T x,map<T,ll> y){
  if(y.count(x)){
    ++y[x];
  }else{
    y[x]=1;
  }
}
void solve(long long N, std::vector<long long> A){
  vector<vector<ll>> dp(N+1,vector<ll>(N+1,-INF));
  dp[A[0]][A[1]]=dp[A[1]][A[0]]=0;
  ll cnt=0;
  REP(N-1){
    map<pll,ll> update;
    auto updf=[&update](pll x,ll y){
      if(update.count(x)){
        update[x]=max(update[x],y);
      }else{
        update[x]=y;
      }
    };
    map<ll,ll> m;
    vector<ll> mv;
    For(j,3){
      ll tmp=A[N*i+2+j];
      mv.push_back(tmp);
      if(m.count(tmp)){
        ++m[tmp];
      }else{
        m[tmp]=1;
      }
    }
    bool db=false;
    ll dbl=0,dbr=0;
    for (auto &&j : m)
    {
      if(j.second==3){
        ++cnt;
        break;
      }else if(j.second==2){
        db=true;
        dbl=j.first;
      }else{
        dbr=j.first;
      }
    }
    if(db){
      FOR(k,1,N+1){
        updf(pll(k,dbr),dp[k][dbl]+1);
        updf(pll(dbr,k),dp[k][dbl]+1);
      }
    }
    updf(pll(mv[0],mv[1]),dp[mv[2]][mv[2]]+1);
    updf(pll(mv[1],mv[0]),dp[mv[2]][mv[2]]+1);

    updf(pll(mv[1],mv[2]),dp[mv[0]][mv[0]]+1);
    updf(pll(mv[2],mv[1]),dp[mv[0]][mv[0]]+1);

    updf(pll(mv[0],mv[2]),dp[mv[1]][mv[1]]+1);
    updf(pll(mv[2],mv[0]),dp[mv[1]][mv[1]]+1);
    for (auto &&j : update)
    {
      auto x=j.first.first,y=j.first.second;
      dp[x][y]=max(j.second,dp[x][y]);
    }

  }
  ll ans=0;
  For(i,N+1){
    For(j,N+1){
      if(A.back()==i&&i==j){
        ans=max(ans,dp[i][j]+1);
      }else{
        ans=max(ans,dp[i][j]);
      }
    }
  }
  cout<<ans+cnt<<endl;
}

