int q(int N, vi A) {
  int ans = 0;
  vp v;
  vi used(N * 3);
  vvi memo(N);
  rep(i, sz(A)) {
    if (used[i]) continue;
    memo[A[i]].pb(i);
    if (sz(memo[A[i]]) >= 3) {
      int s = sz(memo[A[i]]);
      int l = memo[A[i]][s - 3];
      int r = memo[A[i]][s - 1];
      if( (l + 1) / 3 == (r + 1) / 3) ans++;
      else v.emplace_back( (l + 1)/ 3,(r + 1) / 3);
    }
  }

  sort(all(v), [](P a, P b) { return a.second < b.second; });

  int R = -1;
  rep(i, sz(v)) {
    while (i != sz(v) and R >= v[i].first) i++;
    if (i == sz(v)) break;
    ans++;
    R = v[i].second;
  }

  return ans;
}

void solve() {
  int N;
  in(N);
  vi A(3 * N);
  in(A);
  each(x, A) x--;
  int ans = 0;

