#define umx(i,j) ((i)=max(i,j))
int n,a[N*3],dp2,dp1[N],dp[N][N],add=0;
inline void upd(int i,int j,int v){
	umx(dp[i][j],v);umx(dp[j][i],v);
	umx(dp1[i],v);umx(dp1[j],v);
	umx(dp2,v);
