ll n,a[N],ans=0,cnt[N],cnt2[N];
void doit1(vector<pair<ll,ll> > num,ll l,ll r)
{
	ll i;
	vector<ll> hope;
	for(i=0;i<num.size();i++)
	{
		if(cnt[num[i].F]%3==0)
		{
			hope.push_back(num[i].S);
		}
	}
	if(hope.size()==1)
	{
		swap(a[hope[0]],a[r]);
	}
	else if(hope.size()==2)
	{
		swap(a[hope[0]],a[r]);
		if(hope[1]==r)
		{
			swap(a[hope[0]],a[r-1]);
		}
		else
		{
			swap(a[hope[1]],a[r-1]);
		}
	}
	for(i=l;i<=l+2;i++)
	{
		cnt[a[i]]--;
	}
	return;
}
void doit2(vector<pair<ll,ll> > num,ll l,ll r)
{
	ll i;
	vector<ll> hope,hop;
	memset(cnt2,0,sizeof(cnt2));
	for(i=0;i<num.size();i++)
	{
		cnt2[num[i].F]++;
	}
	for(i=0;i<num.size();i++)
	{
		if(i>0&&num[i].F==num[i-1].F)
		{
			continue;
		}
		if(cnt2[num[i].F]==1)
		{
			if(cnt[num[i].F]%3==0)
			{
				hope.push_back(num[i].S);
			}
		}
		else
		{
			if(cnt[num[i].F]%3==0)
			{
				hope.push_back(num[i].S);
				hope.push_back(num[i+1].S);
			}
			else if(cnt[num[i].F]%3==1)
			{
				hope.push_back(num[i].S);
			}
		}
	}
	if(hope.size()>=2)
	{
		swap(a[hope[0]],a[r]);
		if(hope[1]==r)
		{
			swap(a[hope[0]],a[r-1]);
		}
		else
		{
			swap(a[hope[1]],a[r-1]);
		}
	}
	else if(hope.size()==1)
	{
		swap(a[hope[0]],a[r]);
	}
	else if(hop.size()!=0)
	{
		swap(a[hop[0]],a[r]);
		if(hop[0]+1==r)
		{
			swap(a[hop[0]],a[r-1]);
		}
		else
		{
			swap(a[hop[0]+1],a[r-1]);
		}
	}
	for(i=l;i<=l+2;i++)
	{
		cnt[a[i]]--;
	}
	return;
}
void getans(ll l,ll r)
{
	vector<ll> un;
	vector<pair<ll,ll> > num;
	ll i;
	for(i=l;i<=r;i++)
	{
		un.push_back(a[i]);
		num.push_back(make_pair(a[i],i));
	}
	sort(un.begin(),un.end());
	sort(num.begin(),num.end());
	if(un[0]==un[1]&&un[1]==un[2])
	{
		ans++;
		for(i=l;i<=r;i++)
		{
			if(a[i]!=un[2])
			{
				if(a[r]==un[2])
				{
					swap(a[i],a[r]);
				}
				else
				{
					swap(a[i],a[r-1]);
				}
			}
		}
		cnt[un[2]]-=3;
		return;
	}
	if(un[1]==un[2]&&un[2]==un[3])
	{
		ans++;
		for(i=l;i<=r;i++)
		{
			if(a[i]!=un[2])
			{
				if(a[r]==un[2])
				{
					swap(a[i],a[r]);
				}
				else
				{
					swap(a[i],a[r-1]);
				}
			}
		}
		cnt[un[2]]-=3;
		return;
	}
	if(un[2]==un[3]&&un[3]==un[4])
	{
		ans++;
		for(i=l;i<=r;i++)
		{
			if(a[i]!=un[2])
			{
				if(a[r]==un[2])
				{
					swap(a[i],a[r]);
				}
				else
				{
					swap(a[i],a[r-1]);
				}
			}
		}
		cnt[un[2]]-=3;
		return;
	}
	un.erase(unique(un.begin(),un.end()),un.end());
	if(un.size()==5)
	{
		doit1(num,l,r);
		return;
	}
	doit2(num,l,r);
	return;
}
