int dp[2005][2005], mx[2005], nmx[2005];
int a[6005], n, jar, Mx, NMx;
map<pair<int, int>, int> zh;

int inline val(int i, int j) {
	if(zh.count(mak(i, j))) return zh[mak(i, j)];
	else return dp[i][j];
}

void inline zy(int i, int j, int val) {
	if(!zh.count(mak(i, j))) zh[mak(i, j)] = dp[i][j];
	if(!zh.count(mak(j, i))) zh[mak(j, i)] = dp[j][i];
	dp[i][j] = max(dp[i][j], val);
	dp[j][i] = max(dp[j][i], val);
	nmx[i] = max(nmx[i], val);
	nmx[j] = max(nmx[j], val);
	NMx = max(NMx, val);
}

int main() {
	scanf("%d", &n);
	cont(i, 3 * n) scanf("%d", a + i);
	cont(i, n) cont(j, n) dp[i][j] = -Inf;
	cont(i, n) mx[i] = -Inf;
	Mx = -Inf;
	dp[a[1]][a[2]] = 0;
	range(i, 3, 3 * n - 1, 3) {
		cont(j, n) nmx[j] = -Inf;
		NMx = -Inf;
		zh.clear();
		int p = a[i], q = a[i + 1], r = a[i + 2];
		if(p == q && q == r) {
			jar++; continue;
		}
		if(p == q || q == r || p == r) {
			int Q = p ^ q ^ r, P = (p + q + r - Q) >> 1;
			cont(j, n) zy(j, Q, val(j, P) + 1);
		}
		zy(q, r, val(p, p) + 1);
		zy(p, r, val(q, q) + 1);
		zy(p, q, val(r, r) + 1);
		zy(q, r, Mx); zy(p, r, Mx); zy(p, q, Mx);
		cont(j, n) {
			zy(j, q, mx[p]); zy(j, r, mx[p]);
			zy(j, p, mx[q]); zy(j, r, mx[q]);
			zy(j, p, mx[r]); zy(j, q, mx[r]);
		}
		cont(j, n) mx[j] = nmx[j];
		Mx = NMx;
	}
	int res = dp[a[3 * n]][a[3 * n]] + 1;
	cont(i, n) cont(j, n) res = max(res, dp[i][j]);
	printf("%d\n", res + jar);
	return 0;
}

