int dfs(vector<int> ve){
	if((int)ve.size()==3){
		if(ve[0]==ve[1]&&ve[1]==ve[2])return 1;
		return 0;
	}
	int g=ve.size();
	vector<int> w;
	for(int i=g-5;i<g;i++){
		w.pb(ve.back());
		ve.pop_back();
	}

	string s="00011";
	int ans=-inf;
	do{
		set<int> se;
		for(int i=0;i<5;i++){
			if(s[i]=='1'){
				ve.pb(w[i]);
			}
			else{
				se.insert(w[i]);
			}
		}
		if(se.size()==1)ans=max(ans,1+dfs(ve));
		else ans=max(ans,dfs(ve));
		ve.pop_back();
		ve.pop_back();

	}while(next_permutation(s.begin(),s.end()));
	return ans;
}


