		const int b = as.back(); as.pop_back();
		const int c = as.back(); as.pop_back();
		const int d = as.back(); as.pop_back();
		const int e = as.back(); as.pop_back();
		const int hs = calc(a, b, c, d, e);
		if (hs != 0) {
			ans++;
			int count = 0;
			for (int x : {e, d, c, b, a}) {
				if (x != hs) { as.push_back(x); count++; }
			}
			for (; count < 2; count++) as.push_back(hs);
		} else {
			for (int x : {e, d, c, b, a}) as.push_back(x);
			std::priority_queue<std::pair<usize, int>> que;
			for (int x : {a, b, c, d, e}) que.emplace(f(x), x);
			for (int _ = 0; _ < 5; _++) as.pop_back();
			for (int _ = 0; _ < 2; _++) {
				as.push_back(que.top().second);
				que.pop();
			}
		}
	}

	if (as[0] == as[1] and as[1] == as[2]) ans++;

	std::cout << ans << '\n';

	return 0;
}

