    vector<ll> A(3*N);
    vector<set<ll>> s(N);
    for(int i=0;i<3*N;i++){
        ll a;
        cin >> a;
        --a;
        A[i] = a;
        s[a].insert(i);
    }
    map<ll,ll> mp;
    for(int i=0;i<2;i++){
        mp[A[i]]++;
    }
    ll ans =0;
    for(int i=0;i<N-1;i++){
        // cerr <<"i=" << i << endl;
        for(int j=0;j<3;j++){
            mp[A[(i+1)*3+j-1]]++;
        }
        bool skip = false;
        vector<P> val;
        for(auto itr = mp.begin();itr != mp.end();itr++){
            if(itr->second >=3){
                // cerr <<"found at " << itr->first << endl;
                mp[itr->first] -= 3;
                skip = true;
                ans++;
                break;
            }
            if(itr->second == 2){
               auto itr2 = s[itr->first].lower_bound((i+2)*3);
               if(itr2== s[itr->first].end()){
                   val.push_back(P(INF,itr->first));
                   continue;
               }
               ll v = *itr2;
               val.push_back(P(v,itr->first));
            }
            if(itr->second == 1){
                auto itr2 = s[itr->first].lower_bound((i+2)*3);
                 if(itr2== s[itr->first].end()){
                     val.push_back(P(INF,itr->first));
                   continue;
               }
                itr2++;
                if(itr2== s[itr->first].end()){
                    val.push_back(P(INF,itr->first));
                   continue;
               }
                ll v = *itr2;
               val.push_back(P(v,itr->first));
            }
        }
        if(skip){
            // cerr <<"skipped" << endl;
            continue;
        }
        sort(val.rbegin(),val.rend());
        ll erased = 0;
        for(int j=0;j<val.size();j++){
            if(erased<3){
                ll d = min(2ll,mp[val[j].second]);
                mp[val[j].second]-=d;
                erased+=d;
            }
        }
    }
    mp[A.back()]++;
    for(auto itr = mp.begin();itr != mp.end();itr++){
        // cerr <<"itr.first=" <<itr->first <<" second =" << itr->second << endl;
            if(itr->second >=3){
                mp[itr->first] -= 3;
                ans++;
                break;
            }
    }
    cout << ans << endl;

    return 0;
}

