    cin >> n;
    n *= 3;
    vector<int> ar(n);
    for (int i = 0; i < n; i++)
        cin >> ar[i];
    vector<int> ep(2002, 3000);
    for (int i = 0; i < n; i++)
    {
        ep[ar[i]] = i;
    }
    multiset<int> cur;
    for (int i = 0; i < 2; i++)
    {
        cur .insert(ar[i]);
    }
    int ans = 0;
    for (int i = 1; i < n;)
    {
        for (int j = 1; j <= 3; j++)
        {
            if (i + j < n)
            {
                cur.insert(ar[i + j]);
            }
        }
        i += 3;

        map<int, int> rmc;
        // find maximum occuring number
        map<int ,int> cnt;
        int mc = 0, val = 0;
        for (int x: cur)
        {
            cnt[x] ++;
            if (cnt[x] >= mc)
                mc = cnt[x], val = x;
        }
        if (mc == 3)
        {
            ans ++;
            cur.erase(val);
            continue;
        }
        for (int itr = 0; itr < 3; itr++)
        {
            if (cur.empty())
                break;
            int last = -1;
            int lastp = -1;
            for (int x: cur)
            {
                if (ep[x] > lastp)
                {
                    lastp = ep[x];
                    last = x;
                }
            }
            rmc[last] ++;
            cur.erase(cur.find(last));
        }
        for (auto p: rmc)
            if (p.second >= 3)
                ans ++;
    }
    cout << ans << "\n";
    return 0;
}

