void solve() {
    ll n;
    cin >> n;
    vec<ll> a(3 * n);
    REP(i, 3 * n) {
        cin >> a[i];
    }

    vvec<ll> dp(n + 1, vec<ll>(n + 1, -1));
    vec<ll> mak(n + 1, -1);

    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    ll all = 0;
    ll ma = 0;
    REP(i, n - 1) {
        vec<tp> ndp;
        vec<ll> b({a[i * 3 + 2], a[i * 3 + 3], a[i * 3 + 4]});
        if(b[0] == b[1] and b[1] == b[2]) {
            all++;
            continue;
        }

        REP(j, 3) {
            //どれか二つを使う
            if(b[(j + 1) % 3] == b[(j + 2) % 3]) {
                rep(k, 1, n + 1) {
                    ndp.emplace_back(b[j],(ll)k,ma);
                    if(dp[b[(j + 1) % 3]][k] == -1)
                        continue;
                    ndp.push_back({b[j], (ll)k, dp[b[(j + 1) % 3]][k] + 1});
                }
            }

            //どれか一つだけ使う
            if(dp[b[j]][b[j]] != -1)
                ndp.push_back({b[(j + 1) % 3], b[(j + 2) % 3], dp[b[j]][b[j]] + 1});

            //どれか一つだけすてる
            ndp.push_back({b[(j + 1) % 3], b[(j + 2) % 3], ma});

            //どれか二つをすてる
            rep(k, 1, n + 1) {
                ndp.push_back({b[j], (ll)k, mak[k]});
            }
        }
        for(auto [x, y, num] : ndp) {
            chmax(ma, num);
            chmax(mak[x], num);
            chmax(mak[y], num);
            chmax(dp[x][y], num);
            chmax(dp[y][x], num);
        }
    }
    chmax(ma, dp[a[3 * n - 1]][a[3 * n - 1]] + 1);
    cout << ma + all << en;
}

