int N;
int A[6010];

map<tuple<int, int, int>, int> memo;
int dfs(int i, int a, int b) {
  if (memo.count(make_tuple(i, a, b))) return memo[make_tuple(i, a, b)];
  if (memo.count(make_tuple(i, b, a))) return memo[make_tuple(i, b, a)];
  if (i == N) {
    if (a == b && b == A[3 * N - 1]) return 1;
    return 0;
  }
  vector<int> v = {a, b, A[3 * i - 1], A[3 * i], A[3 * i + 1]};
  int ret = 0;
  for (int k = 0; k < 5; k++) {
    for (int l = k + 1; l < 5; l++) {
      vector<int> vv;
      for (int m = 0; m < 5; m++)
        if (m != k && m != l) vv.push_back(v[m]);
      if (vv[0] == vv[1] && vv[1] == vv[2])
        return memo[make_tuple(i, a, b)] = 1 + dfs(i + 1, v[k], v[l]);
    }
  }
  for (int k = 0; k < 5; k++) {
    for (int l = k + 1; l < 5; l++) {
      ret = max(ret, dfs(i + 1, v[k], v[l]));
    }
  }
  return memo[make_tuple(i, a, b)] = ret;
}

