int ant3(int x) {
  return where[x][(int) where[x].size() - 3];
}

void del5() {
  for (int i = n; i >= n - 4; i--) {
    where[a[i]].pop_back();
  }
}

void add2() {
  for (int i = n; i >= n - 1; i--) {
    where[a[i]].push_back(i);
  }
