time_t bg;

double elap() {
  time_t nd = clock();
  return (nd - bg) / CLOCKS_PER_SEC;
}

int nn, b[N];
mt19937 rng(chrono::high_resolution_clock::now().time_since_epoch().count());

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  bg = clock();
  cin >> n;
  n *= 3;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }
  reverse(a + 1, a + n + 1);
  nn = n;
  int be = 0;
  for (int i = 1; i <= n; i++) b[i] = a[i];
  while (elap() < 1) {
    sol = 0;
  n = nn;
  for (int i = 1; i <= n; i++) {
    where[i] = {-100000, -100000, -100000};
  }
  for (int i = 1; i <= n; i++) a[i] = b[i];
  for (int i = 1; i <= n; i++)
    where[a[i]].push_back(i);
  while (n >= 5) {
    map<int, int> ft;
    vector<int> vals;
    for (int j = 0; j < 5; j++) vals.push_back(a[n - j]);
    for (auto &it : vals) ft[it]++;
    vector<pair<int, int>> f;
    for (auto &it : ft) f.push_back(it);
    shuffle(f.begin(), f.end(), rng);
    bool fo = 0;
    for (auto &it : f) {
      if (it.second >= 3) {
        fo = 1;
        it.second -= 3;
      }
    }
    if (fo) {
      sol++;
      del5();
      n -= 5;
      for (auto &it : f) {
        for (int j = 1; j <= it.second; j++) a[++n] = it.first;
      }
      add2();
      continue;
    }
    int need = 3;
    while (need) {
      int mn = (int) 1e9;
      for (auto &it : f) {
        if (it.second)
        mn = min(mn, ant3(it.first));
      }
      for (auto &it : f) {
        if (it.second && ant3(it.first) == mn) {
          int t = min(it.second, need);
          need -= t;
          it.second -= t;
          break;
        }
      }
    }
    del5();
    n -= 5;
    for (auto &it : f) {
      for (int j = 1; j <= it.second; j++) a[++n] = it.first;
    }
    add2();
  }
  sol += (a[1] == a[2] && a[2] == a[3]);
  be = max(be, sol);
  }
  cout << be << "\n";
  return 0;
}

