    }
    for (int i=2; i<3*N; ++i) {
        vector<int> cnt(N);
        if (i%3 == 0) ++cnt[A[i-1]];
        else if (i%3 == 1) {
            ++cnt[A[i-2]];
            ++cnt[A[i-1]];
        }
        for (int j=i+1; j<3*N; ++j) {
            ++cnt[A[j]];
            if (cnt[A[j]] >= 3) G[i].push_back(j);
        }
    }

    int res = 0;
    dfs(0, -1, 0, res, G);
    if (res == N-1) ++res;
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

