				DP[i+1][A[i*3+6]] = max(DP2[i][A[i*3+6]]+1,DP[i+1][A[i*3+6]]);	
			}
		}
		if(A[i*3+6] == A[i*3+7]){
			DP[i+1][A[i*3+6]] = max(maxv,DP[i+1][A[i*3+6]]);
			DP[i+1][A[i*3+6]] = max(DP[i][A[i*3+5]]+1,DP[i+1][A[i*3+6]]);
			if(DP2Pair[i][A[i*3+5]] == A[i*3+6]){
				DP[i+1][A[i*3+5]] = max(DP2[i][A[i*3+5]]+1,DP[i+1][A[i*3+5]]);	
			}
		}
	}
	DP[N-2][A[3*N-1]]++;
	int ans = 0;
	for(int i=0;i<N;i++){
		ans = max(ans,DP2[N-2][i]);
		ans = max(ans,DP[N-2][i]);
	}
	cout << ans << endl;
}
