            // pk,qppからpppを取った場合
            for (int k = 1; k <= N; k++)
                update_next_preparation(k, q, dpk[k] + 1);
            // qq,qppの場合
            update_next_preparation(p, p, dqq + 1);
        }
        else
        {
            // 全部ばらばら
            int p, q, r;
            p = A[3*i-1];
            q = A[3*i];
            r = A[3*i+1];
            // 下準備.更新されないように値を保存。
            int dpp = dp[p][p];
