void sub(int N, int maxp[][MAXN], int maxjmaxp[], int *maxijmaxp, int *tmps, int pair, int rest) {
  int tmp = maxp[rest][rest] + 1;

  for (int i = 0; i < N; i++) {
    tmps[i] = maxp[i][pair] + 1;
  }

  for (int i = 0; i < N; i++) {
    maxp[i][pair] = maxjmaxp[i];
    maxp[pair][i] = maxjmaxp[i];
    maxp[i][rest] = maxjmaxp[i];
    maxp[rest][i] = maxjmaxp[i];
  }
  for (int i = 0; i < N; i++) {
    if (maxjmaxp[pair] < maxjmaxp[i]) maxjmaxp[pair] = maxjmaxp[i];
    if (maxjmaxp[rest] < maxjmaxp[i]) maxjmaxp[rest] = maxjmaxp[i];
  }

  maxp[pair][pair] = *maxijmaxp;
  maxp[rest][pair] = *maxijmaxp;
  maxp[pair][rest] = *maxijmaxp;
  maxjmaxp[pair] = *maxijmaxp;
  maxjmaxp[rest] = *maxijmaxp;

  for (int i = 0; i < N; i++) {
    if (maxp[i][rest] < tmps[i]) {
      maxp[i][rest] = tmps[i];
      maxp[rest][i] = tmps[i];
    }
    if (maxjmaxp[i] < tmps[i]) maxjmaxp[i] = tmps[i];
    if (maxjmaxp[rest] < tmps[i]) maxjmaxp[rest] = tmps[i];
    if (*maxijmaxp < tmps[i]) *maxijmaxp = tmps[i];
  }

  if (maxp[pair][pair] < tmp) maxp[pair][pair] = tmp;
  if (maxjmaxp[pair] < tmp) maxjmaxp[pair] = tmp;
  if (*maxijmaxp < tmp) *maxijmaxp = tmp;
}

