import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.HashMap;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int[] a = sc.ints(3 * n);
        if (n == 1) {
            out.writeln(a[0] == a[1] && a[1] == a[2] ? 1 : 0);
            return;
        }
        int max = 0;
        HashMap<IntPair, Integer> set = new HashMap<>();
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 4; j++) {
                for (int k = j + 1; k < 5; k++) {
                    int s = 0;
                    if (a[i] == a[j] && a[j] == a[k]) {
                        max = 1;
                        s = 1;
                    }
                    IntPair p = new IntPair(-1, -1);
                    for (int l = 0; l < 5; l++) {
                        if (l != i && l != j && l != k) {
                            if (p.fst < 0) p.fst = a[l];
                            else p.snd = a[l];
                        }
                    }
                    if (set.getOrDefault(p, 0) <= s) set.put(p, s);
                }
            }
        }
        for (int x = 1; x < n - 1; x++) {
            HashMap<IntPair, Integer> nxt = new HashMap<>();
            int m = max;
            for (var e : set.entrySet()) {
                IntPair p = e.getKey();
                int score = e.getValue();
                if (score <= m - 2 || score + 1 <= max - 2) continue;
                int[] sel = {p.fst, p.snd, a[3 * x + 2], a[3 * x + 3], a[3 * x + 4]};
                for (int i = 0; i < 3; i++) {
                    for (int j = i + 1; j < 4; j++) {
                        for (int k = j + 1; k < 5; k++) {
                            int s = score;
                            if (sel[i] == sel[j] && sel[j] == sel[k]) {
                                max = Math.max(max, ++s);
                            }
                            IntPair q = new IntPair(-1, -1);
                            for (int l = 0; l < 5; l++) {
                                if (l != i && l != j && l != k) {
                                    if (q.fst < 0) q.fst = sel[l];
                                    else q.snd = sel[l];
                                }
                            }
                            if (nxt.getOrDefault(q, 0) <= s) nxt.put(q, s);
                        }
                    }
                }
            }
            var tmp = nxt; nxt = set; set = tmp;
        }
        for (var e : set.entrySet()) {
            IntPair p = e.getKey();
            int s = e.getValue();
            max = Math.max(max, s + (p.fst == p.snd && p.fst == a[3 * n - 1] ? 1 : 0));
        }
        out.writeln(max);
    }
}


