import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに実装したソースコード
 * 
 * https://atcoder.jp/contests/abc176/submissions/16164166 にも参考
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int n3 = n * 3;
			int[] a = new int[n3];
			IntStream.range(0, n3).forEach(i -> a[i] = scanner.nextInt() - 1);
			int[][] dp = new int[n][n];
			IntStream.range(0, n).forEach(i -> Arrays.fill(dp[i], -1));
			dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
			int[] max = new int[n];
			Arrays.fill(max, -1);
			int maxOfMax = 0, answer = 0;
			for (int i = 2; i < n3; i += 3) {
				if (n3 - 1 == i) {
					maxOfMax = Math.max(maxOfMax, dp[a[i]][a[i]] + 1);
				} else {
					// 左から 3,4,5 番目の数字が等しいときは、必ずそれら 3 枚を取り除くことにします
					if ((a[i] == a[i + 1]) && (a[i] == a[i + 2])) {
						answer++;
						continue;
					}

					List<Data> updates = new ArrayList<>();
					for (int j = 0; j < 3; j++) {
						int t1 = i + j;
						// 3,4,5 番目の数字の一つを p、残りを左から q,r として、DP[i+1][q][r] を DP[i][p][p]+1 で最大化します
						if (-1 != dp[a[t1]][a[t1]]) {
							int t2 = i + ((j + 1) % 3), t3 = i + ((j + 2) % 3);
							updates.add(new Data(a[t2], a[t3], dp[a[t1]][a[t1]] + 1));
						}
					}
					for (int t1 = i; t1 < i + 3; t1++) {
						for (int t2 = t1 + 1; t2 < i + 3; t2++) {
							int t3 = 3 * (i + 1) - t1 - t2;
							if (a[t1] == a[t2]) {
								// 3,4,5 番目の数字に等しい数字のペアがあるとき、その値を p、残りの一つの値を q 、k を 1 以上 N 以下の任意の整数として、DP[i+1][k][q] を
								// DP[i][p][k]+1 や DP[i][k][p]+1 で最大化します
								for (int k = 0; k < n; k++) {
									if (-1 != dp[k][a[t1]]) {
										updates.add(new Data(k, a[t3], dp[k][a[t1]] + 1));
									}
								}
							}
							// 3,4,5 番目の数字を左から p,q,r 、k,l を 1 以上 N 以下の任意の整数として、DP[i+1][p][q] や DP[i+1][p][r] や
							// DP[i+1][q][r] を DP[i][k][l] の最大値で最大化します
							updates.add(new Data(a[t1], a[t2], maxOfMax));
						}
						// DP[i+1][k][q] を DP[i][p][k]+1 や DP[i][k][p]+1 で最大化します
						for (int k = 0; k < n; k++) {
							updates.add(new Data(k, a[t1], max[k]));
						}
					}
					for (Data data : updates) {
						dp[data.i][data.j] = dp[data.j][data.i] = Math.max(dp[data.i][data.j], data.dp);
						max[data.i] = Math.max(max[data.i], dp[data.i][data.j]);
						max[data.j] = Math.max(max[data.j], dp[data.j][data.i]);
						maxOfMax = Math.max(dp[data.i][data.j], maxOfMax);
					}
				}
			}
			System.out.println(maxOfMax + answer);
		}
	}

	/**
	 * i,j,dpを表すクラス
	 */
	private static class Data {
		int i;
		int j;
		int dp;

		Data(int i, int j, int dp) {
			super();
			this.i = i;
			this.j = j;
			this.dp = dp;
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {
    private static final boolean N_CASE = false;

    private void solve() {
        int N = sc.nextInt();
        int M = N * 3;
        int[] A = sc.nextIntArray(M);

        int[][] dp = new int[N + 1][N + 1];
        fill(dp, -1);
        dp[A[0]][A[1]] = dp[A[1]][A[0]] = 0;
        int ans = 0;
        int add = 0;
        for (int i = 2; i < M; i += 3) {
            if (i == M - 1) {
                if (dp[A[i]][A[i]] != -1) {
                    ans = Math.max(ans, dp[A[i]][A[i]] + 1);
                }
            } else {
                if (A[i] == A[i + 1] && A[i] == A[i + 2]) {
                    ++add;
                    continue;
                }

                for (int j = 0; j < 3; ++j) {
                    int k = i + j;
                    if (dp[A[k]][A[k]] != -1) {
                        int t1 = i + (j + 1) % 3;
                        int t2 = i + (j + 2) % 3;
                        dp[A[t1]][A[t2]] = dp[A[t2]][A[t1]] = Math.max(dp[A[t1]][A[t2]], dp[A[k]][A[k]] + 1);

                        ans = Math.max(dp[A[t1]][A[t2]], ans);
                    }
                }

                for (int j1 = 0; j1 < 3; ++j1) {
                    for (int j2 = j1 + 1; j2 < 3; ++j2) {
                        int j3 = 4 - j1 - j2;
                        int t1 = i + j1;
                        int t2 = i + j2;
                        int t3 = i + j3;

                        if (A[t1] == A[t2]) {
                            for (int k = 1; k <= N; ++k) {
                                if (dp[k][A[t1]] != -1) {
                                    dp[k][A[t3]] = dp[A[t3]][k] = Math.max(dp[k][A[t3]], dp[k][A[t1]] + 1);
                                    ans = Math.max(dp[k][A[t3]], ans);
                                }
                            }
                        }
                    }
                }
            }
        }

        out.println(ans + add);
    }

    private void run() {
        int T = N_CASE ? sc.nextInt() : 1;
        for (int t = 0; t < T; ++t) {
            solve();
        }
    }

    private static MyWriter out;
    private static MyScanner sc;

    private static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        private MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        int[][] nextIntArray(int n, int m) {
            int[][] a = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    a[i][j] = sc.nextInt();
                }
            }
            return a;
        }

        long[][] nextLongArray(int n, int m) {
            long[][] a = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    a[i][j] = nextLong();
                }
            }
            return a;
        }

        List<Integer> nextList(int n) {
            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                list.add(nextInt());
            }
            return list;
        }

        List<Long> nextLongList(int n) {
            List<Long> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                list.add(nextLong());
            }
            return list;
        }

        char[] nextCharArray(int n) {
            return sc.next().toCharArray();
        }

        char[][] nextCharArray(int n, int m) {
            char[][] c = new char[n][m];
            for (int i = 0; i < n; i++) {
                String s = sc.next();
                for (int j = 0; j < m; j++) {
                    c[i][j] = s.charAt(j);
                }
            }
            return c;
        }
    }

    private static class MyWriter extends PrintWriter {
        private MyWriter(OutputStream outputStream) {
            super(outputStream);
        }

        void printArray(int[] a) {
            for (int i = 0; i < a.length; ++i) {
                print(a[i]);
                print(i == a.length - 1 ? '\n' : ' ');
            }
        }

        void printlnArray(int[] a) {
            for (int v : a) {
                println(v);
            }
        }

        void printList(List<Integer> list) {
            for (int i = 0; i < list.size(); ++i) {
                print(list.get(i));
                print(i == list.size() - 1 ? '\n' : ' ');
            }
        }

        void printlnList(List<Integer> list) {
            list.forEach(this::println);
        }
    }

    private <T> List<List<T>> createGraph(int n) {
        List<List<T>> g = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            g.add(new ArrayList<>());
        }
        return g;
    }

    private void fill(int[][] a, int value) {
        for (int[] row : a) {
            Arrays.fill(row, value);
        }
    }

    public static void main(String[] args) {
        out = new MyWriter(new BufferedOutputStream(System.out));
        sc = new MyScanner();
        new Main().run();
        out.close();
    }
}

