import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.stream.Stream;

public class Main {

  public static void main(String[] args) throws Exception {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    int n = Integer.parseInt(br.readLine());
    // TODO あとでマイナス１する処理をつける
    int[] a = Stream.of(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    br.close();

    int[][] dp = new int[n + 1][n + 1];
    for (int[] sub : dp) {
      Arrays.fill(sub, -1);
    }
    int[] colMax = new int[n + 1];
    Arrays.fill(colMax, -1);

    int base = 0;
    int dpMax = 0;
    dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
    colMax[a[0]] = 0;
    colMax[a[1]] = 0;

    ArrayList<Query> queryList = new ArrayList<>();

    for (int loop = 1; loop < n; loop++) {
      int start = (loop * 3) - 1;
      if (a[start] == a[start + 1] && a[start] == a[start + 2]) {
        base++;
        continue;
      }

      queryList.clear();

      //揃える場合の遷移
      for (int temp = 0; temp < 3; temp++) {
        int x = a[start + (temp % 3)];
        int y = a[start + ((temp + 1) % 3)];
        int z = a[start + ((temp + 2) % 3)];
        //追加される3枚にペアがある場合
        if (x == y) {
          for (int i = 1; i <= n; i++) {
            if(dp[i][x] >= 0) queryList.add(new Query(i, z, dp[i][x] + 1));
            if(dp[x][i] >= 0) queryList.add(new Query(z, i, dp[x][i] + 1));
          }
        } else {
          //xを採用
          if (dp[x][x] >= 0) {
            queryList.add(new Query(y, z, dp[x][x] + 1));
            queryList.add(new Query(z, y, dp[x][x] + 1));
          }
        }
      }

      for (int temp = 0; temp < 3; temp++) {
        int x = a[start + (temp % 3)];
        int y = a[start + ((temp + 1) % 3)];
        //int z = a[start + ((temp + 2) % 3)];
        //揃えない場合
        //xのみ採用
        for (int i = 1; i <= n; i++) {
          queryList.add(new Query(i,x,Math.max(colMax[x], colMax[i])));
          queryList.add(new Query(x,i,Math.max(colMax[i], colMax[x])));
        }
        //xyを採用
        queryList.add(new Query(x,y,dpMax));
        queryList.add(new Query(y,x,dpMax));
      }

      for(Query q : queryList){
        dpMax = Math.max(dpMax, q.value);
        colMax[q.a] = Math.max(colMax[q.a], q.value);
        colMax[q.b] = Math.max(colMax[q.b], q.value);
        dp[q.a][q.b] = Math.max(dp[q.a][q.b], q.value);
      }
    }
    System.out.println(Math.max(dp[a[a.length - 1]][a[a.length - 1]] + 1, dpMax) + base);
  }
}

class Query {

  int a, b, value;

  Query(int a, int b, int value) {
    this.a = a;
    this.b = b;
    this.value = value;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve() {
        int n = in.nextInt();
        int[] p = in.nextIntArray(n * 3);
        for (int i = 0; i < n * 3; i++) {
            p[i]--;
        }
        int[][] dp = new int[n][n];
        int base = 0;
        int max = 0;
        int[] xMax = new int[n];
        int[] yMax = new int[n];
        for (int i = 0; i < n; i++) {
            xMax[i] = -iinf;
            yMax[i] = -iinf;
            for (int j = 0; j < n; j++) {
                dp[i][j] = -iinf;
            }
        }
        dp[p[0]][p[1]] = 0;
        dp[p[1]][p[0]] = 0;
        xMax[p[0]] = 0;
        yMax[p[0]] = 0;
        xMax[p[1]] = 0;
        yMax[p[1]] = 0;
        for (int i = 0; i < n - 1; i++) {
            if (p[i * 3 + 2] == p[i * 3 + 3] && p[i * 3 + 3] == p[i * 3 + 4]) {
                base++;
                continue;
            }
            Map<IntPair, Integer> changes = new HashMap<>();
            int oldMax = max;
            int[] oldXMax = Arrays.copyOf(xMax, n);
            int[] oldYMax = Arrays.copyOf(yMax, n);
            for (int j = 0; j < 3; j++) {
                int a = p[i * 3 + 2 + (0 + j) % 3];
                int b = p[i * 3 + 2 + (1 + j) % 3];
                int c = p[i * 3 + 2 + (2 + j) % 3];
                changes.merge(new IntPair(a, b), Math.max(dp[a][b], oldMax), Integer::max);
                if (a == b) {
                    for (int k = 0; k < n; k++) {
                        int v = Math.max(Math.max(dp[k][c], dp[c][k]), Math.max(dp[a][k], dp[k][a]) + 1);
                        changes.merge(new IntPair(k, c), v, Integer::max);
                        changes.merge(new IntPair(c, k), v, Integer::max);
                        max = Math.max(max, v);
                        xMax[k] = Math.max(xMax[k], v);
                        xMax[c] = Math.max(xMax[c], v);
                        yMax[k] = Math.max(xMax[k], v);
                        yMax[c] = Math.max(xMax[c], v);
                    }
                }
                int v = Math.max(Math.max(dp[a][b], dp[b][a]), dp[c][c] + 1);
                changes.merge(new IntPair(a, b), v, Integer::max);
                changes.merge(new IntPair(b, a), v, Integer::max);
                max = Math.max(max, v);
                xMax[a] = Math.max(xMax[a], v);
                xMax[b] = Math.max(xMax[b], v);
                yMax[a] = Math.max(yMax[a], v);
                yMax[b] = Math.max(yMax[b], v);
                for (int k = 0; k < n; k++) {
                    v = Math.max(oldXMax[k], oldYMax[k]);
                    changes.merge(new IntPair(k, a), v, Integer::max);
                    changes.merge(new IntPair(a, k), v, Integer::max);
                    xMax[k] = Math.max(xMax[k], v);
                    xMax[a] = Math.max(xMax[a], v);
                    yMax[k] = Math.max(yMax[k], v);
                    yMax[a] = Math.max(yMax[a], v);
                }
            }
            for (Map.Entry<IntPair, Integer> entry : changes.entrySet()) {
                dp[entry.getKey().first][entry.getKey().second] = entry.getValue();
            }
        }
        dp[p[n * 3 - 1]][p[n * 3 - 1]]++;
        out.println(base + Math.max(dp[p[n * 3 - 1]][p[n * 3 - 1]], max));
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class IntPair implements Comparable<IntPair> {
    int first;
    int second;

    IntPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof IntPair)) {
            return false;
        }
        IntPair that = (IntPair)o;
        return first == that.first && second == that.second;
    }

    @Override
    public int hashCode() {
        return first * 31 + second;
    }

    @Override
    public int compareTo(IntPair o) {
        return first == o.first ? Integer.compare(second, o.second) : Integer.compare(first, o.first);
    }

    @Override
    public String toString() {
        return String.format("[%s, %s]", first, second);
    }
}

