				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}
	private static boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}
	private static int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}
	@SuppressWarnings("unused")
	private static double nd() {
		return Double.parseDouble(ns());
	}
	@SuppressWarnings("unused")
	private static char nc() {
		return (char) skip();
	}
	private static String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	private static char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}
	@SuppressWarnings("unused")
	private static char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}
	@SuppressWarnings("unused")
	private static int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}
	@SuppressWarnings("unused")
	private static long[] nla(int n) {
		long[] a = new long[n];
		for (int i = 0; i < n; i++)
			a[i] = nl();
		return a;
	}
	@SuppressWarnings("unused")
	private static int[][] na(int n, int m){
		int[][] res = new int[n][m];
		for(int i=0;i<n;i++) {
			for(int j=0;j<m;j++) {
				res[i][j] = ni();
			}
		}
		return res;
	}
	@SuppressWarnings("unused")
	private static long[][] nla(int n, int m){
		long[][] res = new long[n][m];
		for(int i=0;i<n;i++) {
			for(int j=0;j<m;j++) {
				res[i][j] = nl();
			}
		}
		return res;
	}
	private static int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}
	private static long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}
}

import java.util.*;

public class Main {
    static int[] arr;
    static ArrayList<HashMap<Integer, Integer>> dp = new ArrayList<>();
    static int n;
	public static void main (String[] args) {
    	Scanner sc = new Scanner(System.in);
    	n = sc.nextInt();
    	arr = new int[n * 3];
    	for (int i = 0; i < n * 3; i++) {
    	    arr[i] = sc.nextInt() - 1;
    	}
    	for (int i = 0; i < n; i++) {
    	    dp.add(new HashMap<>());
    	}
    	System.out.println(dfw(Math.min(arr[0], arr[1]),Math.max(arr[0], arr[1]), 0));
    }

    static int dfw(int first, int second, int idx) {
        int key = first * n + second;
        if (dp.get(idx).containsKey(key)) {
            return dp.get(idx).get(key);
        }
        if (idx == n - 1) {
            if (first == second && first == arr[3 * n - 1]) {
                return 1;
            } else {
                return 0;
            }
        }
        int[] tmp = new int[]{first, second, arr[idx * 3 + 2], arr[idx * 3 + 3], arr[idx * 3 + 4]};
        Arrays.sort(tmp);
        if (tmp[0] == tmp[1] && tmp[1] == tmp[2]) {
            int value = dfw(tmp[3], tmp[4], idx + 1) + 1;
            dp.get(idx).put(key, value);
            return value;
        }
        if (tmp[1] == tmp[2] && tmp[2] == tmp[3]) {
            int value = dfw(tmp[0], tmp[4], idx + 1) + 1;
            dp.get(idx).put(key, value);
            return value;
        }
        if (tmp[2] == tmp[3] && tmp[3] == tmp[4]) {
            int value = dfw(tmp[0], tmp[1], idx + 1) + 1;
            dp.get(idx).put(key, value);
            return value;
        }
        int value = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = i + 1; j < 5; j++) {
                value = Math.max(value, dfw(tmp[i], tmp[j], idx + 1));
            }
        }
        dp.get(idx).put(key, value);
        return value;
    }
}

