    void solve() {
        int n = in.nextInt();
        int[] p = in.nextIntArray(n * 3);
        for (int i = 0; i < n * 3; i++) {
            p[i]--;
        }
        int[][] dp = new int[n][n];
        int base = 0;
        int max = 0;
        int[] xMax = new int[n];
        int[] yMax = new int[n];
        for (int i = 0; i < n; i++) {
            xMax[i] = -iinf;
            yMax[i] = -iinf;
            for (int j = 0; j < n; j++) {
                dp[i][j] = -iinf;
            }
        }
        dp[p[0]][p[1]] = 0;
        dp[p[1]][p[0]] = 0;
        xMax[p[0]] = 0;
        yMax[p[0]] = 0;
        xMax[p[1]] = 0;
        yMax[p[1]] = 0;
        for (int i = 0; i < n - 1; i++) {
            if (p[i * 3 + 2] == p[i * 3 + 3] && p[i * 3 + 3] == p[i * 3 + 4]) {
                base++;
                continue;
            }
            Map<IntPair, Integer> changes = new HashMap<>();
            int oldMax = max;
            int[] oldXMax = Arrays.copyOf(xMax, n);
            int[] oldYMax = Arrays.copyOf(yMax, n);
            for (int j = 0; j < 3; j++) {
                int a = p[i * 3 + 2 + (0 + j) % 3];
                int b = p[i * 3 + 2 + (1 + j) % 3];
                int c = p[i * 3 + 2 + (2 + j) % 3];
                changes.merge(new IntPair(a, b), Math.max(dp[a][b], oldMax), Integer::max);
                if (a == b) {
                    for (int k = 0; k < n; k++) {
                        changes.merge(new IntPair(k, c), Math.max(dp[k][c], Math.max(dp[a][k], dp[k][a]) + 1), Integer::max);
                        changes.merge(new IntPair(c, k), Math.max(dp[c][k], Math.max(dp[a][k], dp[k][a]) + 1), Integer::max);
                        max = Math.max(max, dp[k][c]);
                        xMax[k] = Math.max(xMax[k], dp[k][c]);
                        xMax[c] = Math.max(xMax[c], dp[k][c]);
                        yMax[k] = Math.max(xMax[k], dp[k][c]);
                        yMax[c] = Math.max(xMax[c], dp[k][c]);
                    }
                }
                changes.merge(new IntPair(a, b), Math.max(dp[a][b], dp[c][c] + 1), Integer::max);
                changes.merge(new IntPair(b, a), Math.max(dp[b][a], dp[c][c] + 1), Integer::max);
                max = Math.max(max, dp[a][b]);
                xMax[a] = Math.max(xMax[a], dp[a][b]);
                xMax[b] = Math.max(xMax[b], dp[a][b]);
                yMax[a] = Math.max(yMax[a], dp[a][b]);
                yMax[b] = Math.max(yMax[b], dp[a][b]);
                for (int k = 0; k < n; k++) {
                    changes.merge(new IntPair(k, a), Math.max(oldXMax[k], oldYMax[k]), Integer::max);
                    changes.merge(new IntPair(a, k), Math.max(oldXMax[k], oldYMax[k]), Integer::max);
                    xMax[k] = Math.max(xMax[k], dp[k][a]);
                    xMax[a] = Math.max(xMax[a], dp[k][a]);
                    yMax[k] = Math.max(yMax[k], dp[k][a]);
                    yMax[a] = Math.max(yMax[a], dp[k][a]);
                }
            }
            for (Map.Entry<IntPair, Integer> entry : changes.entrySet()) {
                dp[entry.getKey().first][entry.getKey().second] = entry.getValue();
            }
        }
        dp[p[n * 3 - 1]][p[n * 3 - 1]]++;
        out.println(base + Math.max(dp[p[n * 3 - 1]][p[n * 3 - 1]], max));
