/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        FBraveCHAIN solver = new FBraveCHAIN();
        solver.solve(1, in, out);
        out.close();
    }

    static class FBraveCHAIN {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints();
            int[] a = new int[3 * n];
            for (int i = 0; i < 3 * n; i++) a[i] = in.ints() - 1;
            int[][] dp = new int[n][n];
            ArrayUtil.fill(dp, Integer.MIN_VALUE);
            dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
            int all = 0;
            int[] t = new int[3];
            for (int i = 1; i < n; i++) {
                t[0] = a[3 * i - 1];
                t[1] = a[3 * i];
                t[2] = a[3 * i + 1];
                Arrays.sort(t);
                if (t[0] == t[2]) {
                    all++;
                    continue;
                }
                for (int j = 0; j < 3; j++) {
                    int o1 = t[(j + 1) % 3], o2 = t[(j + 2) % 3];
                    dp[o1][o2] = Math.max(dp[o1][o2], dp[t[j]][t[j]] + 1);
                    dp[o2][o1] = Math.max(dp[o2][o1], dp[t[j]][t[j]] + 1);
                }
                for (int j = 0; j < 3; j++) {
                    int s1 = t[(j + 1) % 3], s2 = t[(j + 2) % 3];
                    if (s1 != s2) continue;
                    int o1 = t[j];
                    for (int o2 = 0; o2 < n; o2++) {
                        dp[o1][o2] = Math.max(dp[o1][o2], dp[s1][o2] + 1);
                        dp[o2][o1] = Math.max(dp[o2][o1], dp[s1][o2] + 1);
                    }
                }
            }
            int ans = 0, last = a[3 * n - 1];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == last && j == last) ans = Math.max(ans, dp[i][j] + 1);
                    else ans = Math.max(ans, dp[i][j]);
                }
            }
            out.ans(ans + all).ln();
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new OutputStreamWriter(new BufferedOutputStream(out), Charset.defaultCharset()));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static class LightScanner implements AutoCloseable {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public void close() {
            try {
                this.reader.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static final class ArrayUtil {
        private ArrayUtil() {
        }

        public static void fill(int[] a, int v) {
            Arrays.fill(a, v);
        }

        public static void fill(int[][] a, int v) {
            for (int i = 0; i < a.length; i++) {
                fill(a[i], v);
            }
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve() {
        int n = in.nextInt();
        int[] p = in.nextIntArray(n * 3);
        for (int i = 0; i < n * 3; i++) {
            p[i]--;
        }
        int[][] dp = new int[n][n];
        int base = 0;
        int max = 0;
        int[] xMax = new int[n];
        int[] yMax = new int[n];
        for (int i = 0; i < n; i++) {
            xMax[i] = -iinf;
            yMax[i] = -iinf;
            for (int j = 0; j < n; j++) {
                dp[i][j] = -iinf;
            }
        }
        dp[p[0]][p[1]] = 0;
        dp[p[1]][p[0]] = 0;
        xMax[p[0]] = 0;
        yMax[p[0]] = 0;
        xMax[p[1]] = 0;
        yMax[p[1]] = 0;
        for (int i = 0; i < n - 1; i++) {
            if (p[i * 3 + 2] == p[i * 3 + 3] && p[i * 3 + 3] == p[i * 3 + 4]) {
                base++;
                continue;
            }
            Map<IntPair, Integer> changes = new HashMap<>();
            int oldMax = max;
            int[] oldXMax = Arrays.copyOf(xMax, n);
            int[] oldYMax = Arrays.copyOf(yMax, n);
            for (int j = 0; j < 3; j++) {
                int a = p[i * 3 + 2 + (0 + j) % 3];
                int b = p[i * 3 + 2 + (1 + j) % 3];
                int c = p[i * 3 + 2 + (2 + j) % 3];
                changes.merge(new IntPair(a, b), Math.max(dp[a][b], oldMax), Integer::max);
                if (a == b) {
                    for (int k = 0; k < n; k++) {
                        changes.merge(new IntPair(k, c), Math.max(dp[k][c], Math.max(dp[a][k], dp[k][a]) + 1), Integer::max);
                        max = Math.max(max, dp[k][c]);
                        xMax[k] = Math.max(xMax[k], dp[k][c]);
                        yMax[c] = Math.max(xMax[c], dp[k][c]);
                    }
                }
                changes.merge(new IntPair(a, b), Math.max(dp[a][b], dp[c][c] + 1), Integer::max);
                max = Math.max(max, dp[a][b]);
                xMax[a] = Math.max(xMax[a], dp[a][b]);
                yMax[b] = Math.max(yMax[b], dp[a][b]);
                for (int k = 0; k < n; k++) {
                    changes.merge(new IntPair(k, a), Math.max(oldXMax[k], oldYMax[k]), Integer::max);
                    xMax[k] = Math.max(xMax[k], dp[k][a]);
                    yMax[a] = Math.max(yMax[a], dp[k][a]);
                }
            }
            for (Map.Entry<IntPair, Integer> entry : changes.entrySet()) {
                dp[entry.getKey().first][entry.getKey().second] = entry.getValue();
            }
        }
        dp[p[n * 3 - 1]][p[n * 3 - 1]]++;
        out.println(base + Math.max(dp[p[n * 3 - 1]][p[n * 3 - 1]], max));
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

