import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.stream.Stream;

public class Main {

  public static void main(String[] args) throws Exception {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    int n = Integer.parseInt(br.readLine());
    // TODO あとでマイナス１する処理をつける
    int[] a = Stream.of(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    br.close();

    int[][] dp = new int[n + 1][n + 1];
    for (int[] sub : dp) {
      Arrays.fill(sub, -1);
    }
    int[] colMax = new int[n + 1];
    Arrays.fill(colMax, -1);

    int base = 0;
    int dpMax = 0;
    dp[Math.min(a[0], a[1])][Math.max(a[0], a[1])] = 0;
    colMax[a[0]] = 0;
    colMax[a[1]] = 0;

    ArrayList<Query> queryList = new ArrayList<>();

    for (int loop = 1; loop < n; loop++) {
      int start = (loop * 3) - 1;
      if (a[start] == a[start + 1] && a[start] == a[start + 2]) {
        base++;
        continue;
      }

      queryList.clear();
      for (int temp = 0; temp < 3; temp++) {
        int x = a[start + (temp % 3)];
        int y = a[start + ((temp + 1) % 3)];
        //int z = a[start + ((temp + 2) % 3)];
        //揃えない場合
        //xを採用
        for (int i = 1; i <= n; i++) {
          // dp[min(i,x)][max(i,x)] = max(colMax[i], colMax[x])
          queryList.add(new Query(Math.min(i, x), Math.max(i, x), Math.max(colMax[i], colMax[x])));
        }
        //xyを採用
        queryList.add(new Query(Math.min(x, y), Math.max(x, y), dpMax));
      }

      for (int temp = 0; temp < 3; temp++) {
        int x = a[start + (temp % 3)];
        int y = a[start + ((temp + 1) % 3)];
        int z = a[start + ((temp + 2) % 3)];
        //揃える場合
        //xを採用
        if (dp[x][x] >= 0) {
          queryList.add(new Query(Math.min(y, z), Math.max(y, z), dp[x][x] + 1));
        }
        if (x == y) {
          for (int i = 1; i <= n; i++) {
            if (dp[Math.min(i, x)][Math.max(i, x)] >= 0) {
              queryList.add(new Query(Math.min(i, z), Math.max(i, z),
                  dp[Math.min(i, x)][Math.max(i, x)] + 1));
            }
          }
        }
      }
      for(Query q : queryList){
        dpMax = Math.max(dpMax, q.value);
        colMax[q.a] = Math.max(colMax[q.a], q.value);
        colMax[q.b] = Math.max(colMax[q.b], q.value);
        dp[q.a][q.b] = Math.max(dp[q.a][q.b], q.value);
      }
    }
    System.out.println(Math.max(dp[a[a.length - 1]][a[a.length - 1]] + 1, dpMax) + base);
  }
}

class Query {

  int a, b, value;

  Query(int a, int b, int value) {
    this.a = a;
    this.b = b;
    this.value = value;
  }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.Set;

public class Main {

    private static final Set<int[]> patterns = Set.of(
            new int[] { 0, 1, 2, 3, 4 },
            new int[] { 0, 1, 3, 2, 4 },
            new int[] { 0, 1, 4, 2, 3 },
            new int[] { 0, 2, 3, 1, 4 },
            new int[] { 0, 2, 4, 1, 3 },
            new int[] { 0, 3, 4, 1, 2 },
            new int[] { 1, 2, 3, 0, 4 },
            new int[] { 1, 2, 4, 0, 3 },
            new int[] { 1, 3, 4, 0, 2 },
            new int[] { 2, 3, 4, 0, 1 });

    private static int[] As;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();
        As = new int[N * 3];
        for (int i = 0; i < N * 3; i++) {
            As[i] = sc.nextInt();
        }

        System.out.println(calc(0, Arrays.copyOf(As, 2)));
    }

    private static int calc(int start, int[] left2) {
        if (start + 3 == As.length) {
            return left2[0] == As[start + 2] && left2[1] == As[start + 2] ? 1 : 0;
        }

        int[] left5 = new int[] { left2[0], left2[1], As[start + 2], As[start + 3], As[start + 4] };

        return patterns.stream().map(p -> {
            int[] l5 = new int[5];
            l5[0] = left5[p[0]];
            l5[1] = left5[p[1]];
            l5[2] = left5[p[2]];
            l5[3] = left5[p[3]];
            l5[4] = left5[p[4]];

            Arrays.sort(l5, 0, 3);
            Arrays.sort(l5, 3, 5);

            return l5;
        })
                .distinct()
                .parallel()
                .mapToInt(l5 -> {
                    int curr = (l5[0] == l5[1] && l5[0] == l5[2] ? 1 : 0);
                    int next = calc(start + 3, new int[] { l5[3], l5[4] });
                    return curr + next;
                }).max().getAsInt();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final boolean N_CASE = false;

    private void solve() {
        int N = sc.nextInt();
        int M = N * 3;
        int[] A = sc.nextIntArray(M);

        int[][] dp = new int[N + 1][N + 1];
        fill(dp, -1);
        dp[A[0]][A[1]] = dp[A[1]][A[0]] = 0;
        int ans = 0;
        int add = 0;
        for (int i = 2; i < M; i += 3) {
            if (i == M - 1) {
                if (dp[A[i]][A[i]] != -1) {
                    ans = Math.max(ans, dp[A[i]][A[i]] + 1);
                }
            } else {
                if (A[i] == A[i + 1] && A[i] == A[i + 2]) {
                    ++add;
                    continue;
                }

                List<int[]> update = new ArrayList<>();
                for (int j = 0; j < 3; ++j) {
                    int k = i + j;
                    if (dp[A[k]][A[k]] != -1) {
                        int t1 = i + ((j + 1) % 3);
                        int t2 = i + ((j + 2) % 3);
                        update.add(new int[] { A[t1], A[t2], dp[A[k]][A[k]] + 1 });
                    }
                }

                for (int j1 = 0; j1 < 3; ++j1) {
                    int t1 = i + j1;
                    for (int j2 = j1 + 1; j2 < 3; ++j2) {
                        int j3 = 3 - j1 - j2;
                        int t2 = i + j2;
                        int t3 = i + j3;

                        if (A[t1] == A[t2]) {
                            for (int k = 1; k <= N; ++k) {
                                if (dp[k][A[t1]] != -1) {
                                    update.add(new int[] { k, A[t3], dp[k][A[t1]] + 1 });
                                }
                            }
                        }

                        update.add(new int[] { A[t1], A[t2], 0 });
                    }

                    for (int k = 1; k <= N; ++k) {
                        update.add(new int[] { k, A[t1], 0 });
                    }
                }

                for (int[] u : update) {
                    dp[u[0]][u[1]] = dp[u[1]][u[0]] = Math.max(dp[u[0]][u[1]], u[2]);
                    ans = Math.max(dp[u[0]][u[1]], ans);
                }

            }
        }

        out.println(ans + add);
    }

    private void run() {
        int T = N_CASE ? sc.nextInt() : 1;
        for (int t = 0; t < T; ++t) {
            solve();
        }
    }

    private static MyWriter out;
    private static MyScanner sc;

