/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        FBraveCHAIN solver = new FBraveCHAIN();
        solver.solve(1, in, out);
        out.close();
    }

    static class FBraveCHAIN {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints();
            int[] a = new int[3 * n];
            for (int i = 0; i < 3 * n; i++) a[i] = in.ints() - 1;
            //if (n >= 500 )throw new RuntimeException();
            int all = 0;
            int[][] dp = new int[n][n];
            ArrayUtil.fill(dp, -50000);
            dp[a[0]][a[1]] = dp[a[1]][a[0]] = 0;
            int[] m2 = new int[n];
            Arrays.fill(m2, -50000);
            m2[a[0]] = m2[a[1]] = 0;
            int cur = 0, max = 0;
            int[] dx = new int[8 * n], dy = new int[8 * n], nv = new int[8 * n];
            int[] t = new int[3];
            for (int i = 1; i < n; i++) {
                cur = 0;
                t[0] = a[3 * i - 1];
                t[1] = a[3 * i];
                t[2] = a[3 * i + 1];
                // x y Z Z Z => [Z Z Z] x y
                if (t[0] == t[1] && t[1] == t[2]) {
                    all++;
                    continue;
                }
                for (int j = 0; j < 3; j++) {
                    for (int o1 = 0; o1 < n; o1++) {
                        // v w X Y Z => (w Y Z) v X
                        dx[cur] = t[j];
                        dy[cur] = o1;
                        nv[cur++] = m2[o1];
                    }
                }
                for (int j = 0; j < 3; j++) {
                    int o1 = t[(j + 1) % 3], o2 = t[(j + 2) % 3];
                    // x x X Y Z => [x x X] Y Z
                    dx[cur] = o1;
                    dy[cur] = o2;
                    nv[cur++] = dp[t[j]][t[j]] + 1;
                    // v w X Y Z => (v w X) Y Z
                    dx[cur] = o1;
                    dy[cur] = o2;
                    nv[cur++] = max;
                }
                for (int j = 0; j < 3; j++) {
                    int s1 = t[(j + 1) % 3], s2 = t[(j + 2) % 3];
                    if (s1 != s2) continue;
                    int o1 = t[j];
                    for (int o2 = 0; o2 < n; o2++) {
                        // x y X X Z => [x X X] y Z
                        dx[cur] = o1;
                        dy[cur] = o2;
                        nv[cur++] = dp[s1][o2] + 1;
                    }
                }
                for (int j = 0; j < cur; j++) {
                    if (nv[j] < 0) continue;
                    dp[dx[j]][dy[j]] = dp[dy[j]][dx[j]] = Math.max(dp[dy[j]][dx[j]], nv[j]);
                    max = Math.max(max, nv[j]);
                    m2[dx[j]] = Math.max(m2[dx[j]], nv[j]);
                    m2[dy[j]] = Math.max(m2[dy[j]], nv[j]);

                }
            }
            int last = a[3 * n - 1];
            out.ans(Math.max(dp[last][last] + 1, max) + all).ln();
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new OutputStreamWriter(new BufferedOutputStream(out), Charset.defaultCharset()));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static class LightScanner implements AutoCloseable {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public void close() {
            try {
                this.reader.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static final class ArrayUtil {
        private ArrayUtil() {
        }

        public static void fill(int[] a, int v) {
            Arrays.fill(a, v);
        }

        public static void fill(int[][] a, int v) {
            for (int i = 0; i < a.length; i++) {
                fill(a[i], v);
            }
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;

public class Main {

	public Main() {
		FastScanner scanner = new FastScanner();
		int N = scanner.nextInt();

		LinkedList<Integer> A = new LinkedList<>();
		for (int i = 0, len = 3*N; i < len; i++) {
			A.addLast( scanner.nextInt()-1 );
		}

		int[][] DP = new int[N][N];
		int[]  MAX = new int[N];

		for (int x = 0; x < N; x++) {
			for (int y = 0; y < N; y++) {
				DP[x][y] = Integer.MIN_VALUE;
			}
			MAX[x] = Integer.MIN_VALUE;
		}

		DP[A.get(0)][A.get(1)] = 0;
		MAX[A.poll()] = ( MAX[A.poll()] = 0 );

		int result = 0, max = 0;
		for (int n = 0; n < N-1; n++) {
			//配列で使いやすいように昇順でソート
			Collections.sort(A.subList(0, 3));

			int p = A.poll();
			int q = A.poll();
			int r = A.poll();

			//ソートしたので左端と右端が等しければ3つの値はすべて等しい
			if (p == r) {
				result++;
				continue;
			}

			HashMap<int[], Integer> T = new HashMap<>();

			if (p == q){
				for (int k = 0; k < N; k++) {
					T.put( new int[]{k, r}, Math.max(DP[p][k], DP[k][p]) + 1);
				}
			} else if ( q == r ) {
				for (int k = 0; k < N; k++) {
					T.put( new int[]{k, p}, Math.max(DP[q][k], DP[k][q]) + 1);
				}
			}

			add(T, new int[]{q, r}, Math.max(DP[p][p]+1, max));
			add(T, new int[]{p, r}, Math.max(DP[q][q]+1, max));
			add(T, new int[]{p, q}, Math.max(DP[r][r]+1, max));

			for (int k = 0; k < N; k++) {
				add(T, new int[]{k, p}, MAX[k]);
				add(T, new int[]{k, q}, MAX[k]);
				add(T, new int[]{k, r}, MAX[k]);
			}

			for (int[] key : T.keySet()) {
				int x = key[0];
				int y = key[1];
				int v = T.get(key);

				DP[x][y] = v;
				MAX[x] = Math.max(MAX[x], v);
				MAX[y] = Math.max(MAX[y], v);
				max = Math.max(max, v);
			}
		}

		int last = A.poll();

		if ( DP[last][last] + 1 > max) {
			System.out.println(result + DP[last][last] + 1);
		} else {
			System.out.println(result + max);
		}
	}

	void add(HashMap<int[], Integer> HM, int[] key, int v){
		if ( HM.containsKey(key) ) {
			if (v < HM.get(key)) return;
		}
		HM.put(key, v);
	}

	public static void main(String[] args) {
		new Main();
	}
}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte()) return buffer[ptr++];
		else return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) nl;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.Vector;

/**
 * sp86
 */

class Tasd {
    public int x,y,num;


}

public class sp86 {

    static int[][]arr=new int[2001][2001];
    static int[]arr2=new int[2001];
    static int[]ar=new int[6001];
    static int cn;
    public static void main(String[] args) {
        for(int i=0;i<2001;i++)
            Arrays.fill(arr[i],-1);
        int ak,aj;
        ak=aj=0;
        Scanner sc= new Scanner(System.in);
        cn=sc.nextInt();
        for(int i=1;i<=3*cn;i++)ar[i]=sc.nextInt();
        arr[ar[1]][ar[2]]=0;
        arr[ar[2]][ar[1]]=0;
        arr2[ar[1]]=0;
        arr2[ar[2]]=0;

        for(int i=1;i<cn;i++){
            Vector<Tasd> ts =new Vector<Tasd>();
            int[]ar2=new int[4];
            for(int j=0;j<3;j++)ar2[j+1]=ar[3*i+j];
            if(ar2[1]==ar2[2]&&ar2[2]==ar2[3]){ak++;continue;}
            for(int j=0;j<3;j++){
                if(ar2[(j+1)%3+1]==ar2[(j+2)%3+1]){
                    int k=ar2[(j+1)%3+1];
                    for(int t=1;t<=cn;t++){
                        if(arr[k][t]==-1)continue;
                        Tasd z=new Tasd();
                        z.x=ar2[j+1];
                        z.y=t;
                        z.num=arr[k][t]+1;
                        ts.add(z);


                    }
                }
                if(arr[ar2[j+1]][ar2[j+1]]!=-1){
                    Tasd z=new Tasd();
                    z.x=ar2[(j+1)%3+1];
                    z.y=ar2[(j+2)%3+1];
                    z.num=arr[ar2[j+1]][ar2[j+1]]+1;
                    ts.add(z);
                }
                for(int t=1;t<=cn;t++){
                    if(arr2[t]==-1)continue;
                    Tasd z=new Tasd();
                    z.x=t;
                    z.y=ar2[j+1];
                    z.num=arr2[t];
                    ts.add(z);


                }
                Tasd z=new Tasd();
                z.x=ar2[(j+1)%3+1];
                z.y=ar2[(j+2)%3+1];
                z.num=aj;
                ts.add(z);
            }
            for(Tasd z:ts){
               // System.out.println(z.x+" "+z.y+" "+z.num);
                aj=Math.max(aj,z.num);
                arr[z.x][z.y]=Math.max(arr[z.x][z.y],z.num);
                arr[z.y][z.x]=Math.max(arr[z.y][z.x],z.num);
                arr2[z.x]=Math.max(arr2[z.x],z.num);
                arr2[z.y]=Math.max(arr2[z.y],z.num);
            }
        }
        aj=Math.max(aj,arr[ar[3*cn]][ar[3*cn]]+1);
        int ans=ak+aj;
        System.out.println(ans);

    }
}

