public class Main {
    private static final boolean N_CASE = false;

    private void solve() {
        int N = sc.nextInt();
        int M = N * 3;
        int[] A = sc.nextIntArray(M);

        int[][] dp = new int[N + 1][N + 1];
        fill(dp, -1);
        dp[A[0]][A[1]] = dp[A[1]][A[0]] = 0;

        int[] local = new int[N + 1];
        fill(local, - 1);

        int ans = 0;
        int add = 0;
        for (int i = 2; i < M; i += 3) {
            if (i == M - 1) {
                if (dp[A[i]][A[i]] != -1) {
                    ans = Math.max(ans, dp[A[i]][A[i]] + 1);
                }
            } else {
                if (A[i] == A[i + 1] && A[i] == A[i + 2]) {
                    ++add;
                    continue;
                }

                List<int[]> update = new ArrayList<>();
                for (int j = 0; j < 3; ++j) {
                    int t1 = i + j;
                    if (dp[A[t1]][A[t1]] != -1) {
                        int t2 = i + ((j + 1) % 3);
                        int t3 = i + ((j + 2) % 3);
                        update.add(new int[] { A[t2], A[t3], dp[A[t1]][A[t1]] + 1 });
                    }
                }

                for (int j1 = 0; j1 < 3; ++j1) {
                    int t1 = i + j1;
                    for (int j2 = j1 + 1; j2 < 3; ++j2) {
                        int j3 = 3 - j1 - j2;
                        int t2 = i + j2;
                        int t3 = i + j3;

                        if (A[t1] == A[t2]) {
                            for (int k = 1; k <= N; ++k) {
                                if (dp[k][A[t1]] != -1) {
                                    update.add(new int[] { k, A[t3], dp[k][A[t1]] + 1 });
                                }
                            }
                        }

                        update.add(new int[] { A[t1], A[t2], 0 });
                    }

                    for (int k = 1; k <= N; ++k) {
                        update.add(new int[] { k, A[t1], local[k] });
                    }
                }

                for (int[] u : update) {
                    dp[u[0]][u[1]] = dp[u[1]][u[0]] = Math.max(dp[u[0]][u[1]], u[2]);
                    local[u[0]] = Math.max(local[u[0]], dp[u[0]][u[1]]);
                    local[u[1]] = Math.max(local[u[1]], dp[u[0]][u[1]]);
                    ans = Math.max(dp[u[0]][u[1]], ans);
                }
            }
        }

        out.println(ans + add);
    }

    private void run() {
        int T = N_CASE ? sc.nextInt() : 1;
        for (int t = 0; t < T; ++t) {
            solve();
        }
    }

