import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve() {
        int n = in.nextInt();
        int[] p = in.nextIntArray(n * 3);
        for (int i = 0; i < n * 3; i++) {
            p[i]--;
        }
        int[] dp = new int[n * n];
        int base = 0;
        int max = 0;
        int[] xMax = new int[n];
        int[] yMax = new int[n];
        for (int i = 0; i < n; i++) {
            xMax[i] = -iinf;
            yMax[i] = -iinf;
            for (int j = 0; j < n; j++) {
                dp[i * n + j] = -iinf;
            }
        }
        dp[p[0] * n + p[1]] = 0;
        dp[p[1] * n + p[0]] = 0;
        xMax[p[0]] = 0;
        yMax[p[0]] = 0;
        xMax[p[1]] = 0;
        yMax[p[1]] = 0;
        for (int i = 0; i < n - 1; i++) {
            if (p[i * 3 + 2] == p[i * 3 + 3] && p[i * 3 + 3] == p[i * 3 + 4]) {
                base++;
                continue;
            }
            Map<Integer, Integer> changes = new HashMap<>();
            int oldMax = max;
            int[] oldXMax = Arrays.copyOf(xMax, n);
            int[] oldYMax = Arrays.copyOf(yMax, n);
            for (int j = 0; j < 3; j++) {
                int a = p[i * 3 + 2 + (0 + j) % 3];
                int b = p[i * 3 + 2 + (1 + j) % 3];
                int c = p[i * 3 + 2 + (2 + j) % 3];
                changes.merge(a * n + b, Math.max(dp[a * n + b], oldMax), Integer::max);
                if (a == b) {
                    for (int k = 0; k < n; k++) {
                        int v = Math.max(Math.max(dp[k * n + c], dp[c * n + k]), Math.max(dp[a * n + k], dp[k * n + a]) + 1);
                        changes.merge(k * n + c, v, Integer::max);
                        changes.merge(c * n + k, v, Integer::max);
                        max = Math.max(max, v);
                        xMax[k] = Math.max(xMax[k], v);
                        xMax[c] = Math.max(xMax[c], v);
                        yMax[k] = Math.max(xMax[k], v);
                        yMax[c] = Math.max(xMax[c], v);
                    }
                }
                int v = Math.max(Math.max(dp[a * n + b], dp[b * n + a]), dp[c * n + c] + 1);
                changes.merge(a * n + b, v, Integer::max);
                changes.merge(b * n + a, v, Integer::max);
                max = Math.max(max, v);
                xMax[a] = Math.max(xMax[a], v);
                xMax[b] = Math.max(xMax[b], v);
                yMax[a] = Math.max(yMax[a], v);
                yMax[b] = Math.max(yMax[b], v);
                for (int k = 0; k < n; k++) {
                    v = Math.max(oldXMax[k], oldYMax[k]);
                    changes.merge(k * n + a, v, Integer::max);
                    changes.merge(a * n + k, v, Integer::max);
                    xMax[k] = Math.max(xMax[k], v);
                    xMax[a] = Math.max(xMax[a], v);
                    yMax[k] = Math.max(yMax[k], v);
                    yMax[a] = Math.max(yMax[a], v);
                }
            }
            for (Map.Entry<Integer, Integer> entry : changes.entrySet()) {
                dp[entry.getKey()] = entry.getValue();
            }
        }
        dp[p[n * 3 - 1] * (n + 1)]++;
        out.println(base + Math.max(dp[p[n * 3 - 1] * (n + 1)], max));
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class IntPair implements Comparable<IntPair> {
    int first;
    int second;

    IntPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof IntPair)) {
            return false;
        }
        IntPair that = (IntPair)o;
        return first == that.first && second == that.second;
    }

    @Override
    public int hashCode() {
        return first * 31 + second;
    }

    @Override
    public int compareTo(IntPair o) {
        return first == o.first ? Integer.compare(second, o.second) : Integer.compare(first, o.first);
    }

    @Override
    public String toString() {
        return String.format("[%s, %s]", first, second);
    }
}

