    private void solve() {
        int N = sc.nextInt();
        int M = N * 3;
        int[] A = sc.nextIntArray(M);

        int[] last = new int[N + 1];
        for (int i = 0; i < M; i++) {
            last[A[i]] = i;
        }

        int ans = 0;
        for (int i = 0; i < M; i += 3) {
            Map<Integer, Integer> cnt = new HashMap<>();
            if (i + 5 <= M) {
                int t = -1;
                for (int j = 0; j < 5; ++j) {
                    cnt.put(A[i + j], cnt.getOrDefault(A[i + j], 0) + 1);
                    if (cnt.get(A[i + j]) == 3) {
                        t = A[i + j];
                    }
                }

                List<Integer> tmp = new ArrayList<>();
                if (t != -1) {
                    for (int j = 0; j < 5; ++j) {
                        if (A[i + j] != t) {
                            tmp.add(A[i + j]);
                        }
                    }

                    A[i + 3] = tmp.get(0);
                    A[i + 4] = tmp.get(1);
                    ++ans;
                } else {
                    List<int[]> l = new ArrayList<>();
                    for (int j = 0; j < 5; ++j) {
                        l.add(new int[] { last[A[i + j]], A[i + j]});
                    }
                    l.sort(Comparator.comparingInt(v -> v[0]));

                    A[i + 3] = l.get(0)[1];
                    A[i + 4] = l.get(1)[1];
                }
            }
        }

        if (M >= 3) {
            if (A[M - 1] == A[M - 2] && A[M - 3] == A[M - 2]) {
                ++ans;
            }
        }
        out.println(ans);
