			for (int i = 0; i < n; i++)	
			for (int j = 0; j < n; j++)dp[i][j]=-1000000000;
			var max=Enumerate(n, x => -1000000000);
			max[a[0]]=max[a[1]]=0;
			dp[a[0]][a[1]]=dp[a[1]][a[0]]=0;
			var res=0;
			for (int k = 2; k+3 < a.Length; k+=3){
				var u=new int[]{a[k],a[k+1],a[k+2]};
				var Q=new List<(int,int,int)>();
				Array.Sort(u);
				if(u[0]==u[2]) { res++; continue;}
				else if(u[0]==u[1]){
					for (int i = 0; i < n; i++)
						Q.Add((i,u[2],dp[i][u[0]]+1));

				}else if(u[1]==u[2]){
					for (int i = 0; i < n; i++)
						Q.Add((i,u[0],dp[i][u[2]]+1));
				}
				var ma  = max.Max();
				Q.Add((u[0],u[1],Max(ma,dp[u[2]][u[2]]+1)));
				Q.Add((u[0],u[2],Max(ma,dp[u[1]][u[1]]+1)));
				Q.Add((u[2],u[1],Max(ma,dp[u[0]][u[0]]+1)));
				for (int i = 0; i < n; i++)
					for (int id = 0; id < 3; id++)
					Q.Add((i,u[id],max[i]));
				foreach (var (x,y,v) in Q)
				{
					dp[x][y]=dp[y][x]=Max(dp[x][y],v);
					max[x]=Max(max[x],v);
					max[y]=Max(max[y],v);
				}
			}
			var ans=max.Max();
			ans=Max(ans,dp[a.Last()][a.Last()]+1);
			ans+=res;
