class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var a = sc.IntArr.Select(x => x - 1).ToArray();
        var dp = new int[n][];
        var max = new int[n];
        for (int i = 0; i < n; i++)
        {
            dp[i] = new int[n];
            for (int j = 0; j < n; j++)
            {
                dp[i][j] = -M;
            }
            max[i] = -M;
        }
        dp[a[0]][a[1]] = 0;
        dp[a[1]][a[0]] = 0;
        max[a[0]] = 0;
        max[a[1]] = 0;
        int pl = 0;
        for (int i = 0; i < n - 1; i++)
        {
            int[] b = { a[2 + i * 3], a[2 + i * 3 + 1], a[2 + i * 3 + 2] };
            {
                // 0
                if (b[0] == b[1] && b[1] == b[2]) {
                    ++pl;
                    continue;
                }
            }
            var nex1 = new int[3][];
            {
                // 1
                for (int j = 0; j < 3; j++)
                {
                    nex1[j] = new int[n];
                    int o = b[(j + 1) % 3] == b[(j + 2) % 3] ? b[(j + 1) % 3] : -1;
                    for (int k = 0; k < n; k++)
                    {
                        nex1[j][k] = max[k];
                        if (o != -1) {
                            nex1[j][k] = Math.Max(nex1[j][k], dp[o][k] + 1);
                        }
                    }
                }
            }
            var nex2 = new int[3];
            {
                // 2
                for (int j = 0; j < 3; j++)
                {
                    int b1 = b[(j + 1) % 3];
                    int b2 = b[(j + 2) % 3];
                    for (int k = 0; k < n; k++)
                    {
                        nex2[j] = Math.Max(nex2[j], max[k]);
                    }
                    nex2[j] = Math.Max(nex2[j], dp[b[j]][b[j]] + 1);
                }
            }
            {
                // 1
                for (int j = 0; j < 3; j++)
                {
                    for (int k = 0; k < n; k++)
                    {
                        dp[b[j]][k] = Math.Max(dp[b[j]][k], nex1[j][k]);
                        dp[k][b[j]] = Math.Max(dp[k][b[j]], nex1[j][k]);
                        max[b[j]] = Math.Max(max[b[j]], dp[b[j]][k]);
                        max[k] = Math.Max(max[k], dp[b[j]][k]);
                    }
                }
            }
            {
                // 2
                for (int j = 0; j < 3; j++)
                {
                    int b1 = b[(j + 1) % 3];
                    int b2 = b[(j + 2) % 3];
                    dp[b1][b2] = Math.Max(dp[b1][b2], nex2[j]);
                    dp[b2][b1] = Math.Max(dp[b2][b1], nex2[j]);
                    max[b1] = Math.Max(max[b1], dp[b1][b2]);
                    max[b2] = Math.Max(max[b2], dp[b1][b2]);
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (i == j && i == a.Last()) {
                    ans = Math.Max(ans, dp[i][j] + 1);
                }
                else {
                    ans = Math.Max(ans, dp[i][j]);
                }
            }
        }
        Prt(ans + pl);

    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
    public int CompareTo(pair<T, U> a) {
        int c = Comparer<T>.Default.Compare(v1, a.v1);
        return c != 0 ? c : Comparer<U>.Default.Compare(v2, a.v2);
    }
    public override string ToString() => v1 + " " + v2;
    public void Deconstruct(out T a, out U b) { a = v1; b = v2; }
}
