using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public static class Solution
{
    static void ChMax(ref int cur, int next)
    {
        if (cur < next)
        {
            cur = next;
        }
    }

    public static int Solve(int N, int[] A)
    {
        var dp = new int[N, N];
        var max = 0;
        var kMax = Enumerable.Repeat(int.MinValue, N).ToArray();
        var chain = 0;

        void ChMax(int k, int l, int val)
        {
            Solution.ChMax(ref dp[k, l], val);
            Solution.ChMax(ref dp[l, k], val);
            Solution.ChMax(ref max, val);
            Solution.ChMax(ref kMax[k], val);
            Solution.ChMax(ref kMax[l], val);
        }

        for (int y = 0; y < N; y++)
        {
            for (int x = 0; x < N; x++)
            {
                dp[y, x] = int.MinValue;
            }
        }
        ChMax(A[0], A[1], 0);

        for (int i = 2; i < 3 * N - 1; i += 3)
        {
            var upList = new List<(int k, int l, int v)>();
            // k,l,p,p,p -> k,l
            if (A[i] == A[i + 1] && A[i] == A[i + 2])
            {
                chain++;
                continue;
            }

            // k,p,p,p,q -> k,q
            {
                var p = -1;
                var q = -1;
                if (A[i] == A[i + 1])
                {
                    p = A[i];
                    q = A[i + 2];
                }
                else if (A[i + 1] == A[i + 2])
                {
                    p = A[i + 1];
                    q = A[i];
                }
                else if (A[i] == A[i + 2])
                {
                    p = A[i];
                    q = A[i + 1];
                }
                if (p != -1)
                {
                    for (int k = 0; k < N; k++)
                    {
                        upList.Add((k, q, dp[p, k] + 1));
                    }
                }
            }

            for (int j = 0; j < 3; j++)
            {
                var p = A[i + j];
                var q = A[i + (j + 1) % 3];
                var r = A[i + (j + 2) % 3];
                // p,p,p,q,r -> q,r
                upList.Add((q, r, dp[p, p] + 1));

                // k,l,p,q,r -> p,q or q,r or r,p
                upList.Add((p, q, max));

                // k,l,p,q,r -> k,p or k,q or k,r
                for (int k = 0; k < N; k++)
                {
                    upList.Add((k, p, kMax[k]));
                }
            }

            foreach (var kv in upList)
            {
                ChMax(kv.k, kv.l, kv.v);
            }
        }

        var last = A.Last();
        dp[last, last]++;
        Solution.ChMax(ref max, dp[last, last]);
        chain += max;

        return chain;
    }

    public static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = Console.ReadLine().Split(' ').Select(x => int.Parse(x) - 1).ToArray();
        var chain = Solve(N, A);
        Console.WriteLine(chain);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using CompLib.Util;

public class Program
{
    int N;
    int[] A;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        for (int i = 0; i < 3 * N; i++)
        {
            A[i]--;
        }

        // i,jが残ってる最大
        var dp = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dp[i, j] = int.MinValue;
            }
        }


        int cnt = 0;
        dp[A[0], A[1]] = 0;
        dp[A[1], A[0]] = 0;

        // dp[i,j]の最大値
        int max = 0;

        // dp[i]の最大値
        int[] max2 = new int[N];
        for (int i = 0; i < N; i++)
        {
            max2[i] = int.MinValue;
        }

        max2[A[0]] = 0;
        max2[A[1]] = 0;

        for (int i = 0; i < N - 1; i++)
        {
            // 更新
            var ls = new List<(int j, int k, int v)>();
            int[] p = new int[] { A[i * 3 + 2], A[i * 3 + 3], A[i * 3 + 4] };

            // 3つとも同じ
            if (p[0] == p[1] && p[1] == p[2])
            {
                cnt++;
                continue;
            }

            for (int t = 0; t < 3; t++)
            {
                Swap(ref p[0], ref p[t]);
                // 2ついっしょ
                if (p[1] == p[2])
                {
                    for (int k = 0; k < N; k++)
                    {
                        if (dp[p[1], k] != int.MinValue)
                        {
                            ls.Add((k, p[0], dp[p[1], k] + 1));
                            ls.Add((p[0], k, dp[p[1], k] + 1));
                        }
                    }
                }

                // p[0]と現在の2つで作る
                if (dp[p[0], p[0]] != int.MinValue)
                {
                    ls.Add((p[1], p[2], dp[p[0], p[0]] + 1));
                    ls.Add((p[2], p[1], dp[p[0], p[0]] + 1));
                }

                // 作らない 現在の2つ、p[0]を使う
                ls.Add((p[1], p[2], max));
                ls.Add((p[2], p[1], max));

                // 作らない p[1],p[2],前のやつの片方使う
                for (int k = 0; k < N; k++)
                {
                    if (max2[k] != int.MinValue)
                    {
                        ls.Add((p[0], k, max2[k]));
                        ls.Add((k, p[0], max2[k]));
                    }
                }

                // 作らない p3つ使う
                // 使い回す
            }

            // 更新
            foreach (var tuple in ls)
            {
                dp[tuple.j, tuple.k] = Math.Max(dp[tuple.j, tuple.k], tuple.v);
                max2[tuple.j] = Math.Max(max2[tuple.j], tuple.v);
                max = Math.Max(max, tuple.v);
            }
        }

        int ans = int.MinValue;
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                if (dp[i, j] == int.MinValue) continue;
                var p = dp[i, j];
                if (i == j && j == A[3 * N - 1]) p++;
                ans = Math.Max(ans, p + cnt);
            }
        }

        Console.WriteLine(ans);
    }

    void Swap(ref int l, ref int r)
    {
        int t = l;
        l = r;
        r = t;
    }

    public static void Main(string[] args) => new Program().Solve();
}

