            } else {
                // match case
                if (card1 == card2) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card3, j, dp[card1, j] + 1);
                    }
                }
                if (card2 == card3) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card1, j, dp[card2, j] + 1);
                    }
                }
                if (card1 == card3) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card2, j, dp[card3, j] + 1);
                    }
                }
                UpdatePlan(card1, card2, Math.Max(dp[card3, card3] + 1, maxValue));
                UpdatePlan(card2, card3, Math.Max(dp[card1, card1] + 1, maxValue));
                UpdatePlan(card3, card1, Math.Max(dp[card2, card2] + 1, maxValue));
                // other case
                for (int j = 0; j < n; j++) {
                    // (j,k) c1 c2 c3 --> (k,c2,c3)_(j, c1)
                    UpdatePlan(j, card1, max[j]);
                    UpdatePlan(j, card2, max[j]);
                    UpdatePlan(j, card3, max[j]);
                }

                foreach (var (x, y, value) in plan) {
                    if (dp[x, y] < value) {
                        dp[y, x] = dp[x, y] = value;
                        max[x].UpdateMax(value);
                        max[y].UpdateMax(value);
                        maxValue.UpdateMax(value);
                    }
                }
            }
        }
        int ans = 0;
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (j == k && k == a[a.Length - 1]) {
                    ans = Math.Max(ans, dp[j, k] + 1);
                } else {
                    ans = Math.Max(ans, dp[j, k]);
                }
            }
        }
        cout.WriteLine(ans + baseNumber);
    }

    private static void Fill(int n, int[,] dp, int value) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i, j] = value;
            }
        }
    }
}

