            plan.Add((x, y));
            if (x != y) {
                update[y, x].UpdateMax(value);
                plan.Add((y, x));
            }
        }

        for (int i = 0; i < n - 1; i++) {
            int card1 = a[3 * i + 2];
            int card2 = a[3 * i + 3];
            int card3 = a[3 * i + 4];
            if (card1 == card2 && card2 == card3) {
                baseNumber++;
            } else {
                plan.Clear();
                // match case
                if (card1 == card2) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card3, j, dp[card1, j] + 1);
                    }
                }
                if (card2 == card3) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card1, j, dp[card2, j] + 1);
                    }
                }
                if (card1 == card3) {
                    for (int j = 0; j < n; j++) {
                        UpdatePlan(card2, j, dp[card3, j] + 1);
                    }
                }
                for (int j = 0; j < n; j++) {
                    UpdatePlan(card1, card2, dp[card3, card3] + 1);
                    UpdatePlan(card2, card3, dp[card1, card1] + 1);
                    UpdatePlan(card3, card1, dp[card2, card2] + 1);
                }
                // other case
                for (int j = 0; j < n; j++) {
                    UpdatePlan(j, card1, maxY[j]);
                    UpdatePlan(j, card2, maxY[j]);
                    UpdatePlan(j, card3, maxY[j]);
                    UpdatePlan(j, card1, maxX[j]);
                    UpdatePlan(j, card2, maxX[j]);
                    UpdatePlan(j, card3, maxX[j]);
                }

                UpdatePlan(card1, card2, maxValue);
                UpdatePlan(card2, card3, maxValue);
                UpdatePlan(card3, card1, maxValue);

                foreach (var (x, y) in plan) {
                    dp[x, y].UpdateMax(update[x, y]);
                    maxX[x].UpdateMax(dp[x, y]);
                    maxY[y].UpdateMax(dp[x, y]);
                    maxValue.UpdateMax(dp[x, y]);
                }
            }
        }
        int ans = 0;
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (j == k && k == a[a.Length - 1]) {
                    ans = Math.Max(ans, dp[j, k] + 1);
                } else {
                    ans = Math.Max(ans, dp[j, k]);
                }
            }
        }
        cout.WriteLine(ans + baseNumber);
    }

    private static void Fill(int n, int[,] dp, int value) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i, j] = value;
            }
        }
    }
