function main(){
  var n = next();
  var dp = xArray(-1,n,n), mx = 0, add = 0;
  var a = nexts(2).sort((a,b)=>a-b).map(a=>a-1);
  var q = [];
  var map = xArray(0,n);
  dp[a[0]][a[1]] = 0;
  map[a[0]]++, map[a[1]]++;
  for(var i = 1; i < n; i++){
    a = nexts(3).sort((a,b)=>a-b).map(a=>a-1);
    if(a[0] === a[2]){
      add++;
      continue;
    }
    q = [];
    solve(a[0],a[0],a[1],a[2]);
    if(a[0] !== a[1])solve(a[1],a[1],a[0],a[2]);
    else{
      for(var j = 0; j < a[0]; j++){
        solve(j,a[0],j,a[2]);
      }
      for(var j = a[0]+1; j < a[2]; j++){
        solve(a[0],j,j,a[2]);
      }
      for(var j = a[2]; j < n; j++){
        solve(a[0],j,a[2],j);
      }
    }
    if(a[1] !== a[2])solve(a[2],a[2],a[0],a[1]);
    else{
      for(var j = 0; j < a[0]; j++){
        solve(j,a[1],j,a[0]);
      }
      for(var j = a[0]; j < a[2]; j++){
        solve(j,a[2],a[0],j);
      }
      for(var j = a[2]+1; j < n; j++){
        solve(a[2],j,a[0],j);
      }
    }
    while(q.length){
      var w = q.pop(), v = q.pop(), u = q.pop();
      dp[u][v] = Math.max(dp[u][v], w);
    }
    for(var j = 0; j < 3; j++){
      var t = a[j];
      if(map[t] === 1)map[t] = 2, dp[t][t] = Math.max(0,dp[t][t]);
      else if(map[t] === 0){
        map[t] = 1;
        for(var k = 0; k < t; k++){
          if(map[k] === 0)continue;
          dp[k][t] = Math.max(0,dp[k][t]);
        }
        for(var k = t+1; k < n; k++){
          if(map[k] === 0)continue;
          dp[t][k] = Math.max(0,dp[t][k]);
        }
      }
    }
  }
  a = next()-1;
  solve(a,a,a,a);
  return mx+add;
  function solve(t,u,v,w){
    var x = Math.max(dp[v][w], dp[t][u]+1);
    q.push(v,w,x);
    mx = Math.max(mx,x);
  }
}

