      if(dp[x][y] < z)dp[x][y] = z;
    }
  }
  function solve1(u){
    f1(0,0,u,u);
    for(var i = 0; i < u; i++){
      f0(i,u,0,i);
    }
    for(var i = u; i <= n; i++){
      f0(u,i,0,i);
    }
  }
  function solve2(u,v){
    f0(u,v,0,0);
    f1(0,v,u,u);
    if(u < v){
      f1(0,u,v,v);
    }else{//u=v
      for(var i = 0; i < u; i++){
        f1(0,i,i,u);
      }
      for(var i = u; i <= n; i++){
        f1(0,i,u,i);
      }
    }
  }
  function solve3(u,v,w){
    f1(v,w,u,u);
    if(u < v){
      f1(u,w,v,v);
      if(v < w){
        f1(u,v,w,w);
      }else{//v=w
        for(var i = 0; i < u; i++){
          f1(i,u,i,w);
        }
        for(var i = u; i < w; i++){
          f1(u,i,i,w);
        }
        for(var i = w; i <= n; i++){
          f1(u,i,w,i);
        }
      }
    }else{//u=v
      f1(u,u,w,w);
      for(var i = 0; i < u; i++){
        f1(i,w,i,u);
      }
      for(var i = u; i < w; i++){
        f1(i,w,u,i);
      }
      for(var i = w; i <= n; i++){
        f1(w,i,u,i);
      }
    }
  }
  function f0(a,b,c,d){
    if(dp[a][b] < dp[c][d])q.push(dp[c][d],b,a);
  }
  function f1(a,b,c,d){
    if(dp[a][b] < dp[c][d]+1)q.push(dp[c][d]+1,b,a);
  }
}

