import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func out(x ...interface{}) {
	fmt.Println(x...)
}

var sc = bufio.NewScanner(os.Stdin)

func getInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func getInts(N int) []int {
	ret := make([]int, N)
	for i := 0; i < N; i++ {
		ret[i] = getInt()
	}
	return ret
}

func getString() string {
	sc.Scan()
	return sc.Text()
}

// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func lowerBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] >= x
	})
	return idx
}

func upperBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] > x
	})
	return idx
}

type pair struct {
	n, pos, v int
}

func main() {
	sc.Split(bufio.ScanWords)
	N := getInt()
	a := getInts(3 * N)
	m := make(map[int]int)
	p := make(map[int]int)
	for i := 0; i < len(a); i++ {
		m[a[i]]++
		p[a[i]] = i
	}

	ans := 0
	t := make([]pair, 5)
	for k := 0; k < N-1; k++ {
		pos := k * 3
		x := make(map[int]int)
		for i := 0; i < 5; i++ {
			v := a[pos+i]
			t[i] = pair{m[v], p[v], v}
			x[v]++
		}
		sort.Slice(t, func(i, j int) bool {
			if t[i].n == t[j].n {
				return t[i].pos < t[j].pos
			}
			return t[i].n > t[j].n
		})
		find := false
		val := -1
		for i, v := range x {
			if v == 3 {
				find = true
				ans++
				val = i
				break
			}
		}
		if find == true {
			for i, j := 0, pos+3; i < 5; i++ {
				if t[i].v != val {
					a[j] = t[i].v
					j++
				}
			}
		} else {
			for i := 0; i < 3; i++ {
				a[pos+3+i] = t[i].v
			}
		}
	}
	last := 3*N - 3
	if a[last] == a[last+1] && a[last] == a[last+2] {
		ans++
	}
	out(ans)
}

