function main(input) {
  input = input.split("\n");
  const N = parseInt(input[0]);
  const AList = input[1].split(' ').map(i => parseInt(i));
  let count = 0;
  const cardList = new Array(N).fill(0);

  function cut(num: number) {
    for (let idx = 0; idx < cardList.length; idx++) {
      cardList[idx] = Math.min(num, cardList[idx]);
    }
  }

  function inputOne(idx: number) {
    cardList[AList[idx] - 1]++;
  }

  function inputThree(idx: number) {
    let newList = [AList[idx], AList[idx + 1], AList[idx + 2]];
    newList = newList.sort();
    if (newList[0] === newList[1] && newList[1] === newList[2]) {
      count++;
      return;
    } else if (newList[0] == newList[1] || newList[1] === newList[2]) {
      if (cardList[newList[1] - 1] >= 1) {
        count++;
        cut(1);
        let another = newList[0];
        if (newList[0] === newList[1]) {
          another = newList[2];
        }
        cardList[another - 1]++;
        return;
      }
    }
    for (let num of newList) {
      if (cardList[num - 1] >= 2) {
        count++;
        cut(0);
        for (let _num of newList) {
          if (_num !== num) {
            cardList[_num - 1]++;
          }
        }
        break;
      }
    }
  }

  inputOne(0);
  inputOne(1);

  for (let i = 0; i < N - 1; i++) {
    //console.log(cardList, count);
    inputThree(2 + i * 3);
  }
  //console.log(cardList, count);


  if (cardList[AList[3 * N - 1] - 1] >= 2) {
    count++;
  }


  console.log('%d', count);
  return 0;
}

