void main()
{
	auto N = RD!int;
	auto A = RDA(-1);

	auto dp = new int[int][](N);
	dp[0][A[0]*N+A[1]] = 0;
	long last;
	foreach (i; 0..N-1)
	{
		int[int] cnt_b;
		foreach (j; 0..3)
		{
			auto x = A[i*3+2+j];
			++cnt_b[x];
		}
		foreach (key; dp[i].keys)
		{
			if (dp[i][key] < last - 1) continue;
			auto cnt = cnt_b.dup;
			auto x = key / N;
			auto y = key % N;
			++cnt[x]; ++cnt[y];

			bool ok;
			foreach (key2; cnt.keys)
			{
				if (cnt[key2] >= 3)
				{
					ok = true;
					cnt[key2] -= 3;
				}
			}
			if (ok)
			{
				int[] next;
				foreach (key2; cnt.keys)
				{
					foreach (_; 0..cnt[key2])
					{
						next ~= key2;
					}
				}
				if (next[0] > next[1])
					swap(next[0], next[1]);
				auto nKey = next[0]*N + next[1];
				auto c = dp[i][key] + 1;
				dp[i+1][nKey] = c;
				last.chmax(c);
				continue;
			}

			auto arr = A[i*3+2..i*3+5].dup;
			arr ~= cast(int)x;
			arr ~= cast(int)y;
			foreach (j; 0..4)
			{
				foreach (k; j+1..5)
				{
					int[] next = [arr[j], arr[k]];
					if (next[0] > next[1])
						swap(next[0], next[1]);
					auto nKey = next[0]*N + next[1];
					auto c = dp[i][key];
					dp[i+1][nKey] = c;
					last.chmax(c);
				}
			}
		}
	}

	long ans;
	foreach (key; dp[N-1].keys)
	{
		auto x = key / N;
		auto y = key % N;
		if (x == y && x == A[$-1])
			++dp[N-1][key];
		ans.chmax(dp[N-1][key]);
	}

	writeln(ans);
	stdout.flush;
	debug readln;
}

