void solve(long N, long[] A)
{
    alias T = Tuple!(long, long, long, long);
    DList!T Q;
    Q.insert(T(0, min(A[0], A[1]), max(A[0], A[1]), 0));
    long ans;
    bool[T] visited;
    while (!Q.empty)
    {
        auto t = Q.front;
        Q.removeFront();
        if (t in visited)
            continue;
        visited[t] = true;
        auto i = t[0];
        auto a = t[1];
        auto b = t[2];
        auto s = t[3];
        dprint(i, a, b, s);
        if (i == 3 * N)
        {
            ans = ans.max(s);
            continue;
        }
        auto v = [
            a, b, !(i + 2 < 3 * N) ? -1 : A[i + 2], !(i + 3 < 3 * N) ? -2 : A[i + 3],
            !(i + 4 < 3 * N) ? -3 : A[i + 4]
        ];
        v.sort();
        if ((v[0] == v[1] && v[1] == v[2]) || (v[2] == v[3] && v[3] == v[4]))
        {
            if (v[0] == v[1] && v[1] == v[2])
                Q.insert(T(i + 3, v[3], v[4], s + 1));
            if (v[2] == v[3] && v[3] == v[4])
                Q.insert(T(i + 3, v[0], v[1], s + 1));
            continue;
        }
        auto comb = [0, 0, 1, 1, 1];
        do
        {
            long[] r, p;
            foreach (j, c; comb)
            {
                if (c == 0)
                    r ~= v[j];
                if (c == 1)
                    p ~= v[j];
            }
            r.sort();
            Q.insert(T(i + 3, r[0], r[1], s));
        }
        while (nextPermutation(comb));
    }
    writeln(ans);
}

