string FMT_F = "%.10f";

static File _f;
void file_io(string fn) { _f = File(fn, "r"); }
static string[] s_rd;
T _RD(T = long)() { while(!s_rd.length) s_rd = readln.chomp.split; string res = s_rd[0]; s_rd.popFront; return res.to!T; }
T _RD(T = long)(File f) { while(!s_rd.length) s_rd = f.readln.chomp.split; string res = s_rd[0]; s_rd.popFront; return res.to!T; }
T[] _RDA(T = long)(T fix = 0) { auto r = readln.chomp.split.to!(T[]); r[] += fix; return r; }
T[] _RDA(T = long)(File f, T fix = 0) { auto r = f.readln.chomp.split.to!(T[]); r[] += fix; return r; }
T RD(T = long)() { if (_f.isOpen) return _RD!T(_f); else return _RD!T; }
T[] RDA(T = long)(T fix = 0) { if (_f.isOpen)  return _RDA!T(_f, fix); else return _RDA!T(fix); }

size_t[] MAKE_IDX(alias less = "a < b", Range)(Range range) { auto idx = new size_t[](range.length); makeIndex!(less)(range, idx); return idx;}
size_t MIN_POS(alias less = "a < b", Range)(Range range) { auto r = minPos!(less)(range); return range.length - r.length; }

void chmin(T)(ref T x, T y) { x = min(x, y); } void chmax(T)(ref T x, T y) { x = max(x, y); }
bool inside(T)(T x, T b, T e) { return x >= b && x < e; }
T lcm(T)(T x, T y) { return x * (y / gcd(x, y)); }

//long mod = 10^^9 + 7;
long mod = 998_244_353;
//long mod = 1_000_003;
void moda(T)(ref T x, T y) { x = (x + y) % mod; }
void mods(T)(ref T x, T y) { x = ((x + mod) - (y % mod)) % mod; }
void modm(T)(ref T x, T y) { x = (x * y) % mod; }
void modpow(T)(ref T x, T y) { if (!y) { x = 1; return; } auto t = x; x.modpow(y>>1); x.modm(x); if (y&1) x.modm(t); }
void modd(T)(ref T x, T y) { y.modpow(mod - 2); x.modm(y); }

void main()
{
	auto N = RD!int;
	auto A = RDA(-1);

	auto dp = new int[int][](N);
	dp[0][A[0]*N+A[1]] = 0;
	long last;
	foreach (i; 0..N-1)
	{
		int[int] cnt_b;
		foreach (j; 0..3)
		{
			auto x = A[i*3+2+j];
			++cnt_b[x];
		}
		foreach (key; dp[i].keys)
		{
			if (dp[i][key] < last - 1) continue;
			auto cnt = cnt_b.dup;
			auto x = key / N;
			auto y = key % N;
			++cnt[x]; ++cnt[y];

			bool ok;
			foreach (key2; cnt.keys)
			{
				if (cnt[key2] >= 3)
				{
					ok = true;
					cnt[key2] -= 3;
				}
			}
			if (ok)
			{
				int[] next;
				foreach (key2; cnt.keys)
				{
					foreach (_; 0..cnt[key2])
					{
						next ~= key2;
					}
				}
				if (next[0] > next[1])
					swap(next[0], next[1]);
				auto nKey = next[0]*N + next[1];
				auto tmp = dp[i+1].get(nKey, 0);
				tmp.chmax(dp[i][key] + 1);
				dp[i+1][nKey] = tmp;
				last.chmax(tmp);
				continue;
			}

			auto arr = A[i*3+2..i*3+5].dup;
			arr ~= cast(int)x;
			arr ~= cast(int)y;
			foreach (j; 0..4)
			{
				foreach (k; j+1..5)
				{
					int[] next = [arr[j], arr[k]];
					if (next[0] > next[1])
						swap(next[0], next[1]);
					auto nKey = next[0]*N + next[1];
					auto tmp = dp[i+1].get(nKey, 0);
					tmp.chmax(dp[i][key]);
					dp[i+1][nKey] = tmp;
					last.chmax(tmp);
				}
			}
		}
	}

	long ans;
	foreach (key; dp[N-1].keys)
	{
		auto x = key / N;
		auto y = key % N;
		if (x == y && x == A[$-1])
			++dp[N-1][key];
		ans.chmax(dp[N-1][key]);
	}

	writeln(ans);
	stdout.flush;
	debug readln;
}

