    tss[i][] = -1;
  tss.get(as[0], as[1]) = 0;

  long maxV = 0;
  long[] maxVs = new long[N];
  maxVs[] = -1;
  maxVs[as[0]] = 0;
  maxVs[as[1]] = 0;

  long[long] aa;

  long cnt = 0;

  foreach (d; 0 .. N - 1) {
    aa = null;

    long[] xs = as[3 * d + 2 .. 3 * d + 5];
    xs.sort!"a<b";

    foreach (i, x; xs) {
      long y = xs[(i + 1) % 3];
      long z = xs[(i + 2) % 3];
      // use x
      aa.setMax(key(y, z), maxV);
      if (tss.get(x, x) >= 0) {
        aa.setMax(key(y, z), tss.get(x, x) + 1);
      }
    }

    foreach (perm; 3.iota.permutations) {
      if (perm[0] > perm[1])
        continue;
      long x = xs[perm[0]];
      long y = xs[perm[1]];
      long z = xs[perm[2]];
      // use x, y
      foreach (a; 0 .. N) {
        if (maxVs[a] < 0)
          continue;
        aa.setMax(key(a, z), maxVs[a]);
      }
      if (x == y) {
        foreach (a; 0 .. N) {
          if (tss.get(a, x) >= 0) {
            aa.setMax(key(a, z), tss.get(a, x) + 1);
          }
        }
      }
    }

    // aa.byKeyValue.map!(a => format!"(%s, %s, %s)"(a.key / N, a.key % N, a.value)).join(", ")
    //   .writeln;

    if (xs[0] == xs[1] && xs[1] == xs[2]) {
      cnt++;
    }

    foreach (k, v; aa) {
      long u = v;
      if (xs[0] == xs[1] && xs[1] == xs[2]) {
        u--;
      }
      maxV.ch!max(tss.get(k / N, k % N).ch!max(u));
      maxVs[k / N].ch!max(u);
      maxVs[k % N].ch!max(u);
    }

  }

  foreach (x; 0 .. N)
    foreach (y; 0 .. N) {
      long z = as.back;
      if (tss[x][y] < 0)
        continue;
      if (x == y && y == z) {
        tss[x][y]++;
      }
    }

  long ans = 0;
  foreach (x; 0 .. N)
    foreach (y; 0 .. N) {
      if (tss[x][y] < 0)
        continue;
      ans.ch!max(tss[x][y] + cnt);
    }

  ans.writeln;
}

