long setMax(ref long[long] aa, long k, long v) {
  if (k in aa) {
    aa[k].ch!max(v);
  } else {
    aa[k] = v;
  }
  return aa[k];
}

void main() {
  long N;
  scanln(N);
  long[] as = readln.split
    .to!(long[])
    .map!"a-1"
    .array;

  long key(long x, long y) {
    if (x > y)
      swap(x, y);
    return x * N + y;
  }

  long[long] aa, bb;
  aa[key(as[0], as[1])] = 0;
  long maxV = 0;
  long[] maxVs = new long[N];
  maxVs[] = -1;

  long cnt = 0;

  foreach (d; 0 .. N - 1) {
    bb = null;

    long[] xs = as[3 * d + 2 .. 3 * d + 5];
    xs.sort!"a<b";

    foreach (i, x; xs) {
      long y = xs[(i + 1) % 3];
      long z = xs[(i + 2) % 3];
      // use x
      bb.setMax(key(y, z), maxV);
      if (key(x, x) in aa) {
        bb.setMax(key(y, z), aa[key(x, x)] + 1);
      }
    }

    foreach (perm; 3.iota.permutations) {
      if (perm[0] > perm[1])
        continue;
      long x = xs[perm[0]];
      long y = xs[perm[1]];
      long z = xs[perm[2]];
      // use x, y
      foreach (a; 0 .. N) {
        if (maxVs[a] < 0)
          continue;
        bb.setMax(key(a, z), maxVs[a]);
      }
      if (x == y) {
        foreach (a; 0 .. N) {
          if (key(a, x) in aa) {
            bb.setMax(key(a, z), aa[key(a, x)] + 1);
          }
        }
      }
    }

    // bb.byKeyValue.map!(a => format!"(%s, %s, %s)"(a.key / N, a.key % N, a.value)).join(", ")
    //   .writeln;

    if (xs[0] == xs[1] && xs[1] == xs[2]) {
      cnt++;
    }

    foreach (k, v; bb) {
      long u = v;
      if (xs[0] == xs[1] && xs[1] == xs[2]) {
        u--;
      }
      maxV.ch!max(aa.setMax(k, u));
      maxVs[k / N].ch!max(u);
      maxVs[k % N].ch!max(u);
    }

  }

  foreach (k, v; aa) {
    long x = k / N;
    long y = k % N;
    long z = as.back;
    if (x == y && y == z) {
      aa[k]++;
    }
  }

  aa.byValue
    .map!(v => v + cnt)
    .reduce!max
    .writeln;
}

