        new_deque = deque()
        temp2 = [mylist.popleft() for i in range(3)]
        while dq:
            temp = dq.popleft()
            count = Counter(temp+temp2).most_common()
            if count[0][1] >= 3:
                templ=[]
                for key, value in count:
                    if value >= 3:
                        value -= 3
                    for j in range(value):
                        templ.append(key)
                new_deque = deque()
