from functools import lru_cache
from itertools import combinations

def solve():
    N = int(input())
    A = [int(i) for i in input().strip().split()]
    @lru_cache(None)
    def dp(a, b, i):
        if i == 3 * N - 1:
            return 1 if a == b == A[i] else 0

        av = [a, b, A[i], A[i + 1], A[i + 2]]
        av.sort()

        if av[0] == av[1] == av[2]:
            return 1 + dp(av[3], av[4], i + 3)
        elif av[2] == av[3] == av[4]:
            return 1 + dp(av[0], av[1], i + 3)

        ans = 0
        for com in combinations(range(5), 3):
            left = [av[i] for i in range(5) if not i in com]
            ans = max(ans, dp(left[0], left[1], i + 3))
        return ans  
    return dp(A[0], A[1], 2)


