            for _ in range(5):
                A.pop()
            for k, v in reversed(c.most_common()):
                for _ in range(v):
                    A.append(k)
        b = set()
        for _ in range(3):
            b.add(A.pop())
        if len(b) == 1:
            ans += 1

    return ans


