import numpy as np


def solve(inp):
    n = inp[0]
    aaa = inp[1:] - 1
    dp = np.full((n, n), -1, dtype=np.int16)
    ans = 0

    a0, a1 = aaa[:2]
    if a0 > a1:
        a0, a1 = a1, a0
    dp[a0][a1] = 0

    for k in range(n - 1):
        a0, a1, a2 = sorted(aaa[2 + 3 * k:5 + 3 * k])
        if a0 == a1 and a1 == a2:
            ans += 1
            continue

        if a0 == a1:
            if dp[a2][a2] != -1:
                dp[a0][a1] = max(dp[a0][a1], dp[a2][a2] + 1)

            for b in range(a0):
                if dp[b][a0] == -1:
                    continue
                c, d = min(a2, b), max(a2, b)
                dp[c][d] = max(dp[c][d], dp[b][a0] + 1)

            for b in range(a0 + 1, n):
                if dp[a0][b] == -1:
                    continue
                c, d = min(a2, b), max(a2, b)
                dp[c][d] = max(dp[c][d], dp[a0][b] + 1)

        elif a1 == a2:
            if dp[a0][a0] != -1:
                dp[a1][a2] = max(dp[a1][a2], dp[a0][a0] + 1)

            for b in range(a1):
                if dp[b][a1] == -1:
                    continue
                c, d = min(a0, b), max(a0, b)
                dp[c][d] = max(dp[c][d], dp[b][a1] + 1)

            for b in range(a1 + 1, n):
                if dp[a1][b] == -1:
                    continue
                c, d = min(a0, b), max(a0, b)
                dp[c][d] = max(dp[c][d], dp[a1][b] + 1)


        else:
            if dp[a0][a0] != -1:
                dp[a1][a2] = max(dp[a1][a2], dp[a0][a0] + 1)
            if dp[a2][a2] != -1:
                dp[a0][a2] = max(dp[a0][a2], dp[a1][a1] + 1)
            if dp[a2][a2] != -1:
                dp[a0][a1] = max(dp[a0][a1], dp[a2][a2] + 1)

    a = aaa[-1]
    dp[a][a] += 1

    return dp.max() + ans


