def score_and_next_cards(x: int, y: int, Z: List[int]) -> Tuple[int, List[int]]:
    if Z[0] == Z[1] == Z[2]:
        return 1, [x, y]
    elif x == y and Z.count(x) >= 1:
        U = list(filter(lambda u: u != x, Z))
        if len(U) == 2:
            return 1, U
        elif len(U) == 1:
            return 1, [U[0], x]
        else:
            return 1, [x, x]

    elif Z.count(x) >= 2:
        U = list(filter(lambda u: u != x, Z))
        if len(U) > 0:
            return 1, [U[0], y]
        else:
            return 1, [x, y]

    elif Z.count(y) >= 2:
        U = list(filter(lambda u: u != y, Z))
        if len(U) > 0:
            return 1, [U[0], x]
        else:
            return 1, [x, y]

    else:
        return 0, [x, y] + Z


