# O(N^3), should TLE

@lru_cache(maxsize=None)
def dp(a, b, i):
    # Best you can do with [a] + [b] + A[i:]
    # Where len(A[i:]) is 3 * K - 5
    assert (3 * N - i) % 3 == 1
    assert a <= b
    if i == 3 * N - 1:
        return int(a == b == A[-1])
    best = 0
    temp = [a] + [b] + A[i : i + 3]
    assert len(temp) == 5
    for x in temp:
        if temp.count(x) >= 3:
            # If found any triple, alway take the points
            for j in range(3):
                temp.remove(x)
            assert len(temp) == 2
            if temp[0] > temp[1]:
                temp[1], temp[0] = temp[0], temp[1]
            best = 1 + dp(temp[0], temp[1], i + 3)
            break
    else:
        # keep any two
        temp.sort()
        for j in range(5):
            for k in range(j + 1, 5):
                best = max(best, dp(temp[j], temp[k], i + 3))
    return best


