struct DpWtihRowColMax {
    dp: Vec<Vec<i32>>,
    // dp[a][*]
    row_max: Vec<i32>,
    // dp[*][a]
    col_max: Vec<i32>
}

impl DpWtihRowColMax {
    fn new(n: usize) -> Self {
        Self {
            dp: dvec![-INF; n, n],
            row_max: vec![-INF; n],
            col_max: vec![-INF; n]
        }
    }

    fn set(&mut self, row: usize, col: usize, v: i32) {
        if self.dp[row][col] < v {
            self.dp[row][col] = v;
            self.row_max[row] = max(self.row_max[row], v);
        }
    }
}

fn main() {
    input! {
        n: usize, a: [usize1; 3*n]
    };

    let mut add_all = 0;
    let mut dpdp =  DpWtihRowColMax::new(n);
    dpdp.set(a[0], a[1], 0);
    dpdp.set(a[1], a[0], 0);
    for i in 0..n-1 {
        let mut upd = vec![];
        let v = [a[i*3+2], a[i*3+3], a[i*3+4]];
        if v[0] == v[1] && v[1] == v[2] {
            add_all += 1; // ?
            continue;
        }
        for j in 0..3 {
            let other = (0..3).filter(|&k| j != k).map(|k| v[k]).collect::<Vec<_>>();
            let mut amax = 0;
            for a in 0..n {
                amax = max(amax, dpdp.row_max[a]);
            }
            upd.push((other[0], other[1], max(amax, dpdp.dp[v[j]][v[j]] + 1)));

            if other[0] == other[1] {
                for a in 0..n {
                    upd.push((a, v[j], dpdp.dp[other[0]][a]+1));
                    upd.push((v[j], a, dpdp.dp[other[0]][a]+1));
                }
            }
            for a in 0..n {
                let best = dpdp.row_max[a];
                if best >= 0 {
                    upd.push((a, v[j], best));
                    upd.push((v[j], a, best));
                }
            }
        }

        for (row, col, new_value) in upd {
            dpdp.set(row, col, new_value);
        }
    }

    let mut ans = 0;
    for i in 0..n {
        for j in 0..n {
            let pl = ifv!(i == a[3*n-1] && j == a[3*n-1], 1, 0);
            ans = max(ans, dpdp.dp[i][j]+pl);
        }
    }
    println!("{}", ans + add_all);
}

use proconio::{input, fastout};
use proconio::marker::Usize1;

trait ChangeMinMax {
    fn chmin(&mut self, x: Self) -> bool;
    fn chmax(&mut self, x: Self) -> bool;
}

impl<T: PartialOrd> ChangeMinMax for T {
    fn chmin(&mut self, x: Self) -> bool {
        *self > x && {
            *self = x;
            true
        }
    }
    fn chmax(&mut self, x: Self) -> bool {
        *self < x && {
            *self = x;
            true
        }
    }
}

struct DpSolver {
    dp: Vec<Vec<i64>>,
    max: Vec<i64>,
    maximum: i64,
    update_stack: Vec<(usize, usize, i64)>,
}

impl DpSolver {
    fn register(&mut self, a: usize, b: usize, c: i64) {
        self.update_stack.push((a.min(b), a.max(b), c));
    }

    fn register_up_count(&mut self, a: usize, b: usize, c: usize, d: usize) {
        let a1 = a.min(b);
        let a2 = a.max(b);
        if self.dp[a1][a2] != -1 {
            self.register(c.min(d), c.max(d), self.dp[a1][a2] + 1);
        }
    }

    fn update(&mut self, a: usize, b: usize, c: i64) {
        self.dp[a][b].chmax(c);
        self.max[a].chmax(c);
        self.max[b].chmax(c);
        self.maximum.chmax(c);
    }

    fn do_update(&mut self) {
        while !self.update_stack.is_empty() {
            let (a, b, c) = self.update_stack.pop().unwrap();
            self.update(a, b, c);
        }
    }
}


#[fastout]
fn main() {
    input! {
        n: usize,
        aaa: [Usize1; n * 3],
    }

    let mut dps = DpSolver {
        dp: vec![vec![-1; n]; n],
        max: vec![-1; n],
        maximum: 0,
        update_stack: vec![],
    };
    let mut add = 0i64;
    let a = aaa[0].min(aaa[1]);
    let b = aaa[0].max(aaa[1]);
    dps.update(a, b, 0);

    for s in aaa[2..].chunks_exact(3) {
        let (a0, a1, a2) = (s[0], s[1], s[2]);
        if a0 == a1 && a1 == a2 {
            add += 1;
            continue;
        }
        if a0 == a1 || a1 == a2 || a2 == a0 {
            let q = a0 ^ a1 ^ a2;
            let p = (a0 + a1 + a2 - q) / 2;
            for b in 0..n {
                dps.register(q, b, dps.max[b]);
                dps.register_up_count(p, b, q, b);
            }
            dps.register(p, p, dps.maximum);
            dps.register(p, q, dps.maximum);
            dps.register_up_count(q, q, p, p);
        } else {
            dps.register(a0, a1, dps.maximum);
            dps.register(a0, a2, dps.maximum);
            dps.register(a1, a2, dps.maximum);
            dps.register_up_count(a0, a0, a1, a2);
            dps.register_up_count(a1, a1, a0, a2);
            dps.register_up_count(a2, a2, a0, a1);
            for b in 0..n {
                dps.register(a0, b, dps.max[b]);
                dps.register(a1, b, dps.max[b]);
                dps.register(a2, b, dps.max[b]);
            }
        }
        dps.do_update();
    }

    let &la = aaa.last().unwrap();
    dps.maximum.chmax(dps.dp[la][la] + 1);

    let ans = add + dps.maximum;

    println!("{}", ans);
}

use std::io::Read;
use std::cmp::max;

#[allow(non_snake_case)]
fn main() {
  let mut buf = String::new();
  std::io::stdin().read_to_string(&mut buf).unwrap();
  let mut S : Vec<usize> = buf.split_whitespace().map(|s| s.parse().unwrap()).collect();
  let N = S[0];

  let mut dp1 = vec![None; N + 1];
  let mut dp2 = vec![vec![None; N + 1];N + 1];
  {
    let mut s = S[1 ..= 2].to_vec();
    s.sort();
    let (a,b) = (s[0], s[1]);
    dp1[a].get_or_insert(0);
    dp1[b].get_or_insert(0);
    dp1[0].get_or_insert(0);
    dp2[a][b].get_or_insert(0);
  }

  let mut base = 0;
  let mut q = Vec::new();

  for i in 1 .. N {
    let mut s = S[3 * i .. 3 * (i + 1)].to_vec();
    s.sort();
    let (a,b,c) = (s[0],s[1],s[2]);

    if a == c {
      base += 1;
      continue;
    } else if a == b {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][a] {
            q.push((x, c, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[a][x] {
            q.push((x, c, v + 1));
          }
        } else {
          if let Some(v) = dp2[a][x] {
            q.push((c, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, a, v + 1));
      }
    } else if b == c {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][c] {
            q.push((x, a, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[x][c] {
            q.push((a, x, v + 1));
          }
        } else {
          if let Some(v) = dp2[c][x] {
            q.push((a, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[a][a] {
        q.push((c, c, v + 1));
      }
    } else {
      if let Some(v) = dp2[a][a] {
        q.push((b, c, v + 1));
      }
      if let Some(v) = dp2[b][b] {
        q.push((a, c, v + 1));
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, b, v + 1));
      }
    }

    q.push((a, b, dp1[0].unwrap()));
    q.push((a, c, dp1[0].unwrap()));
    q.push((b, c, dp1[0].unwrap()));

    for x in 1 ..= N {
      if let Some(v) = dp1[x] {
        for y in &[a,b,c] {
          if x < *y {
            q.push((x, *y, v));
          } else {
            q.push((*y, x, v));
          }
        }
      }
    }

    while let Some((a,b,v)) = q.pop() {
      if dp2[a][b].is_none() || dp2[a][b].unwrap() < v {
        let u = dp2[a][b].get_or_insert(v);
        *u = v;
        for i in &[0, a, b] {
          let u = dp1[*i].get_or_insert(v);
          *u = max(*u, v);
        }
      }
    }
  }

  let s = S[S.len() - 1];
  println!("{}", match dp2[s][s] {
    Some(v) => base + max(1 + dp2[s][s].unwrap_or(0), dp1[0].unwrap_or(0)),
    None    => base + dp1[0].unwrap(), 
  });
}

use proconio::{input, marker::Usize1};

fn rotate(x: &mut usize, y: &mut usize, z: &mut usize) {
    let w = *x;
    *x = *y;
    *y = *z;
    *z = w;
}

struct DP {
    l12: [Vec<Vec<i64>>; 2],
    l1_max: [Vec<i64>; 2],
    l2_max: [Vec<i64>; 2],
    max: [i64; 2],
    now: usize,
    pre: usize,
}

impl DP {
    fn new(n: usize) -> DP {
        DP {
            l12: [vec![vec![i64::min_value(); n]; n], vec![vec![i64::min_value(); n]; n]],
            l1_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            l2_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            max: [i64::min_value(); 2],
            now: 1,
            pre: 0,
        }
    }
    fn set(&mut self, l1: usize, l2: usize, v: i64) {
        self.l12[self.now][l1][l2] = v.max(self.l12[self.pre][l1][l2]);
        self.l12[self.now][l2][l1] = v.max(self.l12[self.pre][l2][l1]);
        self.l1_max[self.now][l1] = v.max(self.l1_max[self.pre][l1]);
        self.l1_max[self.now][l2] = v.max(self.l1_max[self.pre][l2]);
        self.l2_max[self.now][l1] = v.max(self.l2_max[self.pre][l1]);
        self.l2_max[self.now][l2] = v.max(self.l2_max[self.pre][l2]);
        self.max[self.now] = v.max(self.max[self.pre]);
    }
}

fn main() {
    input! {
        n: usize,
        a: [Usize1; n * 3],
    }

    let mut dp = DP::new(n);
    dp.set(a[0], a[1], 0);
    dp.pre = dp.now;
    dp.now = (dp.now + 1) % 2;
    let mut mc = 0;
    for i in 1..n {
        let (mut x, mut y, mut z) = (a[i * 3 - 1], a[i * 3], a[i * 3 + 1]);
        if x == y && x == z {
            mc += 1;
        } else {
            for _ in 0..3 {
                for l in 0..n {
                    let mut v = dp.l1_max[dp.pre][l];
                    if y == z {
                        v = v.max(dp.l12[dp.pre][l][y] + 1);
                    }
                    dp.set(l, x, v);
                }
                let v = dp.max[dp.pre].max(dp.l12[dp.pre][z][z] + 1);
                dp.set(x, y, v);
                rotate(&mut x, &mut y, &mut z);
            }
            dp.pre = dp.now;
            dp.now = (dp.now + 1) % 2;
        }
    }
    let v = dp.max[dp.pre].max(dp.l12[dp.pre][a[3 * n - 1]][a[3 * n - 1]] + 1);
    println!("{}", v + mc);
}

