struct DpWtihRowColMax {
    dp: Vec<Vec<i32>>,
    // dp[a][*]
    row_max: Vec<SegmentTree<i32>>,
    // dp[*][a]
    col_max: Vec<SegmentTree<i32>>
}

impl DpWtihRowColMax {
    fn new(n: usize) -> Self {
        let mut row_max = vec![];
        let mut col_max = vec![];
        for i in 0..n {
            row_max.push(SegmentTree::new(n+16, -INF, Rc::new(|a,b| max(a,b))));
            col_max.push(SegmentTree::new(n+16, -INF, Rc::new(|a,b| max(a,b))));
        }
        Self {
            dp: dvec![-INF; n, n],
            row_max,
            col_max
        }
    }

    fn set(&mut self, row: usize, col: usize, v: i32) {
        if self.dp[row][col] < v {
            self.dp[row][col] = v;
            self.row_max[row].set(col, v);
            self.col_max[col].set(row, v);
        }
    }
}

fn main() {
    input! {
        n: usize, a: [usize1; 3*n]
    };


    let mut add_all = 0;
    let mut dpdp =  DpWtihRowColMax::new(n);
    dpdp.set(a[0], a[1], 0);
    dpdp.set(a[1], a[0], 0);
    for i in 0..n-1 {
        let mut upd = vec![];
        let v = [a[i*3+2], a[i*3+3], a[i*3+4]];
        if v[0] == v[1] && v[1] == v[2] {
            add_all += 1; // ?
            continue;
        }
        for j in 0..3 {
            let other = (0..3).filter(|&k| j != k).map(|k| v[k]).collect::<Vec<_>>();
            upd.push((other[0], other[1], dpdp.dp[v[j]][v[j]] + 1));

            if other[0] == other[1] {
                for a in 0..n {
                    upd.push((a, v[j], max(dpdp.dp[other[0]][a], dpdp.dp[a][other[0]])+1));
                    upd.push((v[j], a, max(dpdp.dp[other[0]][a], dpdp.dp[a][other[0]])+1));
                }
            }
            for a in 0..n {
                let best = max(dpdp.col_max[a].compute_range(0, n), dpdp.row_max[a].compute_range(0, n));
                upd.push((a, v[j], best));
                upd.push((v[j], a, best));
            }
        }

        for (row, col, new_value) in upd {
            dpdp.set(row, col, new_value);
        }
    }

    let mut ans = 0;
    for i in 0..n {
        for j in 0..n {
            let pl = ifv!(i == a[3*n-1] && j == a[3*n-1], 1, 0);
            ans = max(ans, dpdp.dp[i][j]+pl);
        }
    }
    println!("{}", ans + add_all);
}

