    for i in (2..(3 * N - 1)).step_by(3) {
        if A[i] == A[i + 1] && A[i + 1] == A[i + 2] {
            ans += 1;
            continue;
        }

        let mut q = Vec::new();
        for j in 0..3 {
            let x = A[i + j % 3];
            let y = A[i + (1 + j) % 3];
            let z = A[i + (2 + j) % 3];

            // 難関
            for a in 0..=N {
                let mut v = dp[a][N];
                if y == z {
                    v = cmp::max(v, dp[a][y] + 1);
                }
                q.push((a, x, v));
            }

            // 簡単
            let v = cmp::max(dp[N][N], dp[z][z] + 1);
            q.push((x, y, v));
        }

        for (a, b, v) in q {
            upd(a, b, v, &mut dp, N);
        }
    }

    let l = A[3 * N - 1];
    ans += cmp::max(dp[N][N], dp[l][l] + 1);
    println!("{}", ans);
}

