use proconio::{input, fastout};
use proconio::marker::Usize1;
use std::cmp::{min, max};

trait ChangeMinMax {
    fn chmin(&mut self, x: Self) -> bool;
    fn chmax(&mut self, x: Self) -> bool;
}

impl<T: PartialOrd> ChangeMinMax for T {
    fn chmin(&mut self, x: Self) -> bool {
        *self > x && {
            *self = x;
            true
        }
    }
    fn chmax(&mut self, x: Self) -> bool {
        *self < x && {
            *self = x;
            true
        }
    }
}

struct DpSolver {
    dp: Vec<Vec<i64>>,
    max: Vec<i64>,
    maximum: i64,
    update_stack: Vec<(usize, usize, i64)>,
}

impl DpSolver {
    fn register(&mut self, a: usize, b: usize, c: i64) {
        self.update_stack.push((a.min(b), a.max(b), c));
    }

    fn register_up_count(&mut self, a: usize, b: usize, c: usize, d: usize) {
        let a1 = a.min(b);
        let a2 = a.max(b);
        if self.dp[a1][a2] != -1 {
            self.register(c.min(d), c.max(d), self.dp[a1][a2] + 1);
        }
    }

    fn update(&mut self, a: usize, b: usize, c: i64) {
        self.dp[a][b].chmax(c);
        self.max[a].chmax(c);
        self.max[b].chmax(c);
        self.maximum.chmax(c);
    }

    fn do_update(&mut self) {
        while !self.update_stack.is_empty() {
            let (a, b, c) = self.update_stack.pop().unwrap();
            self.update(a, b, c);
        }
    }
}


#[fastout]
fn main() {
    input! {
        n: usize,
        aaa: [Usize1; n * 3],
    }

    let mut dps = DpSolver {
        dp: vec![vec![-1; n]; n],
        max: vec![0; n],
        maximum: 0,
        update_stack: vec![],
    };
    let mut add = 0i64;
    let a = aaa[0].min(aaa[1]);
    let b = aaa[0].max(aaa[1]);
    dps.update(a, b, 0);

    for s in aaa[2..].chunks_exact(3) {
        let (a0, a1, a2) = (s[0], s[1], s[2]);
        if a0 == a1 && a1 == a2 {
            add += 1;
            continue;
        }
        if a0 == a1 || a1 == a2 || a2 == a0 {
            let q = a0 ^ a1 ^ a2;
            let p = (a0 + a1 + a2 - q) / 2;
            for b in 0..n {
                dps.register(q, b, dps.max[b]);
                dps.register_up_count(p, b, q, b);
            }
            dps.register(p, p, dps.maximum);
            dps.register_up_count(q, q, p, p);
            dps.do_update();
        } else {
            dps.register(a0, a1, dps.maximum);
            dps.register(a0, a2, dps.maximum);
            dps.register(a1, a2, dps.maximum);
            dps.register_up_count(a0, a0, a1, a2);
            dps.register_up_count(a1, a1, a0, a2);
            dps.register_up_count(a2, a2, a0, a1);
            for b in 0..n {
                dps.register(a0, b, dps.max[b]);
                dps.register(a1, b, dps.max[b]);
                dps.register(a2, b, dps.max[b]);
            }
            dps.do_update();
        }
    }

    let &la = aaa.last().unwrap();
    dps.maximum.chmax(dps.dp[la][la] + 1);

    let ans = add + dps.maximum;

    println!("{}", ans);
}

use proconio::{input, marker::Usize1};

fn chmax(a: &mut Option<i32>, b: i32) {
    *a = Some(if let Some(v) = *a {
        v.max(b)
    } else {
        b
    });
}

fn rotate(x: &mut usize, y: &mut usize, z: &mut usize) {
    let w = *x;
    *x = *y;
    *y = *z;
    *z = w;
}

struct DP {
    l12: Vec<Vec<Option<i32>>>,
    l1_max: Vec<Option<i32>>,
    max: Option<i32>,
    n: usize,
}

impl DP {
    fn new(n: usize) -> DP {
        DP {
            l12: vec![vec![None; n + 1]; n + 1],
            l1_max: vec![None; n],
            max: None,
            n: n,
        }
    }
    fn set(&mut self, l1: usize, l2: usize, v: i32) {
        if l2 != self.n {
            chmax(&mut self.l12[l1][l2], v);
            chmax(&mut self.l12[l2][l1], v);
            chmax(&mut self.l1_max[l2], v);
        }
        chmax(&mut self.l1_max[l1], v);
        chmax(&mut self.max, v);
    }
}

fn main() {
    input! {
        n: usize,
        a: [Usize1; n * 3],
    }

    let mut dp = DP::new(n);
    dp.set(a[0], a[1], 0);
    let mut c = 0; // counter, number of cuts 3 to 5 from the left.
    for i in 1..n {
        let (mut x, mut y, mut z) = (a[i * 3 - 1], a[i * 3], a[i * 3 + 1]);
        if x == y && x == z {
            c += 1;
        } else {
            let m = dp.max.unwrap();
            let mut q = vec![];
            for _ in 0..3 {
                for l in 0..n {
                    if let Some(m) = dp.l1_max[l] {
                        let v = if y == z {
                            if let Some(l12) = dp.l12[l][y] {
                                m.max(l12 + 1)
                            } else {
                                m
                            }
                        } else {
                            m
                        };
                        q.push((l, x, v));
                    }
                }
                let v = if y == z {
                    if let Some(l1_max) = dp.l1_max[y] {
                        m.max(l1_max + 1)
                    } else {
                        m
                    }
                } else {
                    m
                };
                q.push((x, n, v));

                let v = if let Some(l12) = dp.l12[z][z] {
                    m.max(l12 + 1)
                } else {
                    m
                };
                q.push((x, y, v));

                rotate(&mut x, &mut y, &mut z);
            }

            for (x, y, v) in q {
                dp.set(x, y, v);
            }
        }
    }

    let mut v = dp.max.unwrap();
    let l = a[3 * n - 1];
    if let Some(l12) = dp.l12[l][l] {
        v = v.max(l12 + 1);
    }
    println!("{}", v + c);
}

fn main() {
    proconio::input! {
        n: usize,
        a1: proconio::marker::Usize1,
        a2: proconio::marker::Usize1,
        a: [(proconio::marker::Usize1, proconio::marker::Usize1, proconio::marker::Usize1); n-1],
        an: proconio::marker::Usize1
    };
    let mut dp = vec![vec![-1; n]; n];
    let mut line = vec![-1; n];
    let mut all = 0;
    let mut plus = 0;
    dp[a1][a2] = 0;
    dp[a2][a1] = 0;
    line[a1] = 0;
    line[a2] = 0;
    for &p in &a {
        if p.0 == p.1 && p.1 == p.2 {
            plus += 1;
            continue;
        }
        let mut update = Vec::new();
        update.push((p.1, p.2, all.max(dp[p.0][p.0] + 1)));
        update.push((p.2, p.0, all.max(dp[p.1][p.1] + 1)));
        update.push((p.0, p.1, all.max(dp[p.2][p.2] + 1)));
        for i in 0..n {
            if dp[i][p.1] != -1 && p.1 == p.2 {
                update.push((i, p.0, dp[i][p.1] + 1));
            }
            if dp[i][p.2] != -1 && p.2 == p.0 {
                update.push((i, p.1, dp[i][p.2] + 1));
            }
            if dp[i][p.0] != -1 && p.0 == p.1 {
                update.push((i, p.2, dp[i][p.0] + 1));
            }
            if line[i] != -1 {
                update.push((i, p.0, line[i]));
                update.push((i, p.1, line[i]));
                update.push((i, p.2, line[i]));
            }
        }
        for &u in &update {
            dp[u.0][u.1] = dp[u.0][u.1].max(u.2);
            dp[u.1][u.0] = dp[u.1][u.0].max(u.2);
            line[u.0] = line[u.0].max(u.2);
            line[u.1] = line[u.1].max(u.2);
            all = all.max(u.2);
        }
    }
    let mut res = 0;
    for i in 0..n {
        for j in 0..n {
            res = res.max(dp[i][j] + plus + if i == j && i == an { 1 } else { 0 });
        }
    }
    println!("{}", res);
}

