use proconio::*;
use proconio::marker::*;

fn run() {
    input! {
        n: usize,
        a: [Usize1; 3 * n],
    }
    let mut dp = vec![vec![-5000; n]; n];
    let mut max = vec![-5000; n];
    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    max[a[0]] = 0;
    max[a[1]] = 0;
    let mut add = 0;
    let mut change = vec![];
    for a in a[2..].chunks_exact(3) {
        let (a, b, c) = (a[0], a[1], a[2]);
        if a == b && b == c {
            add += 1;
            continue;
        }
        change.clear();
        let v = *max.iter().max().unwrap();
        if a == b || b == c || c == a {
            let q = a ^ b ^ c;
            let p = (a + b + c - q) / 2;
            for (i, (max, dp)) in max.iter().zip(dp.iter()).enumerate() {
                change.push((i, q, std::cmp::max(*max, dp[p] + 1)));
                change.push((i, p, *max));
            }
            change.push((p, p, std::cmp::max(v, dp[q][q] + 1)));
            change.push((p, q, v));
        } else {
            change.push((b, c, dp[a][a] + 1));
            change.push((c, a, dp[b][b] + 1));
            change.push((a, b, dp[c][c] + 1));
            change.push((a, b, v));
            change.push((b, c, v));
            change.push((c, a, v));
            for &x in [a, b, c].iter() {
                for (i, max) in max.iter().enumerate() {
                    change.push((x, i, *max));
                }
            }
        }
        for &(x, y, v) in change.iter() {
            dp[x][y].chmax(v);
            dp[y][x].chmax(v);
            max[x].chmax(v);
            max[y].chmax(v);
        }
    }
    let last = *a.last().unwrap();
    let ans = add + std::cmp::max(*dp.iter().flatten().max().unwrap(), dp[last][last] + 1);
    println!("{}", ans);
}

fn main() {
    run();
}

