fn cal1(x:usize, n:usize, m:usize, h:&mut HashMap<usize, usize>)->usize{
    if h.contains_key(&n){
        return h[&n];
    }
    if n == 1{
        return x;
    }
    if n == 0{
        return 0;
    }
    let mut res = 0;
    let mut a = n/2;
    let mut b = n-a;
    res = cal1(x, b, m, h)%m;
    res = ((res*modpow3((10)%m, a*x.to_string().len(), m)%m)%m + cal1(x, a, m, h)%m)%m;
    h.insert(n, res);
    return res;
}
