        let mut res = 0;
        let mut vv = vec![];
        if dp.contains_key(&(s, a, b)){
            return dp[&(s, a, b)];
        }
        if a != N{
            vv.push(a);
            vv.push(b);
        }
        let mut ii = s;
        while(vv.len() != 5){
            vv.push(v[ii]);
