            vv.sort();
            if vv[0] == vv[1]{
                res+=1;
            }
            return res;
        }
        for i in 0..5{
            for j in i+1..5{
                let mut vvv = vec![];
                for k in 0..5{
                    if k != i && k != j{
                        vvv.push(vv[k]);
                    }
                }
                vvv.sort();
