        free2[a[i]] += 1;
    }

    // n-2回操作する 3つずつ補充される
    for i in 0..n - 1 {
        let k = 2 + i * 3;
        let mut s = HashMap::new();
        for j in k..k + 3 {
            *s.entry(a[j]).or_insert(0) += 1;
        }
        //全部同じ
        if s.len() == 1 {
            score += 1;
            continue;
        }
        // aiを1個つかって3つにするパターン
        let mut one = 0;
        // aiを2個つかって3つにするパターン
        let mut two = 0;
        for (ai, count) in s {
            match count {
                1 => {
                    if free1[ai] + free2[ai] + 1 >= 3 {
                        one = ai;
                    }
                }
                2 => {
                    if free1[ai] + free2[ai] + 2 >= 3 {
                        two = ai;
                    }
                }
                _ => unreachable!(),
            }
        }
        //2個使う方を優先
        if two > 0 {
            score += 1;
            free1 = free2.iter().cloned().map(|c| min(c, 1)).collect();
            free1[two] = 0;
            free2 = vec![0; n + 1];
            for j in k..k + 3 {
                if a[j] == two {
                    continue;
                }
                free2[a[j]] = 1;
            }
            continue;
        }
        if one > 0 {
            score += 1;
            free1 = vec![0; n + 1];
            free2 = vec![0; n + 1];
            for j in k..k + 3 {
                if a[j] == one {
                    continue;
                }
                free2[a[j]] += 1;
            }
            continue;
        }
        for j in k..k + 3 {
            free2[a[j]] = min(free2[a[j]] + 1, 2);
        }
    }
    if free2[a[n * 3 - 1]] + free1[a[n * 3 - 1]] >= 2 {
        score += 1;
    }
    println!("{}", score);
}

