pub fn solve<R: BufRead>(mut reader: StdinReader<R>) {
    let n = reader.u();
    let a = reader.uv(n * 3);

    // 一つしか持ち越せないグループ
    let mut free1 = vec![0; n + 1];
    // 二つ持ち越せるグループ
    let mut free2 = vec![0; n + 1];
    let mut score = 0;
    //初期設定
    for i in 0..5 {
        free2[a[i]] += 1;
        if free2[a[i]] == 3 {
            free2[a[i]] = 0;
            score += 1;
        }
    }

    // n-2回操作する 3つずつ補充される
    for i in 0..n - 2 {
        let k = 5 + i * 3;
        let mut s = HashMap::new();
        for j in k..k + 3 {
            *s.entry(a[j]).or_insert(0) += 1;
        }
        //全部同じ
        if s.len() == 1 {
            score += 1;
            continue;
        }
        // aiを1個つかって3つにするパターン
        let mut one = 0;
        let mut one_rest = HashSet::new();
        // aiを2個つかって3つにするパターン
        let mut two = 0;
        let mut two_rest = 0;
        for (ai, count) in s {
            match count {
                1 => {
                    if free1[ai] + free2[ai] + 1 >= 3 {
                        one = ai;
                    }
                    two_rest = ai;
                    one_rest.insert(ai);
                }
                2 => {
                    if free1[ai] + free2[ai] + 1 >= 3 {
                        two = ai;
                    }
                    one_rest.insert(ai);
                }
                _ => unreachable!(),
            }
        }
        //2個使う方を優先
        if two > 0 {
            score += 1;
            free1 = free2.iter().cloned().map(|c| max(c, 1)).collect();
            free2 = vec![0; n + 1];
            free2[two_rest] = 1;
            continue;
        }
        if one > 0 {
            score += 1;
            free1 = vec![0; n + 1];
            free2 = vec![0; n + 1];
            match one_rest.len() {
                1 => {
                    free2[*one_rest.iter().next().unwrap()] = 2;
                }
                2 => {
                    let mut it = one_rest.iter();
                    free2[*it.next().unwrap()] = 1;
                    free2[*it.next().unwrap()] = 1;
                }
                _ => unreachable!(),
            }
        }
        for j in k..k + 3 {
            free2[a[j]] += 1;
        }
    }
    if free2[a[n * 3 - 1]] == 2 {
        score += 1;
    }
    println!("{}", score);
}

