fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, a: [u1; 3 * n]);
    let mut idx: Vec<VecDeque<usize>> = vec![VecDeque::new(); n];
    let mut ret = 0;
    for (i, &ai) in a.iter().enumerate() {
        idx[ai].push_back(i);
        if idx[ai].len() == 3 {
            let ai0 = idx[ai][0];
            ret += 1;
            idx[ai].clear();
            if i <= 4 {
                continue;
            }
            match ai0 % 3 {
                0 => {
                    for line in &mut idx {
                        while line.len() > 0 {
                            if line[0] < ai0 {
                                line.pop_front();
                            }
                        }
                    }
                }
                1 => {
                    for line in &mut idx {
                        let mut count = 0;
                        for li in line.iter() {
                            if *li < ai0 {
                                count += 1;
                            }
                        }
                        if count >= 2 {
                            line.pop_front();
                        }
                    }
                }
                2 => {}
                _ => unreachable!(),
            }
        }
    }
    println!("{}", ret);
}

