            q.push((x, c, v + 1));
          }
        } else {
          if let Some(v) = dp2[a][x] {
            q.push((c, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, a, v + 1));
      }
    } else if b == c {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][c] {
