    let mut dp = vec![vec![(0, false); n]; n];
    dp[a[0]][a[1]].1 = true;
    dp[a[1]][a[0]].1 = true;

    for i in 0..(n - 1) {
        if a[i * 3 + 2] == a[i * 3 + 3] && a[i * 3 + 2] == a[i * 3 + 4] {
            for j in 0..n {
                for k in 0..n {
                    dp[j][k] = (dp[j][k].0 + 1, dp[j][k].1);
                }
            }
        }
        else {
            if a[i * 3 + 2] == a[i * 3 + 3] {
                let other = 4;
                let tmp = a[i * 3 + 2];
                for j in 0..n {
                    dp[j][a[i * 3 + other]] = {
                        if dp[j][a[i * 3 + other]].1 ^ dp[j][tmp].1 {
                            if dp[j][a[i * 3 + other]].1 {
                                dp[j][a[i * 3 + other]]
                            }
                            else {
                                (dp[j][tmp].0 + 1, dp[j][tmp].1)
                            }
                        }
                        else {
                            (
                                dp[j][a[i * 3 + other]].0.max(dp[j][tmp].0 + 1),
                                dp[j][tmp].1,
                            )
                        }
                    };
                    dp[a[i * 3 + other]][j] = dp[j][a[i * 3 + other]];
                }
            }
            else if a[i * 3 + 2] == a[i * 3 + 4] {
                let other = 3;
                let tmp = a[i * 3 + 2];
                for j in 0..n {
                    dp[j][a[i * 3 + other]] = {
                        if dp[j][a[i * 3 + other]].1 ^ dp[j][tmp].1 {
                            if dp[j][a[i * 3 + other]].1 {
                                dp[j][a[i * 3 + other]]
                            }
                            else {
                                (dp[j][tmp].0 + 1, dp[j][tmp].1)
                            }
                        }
                        else {
                            (
                                dp[j][a[i * 3 + other]].0.max(dp[j][tmp].0 + 1),
                                dp[j][tmp].1,
                            )
                        }
                    };
                    dp[a[i * 3 + other]][j] = dp[j][a[i * 3 + other]];
                }
            }
            else if a[i * 3 + 3] == a[i * 3 + 4] {
                let other = 2;
                let tmp = a[i * 3 + 3];
                for j in 0..n {
                    dp[j][a[i * 3 + other]] = {
                        if dp[j][a[i * 3 + other]].1 ^ dp[j][tmp].1 {
                            if dp[j][a[i * 3 + other]].1 {
                                dp[j][a[i * 3 + other]]
                            }
                            else {
                                (dp[j][tmp].0 + 1, dp[j][tmp].1)
                            }
                        }
                        else {
                            (
                                dp[j][a[i * 3 + other]].0.max(dp[j][tmp].0 + 1),
                                dp[j][tmp].1,
                            )
                        }
                    };
                    dp[a[i * 3 + other]][j] = dp[j][a[i * 3 + other]];
                }
            }
            else {
                dp[a[i * 3 + 2]][a[i * 3 + 3]] = {
                    let other = 5;
                    if dp[a[i * 3 + other]][a[i * 3 + other]].1 ^ dp[a[i * 3 + 2]][a[i * 3 + 3]].1 {
                        if dp[a[i * 3 + 2]][a[i * 3 + 3]].1 {
                            dp[a[i * 3 + 2]][a[i * 3 + 3]]
                        }
                        else {
                            (
                                dp[a[i * 3 + other]][a[i * 3 + other]].0 + 1,
                                dp[a[i * 3 + other]][a[i * 3 + other]].1,
                            )
                        }
                    }
                    else {
                        (
                            dp[a[i * 3 + 2]][a[i * 3 + 3]]
                                .0
                                .max(dp[a[i * 3 + other]][a[i * 3 + other]].0 + 1),
                            dp[a[i * 3 + other]][a[i * 3 + other]].1,
                        )
                    }
                };
                dp[a[i * 3 + 2]][a[i * 3 + 4]] = {
                    let other = 3;
                    if dp[a[i * 3 + other]][a[i * 3 + other]].1 ^ dp[a[i * 3 + 2]][a[i * 3 + 4]].1 {
                        if dp[a[i * 3 + 2]][a[i * 3 + 4]].1 {
                            dp[a[i * 3 + 2]][a[i * 3 + 4]]
                        }
                        else {
                            (
