                                dp[a[i * 3 + other]][a[i * 3 + other]].1,
                            )
                        }
                    }
                    else {
                        (
                            dp[a[i * 3 + 2]][a[i * 3 + 4]]
                                .0
                                .max(dp[a[i * 3 + other]][a[i * 3 + other]].0 + 1),
                            dp[a[i * 3 + other]][a[i * 3 + other]].1,
                        )
                    }
                };
                dp[a[i * 3 + 3]][a[i * 3 + 4]] = {
                    let other = 2;
                    if dp[a[i * 3 + other]][a[i * 3 + other]].1 ^ dp[a[i * 3 + 3]][a[i * 3 + 4]].1 {
                        if dp[a[i * 3 + 3]][a[i * 3 + 4]].1 {
                            dp[a[i * 3 + 3]][a[i * 3 + 4]]
                        }
                        else {
                            (
                                dp[a[i * 3 + other]][a[i * 3 + other]].0 + 1,
                                dp[a[i * 3 + other]][a[i * 3 + other]].1,
                            )
                        }
                    }
                    else {
                        (
                            dp[a[i * 3 + 3]][a[i * 3 + 4]]
                                .0
                                .max(dp[a[i * 3 + other]][a[i * 3 + other]].0 + 1),
                            dp[a[i * 3 + other]][a[i * 3 + other]].1,
                        )
                    }
                };

                dp[a[i * 3 + 3]][a[i * 3 + 2]] = dp[a[i * 3 + 2]][a[i * 3 + 3]];
                dp[a[i * 3 + 4]][a[i * 3 + 2]] = dp[a[i * 3 + 2]][a[i * 3 + 4]];
                dp[a[i * 3 + 4]][a[i * 3 + 3]] = dp[a[i * 3 + 3]][a[i * 3 + 4]];
            }
        }
        dp = dp;
    }

    if a[3 * n - 2] == a[3 * n - 1] {
        for i in 0..n {
            dp[i][a[3 * n - 2]].0 += 1;
            if i != a[3 * n - 2] {
                dp[a[3 * n - 2]][i].0 += 1;
            }
        }
    }
    else {
        dp[a[3 * n - 2]][a[3 * n - 2]].0 += 1;
        dp[a[3 * n - 1]][a[3 * n - 1]].0 += 1;
    }

    let mut max_value = 0;
    for v in dp {
        for (c, b) in v {
            if b && c > max_value {
                max_value = c;
            }
        }
    }

    println!("{}", max_value);
}

