    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    for a in a[2..].chunks_exact(3) {
        let mut next = vec![vec![-5000; n]; n];
        let (a, b, c) = (a[0], a[1], a[2]);
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate() {
                let mut b = [i, j, a, b, c];
                b.sort();
                let a = b;
                if a[0] == a[2] {
                    let (x, y) = (a[3], a[4]);
                    next[x][y].chmax(v + 1);
                    next[y][x].chmax(v + 1);
                } else if a[1] == a[3] {
                    let (x, y) = (a[0], a[4]);
                    next[x][y].chmax(v + 1);
                    next[y][x].chmax(v + 1);
                } else if a[2] == a[4] {
                    let (x, y) = (a[0], a[1]);
                    next[x][y].chmax(v + 1);
