                } else {
                    for (i, &x) in a.iter().enumerate() {
                        for &y in a.iter().take(i) {
                            next[x][y].chmax(v);
                            next[y][x].chmax(v);
                        }
                    }
                }
            }
        }
        dp = next;
    }
    let last = *a.last().unwrap();
    let ans = max(*dp.iter().flatten().max().unwrap(), dp[last][last] + 1);
