fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, a: [u1; 3 * n]);
    let mut idx: Vec<VecDeque<usize>> = vec![VecDeque::new(); n];
    let mut ret = 0;
    for (i, &ai) in a.iter().enumerate() {
        idx[ai].push_back(i);
        if idx[ai].len() == 3 {
            let ai0 = idx[ai][0];
            ret += 1;
            idx[ai].clear();
            if i <= 4 {
                continue;
            }
            match ai0 % 3 {
                0 => {
                    for line in &mut idx {
                        line.clear();
                    }
                }
                1 => {
                    for line in &mut idx {
                        while line.len() >= 2 {
                            line.pop_front();
                        }
                    }
                }
                2 => {
                    for line in &mut idx {
                        while line.len() >= 3 {
                            line.pop_front();
                        }
                    }
                }
                _ => unreachable!(),
            }
        }
    }
    println!("{}", ret);
}

