struct Dp(BTreeMap<(usize, usize), usize>);
impl Dp {
    fn set(&mut self, a: usize, b: usize, x: usize) {
        if a < b {
            self.0
                .entry((a, b))
                .and_modify(|v| *v = max(*v, x))
                .or_insert(x);
        } else {
            self.0
                .entry((b, a))
                .and_modify(|v| *v = max(*v, x))
                .or_insert(x);
        }
    }
}

#[fastout]
fn main() {
    input! {
        n: usize,
        a: [usize; 3*n]
    }
    let mut dp = Dp(BTreeMap::<_, _>::new());
    dp.set(a[0], a[1], 0);
    for (ai, aj, ak) in (0..n - 1).map(|i| (3 * i + 2, 3 * i + 3, 3 * i + 4)) {
        if a[ai] == a[aj] && a[aj] == a[ak] {
            for (_, v) in dp.0.iter_mut() {
                *v += 1;
            }
            continue;
        }

        if a[ai] == a[aj] || a[aj] == a[ak] || a[ak] == a[ai] {
            let (a1, a2) = if a[aj] == a[ak] {
                (a[ai], a[aj])
            } else if a[ai] == a[ak] {
                (a[aj], a[ak])
            } else {
                (a[ak], a[ai])
            };

            let mut next = dp.clone();
            for (&(b1, b2), &v) in dp.0.iter() {
                if b1 == b2 && b1 == a1 {
                    next.set(a2, a2, v + 1);
                }
                if b1 == a2 {
                    next.set(b2, a1, v + 1);
                }
                if b2 == a2 {
                    next.set(b1, a1, v + 1);
                }
                next.set(b1, a1, v);
                next.set(b1, a2, v);
                next.set(b2, a1, v);
                next.set(b2, a2, v);
            }
            dp = next;
            continue;
        }

        let mut next = dp.clone();
        let (a1, a2, a3) = (a[ai], a[aj], a[ak]);
        for (&(b1, b2), &v) in dp.0.iter() {
            if b1 == b2 {
                if b1 == a1 {
                    next.set(a2, a3, v + 1);
                }
                if b1 == a2 {
                    next.set(a1, a3, v + 1);
                }
                if b1 == a3 {
                    next.set(a1, a2, v + 1);
                }
            }
            next.set(b1, a1, v);
            next.set(b1, a2, v);
            next.set(b1, a3, v);
            next.set(b2, a1, v);
            next.set(b2, a2, v);
            next.set(b2, a3, v);
            next.set(a1, a2, v);
            next.set(a2, a3, v);
            next.set(a3, a1, v);
        }
        dp = next;
    }
    if let Some(v) = dp.0.get_mut(&(a[3 * n - 1], a[3 * n - 1])) {
        *v += 1;
    }
    let mut ans = 0;
    for &v in dp.0.values() {
        ans = max(ans, v);
    }
    println!("{}", ans);
}

