            v.push(i+1);
        }
        *count += 1;
    }
    let mut sum:usize = 0;
    for i in 0..v.len() {
        if 5+i*3<v[i] {
            sum+=v[i]-5-i*3
        }
    }
    println!("{}",n-sum)
}

