use proconio::{input, fastout};
use std::cmp;

fn chmax(y: &mut i32, x: i32) {
    if *y < x { *y = x; }
}

fn upd(dp: &mut Vec<Vec<i32>>, n: usize, i: usize, j: usize, x: i32){
    chmax(&mut dp[i][j], x);
    chmax(&mut dp[j][i], x);
    chmax(&mut dp[i][n], x);
    chmax(&mut dp[n][i], x);
    chmax(&mut dp[n][j], x);
    chmax(&mut dp[j][n], x);
    chmax(&mut dp[n][n], x);
}

#[fastout]
fn main() {
    input! {
        n: usize,
        mut a: [usize; n*3],
    }
    for i in 0..a.len() {a[i] -= 1}
    let mut dp: Vec<Vec<i32>> = vec![vec![-1000000000;n+1];n+1];
    upd(&mut dp, n, a[0], a[1], 0);
    let mut base = 0;
    for aa in a[2..].chunks_exact(3) {
        let mut x = aa[0];
        let mut y = aa[1];
        let mut z = aa[2];
        if x==y && y==z {
            base += 1;
            continue;
        }
        let mut q = Vec::new();
        for _ in 0..3 {
            for ai in 0..(n+1) {
                let mut now = dp[ai][n];
                if y==z { now = cmp::max(now,dp[ai][y]+1)}
                q.push((ai,x,now));
            }
            let now = cmp::max(dp[n][n], dp[z][z]+1);
            q.push((x,y,now));
            let t = x; x = y; y = z; z = t;
        }
        for (x,y,now) in q {upd(&mut dp, n, x, y, now)}
    }
    let mut ans = dp[n][n];
    let l = a[n*3-1];
    ans = cmp::max(ans, dp[l][l]+1);
    ans += base;
    println!("{}", ans);
}

fn main() {
    proconio::input! {
        n: usize,
        a1: proconio::marker::Usize1,
        a2: proconio::marker::Usize1,
        a: [(proconio::marker::Usize1, proconio::marker::Usize1, proconio::marker::Usize1); n-1],
        an: proconio::marker::Usize1
    };
    let mut dp = vec![vec![-1; n]; n];
    let mut line = vec![-1; n];
    let mut all = 0;
    dp[a1][a2] = 0;
    dp[a2][a1] = 0;
    line[a1] = 0;
    line[a2] = 0;
    for &p in &a {
        if p.0 == p.1 && p.1 == p.2 {
            all += 1;
            continue;
        }
        let mut update = Vec::new();
        update.push((p.1, p.2, if dp[p.0][p.0] != -1 { dp[p.0][p.0] + 1 } else { 0 }));
        update.push((p.2, p.0, if dp[p.1][p.1] != -1 { dp[p.1][p.1] + 1 } else { 0 }));
        update.push((p.0, p.1, if dp[p.2][p.2] != -1 { dp[p.2][p.2] + 1 } else { 0 }));
        for i in 0..n {
            if dp[i][p.1] != -1 {
                update.push((i, p.0, dp[i][p.1] + if p.1 == p.2 { 1 } else { 0 }));
            }
            if dp[i][p.2] != -1 {
                update.push((i, p.1, dp[i][p.2] + if p.2 == p.0 { 1 } else { 0 }));
            }
            if dp[i][p.0] != -1 {
                update.push((i, p.2, dp[i][p.0] + if p.0 == p.1 { 1 } else { 0 }));
            }
            if line[i] != -1 {
                update.push((i, p.0, line[i]));
                update.push((i, p.1, line[i]));
                update.push((i, p.2, line[i]));
            }
        }
        for &u in &update {
            dp[u.0][u.1] = dp[u.0][u.1].max(u.2);
            dp[u.1][u.0] = dp[u.1][u.0].max(u.2);
            line[u.0] = line[u.0].max(u.2);
            line[u.1] = line[u.1].max(u.2);
        }
    }
    let mut res = 0;
    for i in 0..n {
        for j in 0..n {
            res = res.max(dp[i][j] + all + if i == j && i == an { 1 } else { 0 });
        }
    }
    println!("{}", res);
}

