struct DpWtihRowColMax {
    dp: Vec<Vec<i32>>,
    // dp[a][*]
    row_max: Vec<SegmentTree<i32>>,
    // dp[*][a]
    col_max: Vec<SegmentTree<i32>>
}

impl DpWtihRowColMax {
    fn new(n: usize) -> Self {
        let mut row_max = vec![];
        let mut col_max = vec![];
        for _ in 0..n {
            row_max.push(SegmentTree::new(n+16, -INF, Rc::new(|a,b| max(a,b))));
            col_max.push(SegmentTree::new(n+16, -INF, Rc::new(|a,b| max(a,b))));
        }
        Self {
            dp: dvec![-INF; n, n],
            row_max,
            col_max
        }
    }

    fn set(&mut self, row: usize, col: usize, v: i32) {
        if self.dp[row][col] < v {
            self.dp[row][col] = v;
            self.row_max[row].set(col, v);
            // self.col_max[col].set(row, v);
        }
    }
}

fn main() {
    input! {
        n: usize, a: [usize1; 3*n]
    };


    let mut add_all = 0;
    let mut dpdp =  DpWtihRowColMax::new(n);
    dpdp.set(a[0], a[1], 0);
    dpdp.set(a[1], a[0], 0);
    for i in 0..n-1 {
        let mut upd = vec![];
        let v = [a[i*3+2], a[i*3+3], a[i*3+4]];
        if v[0] == v[1] && v[1] == v[2] {
            add_all += 1; // ?
            continue;
        }
        for j in 0..3 {
            let other = (0..3).filter(|&k| j != k).map(|k| v[k]).collect::<Vec<_>>();
            upd.push((other[0], other[1], dpdp.dp[v[j]][v[j]] + 1));

            if other[0] == other[1] {
                for a in 0..n {
                    upd.push((a, v[j], max(dpdp.dp[other[0]][a], dpdp.dp[a][other[0]])+1));
                    upd.push((v[j], a, max(dpdp.dp[other[0]][a], dpdp.dp[a][other[0]])+1));
                }
            }
            for a in 0..n {
                let best = dpdp.row_max[a].compute_range(0, n);
                if best >= 0 {
                    upd.push((a, v[j], best));
                    upd.push((v[j], a, best));
                }
            }
        }

        for (row, col, new_value) in upd {
            dpdp.set(row, col, new_value);
        }
    }

    let mut ans = 0;
    for i in 0..n {
        for j in 0..n {
            let pl = ifv!(i == a[3*n-1] && j == a[3*n-1], 1, 0);
            ans = max(ans, dpdp.dp[i][j]+pl);
        }
    }
    println!("{}", ans + add_all);
}

use proconio::{input, marker::Usize1};

fn chmax(a: &mut i64, b: i64) { *a = (*a).max(b); }
fn rotate(x: &mut usize, y: &mut usize, z: &mut usize) {
    let w = *x;
    *x = *y;
    *y = *z;
    *z = w;
}

struct DP {
    l12: [Vec<Vec<i64>>; 2],
    l1_max: [Vec<i64>; 2],
    l2_max: [Vec<i64>; 2],
    max: [i64; 2],
    now: usize,
    pre: usize,
}

impl DP {
    fn new(n: usize) -> DP {
        DP {
            l12: [vec![vec![i64::min_value(); n]; n], vec![vec![i64::min_value(); n]; n]],
            l1_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            l2_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            max: [i64::min_value(); 2],
            now: 1,
            pre: 0,
        }
    }
    fn set(&mut self, l1: usize, l2: usize, v: i64) {
        chmax(&mut self.l12[self.now][l1][l2], v);
        chmax(&mut self.l12[self.now][l2][l1], v);
        chmax(&mut self.l1_max[self.now][l1], v);
        chmax(&mut self.l1_max[self.now][l2], v);
        chmax(&mut self.l2_max[self.now][l1], v);
        chmax(&mut self.l2_max[self.now][l2], v);
        chmax(&mut self.max[self.now], v);
    }
}

fn main() {
    input! {
        n: usize,
        a: [Usize1; n * 3],
    }

    let mut dp = DP::new(n);
    dp.set(a[0], a[1], 0);
    dp.pre = dp.now;
    dp.now = (dp.now + 1) % 2;
    let mut mc = 0;
    for i in 1..n {
        let (mut x, mut y, mut z) = (a[i * 3 - 1], a[i * 3], a[i * 3 + 1]);
        if x == y && x == z {
            mc += 1;
        } else {
            for _ in 0..3 {
                for l in 0..n {
                    let mut v = dp.l1_max[dp.pre][l];
                    if y == z {
                        v = v.max(dp.l12[dp.pre][l][y] + 1);
                    }
                    dp.set(l, x, v);
                }
                let v = dp.max[dp.pre].max(dp.l12[dp.pre][z][z] + 1);
                dp.set(x, y, v);
                rotate(&mut x, &mut y, &mut z);
            }
        }
        dp.pre = dp.now;
        dp.now = (dp.now + 1) % 2;
    }
    let v = dp.max[dp.pre].max(dp.l12[dp.pre][a[3 * n - 1]][a[3 * n - 1]] + 1);
    println!("{}", v + mc);
}

use std::fmt::Debug;
use std::str::FromStr;

pub struct TokenReader {
    reader: std::io::Stdin,
    tokens: Vec<String>,
    index: usize,
}

impl TokenReader {
    pub fn new() -> Self {
        Self {
            reader: std::io::stdin(),
            tokens: Vec::new(),
            index: 0,
        }
    }

    pub fn next<T>(&mut self) -> T
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index += 1;
        self.tokens[self.index - 1].parse().unwrap()
    }

    pub fn vector<T>(&mut self) -> Vec<T>
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index = self.tokens.len();
        self.tokens.iter().map(|tok| tok.parse().unwrap()).collect()
    }

    pub fn load_next_line(&mut self) {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();

        self.tokens = line
            .split_whitespace()
            .map(String::from)
            .collect();
        self.index = 0;
    }
}

fn choose(options: &mut Vec<usize>, one: &Vec<usize>, two: &Vec<usize>)
    -> (Vec<usize>, usize) {
    let n = one.len();
    let mut count = vec![0; n];
    options.iter().for_each(|&num| count[num] += 1);

    for &num in options.iter() {
        if count[num] >= 3 {
            let mut left = vec![];
            let mut seen = 0;
            for &x in options.iter() {
                if x != num || seen >= 3 {
                    left.push(x);
                }
                if x == num {
                    seen += 1;
                }
            }
            return (left, 1);
        }
    }

    options.sort_by_key(|&x| {
        -(if count[x] == 1 { two[x] } else { one[x] } as i32)
    });

    let mut left = vec![options[0]];

    if count[options[0]] == 1 {
        for i in 1..options.len() {
            if count[options[i]] == 1 {
                left.push(options[i]);
                break;
            }
        }
        if left.len() < 2 {
            left.push(options[1]);
        }
    } else {
        left.push(options[1]);
    }

    (left, 0)
}

fn solve(nums: &mut Vec<usize>) -> usize {
    nums.reverse();

    let n = nums.len() / 3;
    let mut one = vec![vec![0; n + 1]; nums.len()];
    let mut two = vec![vec![0; n + 1]; nums.len()];

    one[0][nums[0]] = 1;
    for i in 1..nums.len() {
        one[i] = one[i - 1].clone();
        two[i] = two[i - 1].clone();

        one[i][nums[i]] = i + 1;
        if one[i - 1][nums[i]] > 0 {
            two[i][nums[i]] = i + 1;
        }
    }

    let mut res = 0;
    while nums.len() >= 5 {
        let mut options = (0..5).map(|_| nums.pop().unwrap()).collect();
        let one = if nums.len() > 0 { one[nums.len() - 1].clone() } else { vec![0; n + 1] };
        let two = if nums.len() > 0 { two[nums.len() - 1].clone() } else { vec![0; n + 1] };
        let (mut left, points) = choose(&mut options, &one, &two);
        nums.append(&mut left);
        res += points;
    }

    res += if nums[0] == nums[1] && nums[1] == nums[2] { 1 } else { 0 };
    res
}

fn main() {
    let mut reader = TokenReader::new();
    let _n = reader.next::<usize>();
    let mut nums = reader.vector();

    let res = solve(&mut nums);
    println!("{}", res);
}

