fn main() {
    let n = read::<usize>();
    let a = read_vec::<usize>()
        .iter()
        .map(|&x| x - 1)
        .collect::<Vec<_>>();

    let mut a = a.into_iter().collect::<VecDeque<_>>();
    let mut ans = 0;
    'o: while a.len() >= 5 {
        let mut count = HashMap::new();
        for i in 0..5 {
            *count.entry(a[i]).or_insert(0) += 1;
        }
        for (k, v) in count {
            if v >= 3 {
                ans += 1;
                let mut c = 0;
                let mut popped = vec![];
                for _ in 0..5 {
                    let top = a.pop_front().unwrap();
                    if top == k {
                        c += 1;
                        if c >= 4 {
                            popped.push(top);
                        }
                    } else {
                        popped.push(top);
                    }
                }
                for elem in popped {
                    a.push_front(elem);
                }
                continue 'o;
            }
        }
        let mut count = vec![0; n];
        let mut holded_nums = vec![];
        for i in 0..a.len() {
            count[a[i]] += 1;
            if count[a[i]] == 3 {
                holded_nums.push(a[i]);
            }
            if holded_nums.len() >= 3 {
                break;
            }
        }
        let mut holded = vec![];
        'o1: for hi in 0..min(5, holded_nums.len()) {
            for i in 0..5 {
                if a[i] == holded_nums[hi] {
                    holded.push(a[i]);
                    if holded.len() >= 3 {
                        break 'o1;
                    }
                }
            }
        }
        for i in 0..5 {
            if holded.len() == 3 {
                break;
            }
            if holded.iter().filter(|&&x| x == i).count() == 0 {
                holded.push(i);
            }
        }
        for i in 0..5 {
            a.pop_front();
        }
        for elem in holded {
            a.push_front(elem);
        }
        //let mut hold = vec![];
    }
    if a.iter().all(|&x| x == a[0]) {
        ans += 1;
    }

    println!("{}", ans);
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
