use itertools::Itertools;
use proconio::{input, marker::Usize1};

fn main() {
    input!(n: usize, a: [Usize1; 3 * n]);

    let mut add = 0;

    let mut max = vec![i64::min_value(); n];
    max[a[0]] = 0;
    max[a[1]] = 0;

    let mut dp = vec![vec![i64::min_value(); n]; n];
    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;

    for (a, b, c) in a.iter().copied().skip(2).tuples() {
        let m = *max.iter().max().unwrap();
        let mut queue = vec![];
        let mut update = |i, j, v| queue.push((i, j, v));
        if a == b && b == c {
            add += 1;
            continue;
        }
        for (p, q, r) in [a, b, c, a, b].iter().copied().tuple_windows() {
            if p == q {
                for k in 0..n {
                    update(k, r, dp[p][k] + 1);
                    update(k, r, dp[k][p] + 1);
                }
            }
            update(q, r, dp[p][p] + 1);
            update(p, q, m);
            for k in 0..n {
                update(k, p, max[k]);
            }
        }
        for &(x, y, v) in &queue {
            dp[x][y] = dp[x][y].max(v);
            dp[y][x] = dp[y][x].max(v);
            max[x] = max[x].max(v);
            max[y] = max[y].max(v);
        }
    }

    let last = *a.last().unwrap();
    dp[last][last] += 1;

    let ans = add + dp.iter().flatten().max().unwrap();

    println!("{}", ans);
}

