use proconio::input;
use proconio::marker::Usize1;
use std::cmp;

fn upd(i: usize, j: usize, x: i64, dp: &mut Vec<Vec<i64>>, N: usize) {
    dp[i][j] = cmp::max(dp[i][j], x);
    dp[j][i] = cmp::max(dp[j][i], x);
    dp[N][i] = cmp::max(dp[N][j], x);
    dp[i][N] = cmp::max(dp[i][N], x);
    dp[N][j] = cmp::max(dp[N][j], x);
    dp[j][N] = cmp::max(dp[j][N], x);
    dp[N][N] = cmp::max(dp[N][N], x);
}
fn main() {
    input! {
        N: usize,
        A: [Usize1; 3 * N]
    }

    let mut ans = 0;
    let mut dp = vec![vec![std::i64::MIN; N + 1]; N + 1];
    upd(A[0], A[1], 0, &mut dp, N);
    for i in (2..(3 * N - 1)).step_by(3) {
        if A[i] == A[i + 1] && A[i + 1] == A[i + 2] {
            ans += 1;
            continue;
        }

        let mut q = Vec::new();
        for j in 0..3 {
            let x = A[i + j % 3];
            let y = A[i + (1 + j) % 3];
            let z = A[i + (2 + j) % 3];

            for a in 0..=N {
                let mut now = dp[a][N];
                if y == z {
                    now = cmp::max(now, dp[a][y] + 1);
                }
                q.push((a, x, now));
            }

            let now = cmp::max(dp[N][N], dp[z][z] + 1);
            q.push((x, y, now));
        }

        for (a, b, x) in q {
            upd(a, b, x, &mut dp, N);
        }
    }

    let l = A[3 * N - 1];
    ans += cmp::max(dp[N][N], dp[l][l] + 1);
    println!("{}", ans);
}

use std::io::Read;
use std::cmp::max;

#[allow(non_snake_case)]
fn main() {
  let mut buf = String::new();
  std::io::stdin().read_to_string(&mut buf).unwrap();
  let mut S : Vec<usize> = buf.split_whitespace().map(|s| s.parse().unwrap()).collect();
  let N = S[0];

  let mut dp1 = vec![None; N + 1];
  let mut dp2 = vec![vec![None; N + 1];N + 1];
  {
    let s = &mut S[1 ..= 2];
    s.sort();
    let (a,b) = (s[0], s[1]);
    dp1[a].get_or_insert(0);
    dp1[b].get_or_insert(0);
    dp1[0].get_or_insert(0);
    dp2[a][b].get_or_insert(0);
  }

  let mut base = 0;
  let mut q = Vec::new();

  for i in 1 .. N {
    let s = &mut S[3 * i .. 3 * (i + 1)];
    s.sort();
    let (a,b,c) = (s[0],s[1],s[2]);

    if a == c {
      base += 1;
      continue;
    } else if a == b {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][a] {
            q.push((x, c, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[a][x] {
            q.push((x, c, v + 1));
          }
        } else {
          if let Some(v) = dp2[a][x] {
            q.push((c, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, a, v + 1));
      }
    } else if b == c {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][c] {
            q.push((x, a, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[x][c] {
            q.push((a, x, v + 1));
          }
        } else {
          if let Some(v) = dp2[c][x] {
            q.push((a, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[a][a] {
        q.push((c, c, v + 1));
      }
    } else {
      if let Some(v) = dp2[a][a] {
        q.push((b, c, v + 1));
      }
      if let Some(v) = dp2[b][b] {
        q.push((a, c, v + 1));
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, b, v + 1));
      }
    }

    q.push((a, b, dp1[0].unwrap()));
    q.push((a, c, dp1[0].unwrap()));
    q.push((b, c, dp1[0].unwrap()));

    for x in 1 ..= N {
      if let Some(v) = dp1[x] {
        for y in &[a,b,c] {
          if x < *y {
            q.push((x, *y, v));
          } else {
            q.push((*y, x, v));
          }
        }
      }
    }

    while let Some((a,b,v)) = q.pop() {
      if dp2[a][b].is_none() || dp2[a][b].unwrap() < v {
        let u = dp2[a][b].replace(v);
        for i in &[0, a, b] {
          let u = dp1[*i].get_or_insert(v);
          *u = max(*u, v);
        }
      }
    }
  }

  let s = S[S.len() - 1];
  println!("{}", match dp2[s][s] {
    Some(v) => base + max(v + 1, dp1[0].unwrap()),
    None    => base + dp1[0].unwrap(), 
  });
}

