        } else {
            let mut h = std::collections::HashMap::new();
//            let mut q = vec![];
            for _ in 0..3 {
                for l in 0..n {
                    let mut v = dp.l1_max[l];
                    if y == z {
                        v = v.max(dp.l12[y][l] + 1);
                    }
//                    q.push((x, l, v));
                    let hv = h.entry((x, l)).or_insert(v);
                    chmax(hv, v);
                }
                let mut v = dp.max;
                if y == z {
                    v = v.max(dp.l1_max[y] + 1);
                }
//                q.push((x, n, v));
                let hv = h.entry((x, n)).or_insert(v);
                chmax(hv, v);

                let v = dp.max.max(dp.l12[z][z] + 1);
//                q.push((x, y, v));
                let hv = h.entry((x, y)).or_insert(v);
                chmax(hv, v);
                rotate(&mut x, &mut y, &mut z);
            }
//            for (x, y, v) in q {
            for ((x, y), v) in h {
                dp.set(x, y, v);
            }
        }
    }
    let l = a[3 * n - 1];
    let v = dp.max.max(dp.l12[l][l] + 1);
    println!("{}", v + mc);
}

use proconio::{input, marker::Usize1};

fn chmax(a: &mut i64, b: i64) { *a = (*a).max(b); }
fn rotate(x: &mut usize, y: &mut usize, z: &mut usize) {
    let w = *x;
    *x = *y;
    *y = *z;
    *z = w;
}

struct DP {
    l12: [Vec<Vec<i64>>; 2],
    l1_max: [Vec<i64>; 2],
    l2_max: [Vec<i64>; 2],
    max: [i64; 2],
    now: usize,
    pre: usize,
}

impl DP {
    fn new(n: usize) -> DP {
        DP {
            l12: [vec![vec![i64::min_value(); n]; n], vec![vec![i64::min_value(); n]; n]],
            l1_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            l2_max: [vec![i64::min_value(); n], vec![i64::min_value(); n]],
            max: [i64::min_value(); 2],
            now: 1,
            pre: 0,
        }
    }
    fn set(&mut self, l1: usize, l2: usize, v: i64) {
        chmax(&mut self.l12[self.now][l1][l2], v);
        chmax(&mut self.l12[self.now][l2][l1], v);
        chmax(&mut self.l1_max[self.now][l1], v);
        chmax(&mut self.l1_max[self.now][l2], v);
        chmax(&mut self.l2_max[self.now][l1], v);
        chmax(&mut self.l2_max[self.now][l2], v);
        chmax(&mut self.max[self.now], v);
    }
}

fn main() {
    input! {
        n: usize,
        a: [Usize1; n * 3],
    }

    let mut dp = DP::new(n);
    dp.set(a[0], a[1], 0);
    dp.pre = dp.now;
    dp.now = (dp.now + 1) % 2;
    let mut mc = 0;
    for i in 1..n {
        let (mut x, mut y, mut z) = (a[i * 3 - 1], a[i * 3], a[i * 3 + 1]);
        if x == y && x == z {
            mc += 1;
        } else {
            for _ in 0..3 {
                for l in 0..n {
                    let mut v = dp.l1_max[dp.pre][l];
                    if y == z {
                        v = v.max(dp.l12[dp.pre][l][y] + 1);
                    }
                    dp.set(l, x, v);
                }
                let mut v = dp.max[dp.pre];
                if y == z {
                    v = v.max(dp.l2_max[dp.pre][y] + 1);
                }
                chmax(&mut dp.l1_max[dp.now][x], v);
                chmax(&mut dp.l2_max[dp.now][x], v);
                chmax(&mut dp.max[dp.now], v);

                let v = dp.max[dp.pre].max(dp.l12[dp.pre][z][z] + 1);
                dp.set(x, y, v);
                rotate(&mut x, &mut y, &mut z);
            }
            dp.pre = dp.now;
            dp.now = (dp.now + 1) % 2;
        }
    }
    let l = a[3 * n - 1];
    let v = dp.max[dp.pre].max(dp.l12[dp.pre][l][l] + 1);
    println!("{}", v + mc);
}

