fn main() {
    proconio::input! {
        N: usize,
        A: [usize; 3 * N],
    }

    type Node = (usize, usize, usize);
    let mut q = std::collections::VecDeque::new();
    q.push_back((0, A[0], A[1]));

    let mut dp = vec![vec![vec![-1; N + 1]; N + 1]; N + 1];

    for x in 0..N+1 {
        for y in 0..N+1 {
            dp[0][x][y] = 0;
        }
    }

    let update = |q: &mut std::collections::VecDeque<Node>, dp: &mut Vec<Vec<Vec<i32>>>, index: usize, x: usize, y: usize, a: usize, b: usize, c: usize, score: i32| {
        let xx = if x < y { x } else { y };
        let yy = if x < y { y } else { x };
        let newScore = score + if a == b && b == c { 1 } else { 0 };

        if dp[index][xx][yy] >= newScore { return; }
        dp[index][xx][yy] = std::cmp::max(dp[index][xx][yy], newScore);

        q.push_back((index, xx, yy));

        // eprintln!("-> index={}, ({}, {}), newScore={}", index, xx, yy, newScore);
    };

    let mut ans = 0;

    while let Some((index, a1, a2)) = q.pop_front() {
        let a3 = A[index * 3 + 2];

        if index == N - 1 {
            ans = std::cmp::max(ans, dp[index][a1][a2] + if a1 == a2 && a2 == a3 { 1 } else { 0 });
            continue;
        }

        let a4 = A[index * 3 + 3];
        let a5 = A[index * 3 + 4];

        let score = std::cmp::max(dp[index][a1][a2], dp[index][a2][a1]);

        // eprintln!("index={}, cards=({}, {}, {}, {}, {}), score={}", index, a1, a2, a3, a4, a5, score);

        update(&mut q, &mut dp, index + 1, a1, a2, a3, a4, a5, score);
        update(&mut q, &mut dp, index + 1, a1, a3, a2, a4, a5, score);
        update(&mut q, &mut dp, index + 1, a1, a4, a2, a3, a5, score);
        update(&mut q, &mut dp, index + 1, a1, a5, a2, a3, a4, score);

        update(&mut q, &mut dp, index + 1, a2, a3, a1, a4, a5, score);
        update(&mut q, &mut dp, index + 1, a2, a4, a1, a3, a5, score);
        update(&mut q, &mut dp, index + 1, a2, a5, a1, a3, a4, score);

        update(&mut q, &mut dp, index + 1, a3, a4, a1, a2, a5, score);
        update(&mut q, &mut dp, index + 1, a3, a5, a1, a2, a4, score);

        update(&mut q, &mut dp, index + 1, a4, a5, a1, a2, a3, score);
    }

    println!("{}", ans);
}

