fn f(memo: &mut std::collections::BTreeMap<(usize,usize,usize), i64>, v: &mut [usize]) -> i64 {
  if v.len() == 3 {
     return if v[0] == v[1] && v[1] == v[2] { 1 } else { 0 };
  }
  if let Some(&x) = memo.get(&(v.len(), v[0], v[1])) {
    return x;
  }

  let mut res = 0;
  let v2 = v[3..5].collect_vec();
  let v3 = v[..5].sorted().collect_vec();
  if v3[0] == v3[2] {
    v[3] = *v3[3];
    v[4] = *v3[4];
    res = f(memo, &mut v[3..]) + 1;
  } else if v3[1] == v3[3] {
    v[3] = *v3[0];
    v[4] = *v3[4];
    res = f(memo, &mut v[3..]) + 1;
  } else if v3[2] == v3[4] {
    v[3] = *v3[0];
    v[4] = *v3[1];
    res = f(memo, &mut v[3..]) + 1;
  } else {
    for i in (0..5).combinations(2) {
      v[3] = *v3[i[0]];
      v[4] = *v3[i[2]];
      res = std::cmp::max(res, f(memo, &mut v[3..]));
    }
  }
  v[3] = v2[0];
  v[4] = v2[1];
  memo.insert((v.len(), v[0], v[1]), res);
  res
}

fn main() {
    input! {
        n: usize,
        mut a: [Usize1; 3*n],
    }


  	let res = f(&mut std::collections::BTreeMap::new(), &mut a[..]);

    println!("{}", res);
}

use std::io::Read;
use std::cmp::max;

#[allow(non_snake_case)]
fn main() {
  let mut buf = String::new();
  std::io::stdin().read_to_string(&mut buf).unwrap();
  let mut S : Vec<usize> = buf.split_whitespace().map(|s| s.parse().unwrap()).collect();
  let N = S[0];

  let mut dp1 = vec![None; N + 1];
  let mut dp2 = vec![vec![None; N + 1];N + 1];
  {
    let s = &mut S[1 ..= 2];
    s.sort();
    let (a,b) = (s[0], s[1]);
    dp1[a].get_or_insert(0);
    dp1[b].get_or_insert(0);
    dp1[0].get_or_insert(0);
    dp2[a][b].get_or_insert(0);
  }

  let mut base = 0;
  let mut q = Vec::new();


  for i in 1 .. N {
    let s = &mut S[3 * i ..= 3 * i + 2];
    s.sort();
    let (a,b,c) = (s[0],s[1],s[2]);

    if a == c {
      base += 1;
      continue;
    } else if a == b {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][a] {
            q.push((x, c, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[a][x] {
            q.push((x, c, v + 1));
          }
        } else {
          if let Some(v) = dp2[a][x] {
            q.push((c, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, a, v + 1));
      }
    } else if b == c {
      for x in 1 ..= N {
        if x < a {
          if let Some(v) = dp2[x][c] {
            q.push((x, a, v + 1));
          }
        } else if x < c {
          if let Some(v) = dp2[x][c] {
            q.push((a, x, v + 1));
          }
        } else {
          if let Some(v) = dp2[c][x] {
            q.push((a, x, v + 1));
          }
        }
      }
      if let Some(v) = dp2[a][a] {
        q.push((c, c, v + 1));
      }
    } else {
      if let Some(v) = dp2[a][a] {
        q.push((b, c, v + 1));
      }
      if let Some(v) = dp2[b][b] {
        q.push((a, c, v + 1));
      }
      if let Some(v) = dp2[c][c] {
        q.push((a, b, v + 1));
      }
    }

    q.push((a, b, dp1[0].unwrap()));
    q.push((a, c, dp1[0].unwrap()));
    q.push((b, c, dp1[0].unwrap()));

    for x in 1 ..= N {
      if let Some(v) = dp1[x] {
        for y in &[a,b,c] {
          if x < *y {
            q.push((x, *y, v));
          } else {
            q.push((*y, x, v));
          }
        }
      }
    }

    while let Some((a,b,v)) = q.pop() {
      if dp2[a][b].is_none() || dp2[a][b].unwrap() < v {
        let u = dp2[a][b].get_or_insert(v);
        *u = v;
        for i in &[0, a, b] {
          let u = dp1[*i].get_or_insert(v);
          *u = max(*u, v);
        }
      }
    }
  }

  let s = S[3 * N - 1];
  println!("{}", base + max(1 + dp2[s][s].unwrap_or(0), dp1[0].unwrap_or(0)));
}

