use proconio::*;
use proconio::marker::*;
use std::cmp::*;

fn run() {
    input! {
        n: usize,
        a: [Usize1; 3 * n],
    }
    assert!(n < 500);
    let mut dp = vec![vec![-5000; n]; n];
    dp[a[0]][a[1]] = 0;
    dp[a[1]][a[0]] = 0;
    for a in a[2..].chunks_exact(3) {
        let mut next = vec![vec![0; n]; n];
        let (a, b, c) = (a[0], a[1], a[2]);
        for (i, dp) in dp.iter().enumerate() {
            for (j, &v) in dp.iter().enumerate() {
                let mut b = [i, j, a, b, c];
                b.sort();
                let a = b;
                if a[0] == a[2] {
                    let (x, y) = (a[3], a[4]);
                    next[x][y].chmax(v + 1);
                    next[y][x].chmax(v + 1);
                } else if a[1] == a[3] {
                    let (x, y) = (a[0], a[4]);
                    next[x][y].chmax(v + 1);
                    next[y][x].chmax(v + 1);
                } else if a[2] == a[4] {
                    let (x, y) = (a[0], a[1]);
                    next[x][y].chmax(v + 1);
                    next[y][x].chmax(v + 1);
                } else {
                    for (i, &x) in a.iter().enumerate() {
                        for &y in a.iter().take(i) {
                            next[x][y].chmax(v);
                            next[y][x].chmax(v);
                        }
                    }
                }
            }
        }
        dp = next;
    }
    let last = *a.last().unwrap();
    let ans = max(*dp.iter().flatten().max().unwrap(), dp[last][last] + 1);
    println!("{}", ans);
}

fn main() {
    run();
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

