    pub fn getMax(&self, a:usize, b:usize, k:usize, l:usize, r:usize)->i64{
        if (r <= a || b <= l){ return (-INF);}
        if (a <= l && r <= b){ return(self.segMin[k] + self.segAdd[k])};
        let mut left = self.getMax(a, b, k * 2 + 1, l, (l + r) / 2);
        let mut right = self.getMax(a, b, k * 2 + 2, (l + r) / 2, r);
        return (cmp::max(left, right) + self.segAdd[k]);
    }
}

fn solve(){
    let sssss = std::io::stdin();
    let mut sc = Scanner { stdin: sssss.lock() };
    let mut N:usize = sc.read();
    let mut a = vec![0usize;N*3];
    for i in 0..3*N{
        a[i] = sc.read();
        a[i]-=1;
    }
    let mut dp = HashMap::new();
    fn dfs(s:usize, a:usize, b:usize, v:&mut Vec<usize>, dp:&mut HashMap<(usize, usize, usize),usize>, N:usize)->usize{
        let mut res = 0;
        let mut vv = vec![];
        if dp.contains_key(&(s, a, b)){
            return dp[&(s, a, b)];
        }
        if a != N{
            vv.push(a);
            vv.push(b);
        }
        let mut ii = s;
        while(vv.len() != 5){
            vv.push(v[ii]);
            ii+=1;
            if ii == v.len(){
                break;
            }
        }
        if vv.len()==3{
            vv.sort();
            if vv[0] == vv[2]{
                res+=1;
            }
            return res;
        }
        for i in 0..5{
            for j in i+1..5{
                let mut vvv = vec![];
                for k in 0..5{
                    if k != i && k != j{
                        vvv.push(vv[k]);
                    }
                }
                vvv.sort();
                let mut tmp = 0;
                if vvv[0] == vvv[2]{
                    tmp+=1;
                }
                let mut x = vv[i];
                let mut y = vv[j];
                if x>y{
                    mem::swap(&mut x, &mut y);
                }
                if a == N{
                tmp += dfs(s+5, x, y,  v,  dp, N);
                }
                else{
                    tmp += dfs(s+3, x, y, v, dp, N);
                }

                res = cmp::max(res, tmp);
            }
        }
        let mut bef = 0;
        if dp.contains_key(&(s, a, b)){
            bef = dp[&(s, a, b)];
        }
        bef = cmp::max(bef, res);
        dp.insert((s, a, b), bef);
        return res;
    }
    println!("{}", dfs(0, N, N, &mut a, &mut dp, N));








}

