                    }
                };

                dp2[a[i * 3 + 3]][a[i * 3 + 2]] = dp2[a[i * 3 + 2]][a[i * 3 + 3]];
                dp2[a[i * 3 + 4]][a[i * 3 + 2]] = dp2[a[i * 3 + 2]][a[i * 3 + 4]];
                dp2[a[i * 3 + 4]][a[i * 3 + 3]] = dp2[a[i * 3 + 3]][a[i * 3 + 4]];
            }
        }
        dp = dp2;
    }

    if a[3 * n - 2] == a[3 * n - 1] {
        for i in 0..n {
            dp[i][a[3 * n - 2]].0 += 1;
            if i != a[3 * n - 2] {
                dp[a[3 * n - 2]][i].0 += 1;
            }
        }
    }
    else {
        dp[a[3 * n - 2]][a[3 * n - 2]].0 += 1;
        dp[a[3 * n - 1]][a[3 * n - 1]].0 += 1;
    }

    let mut max_value = 0;
    for v in dp {
        for (c, b) in v {
            if b && c > max_value {
                max_value = c;
            }
        }
    }

    println!("{}", max_value);
}

fn main() {
    std::thread::Builder::new()
        .name("solve".into())
        .stack_size(256 * 1024 * 1024)
        .spawn(solve)
        .unwrap()
        .join()
        .unwrap();
}

use proconio::{*, marker::*};

fn main() {
    input! {
        n: usize,
        a: [Usize1; 3*n],
    }

    let mut zero = vec![0; n];
    let mut one = vec![0; n];

    for i in 0..2 {
        zero[a[i]] += 1;
    }

    let mut ans = 0;
    for ii in 0..n-1 {
        for jj in (2+ii*3)..(2+ii*3+3) {
            one[a[jj]] += 1;
        }
        let mut tmp = (3, n);
        for k in 0..n {
            if zero[k] + one[k] >= 3 {
                if zero[k] < tmp.0 {
                    tmp = (zero[k], k);
                }
            }
        }
        if tmp.0 < 3 {
            ans += 1;
        }
        if tmp.0 == 0 {
            assert!(one[tmp.1] >= 3);
            one[tmp.1] -= 3;
            for i in 0..n {
                zero[i] += one[i];
            }
        }
        if tmp.0 == 1 {
            assert_eq!(zero[tmp.1], 1);
            zero[tmp.1] -= 1;
            one[tmp.1] -= 2;
            for i in 0..n {
                zero[i] = (zero[i]).min(1);
                zero[i] += one[i];
            }
        }
        if tmp.0 == 2 {
            assert_eq!(zero[tmp.1], 2);
            one[tmp.1] -= 1;
            for i in 0..n {
                zero[i] = one[i];
            }
        }
        if tmp.0 == 3 {
            for i in 0..n {
                zero[i] += one[i];
            }
        }
        for i in 0..n {
            one[i] = 0;
        }
    }


    one[a[3*n-1]] += 1;

    // println!("{:?}", zero);
    // println!("{:?}", one);
    let mut three = false;
    for i in 0..n {
        if zero[i] + one[i] >= 3 {
            three = true;
        }
    }
    if three {
        ans += 1;
    }

    println!("{}", ans);
}
